CREATE OR REPLACE FUNCTION "agri_connect"."announcements_scope_immutable"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.announcement_type IS DISTINCT FROM OLD.announcement_type
     OR NEW.community_id IS DISTINCT FROM OLD.community_id
     OR NEW.entity_id IS DISTINCT FROM OLD.entity_id
     OR NEW.published_by IS DISTINCT FROM OLD.published_by THEN
    RAISE EXCEPTION 'announcement type, community/entity scope, and publisher identity are immutable'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."announcements_scope_immutable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."attach_discussion_media"("p_discussion_id" "uuid", "p_file_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_profile_id uuid;
  v_discussion agri_connect.discussions%ROWTYPE;
  v_community agri_connect.communities%ROWTYPE;
  v_object storage.objects%ROWTYPE;
  v_entity_id uuid;
  v_path text;
  v_size bigint;
  v_media_ids jsonb;
BEGIN
  v_profile_id := agri_connect.current_profile_id();
  IF core.auth_user_id() IS NULL OR v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Authentication and an active profile are required' USING ERRCODE='42501';
  END IF;

  SELECT * INTO v_discussion
  FROM agri_connect.discussions d
  WHERE d.id = p_discussion_id
  FOR UPDATE;
  IF NOT FOUND OR NOT agri_connect.can_manage_discussion_media(p_discussion_id) THEN
    RAISE EXCEPTION 'Caller cannot attach media to this discussion' USING ERRCODE='42501';
  END IF;

  IF v_discussion.metadata IS NULL OR jsonb_typeof(v_discussion.metadata) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Discussion metadata must be a JSON object' USING ERRCODE='23514';
  END IF;
  v_media_ids := COALESCE(v_discussion.metadata->'media_file_ids', '[]'::jsonb);
  IF jsonb_typeof(v_media_ids) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'metadata.media_file_ids must be a JSON array' USING ERRCODE='23514';
  END IF;
  IF jsonb_array_length(v_media_ids) >= 2 THEN
    RAISE EXCEPTION 'A discussion can have at most 2 images' USING ERRCODE='23514';
  END IF;
  IF v_media_ids @> jsonb_build_array(p_file_id::text)
     OR EXISTS (SELECT 1 FROM media.files f WHERE f.id = p_file_id) THEN
    RAISE EXCEPTION 'Media file is already attached or registered' USING ERRCODE='23505';
  END IF;

  IF v_discussion.community_id IS NOT NULL THEN
    SELECT * INTO v_community
    FROM agri_connect.communities c
    WHERE c.id = v_discussion.community_id;
  END IF;
  v_entity_id := COALESCE(v_community.entity_id, core.current_entity_id());
  IF v_entity_id IS NULL THEN
    RAISE EXCEPTION 'An active entity context is required to attach discussion media' USING ERRCODE='42501';
  END IF;

  v_path := 'images/agri_connect/discussions/'
    || p_discussion_id::text || '/' || p_file_id::text || '.webp';
  SELECT * INTO v_object
  FROM storage.objects o
  WHERE o.bucket_id = 'media' AND o.name = v_path
  FOR SHARE;
  IF NOT FOUND OR v_object.owner_id IS DISTINCT FROM core.auth_user_id()::text
     OR (v_object.metadata->>'mimetype') IS DISTINCT FROM 'image/webp' THEN
    RAISE EXCEPTION 'Uploaded discussion image is missing or not owned by the caller' USING ERRCODE='23514';
  END IF;

  v_size := COALESCE(
    (v_object.metadata->>'size')::bigint,
    (v_object.metadata->>'contentLength')::bigint
  );
  IF v_size IS NULL OR v_size <= 0 OR v_size > 2097152 THEN
    RAISE EXCEPTION 'Discussion image must be no larger than 2 MiB' USING ERRCODE='23514';
  END IF;

  INSERT INTO media.files (
    id, bucket, path, entity_id, context_type, context_id,
    file_type, mime_type, extension, size_bytes,
    is_public, is_original_stored, is_deleted, created_by
  ) VALUES (
    p_file_id, 'media', v_path, v_entity_id, 'agri_connect_discussion', p_discussion_id,
    'image', 'image/webp', 'webp', v_size,
    false, true, false, v_profile_id
  );

  UPDATE agri_connect.discussions
  SET metadata = jsonb_set(
        v_discussion.metadata,
        '{media_file_ids}',
        v_media_ids || jsonb_build_array(p_file_id::text),
        true
      )
  WHERE id = p_discussion_id;

  INSERT INTO media.file_events (file_id, event_type, entity_id, context_id)
  VALUES (p_file_id, 'upload', v_entity_id, p_discussion_id);

  RETURN jsonb_build_object(
    'id', p_file_id,
    'bucket', 'media',
    'path', v_path,
    'entity_id', v_entity_id,
    'context_type', 'agri_connect_discussion',
    'context_id', p_discussion_id,
    'file_type', 'image',
    'mime_type', 'image/webp',
    'extension', 'webp',
    'size_bytes', v_size,
    'width', NULL,
    'height', NULL,
    'is_public', false,
    'is_deleted', false,
    'created_by', v_profile_id
  );
END;
$$;


ALTER FUNCTION "agri_connect"."attach_discussion_media"("p_discussion_id" "uuid", "p_file_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."attach_post_media"("p_post_id" "uuid", "p_file_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_profile_id uuid;
  v_post agri_connect.posts%ROWTYPE;
  v_object storage.objects%ROWTYPE;
  v_upload agri_connect.post_media_uploads%ROWTYPE;
  v_existing media.files%ROWTYPE;
  v_entity_id uuid;
  v_path text;
  v_size bigint;
  v_attachment_count integer;
BEGIN
  IF p_post_id IS NULL OR p_file_id IS NULL
     OR core.auth_user_id() IS NULL
     OR agri_connect.current_profile_id() IS NULL THEN
    RAISE EXCEPTION 'Authentication, an active profile, and valid IDs are required' USING ERRCODE='42501';
  END IF;
  v_profile_id := agri_connect.current_profile_id();

  SELECT * INTO v_post
  FROM agri_connect.posts p
  WHERE p.id = p_post_id
  FOR UPDATE;
  IF NOT FOUND OR NOT agri_connect.can_manage_post_media(p_post_id) THEN
    RAISE EXCEPTION 'Caller cannot attach media to this post' USING ERRCODE='42501';
  END IF;

  SELECT * INTO v_upload
  FROM agri_connect.post_media_uploads u
  WHERE u.file_id = p_file_id
    AND u.post_id = p_post_id
    AND u.profile_id = v_profile_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'A valid upload reservation is required' USING ERRCODE='42501';
  END IF;

  IF v_upload.status = 'attached' THEN
    SELECT f.* INTO v_existing
    FROM media.files f
    JOIN agri_connect.post_media pm ON pm.media_file_id = f.id
    WHERE pm.post_id = p_post_id
      AND pm.media_file_id = p_file_id
      AND f.is_deleted IS FALSE;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'id', v_existing.id,
        'bucket', v_existing.bucket,
        'path', v_existing.path,
        'entity_id', v_existing.entity_id,
        'context_type', v_existing.context_type,
        'context_id', v_existing.context_id,
        'file_type', v_existing.file_type,
        'mime_type', v_existing.mime_type,
        'extension', v_existing.extension,
        'size_bytes', v_existing.size_bytes,
        'is_public', v_existing.is_public,
        'is_deleted', v_existing.is_deleted,
        'created_by', v_existing.created_by
      );
    END IF;
    RAISE EXCEPTION 'Upload reservation has already been consumed' USING ERRCODE='23505';
  END IF;
  IF v_upload.status <> 'reserved' OR v_upload.expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'Upload reservation is expired or released' USING ERRCODE='23514';
  END IF;

  SELECT count(*)::integer INTO v_attachment_count
  FROM agri_connect.post_media pm
  WHERE pm.post_id = p_post_id;
  IF v_attachment_count >= 2 THEN
    RAISE EXCEPTION 'A post can have at most 2 images' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT 1 FROM media.files f WHERE f.id = p_file_id) THEN
    RAISE EXCEPTION 'Media file is already registered' USING ERRCODE='23505';
  END IF;

  SELECT COALESCE(c.entity_id, core.current_entity_id()) INTO v_entity_id
  FROM agri_connect.discussions d
  LEFT JOIN agri_connect.communities c ON c.id = d.community_id
  WHERE d.id = v_post.discussion_id;
  IF v_entity_id IS NULL THEN
    RAISE EXCEPTION 'An active entity context is required to attach post media' USING ERRCODE='42501';
  END IF;

  v_path := 'images/agri_connect/posts/' || p_post_id::text || '/' || p_file_id::text || '.webp';
  IF v_upload.path IS DISTINCT FROM v_path THEN
    RAISE EXCEPTION 'Upload reservation path is invalid' USING ERRCODE='23514';
  END IF;

  SELECT * INTO v_object
  FROM storage.objects o
  WHERE o.bucket_id = 'media' AND o.name = v_path
  FOR SHARE;
  IF NOT FOUND OR (v_object.metadata->>'mimetype') IS DISTINCT FROM 'image/webp' THEN
    RAISE EXCEPTION 'Uploaded post image is missing or not WebP' USING ERRCODE='23514';
  END IF;

  v_size := COALESCE(
    (v_object.metadata->>'size')::bigint,
    (v_object.metadata->>'contentLength')::bigint
  );
  IF v_size IS NULL OR v_size <= 0 OR v_size > 2097152 THEN
    RAISE EXCEPTION 'Post image must be no larger than 2 MiB' USING ERRCODE='23514';
  END IF;

  INSERT INTO media.files (
    id, bucket, path, entity_id, context_type, context_id,
    file_type, mime_type, extension, size_bytes,
    is_public, is_original_stored, is_deleted, created_by
  ) VALUES (
    p_file_id, 'media', v_path, v_entity_id, 'agri_connect_post', p_post_id,
    'image', 'image/webp', 'webp', v_size,
    false, true, false, v_profile_id
  );

  INSERT INTO agri_connect.post_media (post_id, media_file_id)
  VALUES (p_post_id, p_file_id);

  INSERT INTO media.file_events (file_id, event_type, entity_id, context_id)
  VALUES (p_file_id, 'upload', v_entity_id, p_post_id);

  UPDATE agri_connect.post_media_uploads
  SET status = 'attached', finished_at = clock_timestamp()
  WHERE file_id = p_file_id AND status = 'reserved';

  RETURN jsonb_build_object(
    'id', p_file_id,
    'bucket', 'media',
    'path', v_path,
    'entity_id', v_entity_id,
    'context_type', 'agri_connect_post',
    'context_id', p_post_id,
    'file_type', 'image',
    'mime_type', 'image/webp',
    'extension', 'webp',
    'size_bytes', v_size,
    'is_public', false,
    'is_deleted', false,
    'created_by', v_profile_id
  );
END;
$$;


ALTER FUNCTION "agri_connect"."attach_post_media"("p_post_id" "uuid", "p_file_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."bootstrap_community_owner"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
BEGIN
  IF core.auth_user_id() IS NULL
     OR NEW.created_by IS DISTINCT FROM agri_connect.current_profile_id() THEN
    RAISE EXCEPTION 'community owner must be its authenticated creator' USING ERRCODE='42501';
  END IF;
  INSERT INTO agri_connect.community_members
    (community_id, profile_id, role, status, joined_at, approved_by, approved_at)
  VALUES (NEW.id, NEW.created_by, 'owner', 'active', statement_timestamp(), NEW.created_by, statement_timestamp());
  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."bootstrap_community_owner"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."can_manage_discussion_media"("p_discussion_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  SELECT core.auth_user_id() IS NOT NULL
     AND agri_connect.current_profile_id() IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM agri_connect.discussions d
       WHERE d.id = p_discussion_id
         AND d.is_active IS TRUE
         AND (
           d.community_id IS NULL
           OR agri_connect.is_active_community_member(
                d.community_id, ARRAY['member','moderator','admin','owner']::text[]
              )
         )
         AND (
           agri_connect.is_active_community_member(
             d.community_id, ARRAY['moderator','admin','owner']::text[]
           )
           OR (d.created_by = agri_connect.current_profile_id() AND d.is_locked IS FALSE)
         )
     );
$$;


ALTER FUNCTION "agri_connect"."can_manage_discussion_media"("p_discussion_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."can_manage_post_media"("p_post_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  SELECT core.auth_user_id() IS NOT NULL
     AND agri_connect.current_profile_id() IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM agri_connect.posts p
       JOIN agri_connect.discussions d ON d.id = p.discussion_id
       LEFT JOIN agri_connect.communities c ON c.id = d.community_id
       WHERE p.id = p_post_id
         AND p.is_deleted IS FALSE
         AND d.is_active IS TRUE
         AND (
           (
             p.author_profile_id = agri_connect.current_profile_id()
             AND d.is_locked IS FALSE
             AND (
               d.community_id IS NULL
               OR (
                 c.is_active IS TRUE
                 AND agri_connect.is_active_community_member(
                   d.community_id, ARRAY['member','moderator','admin','owner']::text[]
                 )
               )
             )
           )
           OR (
             d.community_id IS NOT NULL
             AND c.is_active IS TRUE
             AND agri_connect.is_active_community_member(
               d.community_id, ARRAY['moderator','admin','owner']::text[]
             )
           )
         )
     );
$$;


ALTER FUNCTION "agri_connect"."can_manage_post_media"("p_post_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."can_read_discussion_media"("p_discussion_id" "uuid", "p_file_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM agri_connect.discussions d
    WHERE d.id = p_discussion_id
      AND d.is_active IS TRUE
      AND COALESCE(jsonb_typeof(d.metadata->'media_file_ids') = 'array', false)
      AND (d.metadata->'media_file_ids') @> jsonb_build_array(p_file_id::text)
      AND (
        d.community_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM agri_connect.communities c
          WHERE c.id = d.community_id
            AND c.is_active IS TRUE
            AND c.visibility = 'public'
        )
        OR agri_connect.is_active_community_member(
             d.community_id, ARRAY['member','moderator','admin','owner']::text[]
           )
      )
  );
$$;


ALTER FUNCTION "agri_connect"."can_read_discussion_media"("p_discussion_id" "uuid", "p_file_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."can_read_media_object"("p_bucket" "text", "p_path" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM media.files f
    WHERE f.bucket = p_bucket
      AND f.path = p_path
      AND f.is_deleted IS FALSE
      AND (
        (
          f.context_type = 'agri_connect_community'
          AND EXISTS (
            SELECT 1
            FROM agri_connect.communities c
            WHERE c.id = f.context_id
              AND c.profile_image_file_id = f.id
              AND c.is_active IS TRUE
              AND (
                (c.visibility = 'public' AND f.is_public IS TRUE)
                OR agri_connect.is_active_community_member(
                     c.id, ARRAY['member','moderator','admin','owner']::text[]
                   )
              )
          )
        )
        OR (
          f.context_type = 'agri_connect_conversation'
          AND f.is_public IS FALSE
          AND EXISTS (
            SELECT 1
            FROM agri_connect.messages m
            JOIN agri_connect.conversations c ON c.id = m.conversation_id
            WHERE m.media_file_id = f.id
              AND m.conversation_id = f.context_id
              AND m.is_deleted IS FALSE
              AND c.is_active IS TRUE
              AND agri_connect.messaging_has_active_identity(c.id)
              AND (
                c.community_id IS NULL
                OR agri_connect.is_active_community_member(
                     c.community_id, ARRAY['member','moderator','admin','owner']::text[]
                   )
              )
          )
        )
        OR (
          f.context_type = 'agri_connect_discussion'
          AND f.is_public IS FALSE
          AND agri_connect.can_read_discussion_media(f.context_id, f.id)
        )
        OR (
          f.context_type = 'agri_connect_post'
          AND f.is_public IS FALSE
          AND EXISTS (
            SELECT 1
            FROM agri_connect.post_media pm
            WHERE pm.media_file_id = f.id
              AND agri_connect.can_read_post_media(pm.post_id, f.id)
          )
        )
      )
  );
$$;


ALTER FUNCTION "agri_connect"."can_read_media_object"("p_bucket" "text", "p_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."can_read_post_media"("p_post_id" "uuid", "p_file_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  SELECT core.auth_user_id() IS NOT NULL
     AND agri_connect.current_profile_id() IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM agri_connect.post_media pm
       JOIN agri_connect.posts p ON p.id = pm.post_id
       JOIN agri_connect.discussions d ON d.id = p.discussion_id
       LEFT JOIN agri_connect.communities c ON c.id = d.community_id
       JOIN media.files f ON f.id = pm.media_file_id
       WHERE pm.post_id = p_post_id
         AND pm.media_file_id = p_file_id
         AND p.is_deleted IS FALSE
         AND d.is_active IS TRUE
         AND f.context_type = 'agri_connect_post'
         AND f.is_public IS FALSE
         AND f.is_deleted IS FALSE
         AND (
           d.community_id IS NULL
           OR (
             c.is_active IS TRUE
             AND (
               c.visibility = 'public'
               OR agri_connect.is_active_community_member(
                 d.community_id, ARRAY['member','moderator','admin','owner']::text[]
               )
             )
           )
         )
     );
$$;


ALTER FUNCTION "agri_connect"."can_read_post_media"("p_post_id" "uuid", "p_file_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."community_members_member_count_trg"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_community_id uuid;
  v_delta int := 0;
  v_old_active boolean;
  v_new_active boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_community_id := NEW.community_id;
    v_new_active := (NEW.status = 'active');
    v_delta := CASE WHEN v_new_active THEN 1 ELSE 0 END;

  ELSIF TG_OP = 'UPDATE' THEN
    v_community_id := NEW.community_id;

    -- if community_id changes, adjust both communities
    IF NEW.community_id IS DISTINCT FROM OLD.community_id THEN
      -- subtract from old community
      v_old_active := (OLD.status = 'active');
      IF v_old_active THEN
        UPDATE agri_connect.communities
        SET member_count = member_count - 1
        WHERE id = OLD.community_id;
      END IF;
      -- add to new community
      v_new_active := (NEW.status = 'active');
      IF v_new_active THEN
        UPDATE agri_connect.communities
        SET member_count = member_count + 1
        WHERE id = NEW.community_id;
      END IF;
      RETURN NEW;
    END IF;

    v_old_active := (OLD.status = 'active');
    v_new_active := (NEW.status = 'active');
    v_delta := (CASE WHEN v_new_active THEN 1 ELSE 0 END) - (CASE WHEN v_old_active THEN 1 ELSE 0 END);

  ELSIF TG_OP = 'DELETE' THEN
    v_community_id := OLD.community_id;
    v_old_active := (OLD.status = 'active');
    v_delta := CASE WHEN v_old_active THEN -1 ELSE 0 END;

  ELSE
    RETURN NULL;
  END IF;

  IF v_delta <> 0 THEN
    UPDATE agri_connect.communities
    SET member_count = member_count + v_delta
    WHERE id = v_community_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."community_members_member_count_trg"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."content_reports_prevent_scope_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Block changes to identity/scope and immutable report content
  IF (NEW.reporter_profile_id IS DISTINCT FROM OLD.reporter_profile_id)
     OR (NEW.target_type IS DISTINCT FROM OLD.target_type)
     OR (NEW.target_id IS DISTINCT FROM OLD.target_id)
     OR (NEW.reason IS DISTINCT FROM OLD.reason)
     OR (NEW.description IS DISTINCT FROM OLD.description)
     OR (NEW.created_at IS DISTINCT FROM OLD.created_at)
  THEN
    RAISE EXCEPTION 'content_reports is immutable for reporter/target/reason/description/created_at';
  END IF;

  -- Allow updates to moderation fields only (best-effort enforcement)
  -- If other columns are added in the future, this trigger will still block the known immutable ones.
  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."content_reports_prevent_scope_changes"() OWNER TO "postgres";

