    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "communities_community_type_check" CHECK (("community_type" = ANY (ARRAY['interest'::"text", 'location'::"text", 'buyer'::"text", 'self_help'::"text", 'cooperative'::"text", 'organization'::"text", 'private'::"text", 'project'::"text"]))),
    CONSTRAINT "communities_visibility_check" CHECK (("visibility" = ANY (ARRAY['public'::"text", 'private'::"text", 'restricted'::"text"])))
);


