CREATE OR REPLACE FUNCTION "agri_connect"."create_community"("p_name" "text", "p_slug" "text", "p_community_type" "text", "p_visibility" "text" DEFAULT 'public'::"text", "p_description" "text" DEFAULT NULL::"text", "p_entity_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "agri_connect"."communities"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE v_profile_id uuid; v_community agri_connect.communities;
BEGIN
  v_profile_id := agri_connect.current_profile_id();
  IF core.auth_user_id() IS NULL OR v_profile_id IS NULL THEN
    RAISE EXCEPTION 'community creation requires an authenticated FAMHUB profile' USING ERRCODE='42501';
  END IF;
  IF p_entity_id IS NOT NULL AND p_entity_id IS DISTINCT FROM core.current_entity_id() THEN
    RAISE EXCEPTION 'community entity must match the caller active entity context' USING ERRCODE='42501';
  END IF;
  INSERT INTO agri_connect.communities
    (name,slug,description,community_type,visibility,entity_id,location_id,created_by,
     is_active,is_verified,member_count,profile_image_file_id,metadata)
  VALUES
    (p_name,p_slug,p_description,p_community_type,p_visibility,p_entity_id,p_location_id,v_profile_id,
     true,false,0,NULL,COALESCE(p_metadata,'{}'::jsonb))
  RETURNING * INTO v_community;
  RETURN v_community;
END;
$$;


