    "title" "text",
    "community_id" "uuid",
    "created_by" "uuid",
    "context_type" "text",
    "context_id" "uuid",
    "is_active" boolean DEFAULT true NOT NULL,
    "last_message_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "conversations_conversation_type_check" CHECK (("conversation_type" = ANY (ARRAY['direct'::"text", 'group'::"text", 'community'::"text", 'marketplace'::"text", 'support'::"text", 'organization'::"text"])))
);


ALTER TABLE "agri_connect"."conversations" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."create_conversation"("p_conversation_type" "text", "p_title" "text" DEFAULT NULL::"text", "p_community_id" "uuid" DEFAULT NULL::"uuid", "p_context_type" "text" DEFAULT NULL::"text", "p_context_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "agri_connect"."conversations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE v_profile_id uuid; v_conversation agri_connect.conversations;
BEGIN
  v_profile_id := agri_connect.current_profile_id();
  IF core.auth_user_id() IS NULL OR v_profile_id IS NULL THEN
    RAISE EXCEPTION 'conversation creation requires an authenticated FAMHUB profile' USING ERRCODE='42501';
  END IF;
  IF p_context_type IS NOT NULL OR p_context_id IS NOT NULL THEN
    RAISE EXCEPTION 'contextual conversations must be created by their owning FAMHUB backend module' USING ERRCODE='42501';
  END IF;
  IF p_conversation_type IN ('direct','group') THEN
    IF p_community_id IS NOT NULL THEN
      RAISE EXCEPTION 'direct and group conversations cannot have a community scope' USING ERRCODE='23514';
    END IF;
  ELSIF p_conversation_type = 'community' THEN
    IF p_community_id IS NULL OR NOT agri_connect.is_active_community_member(
      p_community_id, ARRAY['member','moderator','admin','owner']::text[]) THEN
      RAISE EXCEPTION 'community conversation creation requires active community membership' USING ERRCODE='42501';
    END IF;
  ELSE
    RAISE EXCEPTION 'this conversation type is created only by its owning FAMHUB backend module' USING ERRCODE='42501';
  END IF;
  INSERT INTO agri_connect.conversations
    (conversation_type,title,community_id,created_by,context_type,context_id,is_active,metadata)
  VALUES
    (p_conversation_type,p_title,p_community_id,v_profile_id,NULL,NULL,true,COALESCE(p_metadata,'{}'::jsonb))
  RETURNING * INTO v_conversation;
  RETURN v_conversation;
END;
$$;


ALTER FUNCTION "agri_connect"."create_conversation"("p_conversation_type" "text", "p_title" "text", "p_community_id" "uuid", "p_context_type" "text", "p_context_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


