CREATE OR REPLACE FUNCTION "agri_connect"."current_user_has_verified_email"("p_email" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  SELECT p_email IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM auth.users AS u
       JOIN users.profiles AS p ON p.auth_user_id = u.id
       WHERE u.id = auth.uid()
         AND p.id = agri_connect.current_profile_id()
         AND u.email_confirmed_at IS NOT NULL
         AND lower(u.email) = lower(btrim(p_email))
     );
$$;


