CREATE OR REPLACE FUNCTION "agri_connect"."delete_discussion_media"("p_file_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_file media.files%ROWTYPE;
  v_discussion agri_connect.discussions%ROWTYPE;
  v_media_ids jsonb;
  v_next_ids jsonb;
BEGIN
  IF core.auth_user_id() IS NULL OR agri_connect.current_profile_id() IS NULL THEN
    RAISE EXCEPTION 'Authentication and an active profile are required' USING ERRCODE='42501';
  END IF;

  SELECT * INTO v_file
  FROM media.files f
  WHERE f.id = p_file_id
    AND f.context_type = 'agri_connect_discussion'
    AND f.is_deleted IS FALSE
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Discussion media not found' USING ERRCODE='P0002';
  END IF;

  SELECT * INTO v_discussion
  FROM agri_connect.discussions d
  WHERE d.id = v_file.context_id
  FOR UPDATE;
  IF NOT FOUND OR NOT agri_connect.can_manage_discussion_media(v_discussion.id) THEN
    RAISE EXCEPTION 'Caller cannot remove media from this discussion' USING ERRCODE='42501';
  END IF;

  IF v_discussion.metadata IS NULL OR jsonb_typeof(v_discussion.metadata) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Discussion metadata must be a JSON object' USING ERRCODE='23514';
  END IF;
  v_media_ids := COALESCE(v_discussion.metadata->'media_file_ids', '[]'::jsonb);
  IF jsonb_typeof(v_media_ids) IS DISTINCT FROM 'array'
     OR NOT (v_media_ids @> jsonb_build_array(p_file_id::text)) THEN
    RAISE EXCEPTION 'Discussion media is not attached to this discussion' USING ERRCODE='42501';
  END IF;

  SELECT COALESCE(jsonb_agg(item ORDER BY ord), '[]'::jsonb)
  INTO v_next_ids
  FROM jsonb_array_elements(v_media_ids) WITH ORDINALITY AS ids(item, ord)
  WHERE item <> to_jsonb(p_file_id::text);

  UPDATE agri_connect.discussions
  SET metadata = jsonb_set(v_discussion.metadata, '{media_file_ids}', v_next_ids, true)
  WHERE id = v_discussion.id;

  UPDATE media.files
  SET is_deleted = true
  WHERE id = p_file_id AND is_deleted IS FALSE;

  INSERT INTO media.file_events (file_id, event_type, entity_id, context_id)
  VALUES (p_file_id, 'delete', v_file.entity_id, v_file.context_id);

  RETURN jsonb_build_object(
    'success', true,
    'file_id', p_file_id,
    'storage_retained', true
  );
END;
$$;


ALTER FUNCTION "agri_connect"."delete_discussion_media"("p_file_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."discussion_views_view_count_trg"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_discussion_id uuid;
  v_old_valid boolean;
  v_new_valid boolean;
  v_delta int := 0;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_discussion_id := NEW.discussion_id;
    v_new_valid := (NEW.invalidated_at IS NULL);
    v_delta := CASE WHEN v_new_valid THEN 1 ELSE 0 END;

  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.discussion_id IS DISTINCT FROM OLD.discussion_id THEN
      v_old_valid := (OLD.invalidated_at IS NULL);
      IF v_old_valid THEN
        UPDATE agri_connect.discussions
        SET view_count = view_count - 1
        WHERE id = OLD.discussion_id;
      END IF;

      v_new_valid := (NEW.invalidated_at IS NULL);
      IF v_new_valid THEN
        UPDATE agri_connect.discussions
        SET view_count = view_count + 1
        WHERE id = NEW.discussion_id;
      END IF;
      RETURN NEW;
    END IF;

    v_discussion_id := NEW.discussion_id;
    v_old_valid := (OLD.invalidated_at IS NULL);
    v_new_valid := (NEW.invalidated_at IS NULL);
    v_delta := (CASE WHEN v_new_valid THEN 1 ELSE 0 END) - (CASE WHEN v_old_valid THEN 1 ELSE 0 END);

  ELSIF TG_OP = 'DELETE' THEN
    v_discussion_id := OLD.discussion_id;
    v_old_valid := (OLD.invalidated_at IS NULL);
    v_delta := CASE WHEN v_old_valid THEN -1 ELSE 0 END;
  END IF;

  IF v_delta <> 0 THEN
    UPDATE agri_connect.discussions
    SET view_count = view_count + v_delta
    WHERE id = v_discussion_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."discussion_views_view_count_trg"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."enforce_content_reports_immutable"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  old_immutable jsonb;
  new_immutable jsonb;
  caller_profile_id uuid;
BEGIN
  old_immutable := to_jsonb(OLD) - ARRAY['status', 'reviewed_by', 'reviewed_at', 'resolution'];
  new_immutable := to_jsonb(NEW) - ARRAY['status', 'reviewed_by', 'reviewed_at', 'resolution'];

  IF new_immutable IS DISTINCT FROM old_immutable THEN
    RAISE EXCEPTION 'content_reports: reporter, target, reason, description, id, and creation fields are immutable';
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status
     AND NOT (
       (OLD.status = 'pending' AND NEW.status = ANY (ARRAY['reviewing', 'resolved', 'dismissed']))
       OR (OLD.status = 'reviewing' AND NEW.status = ANY (ARRAY['resolved', 'dismissed']))
     )
  THEN
    RAISE EXCEPTION 'content_reports: invalid status transition from % to %', OLD.status, NEW.status;
  END IF;

  IF NEW.status = 'pending' THEN
    IF NEW.reviewed_by IS DISTINCT FROM OLD.reviewed_by
       OR NEW.reviewed_at IS DISTINCT FROM OLD.reviewed_at
       OR NEW.resolution IS DISTINCT FROM OLD.resolution
    THEN
      RAISE EXCEPTION 'content_reports: pending reports cannot have review fields';
    END IF;
  ELSE
    caller_profile_id := agri_connect.current_profile_id();
    IF caller_profile_id IS NULL THEN
      RAISE EXCEPTION 'content_reports: a reviewer profile is required';
    END IF;
    NEW.reviewed_by := caller_profile_id;
    NEW.reviewed_at := statement_timestamp();
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."enforce_content_reports_immutable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."expire_post_media_uploads"("p_post_id" "uuid") RETURNS TABLE("file_id" "uuid", "path" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
BEGIN
  IF p_post_id IS NULL THEN
    RETURN;
  END IF;

  PERFORM 1
  FROM agri_connect.posts p
  WHERE p.id = p_post_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  UPDATE agri_connect.post_media_uploads u
  SET status = 'aborted', finished_at = clock_timestamp()
  WHERE u.post_id = p_post_id
    AND u.status = 'reserved'
    AND u.expires_at <= clock_timestamp()
    AND NOT EXISTS (SELECT 1 FROM agri_connect.post_media pm WHERE pm.media_file_id = u.file_id)
    AND NOT EXISTS (SELECT 1 FROM media.files f WHERE f.id = u.file_id);

  RETURN QUERY
  SELECT u.file_id, u.path
  FROM agri_connect.post_media_uploads u
  WHERE u.post_id = p_post_id
    AND u.status = 'aborted'
    AND NOT EXISTS (SELECT 1 FROM agri_connect.post_media pm WHERE pm.media_file_id = u.file_id)
    AND NOT EXISTS (SELECT 1 FROM media.files f WHERE f.id = u.file_id)
    AND EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'media' AND o.name = u.path);
END;
$$;


ALTER FUNCTION "agri_connect"."expire_post_media_uploads"("p_post_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."guard_community_governance_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_profile_id uuid;
  v_internal_invitation_activation boolean;
  v_standard_rejoin boolean;
  v_owner_rejoin boolean;
BEGIN
  IF core.auth_user_id() IS NULL THEN RETURN NEW; END IF;
  v_profile_id := agri_connect.current_profile_id();

  IF TG_TABLE_NAME = 'community_members' THEN
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.community_id IS DISTINCT FROM OLD.community_id
       OR NEW.profile_id IS DISTINCT FROM OLD.profile_id OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      RAISE EXCEPTION 'membership identity fields are immutable' USING ERRCODE = '42501';
    END IF;

    v_internal_invitation_activation := pg_trigger_depth() > 1
      AND OLD.status = 'pending' AND NEW.status = 'active' AND NEW.role = 'member'
      AND NEW.invited_by IS NOT NULL AND NEW.approved_by IS NULL AND NEW.approved_at IS NULL
      AND NEW.joined_at IS NOT NULL;

    v_standard_rejoin := OLD.profile_id = v_profile_id
      AND OLD.status = 'left' AND NEW.status = 'pending' AND NEW.role = 'member'
      AND NEW.joined_at IS NULL AND NEW.invited_by IS NULL
      AND NEW.approved_by IS NULL AND NEW.approved_at IS NULL
      AND (to_jsonb(NEW) - ARRAY['status','joined_at','invited_by','approved_by','approved_at','updated_at'])
          IS NOT DISTINCT FROM
          (to_jsonb(OLD) - ARRAY['status','joined_at','invited_by','approved_by','approved_at','updated_at']);

    v_owner_rejoin := OLD.profile_id = v_profile_id
      AND OLD.status = 'left' AND NEW.status = 'active'
      AND OLD.role = 'owner' AND NEW.role = 'owner'
      AND NEW.joined_at IS NOT NULL AND NEW.invited_by IS NULL
      AND NEW.approved_by IS NOT DISTINCT FROM OLD.approved_by
      AND NEW.approved_at IS NOT DISTINCT FROM OLD.approved_at
      AND (to_jsonb(NEW) - ARRAY['status','joined_at','updated_at'])
          IS NOT DISTINCT FROM
          (to_jsonb(OLD) - ARRAY['status','joined_at','updated_at']);

    IF OLD.profile_id = v_profile_id AND NOT v_internal_invitation_activation THEN
      IF NOT (
        (OLD.status = 'active' AND NEW.status = 'left'
         AND (to_jsonb(NEW) - ARRAY['status','updated_at']) IS NOT DISTINCT FROM
             (to_jsonb(OLD) - ARRAY['status','updated_at']))
        OR v_standard_rejoin
        OR v_owner_rejoin
      ) THEN
        RAISE EXCEPTION 'members may leave their own active membership or rejoin a prior membership' USING ERRCODE = '42501';
      END IF;
    END IF;

    IF v_internal_invitation_activation
       AND (NEW.approved_by IS DISTINCT FROM OLD.approved_by OR NEW.approved_at IS DISTINCT FROM OLD.approved_at) THEN
      RAISE EXCEPTION 'invitation acceptance cannot rewrite approval identity' USING ERRCODE = '42501';
    END IF;
    IF (NEW.approved_by IS DISTINCT FROM OLD.approved_by OR NEW.approved_at IS DISTINCT FROM OLD.approved_at
        OR (NEW.joined_at IS DISTINCT FROM OLD.joined_at AND NOT v_internal_invitation_activation))
       AND NOT v_owner_rejoin THEN
      IF OLD.status IS DISTINCT FROM 'pending' OR NEW.status IS DISTINCT FROM 'active'
         OR NEW.approved_by IS DISTINCT FROM v_profile_id OR NEW.approved_at IS NULL OR NEW.joined_at IS NULL THEN
        RAISE EXCEPTION 'approval fields may only be set by the acting approver when activating a pending membership' USING ERRCODE = '42501';
      END IF;
    END IF;

    IF NEW.status = 'active' AND OLD.status IS DISTINCT FROM 'active'
       AND (OLD.status IS DISTINCT FROM 'pending' OR NEW.approved_by IS DISTINCT FROM v_profile_id
            OR NEW.approved_at IS NULL OR NEW.joined_at IS NULL)
       AND NOT v_internal_invitation_activation AND NOT v_owner_rejoin THEN
      RAISE EXCEPTION 'only a pending membership may be activated with the acting approver and timestamps' USING ERRCODE = '42501';
    END IF;

  ELSIF TG_TABLE_NAME = 'community_join_requests' THEN
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.community_id IS DISTINCT FROM OLD.community_id
       OR NEW.profile_id IS DISTINCT FROM OLD.profile_id OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      RAISE EXCEPTION 'join request identity fields are immutable' USING ERRCODE = '42501';
    END IF;
    IF OLD.profile_id = v_profile_id THEN
      IF OLD.status IS DISTINCT FROM 'pending' OR NEW.status IS DISTINCT FROM 'cancelled'
         OR (to_jsonb(NEW) - ARRAY['status']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status']) THEN
        RAISE EXCEPTION 'requesters may only cancel their own pending request' USING ERRCODE = '42501';
      END IF;
    END IF;
    IF NEW.reviewed_by IS DISTINCT FROM OLD.reviewed_by OR NEW.reviewed_at IS DISTINCT FROM OLD.reviewed_at
       OR NEW.status IN ('approved','rejected') THEN
      IF OLD.status IS DISTINCT FROM 'pending' OR NEW.status NOT IN ('approved','rejected')
         OR NEW.reviewed_by IS DISTINCT FROM v_profile_id OR NEW.reviewed_at IS NULL THEN
        RAISE EXCEPTION 'request review requires a pending request and the acting reviewer' USING ERRCODE = '42501';
      END IF;
    END IF;

  ELSIF TG_TABLE_NAME = 'community_invitations' THEN
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.community_id IS DISTINCT FROM OLD.community_id
       OR NEW.invited_profile_id IS DISTINCT FROM OLD.invited_profile_id
       OR NEW.invited_email IS DISTINCT FROM OLD.invited_email OR NEW.invited_by IS DISTINCT FROM OLD.invited_by
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      RAISE EXCEPTION 'invitation identity and scope fields are immutable' USING ERRCODE = '42501';
    END IF;

    IF OLD.invited_profile_id IS NULL AND OLD.status = 'pending' AND NEW.status = 'accepted' THEN
      IF OLD.accepted_at IS NOT NULL
         OR (to_jsonb(NEW) - ARRAY['status','accepted_at']) IS DISTINCT FROM
            (to_jsonb(OLD) - ARRAY['status','accepted_at'])
         OR NOT agri_connect.current_user_has_verified_email(OLD.invited_email) THEN
        RAISE EXCEPTION 'email invitation acceptance requires its verified-email owner' USING ERRCODE = '42501';
      END IF;
      NEW.accepted_at := now();
      RETURN NEW;
    END IF;

    IF OLD.invited_profile_id = v_profile_id THEN
      IF OLD.status IS DISTINCT FROM 'pending' OR NEW.status NOT IN ('accepted','declined')
         OR (to_jsonb(NEW) - ARRAY['status','accepted_at']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status','accepted_at']) THEN
        RAISE EXCEPTION 'recipients may only accept or decline their own pending invitation' USING ERRCODE = '42501';
      END IF;
      NEW.accepted_at := CASE WHEN NEW.status = 'accepted' THEN COALESCE(OLD.accepted_at, now()) ELSE NULL END;
    ELSE
      IF OLD.status IS DISTINCT FROM 'pending' OR NEW.status IS DISTINCT FROM 'cancelled'
         OR (to_jsonb(NEW) - ARRAY['status']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status']) THEN
        RAISE EXCEPTION 'managers may only cancel a pending invitation without changing its scope' USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."guard_community_governance_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."guard_community_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE v_old_file media.files%ROWTYPE; v_new_file media.files%ROWTYPE;
BEGIN
  IF TG_OP='INSERT' THEN
    IF core.auth_user_id() IS NULL
       OR NEW.created_by IS DISTINCT FROM agri_connect.current_profile_id()
       OR NEW.member_count <> 0 OR NEW.is_verified IS DISTINCT FROM false
       OR NEW.profile_image_file_id IS NOT NULL
       OR (NEW.entity_id IS NOT NULL AND NEW.entity_id IS DISTINCT FROM core.current_entity_id()) THEN
      RAISE EXCEPTION 'community creation identity, counters, verification, media, or entity scope is invalid' USING ERRCODE='42501';
    END IF;
  ELSE
    IF pg_trigger_depth()>1 THEN
      IF (to_jsonb(NEW)-ARRAY['member_count','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['member_count','updated_at']) THEN
        RAISE EXCEPTION 'nested community trigger may change only the member counter' USING ERRCODE='42501';
      END IF;
      RETURN NEW;
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.created_by IS DISTINCT FROM OLD.created_by
       OR NEW.entity_id IS DISTINCT FROM OLD.entity_id
       OR NEW.member_count IS DISTINCT FROM OLD.member_count
       OR NEW.is_verified IS DISTINCT FROM OLD.is_verified
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      RAISE EXCEPTION 'community identity, entity scope, counters, verification, and creation fields are immutable through the client' USING ERRCODE='42501';
    END IF;
    IF NEW.profile_image_file_id IS DISTINCT FROM OLD.profile_image_file_id AND NEW.profile_image_file_id IS NOT NULL THEN
      IF core.auth_user_id() IS NOT NULL AND NOT agri_connect.is_active_community_member(NEW.id, ARRAY['admin','owner']::text[]) THEN
        RAISE EXCEPTION 'only active community admins or owners may manage profile media' USING ERRCODE='42501';
      END IF;
      SELECT * INTO v_new_file FROM media.files
      WHERE id=NEW.profile_image_file_id AND bucket='media' AND context_type='agri_connect_community'
        AND context_id=NEW.id AND file_type='image' AND is_deleted=false
        AND created_by=agri_connect.current_profile_id()
        AND is_public=(NEW.visibility='public')
        AND ((NEW.entity_id IS NOT NULL AND entity_id=NEW.entity_id)
             OR (NEW.entity_id IS NULL AND core.current_entity_id() IS NOT NULL AND entity_id=core.current_entity_id()));
      IF NOT FOUND THEN RAISE EXCEPTION 'Community profile image must be the caller''s authorized image for this community' USING ERRCODE='42501'; END IF;
    ELSIF NEW.profile_image_file_id IS DISTINCT FROM OLD.profile_image_file_id AND NEW.profile_image_file_id IS NULL
       AND core.auth_user_id() IS NOT NULL
       AND NOT agri_connect.is_active_community_member(NEW.id, ARRAY['admin','owner']::text[]) THEN
      RAISE EXCEPTION 'only active community admins or owners may remove profile media' USING ERRCODE='42501';
    END IF;

    -- Retire public visibility, not the blob, when a public image is replaced or the community goes private.
    IF OLD.profile_image_file_id IS NOT NULL
       AND (NEW.profile_image_file_id IS DISTINCT FROM OLD.profile_image_file_id OR NEW.visibility <> 'public') THEN
      SELECT * INTO v_old_file FROM media.files WHERE id=OLD.profile_image_file_id AND context_type='agri_connect_community';
      IF FOUND AND v_old_file.is_public IS TRUE THEN
        UPDATE media.files SET is_public=false WHERE id=v_old_file.id;
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."guard_community_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."guard_discussion_content_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_profile_id uuid;
  v_ids jsonb;
BEGIN
  IF TG_OP <> 'UPDATE' THEN
    RETURN NEW;
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.community_id IS DISTINCT FROM OLD.community_id
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'discussion identity, scope, creator, and creation time are immutable' USING ERRCODE='42501';
  END IF;

  -- Counts may only be changed by the existing nested counter-maintenance triggers.
  IF pg_trigger_depth() <= 1 AND (
    NEW.reply_count IS DISTINCT FROM OLD.reply_count
    OR NEW.view_count IS DISTINCT FROM OLD.view_count
  ) THEN
    RAISE EXCEPTION 'discussion counters are maintained by protected mechanisms' USING ERRCODE='42501';
  END IF;

  v_profile_id := agri_connect.current_profile_id();
  IF core.auth_user_id() IS NOT NULL AND OLD.created_by = v_profile_id THEN
    IF OLD.is_active IS NOT TRUE OR OLD.is_locked IS TRUE
       OR NEW.is_active IS DISTINCT FROM OLD.is_active
       OR NEW.is_locked IS DISTINCT FROM OLD.is_locked
       OR NEW.is_pinned IS DISTINCT FROM OLD.is_pinned THEN
      RAISE EXCEPTION 'authors may edit only active, unlocked discussions and cannot change discussion state' USING ERRCODE='42501';
    END IF;

    IF NEW.metadata IS NOT NULL AND jsonb_typeof(NEW.metadata) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'discussion metadata must be a JSON object' USING ERRCODE='23514';
    END IF;
    v_ids := COALESCE(NEW.metadata->'media_file_ids', '[]'::jsonb);
    IF jsonb_typeof(v_ids) IS DISTINCT FROM 'array'
       OR jsonb_array_length(v_ids) > 2
       OR EXISTS (
         SELECT 1
         FROM jsonb_array_elements(v_ids) AS item(value)
         WHERE jsonb_typeof(item.value) IS DISTINCT FROM 'string'
            OR NOT EXISTS (
              SELECT 1 FROM media.files f
              WHERE f.id::text = item.value #>> '{}'
                AND f.context_type = 'agri_connect_discussion'
                AND f.context_id = OLD.id
                AND f.is_deleted IS FALSE
            )
       )
       OR (SELECT count(DISTINCT item.value)
           FROM jsonb_array_elements(v_ids) AS item(value)) <> jsonb_array_length(v_ids) THEN
      RAISE EXCEPTION 'discussion images must be unique active media for this discussion (maximum 2)' USING ERRCODE='23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."guard_discussion_content_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."guard_discussion_media_file_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_discussion agri_connect.discussions%ROWTYPE;
  v_community agri_connect.communities%ROWTYPE;
  v_object storage.objects%ROWTYPE;
  v_expected_entity_id uuid;
  v_expected_path text;
  v_object_size bigint;
BEGIN
  IF NEW.context_type IS DISTINCT FROM 'agri_connect_discussion' THEN
    RETURN NEW;
  END IF;

  IF core.auth_user_id() IS NULL
     OR agri_connect.current_profile_id() IS NULL
     OR NEW.created_by IS DISTINCT FROM agri_connect.current_profile_id()
     OR NEW.bucket IS DISTINCT FROM 'media'
     OR NEW.file_type IS DISTINCT FROM 'image'
     OR NEW.mime_type IS DISTINCT FROM 'image/webp'
     OR NEW.extension IS DISTINCT FROM 'webp'
     OR NEW.is_public IS DISTINCT FROM false
     OR NEW.is_deleted IS DISTINCT FROM false
     OR NEW.size_bytes IS NULL OR NEW.size_bytes <= 0 OR NEW.size_bytes > 2097152 THEN
    RAISE EXCEPTION 'Discussion media must be an authenticated private WebP image uploaded by its creator (max 2 MiB)' USING ERRCODE='42501';
  END IF;

  SELECT * INTO v_discussion
  FROM agri_connect.discussions d
  WHERE d.id = NEW.context_id
  FOR SHARE;
  IF NOT FOUND OR NOT agri_connect.can_manage_discussion_media(NEW.context_id) THEN
    RAISE EXCEPTION 'Caller cannot attach media to this discussion' USING ERRCODE='42501';
  END IF;

  IF v_discussion.community_id IS NOT NULL THEN
    SELECT * INTO v_community
    FROM agri_connect.communities c
    WHERE c.id = v_discussion.community_id;
  END IF;
  v_expected_entity_id := COALESCE(v_community.entity_id, core.current_entity_id());
  IF v_expected_entity_id IS NULL OR NEW.entity_id IS DISTINCT FROM v_expected_entity_id THEN
    RAISE EXCEPTION 'Discussion media requires the discussion community or caller active entity scope' USING ERRCODE='42501';
  END IF;

  v_expected_path := 'images/agri_connect/discussions/'
    || NEW.context_id::text || '/' || NEW.id::text || '.webp';
  IF NEW.path IS DISTINCT FROM v_expected_path THEN
    RAISE EXCEPTION 'Discussion media path does not match its discussion and file IDs' USING ERRCODE='23514';
  END IF;

  SELECT * INTO v_object
  FROM storage.objects o
  WHERE o.bucket_id = NEW.bucket AND o.name = NEW.path;
  IF NOT FOUND OR v_object.owner_id IS DISTINCT FROM core.auth_user_id()::text
     OR (v_object.metadata->>'mimetype') IS DISTINCT FROM NEW.mime_type THEN
    RAISE EXCEPTION 'Discussion media must be a caller-owned uploaded Storage object with matching MIME type' USING ERRCODE='23514';
  END IF;

  v_object_size := COALESCE(
    (v_object.metadata->>'size')::bigint,
    (v_object.metadata->>'contentLength')::bigint
  );
  IF v_object_size IS DISTINCT FROM NEW.size_bytes THEN
    RAISE EXCEPTION 'Discussion media size must match its Storage object' USING ERRCODE='23514';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."guard_discussion_media_file_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."guard_discussion_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND (
    NEW.id IS DISTINCT FROM OLD.id OR
    NEW.community_id IS DISTINCT FROM OLD.community_id OR
    NEW.created_by IS DISTINCT FROM OLD.created_by
  ) THEN
    RAISE EXCEPTION 'discussion identity, community, and creator are immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


