    NEW.id IS DISTINCT FROM OLD.id OR
    NEW.discussion_id IS DISTINCT FROM OLD.discussion_id OR
    NEW.profile_id IS DISTINCT FROM OLD.profile_id OR
    NEW.entity_id IS DISTINCT FROM OLD.entity_id
