CREATE OR REPLACE FUNCTION "agri_connect"."guard_media_file_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
BEGIN
  IF OLD.context_type IN (
    'agri_connect_community','agri_connect_conversation','agri_connect_discussion','agri_connect_post'
  ) THEN
    RAISE EXCEPTION 'Agri Connect media uses detach/retention, not direct file deletion' USING ERRCODE='42501';
  END IF;
  RETURN OLD;
END;
$$;


ALTER FUNCTION "agri_connect"."guard_media_file_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."guard_media_file_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
DECLARE
  v_object storage.objects%ROWTYPE;
  v_expected_entity uuid;
  v_community agri_connect.communities%ROWTYPE;
  v_conversation agri_connect.conversations%ROWTYPE;
  v_expected_folder text;
BEGIN
  IF NEW.context_type NOT IN ('agri_connect_community','agri_connect_conversation') THEN
    RETURN NEW;
  END IF;
  IF core.auth_user_id() IS NULL
     OR NEW.created_by IS DISTINCT FROM agri_connect.current_profile_id()
     OR NEW.bucket <> 'media'
     OR NEW.is_deleted IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'Agri Connect media upload requires the authenticated file creator' USING ERRCODE='42501';
  END IF;
  IF NEW.extension IS NULL OR NEW.extension !~ '^[a-z0-9]{1,10}$'
     OR NEW.extension <> lower(NEW.extension)
     OR NEW.mime_type IS NULL OR NEW.size_bytes IS NULL OR NEW.size_bytes < 0 THEN
    RAISE EXCEPTION 'Invalid Agri Connect media metadata' USING ERRCODE='23514';
  END IF;

  IF NEW.context_type = 'agri_connect_community' THEN
    SELECT * INTO v_community FROM agri_connect.communities WHERE id=NEW.context_id;
    IF NOT FOUND OR v_community.is_active IS NOT TRUE
       OR NOT agri_connect.is_active_community_member(NEW.context_id, ARRAY['admin','owner']::text[])
       OR NEW.file_type <> 'image'
       OR NEW.is_public IS DISTINCT FROM (v_community.visibility='public')
       OR (v_community.entity_id IS NOT NULL AND NEW.entity_id IS DISTINCT FROM v_community.entity_id)
       OR (v_community.entity_id IS NULL AND (core.current_entity_id() IS NULL OR NEW.entity_id IS DISTINCT FROM core.current_entity_id())) THEN
      RAISE EXCEPTION 'Community media requires an active community admin or owner and matching media scope' USING ERRCODE='42501';
    END IF;
    v_expected_folder := 'images/agri_connect/communities/'||NEW.context_id::text||'/'||NEW.id::text||'.'||NEW.extension;
  ELSE
    SELECT * INTO v_conversation FROM agri_connect.conversations WHERE id=NEW.context_id;
    IF NOT FOUND OR v_conversation.is_active IS NOT TRUE
       OR NOT agri_connect.messaging_has_active_identity(NEW.context_id)
       OR (v_conversation.community_id IS NOT NULL AND NOT agri_connect.is_active_community_member(v_conversation.community_id, ARRAY['member','moderator','admin','owner']::text[]))
       OR NEW.is_public IS NOT FALSE
       OR (v_conversation.community_id IS NOT NULL AND EXISTS (
           SELECT 1 FROM agri_connect.communities c
           WHERE c.id=v_conversation.community_id AND c.entity_id IS NOT NULL
             AND NEW.entity_id IS DISTINCT FROM c.entity_id))
       OR ((v_conversation.community_id IS NULL OR NOT EXISTS (
           SELECT 1 FROM agri_connect.communities c
           WHERE c.id=v_conversation.community_id AND c.entity_id IS NOT NULL))
           AND (core.current_entity_id() IS NULL OR NEW.entity_id IS DISTINCT FROM core.current_entity_id())) THEN
      RAISE EXCEPTION 'Conversation media requires an active participant and matching conversation scope' USING ERRCODE='42501';
    END IF;
    IF NEW.file_type NOT IN ('image','video','document','audio') THEN
      RAISE EXCEPTION 'Unsupported Agri Connect conversation media type' USING ERRCODE='23514';
    END IF;
    v_expected_folder := (CASE NEW.file_type WHEN 'image' THEN 'images' WHEN 'video' THEN 'videos' WHEN 'document' THEN 'documents' WHEN 'audio' THEN 'audio' END)
      ||'/agri_connect/conversations/'||NEW.context_id::text||'/'||NEW.id::text||'.'||NEW.extension;
  END IF;
  IF NEW.path IS DISTINCT FROM v_expected_folder THEN
    RAISE EXCEPTION 'Media path does not match its Agri Connect context' USING ERRCODE='23514';
  END IF;

  IF NEW.mime_type NOT IN (
    'image/jpeg','image/png','image/webp','image/gif',
    'video/mp4','video/webm','video/quicktime',
    'application/pdf','text/plain','text/csv','application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'audio/mpeg','audio/mp4','audio/aac','audio/ogg','audio/wav','audio/webm'
  ) THEN
    RAISE EXCEPTION 'Unsupported Agri Connect media MIME type' USING ERRCODE='23514';
  END IF;
  IF (NEW.file_type='image' AND NEW.mime_type NOT LIKE 'image/%')
     OR (NEW.file_type='video' AND NEW.mime_type NOT LIKE 'video/%')
     OR (NEW.file_type='audio' AND NEW.mime_type NOT LIKE 'audio/%')
     OR (NEW.file_type='document' AND NEW.mime_type NOT IN (
       'application/pdf','text/plain','text/csv','application/msword',
       'application/vnd.openxmlformats-officedocument.wordprocessingml.document')) THEN
    RAISE EXCEPTION 'Media MIME type does not match the declared file type' USING ERRCODE='23514';
  END IF;

  SELECT * INTO v_object FROM storage.objects
  WHERE bucket_id=NEW.bucket AND name=NEW.path;
  IF NOT FOUND OR (v_object.metadata->>'mimetype') IS DISTINCT FROM NEW.mime_type
     OR COALESCE((v_object.metadata->>'size')::bigint,(v_object.metadata->>'contentLength')::bigint) IS DISTINCT FROM NEW.size_bytes THEN
    RAISE EXCEPTION 'Agri Connect media metadata must match an uploaded Storage object' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "agri_connect"."guard_media_file_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."guard_media_file_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.context_type IN (
      'agri_connect_community','agri_connect_conversation',
      'agri_connect_communities','agri_connect_conversations',
      'agri_connect_discussion','agri_connect_post'
    ) THEN
      RAISE EXCEPTION 'Agri Connect media is detached/revoked through its context reference; physical deletion is not supported' USING ERRCODE='42501';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' AND (
    OLD.context_type IN (
      'agri_connect_community','agri_connect_conversation',
      'agri_connect_communities','agri_connect_conversations',
      'agri_connect_discussion','agri_connect_post'
    )
    OR NEW.context_type IN (
      'agri_connect_community','agri_connect_conversation',
      'agri_connect_communities','agri_connect_conversations',
      'agri_connect_discussion','agri_connect_post'
    )
  ) THEN
    IF OLD.context_type IN ('agri_connect_discussion','agri_connect_post')
       AND NEW.context_type = OLD.context_type
       AND OLD.is_deleted IS FALSE
       AND NEW.is_deleted IS TRUE
       AND (to_jsonb(NEW) - ARRAY['is_deleted'])
           IS NOT DISTINCT FROM (to_jsonb(OLD) - ARRAY['is_deleted']) THEN
      RETURN NEW;
    END IF;

    IF pg_trigger_depth() > 1
       AND OLD.context_type = 'agri_connect_community'
       AND NEW.context_type = OLD.context_type
       AND OLD.is_public IS TRUE
       AND NEW.is_public IS FALSE
       AND (to_jsonb(NEW) - ARRAY['is_public'])
           IS NOT DISTINCT FROM (to_jsonb(OLD) - ARRAY['is_public']) THEN
      RETURN NEW;
    END IF;

    RAISE EXCEPTION 'Agri Connect media metadata is immutable; upload a new file to replace media' USING ERRCODE='42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."guard_media_file_lifecycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."guard_message_media_reference"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE v_file media.files%ROWTYPE;
BEGIN
  IF NEW.media_file_id IS NULL THEN RETURN NEW; END IF;
  -- A soft-deleted message may retain its historical reference, but RLS read checks below revoke access.
  IF NEW.is_deleted IS TRUE THEN
    IF TG_OP='UPDATE' AND NEW.media_file_id IS NOT DISTINCT FROM OLD.media_file_id THEN RETURN NEW; END IF;
    RAISE EXCEPTION 'Deleted messages cannot acquire a media reference' USING ERRCODE='23514';
  END IF;
  IF NEW.message_type NOT IN ('image','video','document','audio')
     OR core.auth_user_id() IS NULL
     OR NOT agri_connect.messaging_has_active_identity(NEW.conversation_id)
     OR (NEW.sender_profile_id IS DISTINCT FROM agri_connect.current_profile_id()
         AND NEW.sender_entity_id IS DISTINCT FROM core.current_entity_id()) THEN
    RAISE EXCEPTION 'Only the authenticated message sender may attach media of the matching message type' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_file FROM media.files
  WHERE id=NEW.media_file_id AND bucket='media' AND is_deleted=false;
  IF NOT FOUND OR v_file.context_type IS DISTINCT FROM 'agri_connect_conversation'
     OR v_file.context_id IS DISTINCT FROM NEW.conversation_id
     OR v_file.created_by IS DISTINCT FROM agri_connect.current_profile_id()
     OR v_file.file_type IS DISTINCT FROM NEW.message_type
     OR v_file.is_public IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'Message media must be the caller''s file authorized for this conversation and message type' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."guard_message_media_reference"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."guard_message_reply_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE v_parent_conversation_id uuid;
BEGIN
  IF NEW.reply_to_message_id IS NOT NULL THEN
    SELECT m.conversation_id INTO v_parent_conversation_id
    FROM agri_connect.messages m WHERE m.id=NEW.reply_to_message_id;
    IF NOT FOUND OR v_parent_conversation_id IS DISTINCT FROM NEW.conversation_id THEN
      RAISE EXCEPTION 'reply target must belong to the same conversation' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."guard_message_reply_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."guard_moderation_action_target"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE v_valid boolean := false;
BEGIN
  IF core.auth_user_id() IS NULL
     OR NEW.moderator_profile_id IS DISTINCT FROM agri_connect.current_profile_id()
     OR NEW.community_id IS NULL
     OR NOT agri_connect.is_active_community_member(NEW.community_id, ARRAY['moderator','admin','owner']::text[]) THEN
    RAISE EXCEPTION 'moderation action requires an active community moderator' USING ERRCODE='42501';
  END IF;
  CASE NEW.target_type
    WHEN 'community' THEN
      SELECT EXISTS (SELECT 1 FROM agri_connect.communities c WHERE c.id=NEW.target_id AND c.id=NEW.community_id) INTO v_valid;
    WHEN 'discussion' THEN
      SELECT EXISTS (SELECT 1 FROM agri_connect.discussions d WHERE d.id=NEW.target_id AND d.community_id=NEW.community_id) INTO v_valid;
    WHEN 'post' THEN
      SELECT EXISTS (SELECT 1 FROM agri_connect.posts p JOIN agri_connect.discussions d ON d.id=p.discussion_id WHERE p.id=NEW.target_id AND d.community_id=NEW.community_id) INTO v_valid;
    WHEN 'message' THEN
      SELECT EXISTS (SELECT 1 FROM agri_connect.messages m JOIN agri_connect.conversations c ON c.id=m.conversation_id WHERE m.id=NEW.target_id AND c.community_id=NEW.community_id) INTO v_valid;
    WHEN 'announcement' THEN
      SELECT EXISTS (SELECT 1 FROM agri_connect.announcements a WHERE a.id=NEW.target_id AND a.community_id=NEW.community_id) INTO v_valid;
    WHEN 'profile' THEN
      SELECT EXISTS (SELECT 1 FROM agri_connect.community_members cm WHERE cm.community_id=NEW.community_id AND cm.profile_id=NEW.target_id AND cm.status='active') INTO v_valid;
    ELSE v_valid := false;
  END CASE;
  IF NOT v_valid THEN
    RAISE EXCEPTION 'moderation target must exist in the action community; profile targets must be active community members' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."guard_moderation_action_target"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."guard_post_edit_metadata"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.body IS DISTINCT FROM OLD.body THEN
    NEW.is_edited := true;
    NEW.edited_at := statement_timestamp();
  ELSIF NEW.is_edited IS DISTINCT FROM OLD.is_edited
     OR NEW.edited_at IS DISTINCT FROM OLD.edited_at THEN
    RAISE EXCEPTION 'post edit metadata is maintained by the database' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END;
$$;


