BEGIN
  IF TG_OP = 'UPDATE' AND (
    NEW.id IS DISTINCT FROM OLD.id OR
    NEW.post_id IS DISTINCT FROM OLD.post_id OR
    NEW.profile_id IS DISTINCT FROM OLD.profile_id
  ) THEN
    RAISE EXCEPTION 'reaction identity, owner, and post are immutable' USING ERRCODE = '23514';
  END IF;
