END;
$$;


ALTER FUNCTION "agri_connect"."guard_post_reaction_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."guard_post_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_parent_discussion_id uuid;
  v_discussion agri_connect.discussions%ROWTYPE;
  v_profile_id uuid;
  v_is_moderator boolean := false;
BEGIN
  IF TG_OP = 'UPDATE' AND (
    NEW.id IS DISTINCT FROM OLD.id OR
    NEW.discussion_id IS DISTINCT FROM OLD.discussion_id OR
    NEW.author_profile_id IS DISTINCT FROM OLD.author_profile_id OR
    NEW.parent_post_id IS DISTINCT FROM OLD.parent_post_id OR
    NEW.created_at IS DISTINCT FROM OLD.created_at
  ) THEN
    RAISE EXCEPTION 'post identity, author, discussion, parent, and creation time are immutable' USING ERRCODE='42501';
  END IF;

  IF TG_OP = 'UPDATE' AND core.auth_user_id() IS NOT NULL THEN
    v_profile_id := agri_connect.current_profile_id();
    IF OLD.author_profile_id = v_profile_id THEN
      SELECT * INTO v_discussion
      FROM agri_connect.discussions d
      WHERE d.id = OLD.discussion_id;

      v_is_moderator := v_discussion.community_id IS NOT NULL
        AND agri_connect.is_active_community_member(
          v_discussion.community_id, ARRAY['moderator','admin','owner']::text[]
        );

      IF NOT v_is_moderator THEN
        IF v_discussion.id IS NULL OR v_discussion.is_active IS NOT TRUE
           OR v_discussion.is_locked IS TRUE OR OLD.is_deleted IS TRUE
           OR NEW.is_deleted IS DISTINCT FROM OLD.is_deleted
           OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
           OR NEW.is_edited IS DISTINCT FROM OLD.is_edited
           OR NEW.edited_at IS DISTINCT FROM OLD.edited_at THEN
          RAISE EXCEPTION 'authors may edit only non-deleted posts in active, unlocked discussions' USING ERRCODE='42501';
        END IF;

        IF NEW.body IS DISTINCT FROM OLD.body THEN
          NEW.is_edited := true;
          NEW.edited_at := statement_timestamp();
        END IF;
      ELSIF NEW.body IS DISTINCT FROM OLD.body THEN
        NEW.is_edited := true;
        NEW.edited_at := statement_timestamp();
      END IF;
    END IF;
  END IF;

  IF NEW.parent_post_id IS NOT NULL THEN
    SELECT p.discussion_id INTO v_parent_discussion_id
    FROM agri_connect.posts AS p
    WHERE p.id = NEW.parent_post_id;
    IF FOUND AND v_parent_discussion_id IS DISTINCT FROM NEW.discussion_id THEN
      RAISE EXCEPTION 'parent post must belong to the same discussion' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."guard_post_scope"() OWNER TO "postgres";


