CREATE OR REPLACE FUNCTION "agri_connect"."join_or_rejoin_community"("p_community_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_profile_id uuid;
  v_membership agri_connect.community_members%ROWTYPE;
  v_community_created_by uuid;
BEGIN
  IF core.auth_user_id() IS NULL THEN
    RAISE EXCEPTION 'joining a community requires authentication' USING ERRCODE = '42501';
  END IF;

  v_profile_id := agri_connect.current_profile_id();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'joining a community requires an active profile' USING ERRCODE = '42501';
  END IF;

  SELECT c.created_by
  INTO v_community_created_by
  FROM agri_connect.communities c
  WHERE c.id = p_community_id AND c.is_active IS TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'community does not exist or is inactive' USING ERRCODE = 'P0002';
  END IF;

  SELECT cm.*
  INTO v_membership
  FROM agri_connect.community_members cm
  WHERE cm.community_id = p_community_id AND cm.profile_id = v_profile_id
  FOR UPDATE;

  IF FOUND THEN
    IF v_membership.status = 'active' THEN
      RETURN jsonb_build_object('community_id', p_community_id, 'status', 'active', 'role', v_membership.role);
    ELSIF v_membership.status = 'pending' THEN
      RETURN jsonb_build_object('community_id', p_community_id, 'status', 'pending', 'role', v_membership.role);
    ELSIF v_membership.status <> 'left' THEN
      RAISE EXCEPTION 'membership cannot be rejoined from status %', v_membership.status USING ERRCODE = '42501';
    END IF;

    IF v_membership.role = 'owner' AND v_community_created_by = v_profile_id THEN
      UPDATE agri_connect.community_members
      SET status = 'active', joined_at = statement_timestamp(), updated_at = statement_timestamp()
      WHERE id = v_membership.id;
      RETURN jsonb_build_object('community_id', p_community_id, 'status', 'active', 'role', 'owner');
    ELSE
      UPDATE agri_connect.community_members
      SET role = 'member', status = 'pending', joined_at = NULL,
          invited_by = NULL, approved_by = NULL, approved_at = NULL,
          updated_at = statement_timestamp()
      WHERE id = v_membership.id;
      RETURN jsonb_build_object('community_id', p_community_id, 'status', 'pending', 'role', 'member');
    END IF;
  END IF;

  INSERT INTO agri_connect.community_members (community_id, profile_id, role, status)
  VALUES (p_community_id, v_profile_id, 'member', 'pending');

  RETURN jsonb_build_object('community_id', p_community_id, 'status', 'pending', 'role', 'member');
END;
$$;


ALTER FUNCTION "agri_connect"."join_or_rejoin_community"("p_community_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."mark_duplicate_discussion_view"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_identity_key text;
BEGIN
  IF NEW.invalidated_at IS NOT NULL THEN
    RETURN NEW;
  END IF;

  v_identity_key := NEW.discussion_id::text || ':'
    || COALESCE(NEW.profile_id::text, '<null>') || ':'
    || COALESCE(NEW.entity_id::text, '<null>');

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_identity_key, 0)
  );

  IF EXISTS (
    SELECT 1
    FROM agri_connect.discussion_views AS existing
    WHERE existing.discussion_id = NEW.discussion_id
      AND existing.profile_id IS NOT DISTINCT FROM NEW.profile_id
      AND existing.entity_id IS NOT DISTINCT FROM NEW.entity_id
      AND existing.invalidated_at IS NULL
  ) THEN
    NEW.invalidated_at := statement_timestamp();
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."mark_duplicate_discussion_view"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."messages_last_message_at_trg"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_conversation_id uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_conversation_id := NEW.conversation_id;

    -- only consider non-deleted
    IF NEW.is_deleted = false THEN
      UPDATE agri_connect.conversations c
      SET last_message_at = GREATEST(
        COALESCE(c.last_message_at, '-infinity'::timestamptz),
        NEW.created_at
      )
      WHERE c.id = v_conversation_id;
    END IF;
    RETURN NEW;

  ELSIF TG_OP = 'UPDATE' THEN
    -- if message moved conversations, we must recompute both
    IF NEW.conversation_id IS DISTINCT FROM OLD.conversation_id THEN
      UPDATE agri_connect.conversations c
      SET last_message_at = (
        SELECT MAX(m.created_at)
        FROM agri_connect.messages m
        WHERE m.conversation_id = OLD.conversation_id
          AND m.is_deleted = false
      )
      WHERE c.id = OLD.conversation_id;

      UPDATE agri_connect.conversations c
      SET last_message_at = (
        SELECT MAX(m.created_at)
        FROM agri_connect.messages m
        WHERE m.conversation_id = NEW.conversation_id
          AND m.is_deleted = false
      )
      WHERE c.id = NEW.conversation_id;

      RETURN NEW;
    END IF;

    -- same conversation: if is_deleted status changes, or created_at changes, recompute
    IF NEW.is_deleted IS DISTINCT FROM OLD.is_deleted
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      UPDATE agri_connect.conversations c
      SET last_message_at = (
        SELECT MAX(m.created_at)
        FROM agri_connect.messages m
        WHERE m.conversation_id = NEW.conversation_id
          AND m.is_deleted = false
      )
      WHERE c.id = NEW.conversation_id;
    END IF;

    RETURN NEW;

  ELSIF TG_OP = 'DELETE' THEN
    v_conversation_id := OLD.conversation_id;
    UPDATE agri_connect.conversations c
    SET last_message_at = (
      SELECT MAX(m.created_at)
      FROM agri_connect.messages m
      WHERE m.conversation_id = v_conversation_id
        AND m.is_deleted = false
    )
    WHERE c.id = v_conversation_id;

    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "agri_connect"."messages_last_message_at_trg"() OWNER TO "postgres";


