CREATE OR REPLACE FUNCTION "agri_connect"."messaging_guard_participant_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_is_self boolean;
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.conversation_id IS DISTINCT FROM OLD.conversation_id
     OR NEW.profile_id IS DISTINCT FROM OLD.profile_id
     OR NEW.entity_id IS DISTINCT FROM OLD.entity_id
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'participant identity and conversation scope are immutable' USING ERRCODE = '42501';
  END IF;

  v_is_self :=
    (OLD.profile_id IS NOT NULL AND OLD.profile_id = agri_connect.current_profile_id())
    OR (OLD.entity_id IS NOT NULL AND OLD.entity_id = core.current_entity_id());

  IF v_is_self THEN
    IF NEW.role IS DISTINCT FROM OLD.role THEN
      RAISE EXCEPTION 'participants cannot change their own role' USING ERRCODE = '42501';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
      (OLD.status = 'invited' AND NEW.status = 'active' AND NEW.joined_at IS NOT NULL)
      OR (OLD.status = 'active' AND NEW.status = 'left')
    ) THEN
      RAISE EXCEPTION 'invalid self-service participant status transition' USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
      (OLD.status = 'invited' AND NEW.status = ANY (ARRAY['active','removed','blocked']::text[]))
      OR (OLD.status = 'active' AND NEW.status = ANY (ARRAY['removed','blocked']::text[]))
    ) THEN
      RAISE EXCEPTION 'invalid manager participant status transition' USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."messaging_guard_participant_update"() OWNER TO "postgres";


