CREATE OR REPLACE FUNCTION "agri_connect"."posts_reply_count_trg"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_discussion_id uuid;
  v_old_qual boolean;
  v_new_qual boolean;
  v_delta int := 0;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_discussion_id := NEW.discussion_id;
    v_new_qual := (NEW.is_deleted = false);
    v_delta := CASE WHEN v_new_qual THEN 1 ELSE 0 END;

  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.discussion_id IS DISTINCT FROM OLD.discussion_id THEN
      v_old_qual := (OLD.is_deleted = false);
      IF v_old_qual THEN
        UPDATE agri_connect.discussions
        SET reply_count = reply_count - 1
        WHERE id = OLD.discussion_id;
      END IF;

      v_new_qual := (NEW.is_deleted = false);
      IF v_new_qual THEN
        UPDATE agri_connect.discussions
        SET reply_count = reply_count + 1
        WHERE id = NEW.discussion_id;
      END IF;
      RETURN NEW;
    END IF;

    v_discussion_id := NEW.discussion_id;
    v_old_qual := (OLD.is_deleted = false);
    v_new_qual := (NEW.is_deleted = false);
    v_delta := (CASE WHEN v_new_qual THEN 1 ELSE 0 END)
             - (CASE WHEN v_old_qual THEN 1 ELSE 0 END);

  ELSIF TG_OP = 'DELETE' THEN
    v_discussion_id := OLD.discussion_id;
    v_old_qual := (OLD.is_deleted = false);
    v_delta := CASE WHEN v_old_qual THEN -1 ELSE 0 END;
  END IF;

  IF v_delta <> 0 THEN
    UPDATE agri_connect.discussions
    SET reply_count = reply_count + v_delta
    WHERE id = v_discussion_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."posts_reply_count_trg"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."release_post_media_upload"("p_post_id" "uuid", "p_file_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_profile_id uuid;
  v_upload agri_connect.post_media_uploads%ROWTYPE;
  v_has_relationship boolean;
  v_has_media_row boolean;
  v_has_storage_object boolean;
BEGIN
  IF p_post_id IS NULL OR p_file_id IS NULL
     OR core.auth_user_id() IS NULL
     OR agri_connect.current_profile_id() IS NULL THEN
    RAISE EXCEPTION 'Authentication, an active profile, and valid IDs are required' USING ERRCODE='42501';
  END IF;
  v_profile_id := agri_connect.current_profile_id();

  PERFORM 1
  FROM agri_connect.posts p
  WHERE p.id = p_post_id
  FOR UPDATE;

  SELECT * INTO v_upload
  FROM agri_connect.post_media_uploads u
  WHERE u.file_id = p_file_id
    AND u.post_id = p_post_id
    AND u.profile_id = v_profile_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Upload reservation not found for caller' USING ERRCODE='P0002';
  END IF;

  IF v_upload.status = 'attached' THEN
    RETURN jsonb_build_object(
      'released', false,
      'should_remove_storage', false,
      'storage_retained', true,
      'status', 'attached',
      'path', v_upload.path
    );
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM agri_connect.post_media pm WHERE pm.media_file_id = p_file_id
  ) INTO v_has_relationship;
  SELECT EXISTS (
    SELECT 1 FROM media.files f WHERE f.id = p_file_id
  ) INTO v_has_media_row;
  SELECT EXISTS (
    SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'media' AND o.name = v_upload.path
  ) INTO v_has_storage_object;

  IF v_upload.status = 'reserved' THEN
    UPDATE agri_connect.post_media_uploads
    SET status = 'aborted', finished_at = clock_timestamp()
    WHERE file_id = p_file_id AND status = 'reserved';
  END IF;

  RETURN jsonb_build_object(
    'released', v_upload.status <> 'aborted',
    'should_remove_storage', NOT v_has_relationship AND NOT v_has_media_row AND v_has_storage_object,
    'storage_retained', v_has_relationship OR v_has_media_row OR NOT v_has_storage_object,
    'status', 'aborted',
    'path', v_upload.path
  );
END;
$$;


ALTER FUNCTION "agri_connect"."release_post_media_upload"("p_post_id" "uuid", "p_file_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."remove_post_media"("p_post_id" "uuid", "p_file_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_file media.files%ROWTYPE;
  v_post agri_connect.posts%ROWTYPE;
  v_remaining integer;
  v_detached integer;
  v_marked_deleted boolean := false;
BEGIN
  IF p_post_id IS NULL OR p_file_id IS NULL
     OR core.auth_user_id() IS NULL
     OR agri_connect.current_profile_id() IS NULL THEN
    RAISE EXCEPTION 'Authentication, an active profile, and valid IDs are required' USING ERRCODE='42501';
  END IF;

  SELECT * INTO v_post
  FROM agri_connect.posts p
  WHERE p.id = p_post_id
  FOR UPDATE;
  IF NOT FOUND OR NOT agri_connect.can_manage_post_media(p_post_id) THEN
    RAISE EXCEPTION 'Caller cannot remove media from this post' USING ERRCODE='42501';
  END IF;

  SELECT * INTO v_file
  FROM media.files f
  WHERE f.id = p_file_id
    AND f.context_type = 'agri_connect_post'
    AND f.is_deleted IS FALSE
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Post media not found' USING ERRCODE='P0002';
  END IF;

  DELETE FROM agri_connect.post_media pm
  WHERE pm.post_id = p_post_id
    AND pm.media_file_id = p_file_id;
  GET DIAGNOSTICS v_detached = ROW_COUNT;
  IF v_detached = 0 THEN
    RAISE EXCEPTION 'Media is not attached to this post' USING ERRCODE='42501';
  END IF;

  SELECT count(*)::integer INTO v_remaining
  FROM agri_connect.post_media pm
  WHERE pm.media_file_id = p_file_id;
  IF v_remaining = 0 THEN
    UPDATE media.files
    SET is_deleted = true
    WHERE id = p_file_id AND is_deleted IS FALSE;
    v_marked_deleted := FOUND;
    IF v_marked_deleted THEN
      INSERT INTO media.file_events (file_id, event_type, entity_id, context_id)
      VALUES (p_file_id, 'delete', v_file.entity_id, v_file.context_id);
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'post_id', p_post_id,
    'file_id', p_file_id,
    'media_marked_deleted', v_marked_deleted,
    'storage_retained', true
  );
END;
$$;


ALTER FUNCTION "agri_connect"."remove_post_media"("p_post_id" "uuid", "p_file_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."report_target_community_id"("p_target_type" "text", "p_target_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
select
  case p_target_type
    when 'community' then p_target_id
    when 'discussion' then (select d.community_id from agri_connect.discussions d where d.id = p_target_id)
    when 'post' then (
      select d.community_id
      from agri_connect.posts p
      join agri_connect.discussions d on d.id = p.discussion_id
      where p.id = p_target_id
    )
    when 'message' then (
      select c.id
      from agri_connect.messages m
      join agri_connect.conversations conv on conv.id = m.conversation_id
      join agri_connect.communities c on c.id = conv.community_id
      where m.id = p_target_id
    )
    when 'announcement' then (select a.community_id from agri_connect.announcements a where a.id = p_target_id)
    else null
  end;
$$;


ALTER FUNCTION "agri_connect"."report_target_community_id"("p_target_type" "text", "p_target_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."reserve_post_media_upload"("p_post_id" "uuid", "p_file_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_profile_id uuid;
  v_post agri_connect.posts%ROWTYPE;
  v_existing agri_connect.post_media_uploads%ROWTYPE;
  v_count integer;
  v_path text;
BEGIN
  IF p_post_id IS NULL OR p_file_id IS NULL
     OR core.auth_user_id() IS NULL
     OR agri_connect.current_profile_id() IS NULL THEN
    RAISE EXCEPTION 'Authentication, an active profile, and valid IDs are required' USING ERRCODE='42501';
  END IF;
  v_profile_id := agri_connect.current_profile_id();

  SELECT * INTO v_post
  FROM agri_connect.posts p
  WHERE p.id = p_post_id
  FOR UPDATE;
  IF NOT FOUND OR NOT agri_connect.can_manage_post_media(p_post_id) THEN
    RAISE EXCEPTION 'Caller cannot attach media to this post' USING ERRCODE='42501';
  END IF;

  SELECT * INTO v_existing
  FROM agri_connect.post_media_uploads u
  WHERE u.file_id = p_file_id
  FOR UPDATE;
  IF FOUND THEN
    IF v_existing.post_id = p_post_id
       AND v_existing.profile_id = v_profile_id
       AND v_existing.status = 'reserved'
       AND v_existing.expires_at > clock_timestamp() THEN
      RETURN jsonb_build_object('file_id', p_file_id, 'path', v_existing.path, 'status', 'reserved');
    END IF;
    RAISE EXCEPTION 'Upload ID is already reserved or consumed' USING ERRCODE='23505';
  END IF;

  SELECT (
    (SELECT count(*) FROM agri_connect.post_media pm WHERE pm.post_id = p_post_id)
    +
    (SELECT count(*) FROM agri_connect.post_media_uploads u
      WHERE u.post_id = p_post_id
        AND u.status = 'reserved'
        AND u.expires_at > clock_timestamp())
  )::integer INTO v_count;
  IF v_count >= 2 THEN
    RAISE EXCEPTION 'A post can have at most 2 images' USING ERRCODE='23514';
  END IF;

  v_path := 'images/agri_connect/posts/' || p_post_id::text || '/' || p_file_id::text || '.webp';
  INSERT INTO agri_connect.post_media_uploads (
    file_id, post_id, profile_id, path, status, expires_at
  ) VALUES (
    p_file_id, p_post_id, v_profile_id, v_path, 'reserved', clock_timestamp() + interval '15 minutes'
  );

  RETURN jsonb_build_object('file_id', p_file_id, 'path', v_path, 'status', 'reserved');
END;
$$;


ALTER FUNCTION "agri_connect"."reserve_post_media_upload"("p_post_id" "uuid", "p_file_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."set_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "agri_connect"."set_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "agri_connect"."sync_community_membership_from_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_actor_profile_id uuid;
  v_invited_profile_id uuid;
  v_membership_status text;
BEGIN
  v_actor_profile_id := agri_connect.current_profile_id();

  IF TG_TABLE_NAME = 'community_join_requests' THEN
    IF OLD.status IS DISTINCT FROM 'pending' OR NEW.status IS DISTINCT FROM 'approved' THEN
      RETURN NEW;
    END IF;
    IF core.auth_user_id() IS NULL
       OR NEW.reviewed_by IS DISTINCT FROM v_actor_profile_id
       OR NOT agri_connect.is_active_community_member(NEW.community_id, ARRAY['admin','owner']::text[]) THEN
      RAISE EXCEPTION 'request approval requires an authorized community manager as reviewer' USING ERRCODE = '42501';
    END IF;

    INSERT INTO agri_connect.community_members
      (community_id, profile_id, role, status, joined_at, approved_by, approved_at)
    VALUES
      (NEW.community_id, NEW.profile_id, 'member', 'active', NEW.reviewed_at, NEW.reviewed_by, NEW.reviewed_at)
    ON CONFLICT (community_id, profile_id) DO UPDATE
      SET status = 'active',
          joined_at = EXCLUDED.joined_at,
          approved_by = EXCLUDED.approved_by,
          approved_at = EXCLUDED.approved_at
      WHERE agri_connect.community_members.status = 'pending'
        AND agri_connect.community_members.role = 'member';

    SELECT status INTO v_membership_status
    FROM agri_connect.community_members
    WHERE community_id = NEW.community_id AND profile_id = NEW.profile_id;

    IF v_membership_status IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION 'request cannot be approved while the existing membership is not pending-member or active' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = 'community_invitations' THEN
    IF OLD.status IS DISTINCT FROM 'pending' OR NEW.status IS DISTINCT FROM 'accepted' THEN
      RETURN NEW;
    END IF;
    IF core.auth_user_id() IS NULL OR v_actor_profile_id IS NULL THEN
      RAISE EXCEPTION 'invitation acceptance requires an authenticated profile' USING ERRCODE = '42501';
    END IF;

    IF NEW.invited_profile_id IS NULL THEN
      IF NOT agri_connect.current_user_has_verified_email(NEW.invited_email) THEN
        RAISE EXCEPTION 'email invitation acceptance requires its verified-email owner' USING ERRCODE = '42501';
      END IF;
      v_invited_profile_id := v_actor_profile_id;
    ELSE
      IF NEW.invited_profile_id IS DISTINCT FROM v_actor_profile_id THEN
        RAISE EXCEPTION 'only the addressed profile may accept an invitation' USING ERRCODE = '42501';
      END IF;
      v_invited_profile_id := NEW.invited_profile_id;
    END IF;

    INSERT INTO agri_connect.community_members
      (community_id, profile_id, role, status, joined_at, invited_by)
    VALUES
      (NEW.community_id, v_invited_profile_id, 'member', 'active', COALESCE(NEW.accepted_at, statement_timestamp()), NEW.invited_by)
    ON CONFLICT (community_id, profile_id) DO UPDATE
      SET status = 'active',
          joined_at = EXCLUDED.joined_at,
          invited_by = EXCLUDED.invited_by
      WHERE agri_connect.community_members.status = 'pending'
        AND agri_connect.community_members.role = 'member';

    SELECT status INTO v_membership_status
    FROM agri_connect.community_members
    WHERE community_id = NEW.community_id AND profile_id = v_invited_profile_id;

    IF v_membership_status IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION 'invitation cannot be accepted while the existing membership is not pending-member or active' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'unexpected lifecycle trigger table' USING ERRCODE = '42501';
END;
$$;


ALTER FUNCTION "agri_connect"."sync_community_membership_from_lifecycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."accept_entity_invitation"("p_invite_id" "uuid", "p_token" "text", "p_profile_id" "uuid") RETURNS TABLE("entity_role_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'commerce', 'core', 'users'
    AS $$
DECLARE
  v_inv core.entity_invitations%ROWTYPE;
  v_profile users.profiles%ROWTYPE;
  v_entity core.entities%ROWTYPE;
  v_role core.user_roles%ROWTYPE;
  v_role_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  SELECT p.*
    INTO v_profile
  FROM users.profiles AS p
  WHERE p.id = p_profile_id
    AND p.auth_user_id = auth.uid()
    AND p.is_active = true
    AND p.account_status = 'active';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile is not the authenticated user' USING ERRCODE = '42501';
  END IF;

  SELECT i.*
    INTO v_inv
  FROM core.entity_invitations AS i
  WHERE i.id = p_invite_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invitation not found';
  END IF;
  IF v_inv.accepted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Invitation already accepted';
  END IF;
  IF v_inv.expires_at IS NOT NULL AND v_inv.expires_at <= now() THEN
    RAISE EXCEPTION 'Invitation expired';
  END IF;
  IF v_inv.invite_token IS DISTINCT FROM p_token THEN
    RAISE EXCEPTION 'Invalid token';
  END IF;
  IF lower(btrim(v_inv.email)) IS DISTINCT FROM lower(btrim(v_profile.email)) THEN
    RAISE EXCEPTION 'Invitation is not addressed to the authenticated profile' USING ERRCODE = '42501';
  END IF;

  SELECT e.*
    INTO v_entity
  FROM core.entities AS e
  WHERE e.id = v_inv.entity_id
    AND e.is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invitation entity is not active';
  END IF;

  SELECT r.*
    INTO v_role
  FROM core.user_roles AS r
  WHERE r.id = v_inv.role_id
    AND r.is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invitation role is not active';
  END IF;

  INSERT INTO core.entity_roles (profile_id, entity_id, role_id, assigned_by, is_active, updated_at)
  VALUES (v_profile.id, v_inv.entity_id, v_inv.role_id, v_profile.id, true, now())
  ON CONFLICT (profile_id, entity_id, role_id)
  DO UPDATE SET is_active = true, assigned_by = v_profile.id, updated_at = now()
  RETURNING id INTO v_role_id;

  INSERT INTO core.entity_members (entity_id, profile_id, role_id, is_active, membership_status)
  VALUES (v_inv.entity_id, v_profile.id, v_inv.role_id, true, 'active')
  ON CONFLICT (entity_id, profile_id)
  DO UPDATE SET role_id = EXCLUDED.role_id,
                is_active = true,
                membership_status = 'active';

  UPDATE core.entity_invitations
  SET accepted_at = now()
  WHERE id = p_invite_id;

  RETURN QUERY SELECT v_role_id;
END;
$$;


ALTER FUNCTION "commerce"."accept_entity_invitation"("p_invite_id" "uuid", "p_token" "text", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."add_owner_entity_role"("p_entity_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'core', 'users'
    AS $$
declare
  v_profile_id uuid := (
    select p.id
    from users.profiles p
    where p.auth_user_id = auth.uid()
    limit 1
  );
  v_role_id uuid;
begin
  if v_profile_id is null then
    raise exception 'Authenticated user profile not found';
  end if;

  select id into v_role_id
  from core.user_roles
  where lower(name) = 'owner' and is_active = true
  order by name
  limit 1;

  if v_role_id is null then
    raise exception 'Active owner role not found';
  end if;

  insert into core.entity_roles (profile_id, entity_id, role_id, assigned_by, is_active)
  select v_profile_id, p_entity_id, v_role_id, v_profile_id, true
  where not exists (
    select 1 from core.entity_roles
    where entity_id = p_entity_id
      and profile_id = v_profile_id
      and is_active = true
  );

  insert into core.entity_members (entity_id, profile_id, role_id, can_manage, membership_status, is_active)
  select p_entity_id, v_profile_id, v_role_id, true, 'active', true
  where not exists (
    select 1 from core.entity_members
    where entity_id = p_entity_id
      and profile_id = v_profile_id
      and is_active = true
      and membership_status = 'active'
  );
end;
$$;


ALTER FUNCTION "commerce"."add_owner_entity_role"("p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."apply_stock_movement"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.movement_type IN ('harvest', 'purchase', 'adjustment', 'sale') THEN
    UPDATE commerce.stock_registry
    SET quantity = quantity + NEW.quantity_change,
        updated_at = now()
    WHERE id = NEW.stock_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "commerce"."apply_stock_movement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."apply_stock_movement"("evt" "commerce"."stock_event_type") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
    BEGIN

      -- 1. Insert immutable ledger entry
        INSERT INTO commerce.stock_movements (
            stock_id,
                quantity_change,
                    movement_type,
                        source_module,
                            source_type,
                                source_ref_id,
                                    order_id,
                                        trade_type,
                                            destination_location_id,
                                                metadata
                                                  )
                                                    VALUES (
                                                        evt.stock_id,
                                                            evt.quantity_change,
                                                                evt.movement_type,
                                                                    evt.source_module,
                                                                        evt.source_type,
                                                                            evt.source_ref_id,
                                                                                evt.order_id,
                                                                                    evt.trade_type,
                                                                                        evt.destination_location_id,
                                                                                            evt.metadata
                                                                                              );

                                                                                                -- 2. Update stock balance ONLY HERE
                                                                                                  UPDATE commerce.stock_registry
                                                                                                    SET
                                                                                                        quantity = GREATEST(quantity + evt.quantity_change, 0),
                                                                                                            updated_at = now()
                                                                                                              WHERE id = evt.stock_id;

                                                                                                              END;
                                                                                                              $$;


ALTER FUNCTION "commerce"."apply_stock_movement"("evt" "commerce"."stock_event_type") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."can_access_stock"("p_entity_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'commerce', 'core', 'users'
    AS $$
  SELECT
    auth.uid() IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM core.entities e
      JOIN users.profiles p
        ON p.auth_user_id = auth.uid()
      WHERE e.id = p_entity_id
        AND (
          e.owner_id = p.id
          OR EXISTS (
            SELECT 1
            FROM core.entity_roles er
            WHERE er.entity_id = p_entity_id
              AND er.profile_id = p.id
              AND er.is_active = true
          )
          OR EXISTS (
            SELECT 1
            FROM core.entity_members em
            WHERE em.entity_id = p_entity_id
              AND em.profile_id = p.id
              AND em.is_active = true
              AND em.membership_status = 'active'
              AND (em.can_manage = true OR em.can_sell = true)
          )
        )
    );
$$;


ALTER FUNCTION "commerce"."can_access_stock"("p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."complete_order_payment"("p_order_id" "uuid", "p_transaction_ref" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
      DECLARE
        v_stock_id uuid;
          v_reserved_qty numeric;
            v_current_qty numeric;
              v_supplier_id uuid;
              BEGIN

                -- Prevent double processing
                  IF (SELECT payment_status FROM commerce.orders WHERE id = p_order_id) = 'completed' THEN
                      RETURN;
                        END IF;

                          -- Lock order
                            UPDATE commerce.orders
                              SET payment_status = 'completed',
                                    status = 'confirmed',
                                          updated_at = now()
                                            WHERE id = p_order_id;

                                              -- Get reservation + lock stock
                                                SELECT 
                                                    r.stock_id,
                                                        r.quantity,
                                                            sr.quantity
                                                              INTO 
                                                                  v_stock_id,
                                                                      v_reserved_qty,
                                                                          v_current_qty
                                                                            FROM commerce.stock_reservations r
                                                                              JOIN commerce.stock_registry sr ON sr.id = r.stock_id
                                                                                WHERE r.order_id = p_order_id
                                                                                  FOR UPDATE;

                                                                                    IF v_stock_id IS NULL THEN
                                                                                        RAISE EXCEPTION 'No reservation found for order';
                                                                                          END IF;

                                                                                            -- Safety check
                                                                                              IF v_current_qty < v_reserved_qty THEN
                                                                                                  RAISE EXCEPTION 'Stock inconsistency detected';
                                                                                                    END IF;

                                                                                                      -- Deduct stock
                                                                                                        UPDATE commerce.stock_registry
                                                                                                          SET quantity = quantity - v_reserved_qty,
                                                                                                                reserved_quantity = reserved_quantity - v_reserved_qty,
                                                                                                                      updated_at = now()
                                                                                                                        WHERE id = v_stock_id;

                                                                                                                          -- Record stock movement
                                                                                                                            INSERT INTO commerce.stock_movements (
                                                                                                                                stock_id,
                                                                                                                                    quantity_change,
                                                                                                                                        movement_type,
                                                                                                                                            source_module,
                                                                                                                                                source_type,
                                                                                                                                                    source_ref_id,
                                                                                                                                                        order_id,
                                                                                                                                                            entity_id
                                                                                                                                                              )
                                                                                                                                                                VALUES (
                                                                                                                                                                    v_stock_id,
                                                                                                                                                                        -v_reserved_qty,
                                                                                                                                                                            'sale',
                                                                                                                                                                                'marketplace',
                                                                                                                                                                                    'order',
                                                                                                                                                                                        p_order_id,
                                                                                                                                                                                            p_order_id,
                                                                                                                                                                                                (SELECT entity_id FROM commerce.orders WHERE id = p_order_id)
                                                                                                                                                                                                  );

                                                                                                                                                                                                    -- Record payment
                                                                                                                                                                                                      INSERT INTO commerce.transactions (
                                                                                                                                                                                                          order_id,
                                                                                                                                                                                                              supplier_id,
                                                                                                                                                                                                                  amount,
                                                                                                                                                                                                                      currency,
                                                                                                                                                                                                                          payment_method,
                                                                                                                                                                                                                              payment_status,
                                                                                                                                                                                                                                  transaction_id,
                                                                                                                                                                                                                                      recorded_by
                                                                                                                                                                                                                                        )
                                                                                                                                                                                                                                          SELECT
                                                                                                                                                                                                                                              o.id,
                                                                                                                                                                                                                                                  o.supplier_id,
                                                                                                                                                                                                                                                      o.total_amount,
                                                                                                                                                                                                                                                          'KES',
                                                                                                                                                                                                                                                              'mpesa',
                                                                                                                                                                                                                                                                  'completed',
                                                                                                                                                                                                                                                                      p_transaction_ref,
                                                                                                                                                                                                                                                                          'system'
                                                                                                                                                                                                                                                                            FROM commerce.orders o
                                                                                                                                                                                                                                                                              WHERE o.id = p_order_id;

                                                                                                                                                                                                                                                                                -- Remove reservation
                                                                                                                                                                                                                                                                                  DELETE FROM commerce.stock_reservations
                                                                                                                                                                                                                                                                                    WHERE order_id = p_order_id;

                                                                                                                                                                                                                                                                                    END;
                                                                                                                                                                                                                                                                                    $$;


ALTER FUNCTION "commerce"."complete_order_payment"("p_order_id" "uuid", "p_transaction_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."complete_service_order_payment"("p_order_id" "uuid", "p_transaction_ref" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_order commerce.orders%rowtype;
  v_tx_exists boolean;
  v_payment_amount numeric;
  v_payment_currency text;
  v_payment_method text;
  v_payment_supplier_id uuid;
  v_buyer_id uuid;
begin
  select * into v_order
  from commerce.orders
  where id = p_order_id
  for update;

  if v_order.id is null then
    raise exception 'Order not found: %', p_order_id;
  end if;

  if v_order.order_kind <> 'service' then
    raise exception 'Order is not a service order: %', p_order_id;
  end if;

  if v_order.payment_status = 'completed' then
    return;
  end if;

  if v_order.payment_status not in ('pending','failed') then
    raise exception 'Order payment_status is not eligible: %, status=%', p_order_id, v_order.payment_status;
  end if;

  -- Idempotency: don't create duplicate transaction records
  select exists(
    select 1
    from commerce.transactions t
    where t.order_id = p_order_id
      and t.transaction_id = p_transaction_ref
  ) into v_tx_exists;

  if not v_tx_exists then
    v_payment_amount := v_order.total_amount;
    v_payment_currency := 'KES';
    v_payment_method := 'mpesa';
    v_payment_supplier_id := v_order.supplier_id;
    v_buyer_id := v_order.buyer_id;

    insert into commerce.transactions (
      id,
      order_id,
      supplier_id,
      amount,
      currency,
      payment_method,
      payment_status,
      transaction_id,
      recorded_by,
      profile_id
    )
    values (
      uuid_generate_v7(),
      v_order.id,
      v_payment_supplier_id,
      v_payment_amount,
      v_payment_currency,
      v_payment_method,
      'completed',
      p_transaction_ref,
      'system',
      v_buyer_id
    );
  end if;

  update commerce.orders
    set payment_status = 'completed',
        status = 'confirmed',
        updated_at = now()
  where id = p_order_id
    and payment_status <> 'completed';

end;
$$;


ALTER FUNCTION "commerce"."complete_service_order_payment"("p_order_id" "uuid", "p_transaction_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."confirm_payment"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN

  UPDATE commerce.orders
    SET payment_status = 'completed',
          status = 'confirmed'
            WHERE id = p_order_id;

              UPDATE commerce.stock_reservations
                SET status = 'consumed'
                  WHERE order_id = p_order_id;

                    UPDATE commerce.stock_registry sr
                      SET quantity = quantity - (
                          SELECT quantity
                              FROM commerce.orders
                                  WHERE id = p_order_id
                                    )
                                      WHERE sr.id = (
                                          SELECT stock_id
                                              FROM commerce.stock_reservations
                                                  WHERE order_id = p_order_id
                                                    );

                                                    END;
                                                    $$;


ALTER FUNCTION "commerce"."confirm_payment"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."create_business_profile"("p_entity_id" "uuid", "p_profile" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("business_profile_id" "uuid", "entity_id" "uuid", "created" boolean, "already_exists" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'users', 'core', 'commerce'
    AS $$
#variable_conflict use_column
DECLARE
  v_profile_id uuid;
  v_business_profile commerce.business_profiles%ROWTYPE;
  v_entity core.entities%ROWTYPE;
  v_supplier_name text;
  v_entity_type text;
  v_contact_person text;
  v_phone text;
  v_email text;
  v_county_id uuid;
  v_subcounty_id uuid;
  v_ward_id uuid;
  v_physical_address text;
  v_business_reg_no text;
  v_kra_pin text;
  v_id_number text;
  v_license_no text;
  v_metadata jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  SELECT p.id INTO v_profile_id
  FROM users.profiles AS p
  WHERE p.auth_user_id = auth.uid()
    AND p.is_active = true
    AND p.account_status = 'active'
    AND p.deleted_at IS NULL;

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'active user profile not found' USING ERRCODE = '42501';
  END IF;

  SELECT e.* INTO v_entity
  FROM core.entities AS e
  WHERE e.id = p_entity_id
    AND e.is_active = true
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'target entity is invalid or inactive' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM core.entity_members AS em
    WHERE em.entity_id = p_entity_id
      AND em.profile_id = v_profile_id
      AND em.is_active = true
      AND em.membership_status = 'active'
      AND em.can_manage = true
  ) THEN
    RAISE EXCEPTION 'user is not an active manager of the target entity' USING ERRCODE = '42501';
  END IF;

  v_entity_type := coalesce(nullif(btrim(p_profile->>'entity_type'), ''), 'trader');
  IF v_entity_type NOT IN ('individual', 'company', 'agrovet', 'cooperative', 'trader') THEN
    RAISE EXCEPTION 'invalid business profile entity_type' USING ERRCODE = '22023';
  END IF;

  v_supplier_name := nullif(btrim(coalesce(p_profile->>'supplier_name', p_profile->>'business_name')), '');
  IF v_supplier_name IS NULL THEN
    RAISE EXCEPTION 'supplier_name is required';
  END IF;

  SELECT bp.* INTO v_business_profile
  FROM commerce.business_profiles AS bp
  WHERE bp.entity_id = p_entity_id
    AND bp.deleted_at IS NULL
    AND bp.is_active = true
  ORDER BY bp.created_at, bp.id
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    business_profile_id := v_business_profile.id;
    entity_id := v_business_profile.entity_id;
    created := false;
    already_exists := true;
    RETURN NEXT;
    RETURN;
  END IF;

  v_contact_person := nullif(btrim(p_profile->>'contact_person'), '');
  v_phone := nullif(btrim(p_profile->>'phone'), '');
  v_email := nullif(btrim(p_profile->>'email'), '');
  v_county_id := nullif(p_profile->>'county_id', '')::uuid;
  v_subcounty_id := nullif(coalesce(p_profile->>'subcounty_id', p_profile->>'sub_county_id'), '')::uuid;
  v_ward_id := nullif(p_profile->>'ward_id', '')::uuid;
  v_physical_address := nullif(btrim(p_profile->>'physical_address'), '');
  v_business_reg_no := nullif(btrim(p_profile->>'business_reg_no'), '');
  v_kra_pin := nullif(btrim(p_profile->>'kra_pin'), '');
  v_id_number := nullif(btrim(p_profile->>'id_number'), '');
  v_license_no := nullif(btrim(p_profile->>'license_no'), '');
  v_metadata := coalesce(p_profile->'metadata', '{}'::jsonb);

  INSERT INTO commerce.business_profiles (
    entity_type, primary_contact_id, supplier_name, contact_person, phone, email,
    county_id, subcounty_id, ward_id, physical_address, business_reg_no, kra_pin,
    id_number, license_no, metadata, entity_id, ownership_scope
  ) VALUES (
    v_entity_type, v_profile_id, v_supplier_name, v_contact_person, v_phone, v_email,
    v_county_id, v_subcounty_id, v_ward_id, v_physical_address, v_business_reg_no, v_kra_pin,
    v_id_number, v_license_no, v_metadata, p_entity_id, 'organizational'
  )
  ON CONFLICT (entity_id) WHERE deleted_at IS NULL AND is_active = true DO NOTHING
  RETURNING * INTO v_business_profile;

  IF NOT FOUND THEN
    SELECT bp.* INTO v_business_profile
    FROM commerce.business_profiles AS bp
    WHERE bp.entity_id = p_entity_id
      AND bp.deleted_at IS NULL
      AND bp.is_active = true
    ORDER BY bp.created_at, bp.id
    LIMIT 1;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'business profile creation did not produce a profile';
    END IF;
    business_profile_id := v_business_profile.id;
    entity_id := v_business_profile.entity_id;
    created := false;
    already_exists := true;
    RETURN NEXT;
    RETURN;
  END IF;

  UPDATE users.user_workspace_entity_contexts AS c
  SET business_profile_id = v_business_profile.id, updated_at = now()
  FROM users.user_workspaces AS uw
  WHERE c.user_workspace_id = uw.id
    AND uw.auth_user_id = auth.uid()
    AND c.entity_id = p_entity_id
    AND c.business_profile_id IS NULL
    AND c.is_active = true
    AND c.mode = 'trader';

  business_profile_id := v_business_profile.id;
  entity_id := v_business_profile.entity_id;
  created := true;
  already_exists := false;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "commerce"."create_business_profile"("p_entity_id" "uuid", "p_profile" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."create_farm_with_auto_entity"("farm_data" "jsonb") RETURNS TABLE("farm_id" "uuid", "entity_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'core', 'users', 'farm_management', 'commerce'
    AS $$
DECLARE
  v_user_id uuid;
  v_entity_id uuid;
  v_requested_entity_id uuid := nullif(farm_data->>'entity_id', '')::uuid;
  v_entity_count integer;
  v_farm_id uuid;
  v_farm_name text := coalesce(nullif(farm_data->>'farm_name', ''), nullif(farm_data->>'name', ''));
  v_size numeric := nullif(farm_data->>'size', '')::numeric;
  v_county_id uuid := nullif(farm_data->>'county_id', '')::uuid;
  v_sub_county_id uuid := nullif(coalesce(farm_data->>'sub_county_id', farm_data->>'subcounty_id'), '')::uuid;
  v_ward_id uuid := nullif(farm_data->>'ward_id', '')::uuid;
BEGIN
  SELECT p.id INTO v_user_id
  FROM users.profiles p
  WHERE p.auth_user_id = auth.uid()
    AND p.is_active = true
    AND p.account_status = 'active';
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'active user profile not found' USING ERRCODE = '42501';
  END IF;
  IF v_farm_name IS NULL THEN
    RAISE EXCEPTION 'farm_name is required';
  END IF;
  IF v_county_id IS NULL OR v_sub_county_id IS NULL OR v_ward_id IS NULL THEN
    RAISE EXCEPTION 'county_id, sub_county_id, and ward_id are required';
  END IF;

  IF v_requested_entity_id IS NOT NULL THEN
    v_entity_id := v_requested_entity_id;
  ELSE
    v_entity_id := core.get_active_entity();
    IF v_entity_id IS NULL THEN
      SELECT count(*)::integer INTO v_entity_count
      FROM core.entities e
      WHERE e.owner_id = v_user_id
        AND e.is_active = true;
      IF v_entity_count > 1 THEN
        RAISE EXCEPTION 'multiple operating entities exist; entity_id is required' USING ERRCODE = '22023';
      ELSIF v_entity_count = 0 THEN
        RAISE EXCEPTION 'an operating entity is required before creating a farm' USING ERRCODE = '42501';
      END IF;
      SELECT e.id INTO v_entity_id
      FROM core.entities e
      WHERE e.owner_id = v_user_id
        AND e.is_active = true;
    END IF;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM core.entities e
    JOIN core.entity_members em
      ON em.entity_id = e.id
     AND em.profile_id = v_user_id
     AND em.is_active = true
     AND em.membership_status = 'active'
    JOIN core.entity_roles er
      ON er.entity_id = em.entity_id
     AND er.profile_id = em.profile_id
     AND er.role_id = em.role_id
     AND er.is_active = true
    JOIN core.user_roles r
      ON r.id = em.role_id
     AND r.is_active = true
    WHERE e.id = v_entity_id
      AND e.is_active = true
  ) THEN
    RAISE EXCEPTION 'user is not an active member of the requested operating entity' USING ERRCODE = '42501';
  END IF;

  INSERT INTO farm_management.farms (
    entity_id, farm_name, description, size, unit, county_id, sub_county_id,
    ward_id, geo_coordinates, village, irrigation_water, ownership
  ) VALUES (
    v_entity_id,
    v_farm_name,
    farm_data->>'description',
    v_size,
    nullif(farm_data->>'unit', '')::uuid,
    v_county_id,
    v_sub_county_id,
    v_ward_id,
    farm_data->>'geo_coordinates',
    farm_data->>'village',
    (farm_data->>'irrigation_water')::boolean,
    farm_data->>'ownership'
  ) RETURNING id INTO v_farm_id;

  INSERT INTO farm_management.fields (farm_id, name, size, field_type, description, is_active)
  VALUES (v_farm_id, 'Main Field', v_size, 'main', 'Automatically created main field', true);

  farm_id := v_farm_id;
  entity_id := v_entity_id;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "commerce"."create_farm_with_auto_entity"("farm_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."create_farm_with_auto_entity_wrapper"("farm_data" "jsonb") RETURNS TABLE("farm_id" "uuid", "entity_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  PERFORM set_config('app.current_function', 'commerce.create_farm_with_auto_entity', true);
  RETURN QUERY SELECT * FROM commerce.create_farm_with_auto_entity(farm_data);
END; $$;


