CREATE OR REPLACE FUNCTION "commerce"."create_order"("p_listing_id" "uuid", "p_quantity" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
      DECLARE
        v_stock_id uuid;
          v_order_id uuid;
          BEGIN

            -- Get stock
              SELECT stock_id INTO v_stock_id
                FROM marketplace.listings
                  WHERE id = p_listing_id;

                    -- Reserve stock FIRST (critical)
                      INSERT INTO commerce.stock_reservations (
                          stock_id,
                              listing_id,
                                  quantity,
                                      expires_at
                                        )
                                          VALUES (
                                              v_stock_id,
                                                  p_listing_id,
                                                      p_quantity,
                                                          now() + interval '30 minutes'
                                                            );

                                                              -- Create order
                                                                INSERT INTO commerce.orders (
                                                                    listing_id,
                                                                        quantity,
                                                                            total_amount,
                                                                                status,
                                                                                    payment_status
                                                                                      )
                                                                                        SELECT
                                                                                            p_listing_id,
                                                                                                p_quantity,
                                                                                                    (price_per_unit * p_quantity),
                                                                                                        'pending',
                                                                                                            'pending'
                                                                                                              FROM marketplace.listings
                                                                                                                WHERE id = p_listing_id
                                                                                                                  RETURNING id INTO v_order_id;

                                                                                                                    RETURN v_order_id;

                                                                                                                    END;
                                                                                                                    $$;


ALTER FUNCTION "commerce"."create_order"("p_listing_id" "uuid", "p_quantity" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."create_order_with_reservation"("p_listing_id" "uuid", "p_quantity" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_order_id uuid;
  v_stock_id uuid;
  v_available_qty numeric;
  v_reserved_qty numeric;
  v_price numeric;
  v_entity_id uuid;
  v_supplier_id uuid;
  v_business_profile_count integer;
BEGIN
  SELECT l.stock_id, l.price_per_unit, l.entity_id
    INTO v_stock_id, v_price, v_entity_id
  FROM marketplace.listings l
  WHERE l.id = p_listing_id
  FOR UPDATE;

  IF v_stock_id IS NULL THEN
    RAISE EXCEPTION 'Listing not found';
  END IF;

  SELECT count(*)::integer, min(bp.id)
    INTO v_business_profile_count, v_supplier_id
  FROM commerce.business_profiles bp
  WHERE bp.entity_id = v_entity_id
    AND bp.is_active = true
    AND bp.user_active = true
    AND bp.deleted_at IS NULL
    AND bp.verification_status = 'verified';

  IF v_business_profile_count = 0 THEN
    RAISE EXCEPTION 'No valid business profile found for listing entity %', v_entity_id;
  ELSIF v_business_profile_count > 1 THEN
    RAISE EXCEPTION 'Multiple valid business profiles found for listing entity %; order creation is ambiguous', v_entity_id;
  END IF;

  SELECT quantity, reserved_quantity
    INTO v_available_qty, v_reserved_qty
  FROM commerce.stock_registry
  WHERE id = v_stock_id
  FOR UPDATE;

  IF v_available_qty IS NULL THEN
    RAISE EXCEPTION 'Stock not found';
  END IF;
  IF (v_available_qty - v_reserved_qty) < p_quantity THEN
    RAISE EXCEPTION 'Not enough stock available';
  END IF;

  INSERT INTO commerce.orders
    (buyer_id, listing_id, supplier_id, quantity, total_amount, status, payment_status, entity_id)
  VALUES
    (core.current_profile_id(), p_listing_id, v_supplier_id, p_quantity,
     p_quantity * v_price, 'pending', 'pending', v_entity_id)
  RETURNING id INTO v_order_id;

  INSERT INTO commerce.stock_reservations (order_id, stock_id, quantity)
  VALUES (v_order_id, v_stock_id, p_quantity);

  UPDATE commerce.stock_registry
  SET reserved_quantity = reserved_quantity + p_quantity,
      updated_at = now()
  WHERE id = v_stock_id;

  RETURN v_order_id;
END;
$$;


ALTER FUNCTION "commerce"."create_order_with_reservation"("p_listing_id" "uuid", "p_quantity" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."deactivate_entity_role"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'commerce', 'core', 'users'
    AS $$
DECLARE
  v_profile_id uuid;
  v_entity_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  SELECT p.id
    INTO v_profile_id
  FROM users.profiles AS p
  WHERE p.auth_user_id = auth.uid()
    AND p.is_active = true
    AND p.account_status = 'active';

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'active profile not found' USING ERRCODE = '42501';
  END IF;

  SELECT er.entity_id
    INTO v_entity_id
  FROM core.entity_roles AS er
  WHERE er.id = p_id;

  IF v_entity_id IS NULL THEN
    RAISE EXCEPTION 'entity role not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM core.entities AS e
    WHERE e.id = v_entity_id
      AND (e.owner_id = v_profile_id OR EXISTS (
        SELECT 1
        FROM core.entity_members AS em
        WHERE em.entity_id = e.id
          AND em.profile_id = v_profile_id
          AND em.is_active = true
          AND em.membership_status = 'active'
          AND em.can_manage = true
      ))
  ) THEN
    RAISE EXCEPTION 'not authorized to deactivate this entity role' USING ERRCODE = '42501';
  END IF;

  UPDATE core.entity_roles
  SET is_active = false, updated_at = now()
  WHERE id = p_id;
END;
$$;


ALTER FUNCTION "commerce"."deactivate_entity_role"("p_id" "uuid") OWNER TO "postgres";


