CREATE OR REPLACE FUNCTION "commerce"."fail_order_payment"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
    DECLARE
      v_stock_id uuid;
        v_reserved_qty numeric;
        BEGIN

          -- Lock reservation + stock
            SELECT 
                r.stock_id,
                    r.quantity
                      INTO 
                          v_stock_id,
                              v_reserved_qty
                                FROM commerce.stock_reservations r
                                  WHERE r.order_id = p_order_id
                                    FOR UPDATE;

                                      IF v_stock_id IS NULL THEN
                                          RETURN;
                                            END IF;

                                              -- Release reserved stock
                                                UPDATE commerce.stock_registry
                                                  SET reserved_quantity = reserved_quantity - v_reserved_qty,
                                                        updated_at = now()
                                                          WHERE id = v_stock_id;

                                                            -- Delete reservation
                                                              DELETE FROM commerce.stock_reservations
                                                                WHERE order_id = p_order_id;

                                                                  -- Update order
                                                                    UPDATE commerce.orders
                                                                      SET payment_status = 'failed',
                                                                            status = 'cancelled',
                                                                                  updated_at = now()
                                                                                    WHERE id = p_order_id;

                                                                                    END;
                                                                                    $$;


ALTER FUNCTION "commerce"."fail_order_payment"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."is_entity_manager"("p_profile_id" "uuid", "p_entity_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'commerce', 'core', 'users'
    AS $$
  SELECT auth.uid() IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM users.profiles AS caller
       JOIN core.entity_roles AS er
         ON er.profile_id = caller.id
        AND er.entity_id = p_entity_id
        AND er.is_active = true
       JOIN core.user_roles AS r
         ON r.id = er.role_id
        AND r.is_active = true
        AND r.type = 'commerce'
        AND r.name = 'Manager'
       WHERE caller.id = p_profile_id
         AND caller.auth_user_id = auth.uid()
         AND caller.is_active = true
         AND caller.account_status = 'active'
     );
$$;


ALTER FUNCTION "commerce"."is_entity_manager"("p_profile_id" "uuid", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."populate_stock_location_from_farm"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'commerce', 'farm_management', 'core'
    AS $$
DECLARE
  v_source_record_id uuid;
  v_farm_id uuid;
  v_location_id uuid;
BEGIN
  IF NEW.location_id IS NULL THEN
    v_source_record_id := NULLIF(NEW.metadata ->> 'source_record_id', '')::uuid;

    IF v_source_record_id IS NOT NULL THEN
      SELECT pr.farm_id
        INTO v_farm_id
      FROM farm_management.production_records AS pr
      WHERE pr.id = v_source_record_id;

      IF v_farm_id IS NOT NULL THEN
        SELECT COALESCE(f.ward_id, f.sub_county_id, f.county_id)
          INTO v_location_id
        FROM farm_management.farms AS f
        WHERE f.id = v_farm_id;

        NEW.location_id := v_location_id;
      END IF;
    END IF;
  END IF;

  IF NEW.location_id IS NULL THEN
    RAISE EXCEPTION
      'Stock location is required; provide location_id or a valid production source_record_id';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "commerce"."populate_stock_location_from_farm"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."process_order_payment"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_payment_status text;
    v_stock_id uuid;
      v_required_qty numeric;
        v_available_qty numeric;
        BEGIN

          -- 🔒 STEP 1: Lock order (prevents race conditions)
            SELECT payment_status
              INTO v_payment_status
                FROM commerce.orders
                  WHERE id = p_order_id
                    FOR UPDATE;

                      -- 🛑 STEP 2: Idempotency guard
                        IF v_payment_status = 'completed' THEN
                            RETURN;
                              END IF;

                                -- 🔒 STEP 3: Get reserved stock
                                  SELECT r.stock_id, r.quantity
                                    INTO v_stock_id, v_required_qty
                                      FROM commerce.stock_reservations r
                                        WHERE r.order_id = p_order_id
                                          FOR UPDATE;

                                            -- 🔒 STEP 4: Lock stock row
                                              SELECT quantity
                                                INTO v_available_qty
                                                  FROM commerce.stock_registry
                                                    WHERE id = v_stock_id
                                                      FOR UPDATE;

                                                        -- 🛑 STEP 5: Invariant check (NO NEGATIVE STOCK)
                                                          IF v_available_qty < v_required_qty THEN
                                                              RAISE EXCEPTION 'Insufficient stock for order %', p_order_id;
                                                                END IF;

                                                                  -- 🔻 STEP 6: Deduct stock safely
                                                                    UPDATE commerce.stock_registry
                                                                      SET quantity = quantity - v_required_qty,
                                                                            updated_at = now()
                                                                              WHERE id = v_stock_id;

                                                                                -- 💳 STEP 7: Mark payment completed
                                                                                  UPDATE commerce.orders
                                                                                    SET payment_status = 'completed',
                                                                                          status = 'confirmed',
                                                                                                updated_at = now()
                                                                                                  WHERE id = p_order_id;

                                                                                                    -- 📊 STEP 8: Record transaction
                                                                                                      INSERT INTO commerce.transactions (
                                                                                                          order_id,
                                                                                                              supplier_id,
                                                                                                                  amount,
                                                                                                                      currency,
                                                                                                                          payment_method,
                                                                                                                              payment_status
                                                                                                                                )
                                                                                                                                  SELECT 
                                                                                                                                      o.id,
                                                                                                                                          o.supplier_id,
                                                                                                                                              o.total_amount,
                                                                                                                                                  'KES',
                                                                                                                                                      'mpesa',
                                                                                                                                                          'completed'
                                                                                                                                                            FROM commerce.orders o
                                                                                                                                                              WHERE o.id = p_order_id;

                                                                                                                                                                -- 📦 STEP 9: Record stock movement
                                                                                                                                                                  INSERT INTO commerce.stock_movements (
                                                                                                                                                                      stock_id,
                                                                                                                                                                          quantity_change,
                                                                                                                                                                              movement_type,
                                                                                                                                                                                  source_module,
                                                                                                                                                                                      source_type,
                                                                                                                                                                                          source_ref_id,
                                                                                                                                                                                              order_id,
                                                                                                                                                                                                  entity_id
                                                                                                                                                                                                    )
                                                                                                                                                                                                      VALUES (
                                                                                                                                                                                                          v_stock_id,
                                                                                                                                                                                                              -v_required_qty,
                                                                                                                                                                                                                  'sale',
                                                                                                                                                                                                                      'marketplace',
                                                                                                                                                                                                                          'order',
                                                                                                                                                                                                                              p_order_id,
                                                                                                                                                                                                                                  p_order_id,
                                                                                                                                                                                                                                      (SELECT entity_id FROM commerce.orders WHERE id = p_order_id)
                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                        END;
                                                                                                                                                                                                                                        $$;


ALTER FUNCTION "commerce"."process_order_payment"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."process_order_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN

  IF NEW.status = 'confirmed' THEN

      -- deduct stock
          INSERT INTO commerce.stock_movements (
                stock_id,
                      quantity_change,
                            movement_type,
                                  source_module,
                                        source_type,
                                              source_ref_id,
                                                    order_id
                                                        )
                                                            SELECT 
                                                                  oi.stock_id,
                                                                        -oi.quantity,
                                                                              'sale',
                                                                                    'commerce.orders',
                                                                                          'order',
                                                                                                NEW.id,
                                                                                                      NEW.id
                                                                                                          FROM commerce.order_items oi
                                                                                                              WHERE oi.order_id = NEW.id;

                                                                                                                  -- release reservation
                                                                                                                      UPDATE commerce.stock_registry sr
                                                                                                                          SET 
                                                                                                                                reserved_quantity = reserved_quantity - oi.quantity,
                                                                                                                                      updated_at = now()
                                                                                                                                          FROM commerce.order_items oi
                                                                                                                                              WHERE oi.order_id = NEW.id
                                                                                                                                                    AND sr.id = oi.stock_id;

                                                                                                                                                      END IF;

                                                                                                                                                        RETURN NEW;
                                                                                                                                                        END;
                                                                                                                                                        $$;


ALTER FUNCTION "commerce"."process_order_stock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."process_order_stock"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  r RECORD;
  BEGIN

    FOR r IN
        SELECT * FROM commerce.order_items WHERE order_id = p_order_id
          LOOP

              PERFORM commerce.apply_stock_movement(
                    ROW(
                            r.product_id,
                                    -r.quantity,
                                            'sale',
                                                    'commerce',
                                                            'order',
                                                                    p_order_id,
                                                                            p_order_id,
                                                                                    'local',
                                                                                            NULL,
                                                                                                    jsonb_build_object('unit_price', r.price_per_unit)
                                                                                                          )::commerce.stock_event_type
                                                                                                              );

                                                                                                                END LOOP;

                                                                                                                END;
                                                                                                                $$;


ALTER FUNCTION "commerce"."process_order_stock"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."record_entity_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_changed_by uuid;
begin
  begin
    v_changed_by := (select public.auth_user_id());
  exception when others then
    v_changed_by := null;
  end;

  if (tg_op = 'INSERT') then
    insert into commerce.entities_audit(entity_id, operation, changed_by, old_data, new_data)
    values (new.id, 'INSERT', v_changed_by, null, to_jsonb(new));
    return new;
  elsif (tg_op = 'UPDATE') then
    insert into commerce.entities_audit(entity_id, operation, changed_by, old_data, new_data)
    values (coalesce(new.id, old.id), 'UPDATE', v_changed_by, to_jsonb(old), to_jsonb(new));
    return new;
  elsif (tg_op = 'DELETE') then
    insert into commerce.entities_audit(entity_id, operation, changed_by, old_data, new_data)
    values (old.id, 'DELETE', v_changed_by, to_jsonb(old), null);
    return old;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "commerce"."record_entity_audit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "commerce"."reserve_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN

  UPDATE commerce.stock_registry
    SET 
        reserved_quantity = reserved_quantity + NEW.quantity,
            updated_at = now()
              WHERE id = NEW.stock_id
                  AND (quantity - reserved_quantity) >= NEW.quantity;

                    IF NOT FOUND THEN
                        RAISE EXCEPTION 'Insufficient available stock';
                          END IF;

                            RETURN NEW;
                            END;
                            $$;


