CREATE OR REPLACE FUNCTION "core"."create_record_with_attributes"("p_domain_id" "uuid", "p_category_id" "uuid", "p_item_id" "uuid", "p_title" "text", "p_description" "text", "p_quantity" numeric, "p_unit_id" "uuid", "p_price" numeric, "p_currency" "text", "p_location" "text", "p_attributes" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_record_id uuid;
  v_attr_item jsonb;
  v_result jsonb;
BEGIN
  -- 1. Insert the main record
  -- This will fire 'trg_core_required_check' IF it's not deferred.
  -- To handle "Required" fields, we must ensure attributes are inserted in the same transaction.
  INSERT INTO core.records (
    domain_id, category_id, item_id, title, description, 
    quantity, unit_id, price, currency, location
  )
  VALUES (
    p_domain_id, p_category_id, p_item_id, p_title, p_description, 
    p_quantity, p_unit_id, p_price, p_currency, p_location
  )
  RETURNING id INTO v_record_id;

  -- 2. Insert Attributes 
  -- Each insert here fires: trg_core_attribute_check, trg_core_datatype_check, trg_core_enum_check
  IF p_attributes IS NOT NULL AND jsonb_array_length(p_attributes) > 0 THEN
    FOR v_attr_item IN SELECT * FROM jsonb_array_elements(p_attributes) LOOP
      INSERT INTO core.record_attributes (
        record_id,
        attribute_id,
        value_text,
        value_number,
        value_boolean,
        value_json,
        enum_value_id -- Added to match your Trigger 3.3
      )
      VALUES (
        v_record_id,
        (v_attr_item->>'attribute_id')::uuid,
        v_attr_item->>'value_text',
        (v_attr_item->>'value_number')::numeric,
        (v_attr_item->>'value_boolean')::boolean,
        (v_attr_item->'value_json'),
        (v_attr_item->>'enum_value_id')::uuid
      );
    END LOOP;
  END IF;

  -- 3. Final Validation Check
  -- If you prefer not to rely on the 'AFTER INSERT' trigger on records 
  -- (which can be finicky with timing), we can manually call a validation check here:
  -- PERFORM core.manual_validate_required(v_record_id);

  RETURN jsonb_build_object(
    'status', 'success',
    'record_id', v_record_id,
    'message', 'Record and attributes validated and created'
  );

EXCEPTION WHEN OTHERS THEN
  -- All inserts (record + attributes) are ROLLED BACK automatically on error
  RETURN jsonb_build_object(
    'status', 'error',
    'message', SQLERRM, 
    'detail', SQLSTATE
  );
END;
$$;


