CREATE OR REPLACE FUNCTION "core"."enforce_domain_normalized_unique"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'core'
    AS $$
DECLARE
  v_normalized text;
BEGIN
  v_normalized := core.normalize_taxonomy_name(NEW.name);
  IF v_normalized = '' THEN
    RAISE EXCEPTION 'domain name must contain a letter or number' USING ERRCODE = '22023';
  END IF;

  IF TG_OP = 'UPDATE'
     AND v_normalized = core.normalize_taxonomy_name(OLD.name) THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('core.domains:' || v_normalized, 0));
  IF EXISTS (
    SELECT 1 FROM core.domains d
    WHERE d.id IS DISTINCT FROM NEW.id
      AND core.normalize_taxonomy_name(d.name) = v_normalized
  ) THEN
    RAISE EXCEPTION 'a domain with the same normalized name already exists' USING ERRCODE = '23505';
  END IF;
  RETURN NEW;
END;
$$;


