CREATE OR REPLACE FUNCTION "core"."enforce_record_schema"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    attr_rule RECORD;
        val_text TEXT;
        BEGIN
            -- This loop now gathers both the Category Identity AND Variant Intrinsic Truths
                FOR attr_rule IN (
                        -- 1. Category-level attributes (Shared by all items in category)
                                SELECT ar.name, ar.data_type, ca.is_required, 'Category' as source
                                        FROM core.category_attribute_map ca
                                                JOIN core.attribute_registry ar ON ca.attribute_id = ar.id
                                                        WHERE ca.category_id = NEW.category_id

                                                                UNION ALL

                                                                        -- 2. Variant-level attributes (The "Intrinsic Truths" specific to the product)
                                                                                -- Only runs if a variant_id is actually provided in the record
                                                                                        SELECT ar.name, ar.data_type, va.is_required, 'Variant' as source
                                                                                                FROM core.variant_attributes va
                                                                                                        JOIN core.attribute_registry ar ON va.attribute_id = ar.id
                                                                                                                WHERE va.variant_id = NEW.variant_id
                                                                                                                    )
                                                                                                                        LOOP
                                                                                                                                val_text := jsonb_extract_path_text(NEW.metadata, attr_rule.name);

                                                                                                                                        -- Required Check: Blocks if a mandatory "Truth" is missing
                                                                                                                                                IF attr_rule.is_required AND (val_text IS NULL OR val_text = '') THEN
                                                                                                                                                            RAISE EXCEPTION '[Steel Wall] % Attribute "%" is required.', 
                                                                                                                                                                            attr_rule.source, attr_rule.name;
                                                                                                                                                                                    END IF;

                                                                                                                                                                                            -- Numeric Type Check: Ensures data integrity for metrics
                                                                                                                                                                                                    IF val_text IS NOT NULL AND val_text <> '' AND attr_rule.data_type = 'number' THEN
                                                                                                                                                                                                                IF val_text !~ '^-?\d+(\.\d+)?$' THEN
                                                                                                                                                                                                                                RAISE EXCEPTION '[Steel Wall] % Attribute "%" must be numeric.', 
                                                                                                                                                                                                                                                    attr_rule.source, attr_rule.name;
                                                                                                                                                                                                                                                                END IF;
                                                                                                                                                                                                                                                                        END IF;
                                                                                                                                                                                                                                                                            END LOOP;

                                                                                                                                                                                                                                                                                RETURN NEW;
                                                                                                                                                                                                                                                                                END;
                                                                                                                                                                                                                                                                                $_$;


ALTER FUNCTION "core"."enforce_record_schema"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."enforce_steel_wall_policy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    required_attr RECORD;
        val_exists BOOLEAN;
            attr_value JSONB;
            BEGIN
                -- 1. Loop through all required attributes for this record's category
                    FOR required_attr IN 
                            SELECT ar.name, ar.data_type 
                                    FROM core.category_attribute_map cam
                                            JOIN core.attribute_registry ar ON cam.attribute_id = ar.id
                                                    WHERE cam.category_id = NEW.category_id AND cam.is_required = true
                                                        LOOP
                                                                -- 2. Check if the key exists in metadata
                                                                        IF NOT (NEW.metadata ? required_attr.name) THEN
                                                                                    RAISE EXCEPTION 'Steel Wall Violation: Category requires missing attribute "%"', required_attr.name;
                                                                                            END IF;

                                                                                                    -- 3. Check Data Type Integrity
                                                                                                            attr_value := NEW.metadata -> required_attr.name;
                                                                                                                    IF required_attr.data_type = 'number' AND jsonb_extract_path_text(NEW.metadata, required_attr.name) !~ '^-?\d+(\.\d+)?$' THEN
                                                                                                                                RAISE EXCEPTION 'Steel Wall Violation: Attribute "%" must be a number.', required_attr.name;
                                                                                                                                        END IF;
                                                                                                                                            END LOOP;

                                                                                                                                                RETURN NEW;
                                                                                                                                                END;
                                                                                                                                                $_$;


ALTER FUNCTION "core"."enforce_steel_wall_policy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."enforce_taxonomy_steel_wall"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    mapping_record RECORD;
        metadata_value JSONB;
            is_valid_number BOOLEAN;
            BEGIN
                -- Loop through all allowed attributes for this specific category
                    FOR mapping_record IN 
                            SELECT ar.name as attr_name, ar.data_type, cam.is_required
                                    FROM core.category_attribute_map cam
                                            JOIN core.attribute_registry ar ON cam.attribute_id = ar.id
                                                    WHERE cam.category_id = NEW.category_id
                                                        LOOP
                                                                metadata_value := NEW.metadata -> mapping_record.attr_name;

                                                                        -- Check for Required Attributes
                                                                                IF mapping_record.is_required AND (metadata_value IS NULL OR metadata_value = 'null'::jsonb) THEN
                                                                                            RAISE EXCEPTION 'Steel Wall Violation: Category requires attribute "%"', mapping_record.attr_name;
                                                                                                    END IF;

                                                                                                            -- Check Data Types for 'number'
                                                                                                                    IF metadata_value IS NOT NULL AND metadata_value != 'null'::jsonb AND mapping_record.data_type = 'number' THEN
                                                                                                                                -- Validate if the string is a valid numeric format
                                                                                                                                            IF jsonb_extract_path_text(NEW.metadata, mapping_record.attr_name) !~ '^-?\d+(\.\d+)?$' THEN
                                                                                                                                                            RAISE EXCEPTION 'Steel Wall Violation: Attribute "%" must be a number (Received: %)', 
                                                                                                                                                                            mapping_record.attr_name, jsonb_extract_path_text(NEW.metadata, mapping_record.attr_name);
                                                                                                                                                                                        END IF;
                                                                                                                                                                                                END IF;
                                                                                                                                                                                                    END LOOP;

                                                                                                                                                                                                        -- Check for "Ghost" Attributes (Preventing pollution)
                                                                                                                                                                                                            IF EXISTS (
                                                                                                                                                                                                                    SELECT 1 FROM jsonb_object_keys(NEW.metadata) k
                                                                                                                                                                                                                            WHERE k NOT IN (
                                                                                                                                                                                                                                        SELECT ar.name 
                                                                                                                                                                                                                                                    FROM core.category_attribute_map cam
                                                                                                                                                                                                                                                                JOIN core.attribute_registry ar ON cam.attribute_id = ar.id
                                                                                                                                                                                                                                                                            WHERE cam.category_id = NEW.category_id
                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                        ) THEN
                                                                                                                                                                                                                                                                                                RAISE EXCEPTION 'Steel Wall Violation: Metadata contains attributes not mapped to this category.';
                                                                                                                                                                                                                                                                                                    END IF;

                                                                                                                                                                                                                                                                                                        RETURN NEW;
                                                                                                                                                                                                                                                                                                        END;
                                                                                                                                                                                                                                                                                                        $_$;


ALTER FUNCTION "core"."enforce_taxonomy_steel_wall"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."enforce_two_tier_steel_wall"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    attr_record RECORD;
        val_text TEXT;
        BEGIN
            FOR attr_record IN (
                    WITH combined_rules AS (
                                -- Get Variant rules
                                            SELECT attribute_id, is_required FROM core.variant_attribute_map WHERE variant_id = NEW.variant_id
                                                        UNION
                                                                    -- Get Category rules
                                                                                SELECT attribute_id, is_required FROM core.category_attribute_map WHERE category_id = NEW.category_id
                                                                                        )
                                                                                                SELECT ar.name, ar.data_type, cr.is_required 
                                                                                                        FROM combined_rules cr
                                                                                                                JOIN core.attribute_registry ar ON cr.attribute_id = ar.id
                                                                                                                    )
                                                                                                                        LOOP
                                                                                                                                val_text := jsonb_extract_path_text(NEW.metadata, attr_record.name);

                                                                                                                                        -- 1. Existence/Requirement Check
                                                                                                                                                IF attr_record.is_required AND (val_text IS NULL OR val_text = '') THEN
                                                                                                                                                            RAISE EXCEPTION 'Steel Wall Violation: "%" is required for this record.', attr_record.name;
                                                                                                                                                                    END IF;

                                                                                                                                                                            -- 2. Data Type Check
                                                                                                                                                                                    IF val_text IS NOT NULL AND val_text <> '' AND attr_record.data_type = 'number' THEN
                                                                                                                                                                                                IF val_text !~ '^-?\d+(\.\d+)?$' THEN
                                                                                                                                                                                                                RAISE EXCEPTION 'Steel Wall Violation: "%" must be a number.', attr_record.name;
                                                                                                                                                                                                                            END IF;
                                                                                                                                                                                                                                    END IF;
                                                                                                                                                                                                                                        END LOOP;

                                                                                                                                                                                                                                            RETURN NEW;
                                                                                                                                                                                                                                            END;
                                                                                                                                                                                                                                            $_$;


ALTER FUNCTION "core"."enforce_two_tier_steel_wall"() OWNER TO "postgres";


