                            end if;

                                return new;
                                end;
                                $$;


ALTER FUNCTION "core"."enforce_variant_attributes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."ensure_entity_for_auth_user"("p_auth_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'core', 'users'
    AS $$
DECLARE
  v_profile_id uuid;
  v_target_auth_user_id uuid;
  v_service_role boolean;
BEGIN
  v_service_role := auth.uid() IS NULL AND auth.role() = 'service_role';

  IF auth.uid() IS NULL AND NOT v_service_role THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  IF v_service_role THEN
    IF p_auth_user_id IS NULL THEN
      RAISE EXCEPTION 'auth user id required for service role' USING ERRCODE = '42501';
    END IF;
    v_target_auth_user_id := p_auth_user_id;
  ELSE
    IF p_auth_user_id IS DISTINCT FROM auth.uid() THEN
      RAISE EXCEPTION 'cannot create entity for another user' USING ERRCODE = '42501';
    END IF;
    v_target_auth_user_id := auth.uid();
  END IF;

  SELECT p.id INTO v_profile_id
  FROM users.profiles p
  WHERE p.auth_user_id = v_target_auth_user_id
    AND p.is_active = true
    AND p.account_status = 'active';

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'active profile not found' USING ERRCODE = '42501';
  END IF;

  PERFORM core.ensure_entity_for_profile(v_profile_id);
END;
$$;


ALTER FUNCTION "core"."ensure_entity_for_auth_user"("p_auth_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."ensure_entity_for_profile"("p_profile_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'core', 'users'
    AS $$
DECLARE
  v_auth_user_id uuid;
  v_profile_id uuid;
  v_entity_id uuid;
  v_owner_role_id uuid;
  v_first_name text;
  v_service_role boolean;
BEGIN
  v_service_role := auth.uid() IS NULL AND auth.role() = 'service_role';

  IF auth.uid() IS NULL AND NOT v_service_role THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  IF v_service_role AND p_profile_id IS NULL THEN
    RAISE EXCEPTION 'profile id required for service role' USING ERRCODE = '42501';
  END IF;

  SELECT p.id, p.auth_user_id, p.first_name
    INTO v_profile_id, v_auth_user_id, v_first_name
  FROM users.profiles p
  WHERE p.is_active = true
    AND p.account_status = 'active'
    AND (
      (v_service_role AND p.id = p_profile_id)
      OR
      (NOT v_service_role AND p.auth_user_id = auth.uid()
       AND (p_profile_id IS NULL OR p.id = p_profile_id))
    )
  FOR UPDATE;

  IF v_profile_id IS NULL OR
     (NOT v_service_role AND v_auth_user_id IS DISTINCT FROM auth.uid()) THEN
    RAISE EXCEPTION 'active profile not found' USING ERRCODE = '42501';
  END IF;

  SELECT r.id
    INTO v_owner_role_id
  FROM core.user_roles r
  WHERE lower(r.name) = 'owner'
    AND r.type = 'system'
    AND r.is_active = true
  ORDER BY r.id
  LIMIT 1;

  IF v_owner_role_id IS NULL THEN
    RAISE EXCEPTION 'missing active system owner role';
  END IF;

  SELECT e.id
    INTO v_entity_id
  FROM core.entities e
  WHERE e.owner_id = v_profile_id
    AND e.entity_type = 'individual_pro'
    AND e.is_active = true
  ORDER BY e.created_at, e.id
  LIMIT 1
  FOR UPDATE;

  IF v_entity_id IS NULL THEN
    INSERT INTO core.entities (
      name, entity_type, owner_id, is_active, metadata,
      primary_contact_profile_id, legal_owner_type
    ) VALUES (
      'Entity for ' || coalesce(nullif(v_first_name, ''), 'user'),
      'individual_pro', v_profile_id, true, '{}'::jsonb,
      v_profile_id, 'individual'
    )
    RETURNING id INTO v_entity_id;
  END IF;

  INSERT INTO core.entity_members (
    entity_id, profile_id, role_id, can_sell, can_manage,
    can_receive_payments, membership_status, is_active
  ) VALUES (
    v_entity_id, v_profile_id, v_owner_role_id, false, true,
    false, 'active', true
  )
  ON CONFLICT (entity_id, profile_id) DO UPDATE
  SET role_id = EXCLUDED.role_id,
      membership_status = 'active',
      is_active = true,
      can_manage = true;

  INSERT INTO core.entity_roles (
    entity_id, profile_id, role_id, assigned_by, is_active
  ) VALUES (
    v_entity_id, v_profile_id, v_owner_role_id, v_profile_id, true
  )
  ON CONFLICT (profile_id, entity_id, role_id) DO UPDATE
  SET assigned_by = coalesce(core.entity_roles.assigned_by, EXCLUDED.assigned_by),
      is_active = true,
      updated_at = now();
END;
$$;


ALTER FUNCTION "core"."ensure_entity_for_profile"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."fn_ensure_global_record"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_record_id uuid;
  v_domain_id uuid;
BEGIN
  IF NEW.record_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_domain_id
  FROM core.domains
  WHERE name = (CASE
    WHEN TG_TABLE_SCHEMA = 'farm' THEN 'Agriculture'
    WHEN TG_TABLE_SCHEMA = 'commerce' THEN 'Commerce'
    ELSE 'General'
  END);

  INSERT INTO core.records
    (domain_id, entity_id, module, status, created_by, category_id)
  VALUES
    (v_domain_id, NEW.entity_id, TG_TABLE_NAME, 'active',
     COALESCE(core.current_profile_id(), NEW.created_by),
     (SELECT category_id FROM core.items WHERE id = NEW.item_id LIMIT 1))
  RETURNING id INTO v_record_id;

  NEW.record_id = v_record_id;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "core"."fn_ensure_global_record"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."get_active_entity"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users'
    AS $$
  SELECT ecs.entity_id
  FROM core.entity_context_sessions AS ecs
  JOIN users.profiles AS p
    ON p.id = ecs.user_id
   AND p.auth_user_id = auth.uid()
   AND p.is_active = true
   AND p.account_status = 'active'
  JOIN core.entities AS e
    ON e.id = ecs.entity_id
   AND e.is_active = true
  JOIN core.entity_members AS em
    ON em.entity_id = ecs.entity_id
   AND em.profile_id = p.id
   AND em.role_id = ecs.active_role_id
   AND em.is_active = true
   AND em.membership_status = 'active'
  JOIN core.entity_roles AS er
    ON er.entity_id = ecs.entity_id
   AND er.profile_id = p.id
   AND er.role_id = ecs.active_role_id
   AND er.is_active = true
  JOIN core.user_roles AS r
    ON r.id = ecs.active_role_id
   AND r.is_active = true
  WHERE ecs.user_id = p.id
    AND ecs.session_status = 'active'
  ORDER BY ecs.is_default DESC,
           ecs.last_switched_at DESC,
           ecs.created_at DESC,
           ecs.id DESC
  LIMIT 1;
$$;


ALTER FUNCTION "core"."get_active_entity"() OWNER TO "postgres";


