CREATE OR REPLACE FUNCTION "core"."get_effective_context"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users'
    AS $$
  SELECT jsonb_build_object(
    'profile', jsonb_build_object(
      'id', p.id,
      'is_active', p.is_active,
      'account_status', p.account_status
    ),
    'active_entity', CASE WHEN ac.entity_id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', ac.entity_id,
      'name', ac.entity_name,
      'entity_type', ac.entity_type
    ) END,
    'membership', CASE WHEN ac.membership_id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', ac.membership_id,
      'status', ac.membership_status,
      'is_active', ac.membership_is_active
    ) END,
    'active_role', CASE WHEN ac.role_id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', ac.role_id,
      'name', ac.role_name,
      'type', ac.role_type
    ) END,
    'active_mode', ac.active_mode,
    'business_profile_id', ac.business_profile_id
  )
  FROM users.profiles AS p
  LEFT JOIN LATERAL (
    SELECT
      e.id AS entity_id,
      e.name AS entity_name,
      e.entity_type,
      em.id AS membership_id,
      em.membership_status,
      em.is_active AS membership_is_active,
      r.id AS role_id,
      r.name AS role_name,
      r.type AS role_type,
      ecs.active_mode,
      ecs.business_profile_id
    FROM core.entity_context_sessions AS ecs
    JOIN core.entities AS e
      ON e.id = ecs.entity_id
     AND e.is_active = true
    JOIN core.entity_members AS em
      ON em.entity_id = e.id
     AND em.profile_id = p.id
     AND em.role_id = ecs.active_role_id
     AND em.is_active = true
     AND em.membership_status = 'active'
    JOIN core.entity_roles AS er
      ON er.entity_id = e.id
     AND er.profile_id = p.id
     AND er.role_id = ecs.active_role_id
     AND er.is_active = true
    JOIN core.user_roles AS r
      ON r.id = ecs.active_role_id
     AND r.is_active = true
    WHERE ecs.user_id = p.id
      AND ecs.session_status = 'active'
    ORDER BY ecs.is_default DESC,
             ecs.last_switched_at DESC,
             ecs.created_at DESC,
             ecs.id DESC
    LIMIT 1
  ) AS ac ON true
  WHERE p.auth_user_id = auth.uid()
    AND p.is_active = true
    AND p.account_status = 'active';
$$;


ALTER FUNCTION "core"."get_effective_context"() OWNER TO "postgres";


