CREATE OR REPLACE FUNCTION "core"."has_permission"("p_permission" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users'
    AS $$
  WITH caller AS (
    SELECT p.id AS profile_id
    FROM users.profiles AS p
    WHERE p.auth_user_id = auth.uid()
      AND p.is_active = true
      AND p.account_status = 'active'
  ),
  active_context AS (
    SELECT
      c.profile_id,
      ecs.entity_id,
      ecs.active_role_id AS role_id
    FROM caller AS c
    JOIN core.entity_context_sessions AS ecs
      ON ecs.user_id = c.profile_id
     AND ecs.session_status = 'active'
    JOIN core.entities AS e
      ON e.id = ecs.entity_id
     AND e.is_active = true
    JOIN core.entity_members AS em
      ON em.entity_id = ecs.entity_id
     AND em.profile_id = c.profile_id
     AND em.role_id = ecs.active_role_id
     AND em.is_active = true
     AND em.membership_status = 'active'
    JOIN core.entity_roles AS er
      ON er.entity_id = ecs.entity_id
     AND er.profile_id = c.profile_id
     AND er.role_id = ecs.active_role_id
     AND er.is_active = true
    JOIN core.user_roles AS r
      ON r.id = ecs.active_role_id
     AND r.is_active = true
    ORDER BY ecs.is_default DESC,
             ecs.last_switched_at DESC,
             ecs.created_at DESC,
             ecs.id DESC
    LIMIT 1
  ),
  requested_permission AS (
    SELECT p.id, p.scope_type, p.module
    FROM core.permissions AS p
    WHERE p.code = p_permission
  ),
  scoped_role AS (
    SELECT EXISTS (
      SELECT 1
      FROM active_context AS ac
      JOIN requested_permission AS p ON true
      JOIN core.entity_role_scopes AS ers
        ON ers.profile_id = ac.profile_id
       AND ers.role_id = ac.role_id
       AND (
         (p.scope_type = 'global'
          AND ers.scope_type = 'global'
          AND ers.entity_id IS NULL
          AND ers.module IS NULL)
         OR
         (p.scope_type = 'entity'
          AND ers.scope_type = 'entity'
          AND ers.entity_id = ac.entity_id
          AND ers.module IS NULL)
         OR
         (p.scope_type = 'module'
          AND ers.scope_type = 'module'
          AND ers.entity_id = ac.entity_id
          AND ers.module = p.module)
       )
      JOIN core.role_permissions AS rp
        ON rp.role_id = ac.role_id
       AND rp.permission_id = p.id
       AND rp.is_active = true
    ) AS allowed
  ),
  scoped_override AS (
    SELECT COALESCE(bool_and(po.allow), false) AS allowed
    FROM active_context AS ac
    JOIN requested_permission AS p ON true
    JOIN core.permission_overrides AS po
      ON po.profile_id = ac.profile_id
     AND po.permission_code = p_permission
     AND (po.expires_at IS NULL OR po.expires_at > now())
     AND (
       (p.scope_type = 'global'
        AND po.entity_id IS NULL
        AND EXISTS (
          SELECT 1
          FROM core.entity_role_scopes AS ers
          WHERE ers.profile_id = ac.profile_id
            AND ers.role_id = ac.role_id
            AND ers.scope_type = 'global'
            AND ers.entity_id IS NULL
            AND ers.module IS NULL
        ))
       OR
       (p.scope_type = 'entity'
        AND po.entity_id = ac.entity_id
        AND EXISTS (
          SELECT 1
          FROM core.entity_role_scopes AS ers
          WHERE ers.profile_id = ac.profile_id
            AND ers.role_id = ac.role_id
            AND ers.scope_type = 'entity'
            AND ers.entity_id = ac.entity_id
            AND ers.module IS NULL
        ))
       OR
       (p.scope_type = 'module'
        AND po.entity_id = ac.entity_id
        AND EXISTS (
          SELECT 1
          FROM core.entity_role_scopes AS ers
          WHERE ers.profile_id = ac.profile_id
            AND ers.role_id = ac.role_id
            AND ers.scope_type = 'module'
            AND ers.entity_id = ac.entity_id
            AND ers.module = p.module
        ))
     )
  )
  SELECT COALESCE((SELECT allowed FROM scoped_override), false)
      OR COALESCE((SELECT allowed FROM scoped_role), false);
$$;


ALTER FUNCTION "core"."has_permission"("p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."is_admin"() RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  SELECT EXISTS (
      SELECT 1
          FROM auth.users u
              WHERE u.id = core.auth_user_id()
                    AND (u.raw_user_meta_data->>'role') = 'admin'
                      );
                      $$;


ALTER FUNCTION "core"."is_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."is_admin"("user_uuid" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  exists_roles boolean;
  is_admin boolean := false;
BEGIN
  -- Check if core.roles table exists
  SELECT EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'core' AND table_name = 'roles'
  ) INTO exists_roles;

  IF NOT exists_roles THEN
    RETURN false;
  END IF;

  -- Try to check for a role row with sufficient level; tolerant to missing columns
  BEGIN
    SELECT EXISTS (
      SELECT 1 FROM core.roles r
      WHERE r.user_id = user_uuid AND (r.level IS NOT NULL AND r.level >= 80)
    ) INTO is_admin;
  EXCEPTION WHEN undefined_column OR undefined_table THEN
    RETURN false;
  END;

  RETURN is_admin;
END; $$;


ALTER FUNCTION "core"."is_admin"("user_uuid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."normalize_item_variant_name"("p_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT PARALLEL SAFE
