CREATE OR REPLACE FUNCTION "core"."set_active_entity"("p_entity_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users'
    AS $$
DECLARE
  v_profile_id uuid;
  v_role_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  SELECT p.id
    INTO v_profile_id
  FROM users.profiles AS p
  WHERE p.auth_user_id = auth.uid()
    AND p.is_active = true
    AND p.account_status = 'active';

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'active profile not found' USING ERRCODE = '42501';
  END IF;

  SELECT (array_agg(DISTINCT em.role_id))[1]
    INTO v_role_id
  FROM core.entity_members AS em
  JOIN core.entities AS e
    ON e.id = em.entity_id
   AND e.is_active = true
  JOIN core.entity_roles AS er
    ON er.entity_id = em.entity_id
   AND er.profile_id = em.profile_id
   AND er.role_id = em.role_id
   AND er.is_active = true
  JOIN core.user_roles AS r
    ON r.id = em.role_id
   AND r.is_active = true
  WHERE em.entity_id = p_entity_id
    AND em.profile_id = v_profile_id
    AND em.is_active = true
    AND em.membership_status = 'active'
  GROUP BY em.entity_id
  HAVING count(DISTINCT em.role_id) = 1;

  IF v_role_id IS NULL THEN
    RAISE EXCEPTION 'entity is not an active membership with one valid active role' USING ERRCODE = '42501';
  END IF;

  UPDATE core.entity_context_sessions
  SET session_status = 'expired'
  WHERE user_id = v_profile_id
    AND session_status = 'active';

  INSERT INTO core.entity_context_sessions
    (user_id, entity_id, session_status, is_default, last_switched_at,
     active_mode, business_profile_id, active_role_id)
  VALUES
    (v_profile_id, p_entity_id, 'active', false, now(),
     NULL, NULL, v_role_id);
END;
$$;


ALTER FUNCTION "core"."set_active_entity"("p_entity_id" "uuid") OWNER TO "postgres";


