CREATE OR REPLACE FUNCTION "core"."validate_attribute_belongs"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
    if not exists (
        select 1
        from core.records r
        join core.items i on r.item_id = i.id
        join core.category_attribute_map cam
            on cam.category_id = i.category_id
        where r.id = new.record_id
          and cam.attribute_id = new.attribute_id
    ) then
        raise exception 'CORE: Attribute not allowed for this category';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "core"."validate_attribute_belongs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."validate_datatype"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
    dtype text;
begin
    select data_type into dtype
    from core.attribute_registry
    where id = new.attribute_id;

    if dtype = 'text' and new.value_text is null then
        raise exception 'CORE: Expected text';
    elsif dtype = 'number' and new.value_number is null then
        raise exception 'CORE: Expected number';
    elsif dtype = 'boolean' and new.value_boolean is null then
        raise exception 'CORE: Expected boolean';
    elsif dtype = 'date' and new.value_date is null then
        raise exception 'CORE: Expected date';
    elsif dtype = 'enum' and new.enum_value_id is null then
        raise exception 'CORE: Expected enum';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "core"."validate_datatype"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."validate_enum"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
    if new.enum_value_id is not null then
        if not exists (
            select 1
            from core.attribute_enum_values
            where id = new.enum_value_id
              and attribute_id = new.attribute_id
        ) then
            raise exception 'CORE: Enum mismatch';
        end if;
    end if;

    return new;
end;
$$;


ALTER FUNCTION "core"."validate_enum"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."validate_item_unit"("p_item_id" "uuid", "p_variant_id" "uuid", "p_unit_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
              DECLARE
                  is_valid boolean;
                  BEGIN

                      -- 1. Check variant-specific rules first
                          IF p_variant_id IS NOT NULL THEN
                                  SELECT EXISTS (
                                              SELECT 1
                                                          FROM core.item_variant_unit_map
                                                                      WHERE variant_id = p_variant_id
                                                                                    AND unit_id = p_unit_id
                                                                                                  AND is_active = true
                                                                                                          ) INTO is_valid;

                                                                                                                  IF is_valid THEN
                                                                                                                              RETURN true;
                                                                                                                                      END IF;
                                                                                                                                          END IF;

                                                                                                                                              -- 2. Fallback to item-level rules
                                                                                                                                                  SELECT EXISTS (
                                                                                                                                                          SELECT 1
                                                                                                                                                                  FROM core.item_unit_map
                                                                                                                                                                          WHERE item_id = p_item_id
                                                                                                                                                                                    AND unit_id = p_unit_id
                                                                                                                                                                                              AND is_active = true
                                                                                                                                                                                                  ) INTO is_valid;

                                                                                                                                                                                                      RETURN is_valid;

                                                                                                                                                                                                      END;
                                                                                                                                                                                                      $$;


ALTER FUNCTION "core"."validate_item_unit"("p_item_id" "uuid", "p_variant_id" "uuid", "p_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."validate_module_data"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $_$
                                                declare
                                                    attr_rule record;
                                                        val_text text;
                                                            rec_category uuid;
                                                            begin
                                                                -- Get category from shared.records
                                                                    select category_id into rec_category
                                                                        from shared.records
                                                                            where id = NEW.record_id;

                                                                                -- CATEGORY RULES
                                                                                    for attr_rule in (
                                                                                            select ar.name, ar.data_type, ca.is_required
                                                                                                    from core.category_attribute_map ca
                                                                                                            join core.attribute_registry ar on ca.attribute_id = ar.id
                                                                                                                    where ca.category_id = rec_category
                                                                                                                        )
                                                                                                                            loop
                                                                                                                                    val_text := jsonb_extract_path_text(NEW.data, attr_rule.name);

                                                                                                                                            if attr_rule.is_required and (val_text is null or val_text = '') then
                                                                                                                                                        raise exception 
                                                                                                                                                                    'Validation Error: "%" is required',
                                                                                                                                                                                attr_rule.name;
                                                                                                                                                                                        end if;

                                                                                                                                                                                                if val_text is not null then
                                                                                                                                                                                                            if attr_rule.data_type = 'number' then
                                                                                                                                                                                                                            if val_text !~ '^-?\d+(\.\d+)?$' then
                                                                                                                                                                                                                                                raise exception 
                                                                                                                                                                                                                                                                    'Validation Error: "%" must be numeric',
                                                                                                                                                                                                                                                                                        attr_rule.name;
                                                                                                                                                                                                                                                                                                        end if;
                                                                                                                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                                                                                                                                if attr_rule.data_type = 'date' then
                                                                                                                                                                                                                                                                                                                                                begin
                                                                                                                                                                                                                                                                                                                                                                    perform val_text::date;
                                                                                                                                                                                                                                                                                                                                                                                    exception when others then
                                                                                                                                                                                                                                                                                                                                                                                                        raise exception 
                                                                                                                                                                                                                                                                                                                                                                                                                            'Validation Error: "%" must be a valid date',
                                                                                                                                                                                                                                                                                                                                                                                                                                                attr_rule.name;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            end if;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end if;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end loop;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- MODULE RULES (USING TABLE NAME)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for attr_rule in (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        select ar.name, ar.data_type, ma.is_required
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                from core.module_attribute_map ma
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        join core.attribute_registry ar on ma.attribute_id = ar.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                where ma.module_name = TG_TABLE_NAME
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        loop
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                val_text := jsonb_extract_path_text(NEW.data, attr_rule.name);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if attr_rule.is_required and (val_text is null or val_text = '') then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    raise exception 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'Validation Error: "%" required for module %',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            attr_rule.name, TG_TABLE_NAME;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end if;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end loop;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return NEW;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $_$;


ALTER FUNCTION "core"."validate_module_data"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."validate_record_attribute"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    attr RECORD;
        rec RECORD;
        BEGIN
            -- Get attribute definition
                SELECT * INTO attr
                    FROM core.attribute_registry
                        WHERE id = NEW.attribute_id;

                            IF attr IS NULL THEN
                                    RAISE EXCEPTION 'Invalid attribute_id';
                                        END IF;

                                            -- 🔹 TYPE VALIDATION
                                                IF attr.data_type = 'text' THEN
                                                        IF NEW.value_text IS NULL THEN
                                                                    RAISE EXCEPTION 'Expected text value for %', attr.name;
                                                                            END IF;

                                                                                ELSIF attr.data_type = 'number' THEN
                                                                                        IF NEW.value_number IS NULL THEN
                                                                                                    RAISE EXCEPTION 'Expected numeric value for %', attr.name;
                                                                                                            END IF;

                                                                                                                ELSIF attr.data_type = 'boolean' THEN
                                                                                                                        IF NEW.value_boolean IS NULL THEN
                                                                                                                                    RAISE EXCEPTION 'Expected boolean value for %', attr.name;
                                                                                                                                            END IF;

                                                                                                                                                ELSIF attr.data_type = 'json' THEN
                                                                                                                                                        IF NEW.value_json IS NULL THEN
                                                                                                                                                                    RAISE EXCEPTION 'Expected json value for %', attr.name;
                                                                                                                                                                            END IF;

                                                                                                                                                                                ELSIF attr.data_type = 'enum' THEN
                                                                                                                                                                                        IF NEW.enum_value_id IS NULL THEN
                                                                                                                                                                                                    RAISE EXCEPTION 'Expected enum value for %', attr.name;
                                                                                                                                                                                                            END IF;

                                                                                                                                                                                                                ELSE
                                                                                                                                                                                                                        RAISE EXCEPTION 'Unsupported attribute type: %', attr.data_type;
                                                                                                                                                                                                                            END IF;

                                                                                                                                                                                                                                -- Get record
                                                                                                                                                                                                                                    SELECT * INTO rec
                                                                                                                                                                                                                                        FROM core.records
                                                                                                                                                                                                                                            WHERE id = NEW.record_id;

                                                                                                                                                                                                                                                -- 🔹 FARM VALIDATION
                                                                                                                                                                                                                                                    IF rec.module = 'farm' THEN
                                                                                                                                                                                                                                                            IF attr.activity_type_id IS NOT NULL
                                                                                                                                                                                                                                                                       AND attr.activity_type_id <> rec.activity_type_id THEN
                                                                                                                                                                                                                                                                                   RAISE EXCEPTION 'Attribute % not allowed for this activity', attr.name;
                                                                                                                                                                                                                                                                                           END IF;
                                                                                                                                                                                                                                                                                               END IF;

                                                                                                                                                                                                                                                                                                   RETURN NEW;
                                                                                                                                                                                                                                                                                                   END;
                                                                                                                                                                                                                                                                                                   $$;


ALTER FUNCTION "core"."validate_record_attribute"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."validate_required"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
    if exists (
        select 1
        from core.items i
        join core.category_attribute_map cam
            on cam.category_id = i.category_id
        where i.id = new.item_id
          and cam.is_required = true
          and cam.attribute_id not in (
              select attribute_id
              from core.record_attributes
              where record_id = new.id
          )
    ) then
        raise exception 'CORE: Missing required attributes';
    end if;

    return new;
end;
$$;


ALTER FUNCTION "core"."validate_required"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."validate_unit_type"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.unit_type NOT IN (
            'count','time','mass','volume','area','length','power','currency'
                ) THEN
                        RAISE EXCEPTION 'Invalid unit_type: %', NEW.unit_type;
                            END IF;

                                RETURN NEW;
                                END;
                                $$;


ALTER FUNCTION "core"."validate_unit_type"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."validate_variant_attribute"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- Check if the attribute is allowed for the category this variant belongs to
        IF NOT EXISTS (
                SELECT 1 FROM core.category_attribute_map cam
                        JOIN core.items i ON i.category_id = cam.category_id
                                JOIN core.item_variants iv ON iv.item_id = i.id
                                        WHERE iv.id = NEW.variant_id AND cam.attribute_id = NEW.attribute_id
                                            ) THEN
                                                    RAISE EXCEPTION 'Attribute ID % is not allowed for this Variant Category', NEW.attribute_id;
                                                        END IF;
                                                            RETURN NEW;
                                                            END;
                                                            $$;


ALTER FUNCTION "core"."validate_variant_attribute"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "core"."validate_variant_attribute_consistency"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- STEP: Trace the Variant back to its Category through the Item
        -- IF the attribute is not mapped to that category, BLOCK IT.
            IF NOT EXISTS (
                    SELECT 1 
                            FROM core.category_attribute_map cam
                                    JOIN core.items i ON i.category_id = cam.category_id
                                            JOIN core.item_variants iv ON iv.item_id = i.id
                                                    WHERE iv.id = NEW.variant_id 
                                                            AND cam.attribute_id = NEW.attribute_id
                                                                ) THEN
                                                                        RAISE EXCEPTION 'Identity Breach: Attribute ID % is not valid for the Category assigned to this Variant.', NEW.attribute_id;
                                                                            END IF;

                                                                                RETURN NEW;
                                                                                END;
                                                                                $$;


ALTER FUNCTION "core"."validate_variant_attribute_consistency"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "farm_management"."apply_activity_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_rule RECORD;
  BEGIN
    SELECT * INTO v_rule
      FROM farm.activity_stock_rules
        WHERE activity_type_id = NEW.activity_type_id;

          IF NOT FOUND THEN
              RETURN NEW;
                END IF;

                  -- Example: use production_records or activity_values
                    IF v_rule.stock_direction = 'OUT' THEN

                        INSERT INTO commerce.stock_movements (
                              stock_id,
                                    quantity_change,
                                          movement_type,
                                                source_module,
                                                      source_type,
                                                            source_ref_id
                                                                )
                                                                    SELECT 
                                                                          sr.id,
                                                                                -(pr.quantity * v_rule.quantity_multiplier),
                                                                                      'consumption',
                                                                                            'farm',
                                                                                                  'activity',
                                                                                                        NEW.id
                                                                                                            FROM farm.production_records pr
                                                                                                                JOIN commerce.stock_registry sr 
                                                                                                                      ON sr.variant_id = pr.variant_id
                                                                                                                          WHERE pr.activity_id = NEW.id;

                                                                                                                            END IF;

                                                                                                                              RETURN NEW;
                                                                                                                              END;
                                                                                                                              $$;


ALTER FUNCTION "farm_management"."apply_activity_stock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "farm_management"."apply_farm_context"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  fc RECORD;
    f RECORD;
    BEGIN
      -- Only apply to farm module
        IF NEW.module <> 'farm' THEN
            RETURN NEW;
              END IF;

                -- Ensure farm_crop_id exists
                  IF NEW.farm_crop_id IS NULL THEN
                      RETURN NEW;
                        END IF;

                          SELECT * INTO fc
                            FROM farm.farm_crops
                              WHERE id = NEW.farm_crop_id;

                                IF fc IS NULL THEN
                                    RETURN NEW;
                                      END IF;

                                        SELECT * INTO f
                                          FROM farm.farms
                                            WHERE id = fc.farm_id;

                                              IF f IS NULL THEN
                                                  RETURN NEW;
                                                    END IF;

                                                      -- Apply context
                                                        NEW.entity_id := f.entity_id;
                                                          NEW.organization_id := f.organization_id;
                                                            NEW.owner_id := f.owner_id;

                                                              RETURN NEW;
                                                              END;
                                                              $$;


ALTER FUNCTION "farm_management"."apply_farm_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "farm_management"."apply_variant_defaults"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_attr RECORD;
  BEGIN
    IF NEW.variant_id IS NULL THEN
        RETURN NEW;
          END IF;

            FOR v_attr IN
                SELECT *
                    FROM core.variant_attributes
                        WHERE variant_id = NEW.variant_id
                          LOOP
                              INSERT INTO core.record_attributes (
                                    record_id,
                                          attribute_id,
                                                value_text,
                                                      value_number,
                                                            value_boolean
                                                                )
                                                                    VALUES (
                                                                          NEW.id,
                                                                                v_attr.attribute_id,
                                                                                      v_attr.value_text,
                                                                                            v_attr.value_number,
                                                                                                  v_attr.value_boolean
                                                                                                      )
                                                                                                          ON CONFLICT DO NOTHING;
                                                                                                            END LOOP;

                                                                                                              RETURN NEW;
                                                                                                              END;
                                                                                                              $$;


ALTER FUNCTION "farm_management"."apply_variant_defaults"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "farm_management"."create_activity"("activity_data" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'core', 'users', 'farm_management'
    AS $$
DECLARE
  v_user_id uuid := public.auth_user_id();
  v_asset_id uuid := NULLIF(BTRIM(activity_data->>'asset_id'), '')::uuid;
  v_activity_type_input text := NULLIF(BTRIM(activity_data->>'activity_type_id'), '');
  v_activity_type_id uuid;
  v_performed_at timestamptz;
  v_entity_id uuid;
  v_activity_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authenticated user is required';
  END IF;

  IF v_asset_id IS NULL THEN
    RAISE EXCEPTION 'asset_id is required';
  END IF;

  IF v_activity_type_input IS NULL THEN
    RAISE EXCEPTION 'activity_type_id is required';
  END IF;

  BEGIN
    v_activity_type_id := v_activity_type_input::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    SELECT at.id
      INTO v_activity_type_id
    FROM farm_management.activity_types at
    WHERE LOWER(at.name) = LOWER(v_activity_type_input)
      AND at.is_active = true
    LIMIT 1;
  END;

  IF v_activity_type_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM farm_management.activity_types at
    WHERE at.id = v_activity_type_id
      AND at.is_active = true
  ) THEN
    RAISE EXCEPTION 'Activity type not found or inactive: %', v_activity_type_input;
  END IF;

  IF NULLIF(BTRIM(activity_data->>'performed_at'), '') IS NULL THEN
    v_performed_at := now();
  ELSE
    BEGIN
      v_performed_at := (activity_data->>'performed_at')::timestamptz;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
      RAISE EXCEPTION 'performed_at must be a valid timestamp';
    END;
  END IF;

  IF v_performed_at > now() THEN
    RAISE EXCEPTION 'performed_at cannot be in the future';
  END IF;

  SELECT a.entity_id
    INTO v_entity_id
  FROM farm_management.assets a
  JOIN farm_management.farms f ON f.id = a.farm_id
  JOIN core.entities e ON e.id = f.entity_id AND e.is_active = true
  WHERE a.id = v_asset_id
    AND a.entity_id = f.entity_id
    AND (
      EXISTS (
        SELECT 1
        FROM users.profiles owner_profile
        WHERE owner_profile.id = e.owner_id
          AND owner_profile.auth_user_id = v_user_id
      )
      OR EXISTS (
        SELECT 1
        FROM core.entity_members m
        JOIN users.profiles member_profile
          ON member_profile.id = m.profile_id
        WHERE m.entity_id = f.entity_id
          AND member_profile.auth_user_id = v_user_id
          AND m.is_active = true
          AND m.membership_status = 'active'
          AND m.can_manage = true
      )
      OR EXISTS (
        SELECT 1
        FROM core.entity_roles er
        JOIN users.profiles role_profile
          ON role_profile.id = er.profile_id
        JOIN core.user_roles r
          ON r.id = er.role_id
        WHERE er.entity_id = f.entity_id
          AND role_profile.auth_user_id = v_user_id
          AND er.is_active = true
          AND LOWER(r.name) IN ('owner', 'manager')
      )
    )
  FOR SHARE OF a;

  IF v_entity_id IS NULL THEN
    RAISE EXCEPTION 'Asset not found or caller is not authorized';
  END IF;

  INSERT INTO farm_management.activities (
    activity_type_id,
    performed_at,
    notes,
    entity_id,
    asset_id
  )
  VALUES (
    v_activity_type_id,
    v_performed_at,
    activity_data->>'notes',
    v_entity_id,
    v_asset_id
  )
  RETURNING id INTO v_activity_id;

  RETURN v_activity_id;
END;
$$;


ALTER FUNCTION "farm_management"."create_activity"("activity_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "farm_management"."create_crop_livestock_asset"("asset_data" "jsonb") RETURNS TABLE("asset_id" "uuid", "entity_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'core', 'users', 'farm_management'
    AS $$
declare
  v_auth_user_id uuid := auth.uid();
  v_profile_id uuid;
  v_farm_id uuid := nullif(asset_data->>'farm_id', '')::uuid;
  v_field_id uuid := nullif(asset_data->>'field_id', '')::uuid;
  v_variant_id uuid := nullif(asset_data->>'variant_id', '')::uuid;
  v_asset_type text := lower(nullif(asset_data->>'asset_type', ''));
  v_entity_id uuid;
  v_asset_id uuid;
begin
  if v_auth_user_id is null then raise exception 'Authenticated user is required'; end if;

  select p.id
    into v_profile_id
  from users.profiles p
  where p.auth_user_id = v_auth_user_id;

  if v_profile_id is null then raise exception 'Authenticated user profile is required'; end if;
  if v_farm_id is null or v_variant_id is null then raise exception 'farm_id and variant_id are required'; end if;
  if v_asset_type not in ('crop', 'livestock') then raise exception 'asset_type must be crop or livestock'; end if;
  if v_field_id is null then raise exception 'field_id is required for crop and livestock assets'; end if;

  select f.entity_id into v_entity_id
  from farm_management.farms f
  join core.entities e on e.id = f.entity_id and e.is_active = true
  where f.id = v_farm_id
    and (
      e.owner_id = v_profile_id
      or exists (
        select 1 from core.entity_members m
        where m.entity_id = f.entity_id and m.profile_id = v_profile_id
          and m.is_active = true and m.membership_status = 'active' and m.can_manage = true
      )
      or exists (
        select 1
        from core.entity_roles er join core.user_roles r on r.id = er.role_id
        where er.entity_id = f.entity_id and er.profile_id = v_profile_id and er.is_active = true
          and lower(r.name) in ('owner', 'manager')
      )
    )
  for update;
  if v_entity_id is null then raise exception 'Farm not found or caller is not authorized'; end if;

  if not exists (select 1 from farm_management.fields where id = v_field_id and farm_id = v_farm_id) then
    raise exception 'Field does not belong to the supplied farm';
  end if;
  if not exists (
    select 1 from core.item_variants iv
    join core.items i on i.id = iv.item_id
    join core.categories c on c.id = i.category_id
    where iv.id = v_variant_id
  ) then raise exception 'Variant not found or invalid under the current taxonomy'; end if;

  insert into farm_management.assets (
    entity_id, farm_id, asset_type, variant_id, field_id, status,
    acquired_at, quantity, unit_id, metadata
  ) values (
    v_entity_id, v_farm_id, v_asset_type, v_variant_id, v_field_id,
    coalesce(nullif(asset_data->>'status', ''), 'active'),
    coalesce(nullif(asset_data->>'acquired_at', '')::timestamptz, now()),
    coalesce(nullif(asset_data->>'quantity', '')::numeric, 1),
    nullif(asset_data->>'unit_id', '')::uuid,
    coalesce(asset_data->'metadata', '{}'::jsonb)
  ) returning id into v_asset_id;

  asset_id := v_asset_id;
  entity_id := v_entity_id;
  return next;
end;
$$;


ALTER FUNCTION "farm_management"."create_crop_livestock_asset"("asset_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "farm_management"."create_production_record"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_quantity numeric;
    v_unit_id uuid;
      v_farm_id uuid;
        v_product_id uuid;
        BEGIN

          -- Extract quantity (basic version)
            SELECT av.value_number
              INTO v_quantity
                FROM farm.activity_values av
                  WHERE av.activity_id = NEW.id
                    AND av.value_number IS NOT NULL
                      LIMIT 1;

                        -- ===== CROP =====
                          IF NEW.farm_crop_id IS NOT NULL THEN

                              SELECT farm_id, product_id, unit_id
                                  INTO v_farm_id, v_product_id, v_unit_id
                                      FROM farm.farm_crops
                                          WHERE id = NEW.farm_crop_id;

                                            -- ===== LIVESTOCK =====
                                              ELSIF NEW.farm_livestock_id IS NOT NULL THEN

                                                  SELECT farm_id, product_id, unit_id
                                                      INTO v_farm_id, v_product_id, v_unit_id
                                                          FROM farm.farm_livestock
                                                              WHERE id = NEW.farm_livestock_id;

                                                                END IF;

                                                                  -- Insert production record
                                                                    INSERT INTO farm.production_records (
                                                                        record_id,
                                                                            farm_id,
                                                                                activity_id,
                                                                                    item_id,
                                                                                        quantity,
                                                                                            unit_id,
                                                                                                entity_id,
                                                                                                    created_at
                                                                                                      )
                                                                                                        VALUES (
                                                                                                            gen_random_uuid(),
                                                                                                                v_farm_id,
                                                                                                                    NEW.id,
                                                                                                                        v_product_id,
                                                                                                                            v_quantity,
                                                                                                                                v_unit_id,
                                                                                                                                    NEW.entity_id,
                                                                                                                                        now()
                                                                                                                                          );

                                                                                                                                            RETURN NEW;
                                                                                                                                            END;
                                                                                                                                            $$;


ALTER FUNCTION "farm_management"."create_production_record"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "farm_management"."create_production_record"("p_production_data" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'core', 'farm_management', 'users'
    AS $$
DECLARE
  v_user_id uuid := public.auth_user_id();
  v_activity_id uuid := nullif(p_production_data->>'activity_id', '')::uuid;
  v_activity_entity_id uuid;
  v_activity_asset_id uuid;
  v_asset_entity_id uuid;
  v_asset_farm_id uuid;
  v_asset_field_id uuid;
  v_asset_variant_id uuid;
  v_asset_unit_id uuid;
  v_farm_entity_id uuid;
  v_entity_id uuid;
  v_variant_id uuid;
  v_category_id uuid;
  v_quantity numeric;
  v_unit_id uuid;
  v_source_type farm_management.source_type_enum;
  v_data jsonb;
  v_output_commodity_id uuid;
  v_record_id uuid;
  v_production_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authenticated user is required';
  END IF;
  IF v_activity_id IS NULL THEN
    RAISE EXCEPTION 'activity_id is required';
  END IF;
  IF p_production_data IS NULL OR jsonb_typeof(p_production_data) <> 'object' THEN
    RAISE EXCEPTION 'Production data must be a JSON object';
  END IF;

  SELECT a.entity_id, a.asset_id
    INTO v_activity_entity_id, v_activity_asset_id
  FROM farm_management.activities a
  WHERE a.id = v_activity_id
    AND COALESCE(a.is_deleted, false) = false;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Activity not found';
  END IF;
  IF v_activity_asset_id IS NULL THEN
    RAISE EXCEPTION 'Activity is not linked to an asset';
  END IF;

  SELECT a.entity_id, a.farm_id, a.field_id, a.variant_id, a.unit_id, f.entity_id
    INTO v_asset_entity_id, v_asset_farm_id, v_asset_field_id,
         v_asset_variant_id, v_asset_unit_id, v_farm_entity_id
  FROM farm_management.assets a
  JOIN farm_management.farms f ON f.id = a.farm_id
  WHERE a.id = v_activity_asset_id
  FOR SHARE OF a;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Activity asset or farm not found';
  END IF;
  IF v_activity_entity_id IS DISTINCT FROM v_asset_entity_id
     OR v_asset_entity_id IS DISTINCT FROM v_farm_entity_id THEN
    RAISE EXCEPTION 'Activity, asset, and farm entity context is inconsistent';
  END IF;

  v_entity_id := v_asset_entity_id;

  IF NOT EXISTS (
    SELECT 1
    FROM core.entities e
    WHERE e.id = v_entity_id
      AND e.is_active = true
      AND (
        EXISTS (
          SELECT 1
          FROM users.profiles owner_profile
          WHERE owner_profile.id = e.owner_id
            AND owner_profile.auth_user_id = v_user_id
        )
        OR EXISTS (
          SELECT 1
          FROM core.entity_members m
          JOIN users.profiles member_profile ON member_profile.id = m.profile_id
          WHERE m.entity_id = e.id
            AND member_profile.auth_user_id = v_user_id
            AND m.is_active = true
            AND m.membership_status = 'active'
            AND m.can_manage = true
        )
        OR EXISTS (
          SELECT 1
          FROM core.entity_roles er
          JOIN users.profiles role_profile ON role_profile.id = er.profile_id
          JOIN core.user_roles r ON r.id = er.role_id
          WHERE er.entity_id = e.id
            AND role_profile.auth_user_id = v_user_id
            AND er.is_active = true
            AND lower(r.name) IN ('owner', 'manager')
        )
      )
  ) THEN
    RAISE EXCEPTION 'Activity not found or caller is not authorized for this farm';
  END IF;

  v_quantity := nullif(trim(p_production_data->>'quantity'), '')::numeric;
  IF v_quantity IS NOT NULL AND v_quantity < 0 THEN
    RAISE EXCEPTION 'quantity must be greater than or equal to zero';
  END IF;

  v_data := COALESCE(p_production_data->'data', '{}'::jsonb);
  IF jsonb_typeof(v_data) <> 'object' THEN
    RAISE EXCEPTION 'data must be a JSON object';
  END IF;

  v_unit_id := COALESCE(nullif(p_production_data->>'unit_id', '')::uuid, v_asset_unit_id);
  v_variant_id := v_asset_variant_id;
  v_source_type := COALESCE(NULLIF(p_production_data->>'source_type', ''), 'activity')::farm_management.source_type_enum;
  v_output_commodity_id := nullif(p_production_data->>'output_commodity_id', '')::uuid;
  v_record_id := nullif(p_production_data->>'record_id', '')::uuid;

  IF v_quantity IS NOT NULL AND v_quantity > 0 AND v_output_commodity_id IS NULL THEN
    RAISE EXCEPTION 'output_commodity_id is required when quantity is greater than zero';
  END IF;

  SELECT i.category_id INTO v_category_id
  FROM core.item_variants iv
  JOIN core.items i ON i.id = iv.item_id
  WHERE iv.id = v_variant_id;

  INSERT INTO farm_management.production_records (
    data, farm_id, activity_id, variant_id, quantity, unit_id,
    entity_id, category_id, asset_id, field_id, source_type,
    record_id, activity_ref, output_commodity_id
  )
  VALUES (
    v_data, v_asset_farm_id, v_activity_id, v_variant_id, v_quantity, v_unit_id,
    v_entity_id, v_category_id, v_activity_asset_id, v_asset_field_id, v_source_type,
    v_record_id, v_activity_id, v_output_commodity_id
  )
  RETURNING id INTO v_production_id;

  RETURN v_production_id;
END;
$$;


ALTER FUNCTION "farm_management"."create_production_record"("p_production_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "farm_management"."create_production_record"("p_record_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  r RECORD;
  BEGIN

    SELECT * INTO r FROM farm.production_records WHERE id = p_record_id;

      PERFORM commerce.apply_stock_movement(
          ROW(
                r.variant_id,
                      COALESCE(r.quantity,0),
                            'harvest',
                                  'farm',
                                        'production',
                                              p_record_id,
                                                    NULL,
                                                          NULL,
                                                                NULL,
                                                                      r.data
                                                                          )::commerce.stock_event_type
                                                                            );

                                                                            END;
                                                                            $$;


