CREATE OR REPLACE FUNCTION "farm_management"."refresh_farm_kpis"("p_farm_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_production numeric;
        v_income numeric;
            v_expense numeric;
            BEGIN

                SELECT COALESCE(SUM(quantity),0)
                    INTO v_production
                        FROM farm.production_records
                            WHERE farm_id = p_farm_id;

                                SELECT COALESCE(SUM(change_quantity),0)
                                    INTO v_income
                                        FROM farm.stock_transactions
                                            WHERE farm_id = p_farm_id
                                                AND change_type = 'IN';

                                                    SELECT COALESCE(SUM(change_quantity),0)
                                                        INTO v_expense
                                                            FROM farm.stock_transactions
                                                                WHERE farm_id = p_farm_id
                                                                    AND change_type = 'OUT';

                                                                        INSERT INTO farm.farm_kpis (
                                                                                farm_id,
                                                                                        total_production,
                                                                                                total_income,
                                                                                                        total_expense,
                                                                                                                profit,
                                                                                                                        last_updated
                                                                                                                            )
                                                                                                                                VALUES (
                                                                                                                                        p_farm_id,
                                                                                                                                                v_production,
                                                                                                                                                        v_income,
                                                                                                                                                                v_expense,
                                                                                                                                                                        (v_income - v_expense),
                                                                                                                                                                                now()
                                                                                                                                                                                    )
                                                                                                                                                                                        ON CONFLICT (farm_id)
                                                                                                                                                                                            DO UPDATE SET
                                                                                                                                                                                                    total_production = EXCLUDED.total_production,
                                                                                                                                                                                                            total_income = EXCLUDED.total_income,
                                                                                                                                                                                                                    total_expense = EXCLUDED.total_expense,
                                                                                                                                                                                                                            profit = EXCLUDED.profit,
                                                                                                                                                                                                                                    last_updated = now();

                                                                                                                                                                                                                                    END;
                                                                                                                                                                                                                                    $$;


ALTER FUNCTION "farm_management"."refresh_farm_kpis"("p_farm_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "farm_management"."refresh_production_farm_kpi"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'farm_management'
    AS $$
DECLARE
  v_farm_id uuid;
  v_total_production numeric;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_farm_id := OLD.farm_id;
  ELSE
    v_farm_id := NEW.farm_id;
  END IF;

  SELECT COALESCE(SUM(pr.quantity), 0)
    INTO v_total_production
  FROM farm_management.production_records pr
  WHERE pr.farm_id = v_farm_id;

  INSERT INTO farm_management.farm_kpis (farm_id, total_production, last_updated)
  VALUES (v_farm_id, v_total_production, now())
  ON CONFLICT (farm_id) DO UPDATE
  SET total_production = EXCLUDED.total_production,
      last_updated = EXCLUDED.last_updated;

  IF TG_OP = 'UPDATE' AND NEW.farm_id IS DISTINCT FROM OLD.farm_id THEN
    SELECT COALESCE(SUM(pr.quantity), 0)
      INTO v_total_production
    FROM farm_management.production_records pr
    WHERE pr.farm_id = OLD.farm_id;

    INSERT INTO farm_management.farm_kpis (farm_id, total_production, last_updated)
    VALUES (OLD.farm_id, v_total_production, now())
    ON CONFLICT (farm_id) DO UPDATE
    SET total_production = EXCLUDED.total_production,
        last_updated = EXCLUDED.last_updated;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "farm_management"."refresh_production_farm_kpi"() OWNER TO "postgres";


