CREATE OR REPLACE FUNCTION "farm_management"."sync_activity_to_core"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_domain_id uuid;
  v_category_id uuid;
BEGIN
  SELECT id INTO v_domain_id FROM core.domains WHERE name = 'Agriculture' LIMIT 1;
  SELECT category_id INTO v_category_id FROM core.items
  WHERE id = COALESCE(NEW.farm_crop_id, NEW.farm_livestock_id) LIMIT 1;

  IF NEW.record_id IS NULL THEN
    INSERT INTO core.records
      (domain_id, category_id, owner_id, module, activity_type_id, entity_id)
    VALUES
      (v_domain_id, v_category_id, core.current_profile_id(), 'farm_logs',
       NEW.activity_type_id, NEW.entity_id)
    RETURNING id INTO NEW.record_id;
  END IF;
  RETURN NEW;
END;
$$;


