CREATE OR REPLACE FUNCTION "farm_management"."sync_production_to_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'farm_management', 'commerce', 'core'
    AS $$
DECLARE
  v_stock_id uuid;
  v_product_id uuid;
  v_location_id uuid;
BEGIN
  IF NEW.quantity IS NULL OR NEW.quantity <= 0 THEN
    RETURN NEW;
  END IF;

  IF NEW.entity_id IS NULL
     OR NEW.variant_id IS NULL
     OR NEW.unit_id IS NULL
     OR NEW.output_commodity_id IS NULL THEN
    RAISE EXCEPTION
      'Cannot sync production record % to stock: entity_id, variant_id, unit_id, and output_commodity_id are required',
      NEW.id;
  END IF;

  SELECT COALESCE(f.ward_id, f.sub_county_id, f.county_id)
    INTO v_location_id
  FROM farm_management.farms AS f
  WHERE f.id = NEW.farm_id;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION
      'Cannot sync production record % to stock: farm location is required',
      NEW.id;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      concat_ws(':', NEW.entity_id::text, NEW.output_commodity_id::text,
                NEW.variant_id::text, NEW.unit_id::text, v_location_id::text),
      0
    )
  );

  SELECT c.item_id
    INTO v_product_id
  FROM core.commodities AS c
  WHERE c.id = NEW.output_commodity_id;

  SELECT sr.id
    INTO v_stock_id
  FROM commerce.stock_registry AS sr
  WHERE sr.entity_id = NEW.entity_id
    AND sr.commodity_id = NEW.output_commodity_id
    AND sr.variant_id = NEW.variant_id
    AND sr.unit_id = NEW.unit_id
    AND sr.location_id = v_location_id
  ORDER BY sr.created_at, sr.id
  LIMIT 1
  FOR UPDATE;

  IF v_stock_id IS NULL THEN
    INSERT INTO commerce.stock_registry (
      entity_id,
      variant_id,
      product_id,
      location_id,
      quantity,
      reserved_quantity,
      unit_id,
      status,
      commodity_id,
      metadata
    )
    VALUES (
      NEW.entity_id,
      NEW.variant_id,
      v_product_id,
      v_location_id,
      0,
      0,
      NEW.unit_id,
      'active',
      NEW.output_commodity_id,
      jsonb_build_object('created_from', 'production_record', 'source_record_id', NEW.id)
    )
    RETURNING id INTO v_stock_id;
  END IF;

  INSERT INTO commerce.stock_movements (
    stock_id,
    quantity_change,
    movement_type,
    source_module,
    source_type,
    source_ref_id,
    entity_id,
    metadata
  )
  VALUES (
    v_stock_id,
    NEW.quantity,
    'harvest',
    'farm',
    'production_record',
    NEW.id,
    NEW.entity_id,
    jsonb_build_object('production_record_id', NEW.id)
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "farm_management"."sync_production_to_stock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "farm_management"."tr_process_activity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN

  PERFORM commerce.apply_stock_movement(
      ROW(
            NEW.asset_id,
                  CASE WHEN NEW.activity_type_id IS NULL THEN 0 ELSE 1 END,
                        'adjustment',
                              'farm',
                                    'activity',
                                          NEW.id,
                                                NULL,
                                                      NULL,
                                                            NULL,
                                                                  jsonb_build_object('activity', NEW.activity_type_id)
                                                                      )::commerce.stock_event_type
                                                                        );

                                                                          RETURN NEW;
                                                                          END;
                                                                          $$;


