BEGIN
  IF NEW.record_id IS NULL THEN
    INSERT INTO core.records
      (domain_id, category_id, owner_id, module, status, activity_type_id, entity_id)
    VALUES
      ((SELECT id FROM core.domains WHERE name = 'Agriculture'),
       (SELECT category_id FROM core.items
        WHERE id = COALESCE(NEW.farm_crop_id, NEW.farm_livestock_id) LIMIT 1),
       core.current_profile_id(), 'farm_logs', 'active',
       NEW.activity_type_id, NEW.entity_id)
    RETURNING id INTO v_record_id;

    NEW.record_id = v_record_id;
  END IF;
  RETURN NEW;
END;
$$;


