CREATE OR REPLACE FUNCTION "farm_management"."update_farm_kpis"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   BEGIN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     INSERT INTO farm.farm_kpis (farm_id, total_income, total_expense, last_updated)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       VALUES (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           NEW.farm_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               CASE WHEN NEW.record_type = 'income' THEN NEW.amount ELSE 0 END,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   CASE WHEN NEW.record_type = 'expense' THEN NEW.amount ELSE 0 END,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           ON CONFLICT (farm_id)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             DO UPDATE SET
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 total_income = farm.farm_kpis.total_income +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       CASE WHEN NEW.record_type = 'income' THEN NEW.amount ELSE 0 END,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           total_expense = farm.farm_kpis.total_expense +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 CASE WHEN NEW.record_type = 'expense' THEN NEW.amount ELSE 0 END,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     profit = (farm.farm_kpis.total_income -
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   farm.farm_kpis.total_expense),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       last_updated = now();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         RETURN NEW;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         END;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         $$;


ALTER FUNCTION "farm_management"."update_farm_kpis"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "farm_management"."validate_activity_attributes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    missing_count int;
    BEGIN

        SELECT COUNT(*) INTO missing_count
            FROM farm.activity_attribute_rules r
                LEFT JOIN farm.activity_values v
                        ON v.activity_id = NEW.id
                               AND v.attribute_id = r.attribute_id
                                   WHERE r.activity_type_id = NEW.activity_type_id
                                         AND r.is_required = true
                                               AND v.id IS NULL;

                                                   IF missing_count > 0 THEN
                                                           RAISE EXCEPTION 'Missing required attributes for activity';
                                                               END IF;

                                                                   RETURN NEW;
                                                                   END;
                                                                   $$;


ALTER FUNCTION "farm_management"."validate_activity_attributes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "farm_management"."validate_activity_mapping"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    is_valid boolean;
    BEGIN

        -- Check variant first
            IF NEW.variant_id IS NOT NULL THEN
                    SELECT EXISTS (
                                SELECT 1
                                            FROM farm.item_variant_activity_map
                                                        WHERE variant_id = NEW.variant_id
                                                                      AND activity_type_id = NEW.activity_type_id
                                                                                    AND is_enabled = true
                                                                                            ) INTO is_valid;

                                                                                                    IF is_valid THEN
                                                                                                                RETURN NEW;
                                                                                                                        END IF;
                                                                                                                            END IF;

                                                                                                                                -- Fallback to item
                                                                                                                                    SELECT EXISTS (
                                                                                                                                            SELECT 1
                                                                                                                                                    FROM farm.item_activity_map
                                                                                                                                                            WHERE item_id = NEW.item_id
                                                                                                                                                                      AND activity_type_id = NEW.activity_type_id
                                                                                                                                                                          ) INTO is_valid;

                                                                                                                                                                              IF NOT is_valid THEN
                                                                                                                                                                                      RAISE EXCEPTION 'Invalid activity for item/variant';
                                                                                                                                                                                          END IF;

                                                                                                                                                                                              RETURN NEW;
                                                                                                                                                                                              END;
                                                                                                                                                                                              $$;


ALTER FUNCTION "farm_management"."validate_activity_mapping"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "farm_management"."validate_activity_record"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  attr RECORD;
    val RECORD;
    BEGIN
      -- Only validate farm activities
        IF NEW.module <> 'farm' THEN
            RETURN NEW;
              END IF;

                -- Loop required attributes for this activity
                  FOR attr IN
                      SELECT ar.id, ar.name, ar.data_type
                          FROM core.attribute_registry ar
                              WHERE ar.activity_type_id = NEW.activity_type_id
                                    AND ar.attribute_level = 'record'
                                      LOOP

                                          SELECT * INTO val
                                              FROM core.record_attributes
                                                  WHERE record_id = NEW.id
                                                        AND attribute_id = attr.id;

                                                            IF val IS NULL THEN
                                                                  RAISE EXCEPTION 'Missing required attribute: %', attr.name;
                                                                      END IF;

                                                                          -- Type enforcement (basic)
                                                                              IF attr.data_type = 'number' AND val.value_number IS NULL THEN
                                                                                    RAISE EXCEPTION 'Attribute % requires numeric value', attr.name;
                                                                                        END IF;

                                                                                            IF attr.data_type = 'text' AND val.value_text IS NULL THEN
                                                                                                  RAISE EXCEPTION 'Attribute % requires text value', attr.name;
                                                                                                      END IF;

                                                                                                        END LOOP;

                                                                                                          RETURN NEW;
                                                                                                          END;
                                                                                                          $$;


ALTER FUNCTION "farm_management"."validate_activity_record"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "farm_management"."validate_activity_value"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    attr_type TEXT;
    BEGIN

        SELECT data_type INTO attr_type
            FROM core.attribute_registry
                WHERE id = NEW.attribute_id;

                    IF attr_type IS NULL THEN
                            RAISE EXCEPTION 'Invalid attribute';
                                END IF;

                                    IF attr_type = 'text' AND NEW.value_text IS NULL THEN
                                            RAISE EXCEPTION 'Expected text';
                                                ELSIF attr_type = 'number' AND NEW.value_number IS NULL THEN
                                                        RAISE EXCEPTION 'Expected number';
                                                            ELSIF attr_type = 'boolean' AND NEW.value_boolean IS NULL THEN
                                                                    RAISE EXCEPTION 'Expected boolean';
                                                                        ELSIF attr_type = 'enum' AND NEW.enum_value_id IS NULL THEN
                                                                                RAISE EXCEPTION 'Expected enum';
                                                                                    END IF;

                                                                                        RETURN NEW;
                                                                                        END;
                                                                                        $$;


