        SELECT EXISTS (
                SELECT 1
                        FROM farm.activity_workflow w
                                WHERE w.activity_type_id = NEW.activity_type_id
                                          AND w.is_required = true
                                              ) INTO required_exists;

                                                  IF required_exists THEN
                                                          -- You can extend logic later (step validation)
                                                                  NULL;
                                                                      END IF;

                                                                          RETURN NEW;
                                                                          END;
                                                                          $$;


