CREATE OR REPLACE FUNCTION "farm_management"."validate_asset_entity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.asset_id IS NOT NULL THEN
      IF NOT EXISTS (
            SELECT 1 FROM farm.assets a
                  WHERE a.id = NEW.asset_id
                        AND a.entity_id = NEW.entity_id
                            ) THEN
                                  RAISE EXCEPTION 'Asset does not belong to entity';
                                      END IF;
                                        END IF;

                                          RETURN NEW;
                                          END;
                                          $$;


