CREATE OR REPLACE FUNCTION "farm_management"."validate_production_output_commodity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Enforce explicit production output commodity; never infer from variant.
  IF NEW.quantity IS NOT NULL AND NEW.quantity > 0 THEN
    IF NEW.output_commodity_id IS NULL THEN
      RAISE EXCEPTION 'Production output commodity must be explicitly set (output_commodity_id is NULL) for production_record id=%', NEW.id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


