    IF NOT core.validate_item_unit(
            NEW.item_id,
                    NEW.variant_id,
                            NEW.unit_id
                                ) THEN
                                        RAISE EXCEPTION 
                                                'Invalid unit for item/variant. item_id=% variant_id=% unit_id=%',
                                                        NEW.item_id, NEW.variant_id, NEW.unit_id;
                                                            END IF;

                                                                RETURN NEW;
                                                                END;
                                                                $$;


