CREATE OR REPLACE FUNCTION "farm_management"."validate_record_attribute"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  attr RECORD;
    rec RECORD;
    BEGIN
      SELECT * INTO attr
        FROM core.attribute_registry
          WHERE id = NEW.attribute_id;

            SELECT * INTO rec
              FROM core.records
                WHERE id = NEW.record_id;

                  -- Ensure attribute belongs to activity
                    IF attr.activity_type_id IS NOT NULL
                         AND attr.activity_type_id <> rec.activity_type_id THEN
                             RAISE EXCEPTION 'Attribute not allowed for this activity';
                               END IF;

                                 RETURN NEW;
                                 END;
                                 $$;


