CREATE OR REPLACE FUNCTION "knowledge"."_assert_editable_version"("p_version_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_resource_id uuid; v_status text;
BEGIN
  SELECT v.resource_id INTO v_resource_id FROM knowledge.resource_versions v WHERE v.id=p_version_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='Knowledge version not found'; END IF;
  PERFORM knowledge._lock_resource(v_resource_id,'knowledge.edit',false);
  SELECT v.status INTO v_status FROM knowledge.resource_versions v WHERE v.id=p_version_id AND v.resource_id=v_resource_id FOR UPDATE;
  IF NOT FOUND OR v_status NOT IN ('draft','review') THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='Only draft or review versions can be edited';
  END IF;
  RETURN v_resource_id;
END; $$;


ALTER FUNCTION "knowledge"."_assert_editable_version"("p_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."_audit"("p_action" "text", "p_old" "jsonb", "p_new" "jsonb", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor uuid;
  v_context jsonb;
  v_active_entity_id uuid;
  v_resource_id uuid;
  v_entity_id uuid;
  v_old jsonb := p_old;
  v_new jsonb := p_new;
BEGIN
  v_actor := core.current_profile_id();
  v_context := core.get_effective_context();
  v_active_entity_id := nullif(v_context #>> '{active_entity,id}', '')::uuid;
  v_resource_id := COALESCE(
    nullif(p_new->>'resource_id','')::uuid,
    nullif(p_old->>'resource_id','')::uuid,
    nullif(p_new->>'id','')::uuid,
    nullif(p_old->>'id','')::uuid
  );
  IF v_resource_id IS NOT NULL THEN
    SELECT r.owned_by_entity_id INTO v_entity_id
    FROM knowledge.resources AS r WHERE r.id = v_resource_id;
  END IF;
  IF v_old IS NOT NULL THEN
    v_old := v_old || jsonb_build_object(
      'active_entity_id', v_active_entity_id,
      'entity_id', v_entity_id
    );
  END IF;
  IF v_new IS NOT NULL THEN
    v_new := v_new || jsonb_build_object(
      'active_entity_id', v_active_entity_id,
      'entity_id', v_entity_id
    );
  END IF;
  INSERT INTO system.module_audit_logs(id,module_key,action_type,old_value,new_value,changed_by,reason)
  VALUES(gen_random_uuid(),'knowledge',p_action,v_old,v_new,v_actor,p_reason);
END;
$$;


ALTER FUNCTION "knowledge"."_audit"("p_action" "text", "p_old" "jsonb", "p_new" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."_has_entity_permission"("p_permission" "text", "p_entity_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_context jsonb;
  v_active_entity_id uuid;
BEGIN
  IF auth.uid() IS NULL OR p_entity_id IS NULL THEN
    RETURN false;
  END IF;
  v_context := core.get_effective_context();
  v_active_entity_id := nullif(v_context #>> '{active_entity,id}', '')::uuid;
  RETURN v_active_entity_id = p_entity_id
     AND core.has_permission(p_permission);
END;
$$;


ALTER FUNCTION "knowledge"."_has_entity_permission"("p_permission" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."_has_global_permission"("p_permission" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT auth.uid() IS NOT NULL AND EXISTS (
    SELECT 1
    FROM users.profiles AS pr
    JOIN core.entity_role_scopes AS ers
      ON ers.profile_id = pr.id
     AND ers.scope_type = 'global'
     AND ers.entity_id IS NULL
     AND ers.module IS NULL
    JOIN core.user_roles AS ur
      ON ur.id = ers.role_id
     AND ur.is_active = true
    JOIN core.role_permissions AS rp
      ON rp.role_id = ur.id
     AND rp.is_active = true
    JOIN core.permissions AS perm
      ON perm.id = rp.permission_id
     AND perm.code = p_permission
     AND perm.module = 'knowledge'
    WHERE pr.auth_user_id = auth.uid()
      AND pr.is_active = true
      AND pr.account_status = 'active'
      AND p_permission LIKE 'knowledge.%'
  );
$$;


ALTER FUNCTION "knowledge"."_has_global_permission"("p_permission" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "knowledge"."resources" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "resource_type_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "slug" "text" NOT NULL,
    "summary" "text",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "visibility" "text" DEFAULT 'public'::"text" NOT NULL,
    "is_featured" boolean DEFAULT false NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "owned_by_entity_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "published_at" timestamp with time zone,
    "archived_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "knowledge_resources_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'review'::"text", 'approved'::"text", 'published'::"text", 'archived'::"text"]))),
    CONSTRAINT "knowledge_resources_visibility_check" CHECK (("visibility" = ANY (ARRAY['public'::"text", 'restricted'::"text", 'private'::"text"])))
);


ALTER TABLE "knowledge"."resources" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."_lock_resource"("p_resource_id" "uuid", "p_permission" "text" DEFAULT 'knowledge.edit'::"text", "p_draft_only" boolean DEFAULT false) RETURNS "knowledge"."resources"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_resource knowledge.resources%ROWTYPE;
BEGIN
  SELECT r.* INTO v_resource
  FROM knowledge.resources AS r
  WHERE r.id = p_resource_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='Knowledge resource not found';
  END IF;
  PERFORM knowledge._require_resource_permission(p_permission, p_resource_id);
  IF v_resource.status = 'archived' OR NOT v_resource.is_active THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='Archived or inactive resources cannot be edited';
  END IF;
  IF p_draft_only AND v_resource.status NOT IN ('draft','review') THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='Resource metadata is editable only while draft or in review';
  END IF;
  RETURN v_resource;
END;
$$;


ALTER FUNCTION "knowledge"."_lock_resource"("p_resource_id" "uuid", "p_permission" "text", "p_draft_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."_require_permission"("p_permission" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Authentication required';
  END IF;
  v_actor := core.current_profile_id();
  IF v_actor IS NULL OR NOT knowledge._has_global_permission(p_permission) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE=format('Platform Knowledge permission denied: %s', p_permission);
  END IF;
  RETURN v_actor;
END;
$$;


ALTER FUNCTION "knowledge"."_require_permission"("p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."_require_resource_permission"("p_permission" "text", "p_resource_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor uuid;
  v_owner_entity_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Authentication required';
  END IF;
  v_actor := core.current_profile_id();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Active profile required';
  END IF;
  SELECT r.owned_by_entity_id INTO v_owner_entity_id
  FROM knowledge.resources AS r
  WHERE r.id = p_resource_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='Knowledge resource not found';
  END IF;
  IF knowledge._has_global_permission(p_permission) THEN
    RETURN v_actor;
  END IF;
  IF v_owner_entity_id IS NOT NULL
     AND knowledge._has_entity_permission(p_permission, v_owner_entity_id) THEN
    RETURN v_actor;
  END IF;
  RAISE EXCEPTION USING ERRCODE='42501', MESSAGE=format('Permission denied for this Knowledge resource: %s', p_permission);
END;
$$;


ALTER FUNCTION "knowledge"."_require_resource_permission"("p_permission" "text", "p_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."_resolve_creation_owner"("p_permission" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor uuid;
  v_context jsonb;
  v_active_entity_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Authentication required';
  END IF;
  v_actor := core.current_profile_id();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Active profile required';
  END IF;
  v_context := core.get_effective_context();
  v_active_entity_id := nullif(v_context #>> '{active_entity,id}', '')::uuid;
  IF v_active_entity_id IS NOT NULL
     AND knowledge._has_entity_permission(p_permission, v_active_entity_id) THEN
    RETURN v_active_entity_id;
  END IF;
  IF knowledge._has_global_permission(p_permission) THEN
    RETURN NULL;
  END IF;
  RAISE EXCEPTION USING ERRCODE='42501', MESSAGE=format('Permission denied: %s', p_permission);
END;
$$;


ALTER FUNCTION "knowledge"."_resolve_creation_owner"("p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."approve_version"("p_version_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_resource_id uuid;
  v_status text;
  v_actor uuid;
BEGIN
  SELECT v.resource_id INTO v_resource_id
  FROM knowledge.resource_versions AS v WHERE v.id=p_version_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='Knowledge version not found'; END IF;
  PERFORM knowledge._lock_resource(v_resource_id,'knowledge.approve',false);
  SELECT v.status INTO v_status
  FROM knowledge.resource_versions AS v
  WHERE v.id=p_version_id AND v.resource_id=v_resource_id
  FOR UPDATE;
  IF NOT FOUND OR v_status <> 'review' THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Only reviewed versions may be approved';
  END IF;
  v_actor := core.current_profile_id();
  UPDATE knowledge.resource_versions
  SET status='approved',reviewed_by=v_actor,reviewed_at=now()
  WHERE id=p_version_id;
  UPDATE knowledge.resources SET status='approved'
  WHERE id=v_resource_id AND status='review';
  PERFORM knowledge._audit('version_approved',
    jsonb_build_object('resource_id',v_resource_id,'version_id',p_version_id,'status','review'),
    jsonb_build_object('resource_id',v_resource_id,'version_id',p_version_id,'status','approved','reviewed_by',v_actor),NULL);
END;
$$;


ALTER FUNCTION "knowledge"."approve_version"("p_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."archive_resource"("p_resource_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_old knowledge.resources%ROWTYPE;
  v_actor uuid;
BEGIN
  v_old := knowledge._lock_resource(p_resource_id,'knowledge.archive',false);
  v_actor := core.current_profile_id();
  UPDATE knowledge.resources
  SET status='archived',is_active=false,archived_at=now()
  WHERE id=p_resource_id;
  PERFORM knowledge._audit('resource_archived',to_jsonb(v_old),
    jsonb_build_object('resource_id',p_resource_id,'status','archived','is_active',false,'archived_by',v_actor),p_reason);
END;
$$;


ALTER FUNCTION "knowledge"."archive_resource"("p_resource_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."create_resource"("p_resource_type_id" "uuid", "p_title" "text", "p_slug" "text", "p_summary" "text" DEFAULT NULL::"text", "p_visibility" "text" DEFAULT 'public'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_actor uuid;
  v_owner_entity_id uuid;
  v_resource_id uuid;
  v_version_id uuid;
BEGIN
  v_actor := core.current_profile_id();
  v_owner_entity_id := knowledge._resolve_creation_owner('knowledge.create');
  IF nullif(btrim(p_title),'') IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Title is required'; END IF;
  IF p_slug IS NULL OR p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Slug must be lowercase alphanumeric words separated by hyphens'; END IF;
  IF p_visibility NOT IN ('public','restricted','private') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid resource visibility'; END IF;
  IF p_metadata IS NULL OR jsonb_typeof(p_metadata)<>'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Metadata must be a JSON object'; END IF;
  IF NOT EXISTS(SELECT 1 FROM knowledge.resource_types t WHERE t.id=p_resource_type_id AND t.is_active) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Resource type is unknown or inactive'; END IF;
  INSERT INTO knowledge.resources(resource_type_id,title,slug,summary,status,visibility,created_by,owned_by_entity_id,metadata)
  VALUES(p_resource_type_id,btrim(p_title),p_slug,p_summary,'draft',p_visibility,v_actor,v_owner_entity_id,p_metadata)
  RETURNING id INTO v_resource_id;
  INSERT INTO knowledge.resource_versions(resource_id,version_number,status,title,summary,created_by,metadata)
  VALUES(v_resource_id,1,'draft',btrim(p_title),p_summary,v_actor,p_metadata)
  RETURNING id INTO v_version_id;
  PERFORM knowledge._audit('resource_created',NULL,jsonb_build_object(
    'resource_id',v_resource_id,'version_id',v_version_id,'slug',p_slug
  ),'Initial draft created');
  RETURN jsonb_build_object(
    'resource_id',v_resource_id,'version_id',v_version_id,'version_number',1,
    'owned_by_entity_id',v_owner_entity_id
  );
END;
$_$;


ALTER FUNCTION "knowledge"."create_resource"("p_resource_type_id" "uuid", "p_title" "text", "p_slug" "text", "p_summary" "text", "p_visibility" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."create_version"("p_resource_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_summary" "text" DEFAULT NULL::"text", "p_change_summary" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor uuid;
  v_resource knowledge.resources%ROWTYPE;
  v_num integer;
  v_version_id uuid;
BEGIN
  v_resource := knowledge._lock_resource(p_resource_id,'knowledge.edit',false);
  v_actor := core.current_profile_id();
  IF p_metadata IS NULL OR jsonb_typeof(p_metadata)<>'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Metadata must be a JSON object'; END IF;
  SELECT COALESCE(max(version_number),0)+1 INTO v_num
  FROM knowledge.resource_versions WHERE resource_id=p_resource_id;
  INSERT INTO knowledge.resource_versions(resource_id,version_number,status,title,summary,change_summary,created_by,metadata)
  VALUES(p_resource_id,v_num,'draft',p_title,p_summary,p_change_summary,v_actor,p_metadata)
  RETURNING id INTO v_version_id;
  IF v_resource.status <> 'published' THEN
    UPDATE knowledge.resources SET status='draft' WHERE id=p_resource_id;
  END IF;
  PERFORM knowledge._audit('version_created',NULL,jsonb_build_object(
    'resource_id',p_resource_id,'version_id',v_version_id,'version_number',v_num
  ),'New immutable-history version opened as draft');
  RETURN jsonb_build_object('resource_id',p_resource_id,'version_id',v_version_id,'version_number',v_num);
END;
$$;


ALTER FUNCTION "knowledge"."create_version"("p_resource_id" "uuid", "p_title" "text", "p_summary" "text", "p_change_summary" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."delete_content_block"("p_section_id" "uuid", "p_block_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_version_id uuid; v_resource_id uuid;
BEGIN
  SELECT s.resource_version_id INTO v_version_id FROM knowledge.sections s WHERE s.id=p_section_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='Section not found'; END IF;
  v_resource_id:=knowledge._assert_editable_version(v_version_id);
  DELETE FROM knowledge.content_blocks WHERE id=p_block_id AND section_id=p_section_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Block does not belong to the specified section/version'; END IF;
  PERFORM knowledge._audit('content_block_deleted',jsonb_build_object('resource_id',v_resource_id,'version_id',v_version_id,'section_id',p_section_id,'block_id',p_block_id),NULL,NULL);
END; $$;


ALTER FUNCTION "knowledge"."delete_content_block"("p_section_id" "uuid", "p_block_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."delete_section"("p_version_id" "uuid", "p_section_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_resource_id uuid;
BEGIN
  v_resource_id:=knowledge._assert_editable_version(p_version_id);
  DELETE FROM knowledge.sections WHERE id=p_section_id AND resource_version_id=p_version_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Section does not belong to the specified version'; END IF;
  PERFORM knowledge._audit('section_deleted',jsonb_build_object('resource_id',v_resource_id,'version_id',p_version_id,'section_id',p_section_id),NULL,NULL);
END; $$;


ALTER FUNCTION "knowledge"."delete_section"("p_version_id" "uuid", "p_section_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."manage_source"("p_source_id" "uuid", "p_name" "text", "p_source_type" "text", "p_organization_name" "text" DEFAULT NULL::"text", "p_author_name" "text" DEFAULT NULL::"text", "p_title" "text" DEFAULT NULL::"text", "p_url" "text" DEFAULT NULL::"text", "p_citation" "text" DEFAULT NULL::"text", "p_published_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_is_verified" boolean DEFAULT false, "p_is_active" boolean DEFAULT true, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid; v_id uuid; v_old jsonb;
BEGIN
  v_actor:=knowledge._require_permission('knowledge.manage_sources');
  IF nullif(btrim(p_name),'') IS NULL OR p_source_type IS NULL OR p_metadata IS NULL OR jsonb_typeof(p_metadata)<>'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Source name, type, and object metadata are required'; END IF;
  IF p_source_id IS NULL THEN
    INSERT INTO knowledge.sources(name,source_type,organization_name,author_name,title,url,citation,published_at,is_verified,is_active,metadata)
    VALUES(btrim(p_name),p_source_type,p_organization_name,p_author_name,p_title,p_url,p_citation,p_published_at,COALESCE(p_is_verified,false),COALESCE(p_is_active,true),p_metadata) RETURNING id INTO v_id;
  ELSE
    SELECT to_jsonb(s) INTO v_old FROM knowledge.sources s WHERE s.id=p_source_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='Knowledge source not found'; END IF;
    UPDATE knowledge.sources SET name=btrim(p_name),source_type=p_source_type,organization_name=p_organization_name,author_name=p_author_name,title=p_title,url=p_url,citation=p_citation,published_at=p_published_at,is_verified=COALESCE(p_is_verified,false),is_active=COALESCE(p_is_active,true),metadata=p_metadata WHERE id=p_source_id;
    v_id:=p_source_id;
  END IF;
  PERFORM knowledge._audit(CASE WHEN p_source_id IS NULL THEN 'source_created' ELSE 'source_updated' END,v_old,jsonb_build_object('source_id',v_id,'name',p_name,'source_type',p_source_type,'organization_name',p_organization_name,'author_name',p_author_name,'title',p_title,'url',p_url,'citation',p_citation,'published_at',p_published_at,'is_verified',p_is_verified,'is_active',p_is_active,'metadata',p_metadata),'Source managed by authorized user');
  RETURN v_id;
END; $$;


ALTER FUNCTION "knowledge"."manage_source"("p_source_id" "uuid", "p_name" "text", "p_source_type" "text", "p_organization_name" "text", "p_author_name" "text", "p_title" "text", "p_url" "text", "p_citation" "text", "p_published_at" timestamp with time zone, "p_is_verified" boolean, "p_is_active" boolean, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."publish_version"("p_version_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_resource_id uuid;
  v_old_version_id uuid;
  v_version knowledge.resource_versions%ROWTYPE;
  v_resource knowledge.resources%ROWTYPE;
  v_actor uuid;
BEGIN
  SELECT v.resource_id INTO v_resource_id
  FROM knowledge.resource_versions AS v WHERE v.id=p_version_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='Knowledge version not found'; END IF;
  v_resource := knowledge._lock_resource(v_resource_id,'knowledge.publish',false);
  SELECT v.* INTO v_version
  FROM knowledge.resource_versions AS v
  WHERE v.id=p_version_id AND v.resource_id=v_resource_id
  FOR UPDATE;
  IF NOT FOUND OR v_version.status <> 'approved' THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Only approved versions may be published';
  END IF;
  SELECT v.id INTO v_old_version_id
  FROM knowledge.resource_versions AS v
  WHERE v.resource_id=v_resource_id AND v.status='published' AND v.id<>p_version_id
  ORDER BY v.version_number DESC LIMIT 1 FOR UPDATE;
  UPDATE knowledge.resource_versions SET status='superseded'
  WHERE resource_id=v_resource_id AND status='published' AND id<>p_version_id;
  UPDATE knowledge.resource_versions SET status='published',published_at=now() WHERE id=p_version_id;
  UPDATE knowledge.resources
  SET status='published',is_active=true,published_at=now(),
      title=COALESCE(v_version.title,title),summary=COALESCE(v_version.summary,summary)
  WHERE id=v_resource_id;
  v_actor := core.current_profile_id();
  PERFORM knowledge._audit('version_published',
    jsonb_build_object('resource_id',v_resource_id,'previous_version_id',v_old_version_id),
    jsonb_build_object('resource_id',v_resource_id,'version_id',p_version_id,'version_number',v_version.version_number,'published_by',v_actor),NULL);
END;
$$;


ALTER FUNCTION "knowledge"."publish_version"("p_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."reject_version"("p_version_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_resource_id uuid;
  v_status text;
  v_actor uuid;
BEGIN
  SELECT v.resource_id INTO v_resource_id
  FROM knowledge.resource_versions AS v WHERE v.id=p_version_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='Knowledge version not found'; END IF;
  PERFORM knowledge._lock_resource(v_resource_id,'knowledge.review',false);
  SELECT v.status INTO v_status
  FROM knowledge.resource_versions AS v
  WHERE v.id=p_version_id AND v.resource_id=v_resource_id
  FOR UPDATE;
  IF NOT FOUND OR v_status <> 'review' THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Only reviewed versions may be rejected';
  END IF;
  v_actor := core.current_profile_id();
  UPDATE knowledge.resource_versions
  SET status='rejected',reviewed_by=v_actor,reviewed_at=now()
  WHERE id=p_version_id;
  UPDATE knowledge.resources SET status='draft'
  WHERE id=v_resource_id AND status='review';
  PERFORM knowledge._audit('version_rejected',
    jsonb_build_object('resource_id',v_resource_id,'version_id',p_version_id,'status','review'),
    jsonb_build_object('resource_id',v_resource_id,'version_id',p_version_id,'status','rejected','reviewed_by',v_actor),p_reason);
END;
$$;


ALTER FUNCTION "knowledge"."reject_version"("p_version_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."set_resource_relationship"("p_resource_id" "uuid", "p_kind" "text", "p_target_id" "uuid", "p_action" "text" DEFAULT 'link'::"text", "p_relationship_type" "text" DEFAULT 'primary'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE v_resource knowledge.resources%ROWTYPE; v_table text; v_target_col text;
BEGIN
  v_resource:=knowledge._lock_resource(p_resource_id,'knowledge.edit',true);
  IF v_resource.status='published' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Resource relationships are unversioned and cannot be changed after publication'; END IF;
  IF p_kind NOT IN ('item','variant','commodity','location','activity','topic','resource_relation') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Unsupported Knowledge relationship kind'; END IF;
  IF p_action NOT IN ('link','unlink') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Action must be link or unlink'; END IF;
  IF p_target_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Target id is required'; END IF;
  IF p_action='link' AND nullif(btrim(p_relationship_type),'') IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Relationship type is required'; END IF;
  CASE p_kind
    WHEN 'item' THEN
      v_table:='resource_items';v_target_col:='item_id';
      IF p_action='link' AND (NOT EXISTS(SELECT 1 FROM core.items i WHERE i.id=p_target_id AND i.is_active)
        OR EXISTS(SELECT 1 FROM knowledge.resource_variants rv JOIN core.item_variants iv ON iv.id=rv.variant_id WHERE rv.resource_id=p_resource_id AND iv.item_id<>p_target_id)
        OR EXISTS(SELECT 1 FROM knowledge.resource_commodities rc JOIN core.commodities c ON c.id=rc.commodity_id WHERE rc.resource_id=p_resource_id AND c.item_id IS NOT NULL AND c.item_id<>p_target_id)) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Item is inactive or conflicts with linked variant/commodity canonical item'; END IF;
    WHEN 'variant' THEN
      v_table:='resource_variants';v_target_col:='variant_id';
      IF p_action='link' AND (NOT EXISTS(SELECT 1 FROM core.item_variants iv JOIN core.items i ON i.id=iv.item_id WHERE iv.id=p_target_id AND iv.is_active AND i.is_active)
        OR (EXISTS(SELECT 1 FROM knowledge.resource_items ri WHERE ri.resource_id=p_resource_id) AND NOT EXISTS(SELECT 1 FROM knowledge.resource_items ri JOIN core.item_variants iv ON iv.item_id=ri.item_id WHERE ri.resource_id=p_resource_id AND iv.id=p_target_id))) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Variant is inactive or does not match the resource linked item'; END IF;
    WHEN 'commodity' THEN
      v_table:='resource_commodities';v_target_col:='commodity_id';
      IF p_action='link' AND (NOT EXISTS(SELECT 1 FROM core.commodities c WHERE c.id=p_target_id AND c.is_active)
        OR (EXISTS(SELECT 1 FROM knowledge.resource_items ri WHERE ri.resource_id=p_resource_id) AND EXISTS(SELECT 1 FROM core.commodities c WHERE c.id=p_target_id AND c.item_id IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM knowledge.resource_items ri JOIN core.commodities c ON c.item_id=ri.item_id WHERE ri.resource_id=p_resource_id AND c.id=p_target_id))) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Commodity is inactive or does not match the resource linked item'; END IF;
    WHEN 'location' THEN
      v_table:='resource_locations';v_target_col:='location_id';
      IF p_action='link' AND NOT EXISTS(SELECT 1 FROM core.locations l WHERE l.id=p_target_id AND l.is_active) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Location is unknown or inactive'; END IF;
    WHEN 'activity' THEN
      v_table:='resource_activities';v_target_col:='activity_type_id';
      IF p_action='link' AND NOT EXISTS(SELECT 1 FROM farm_management.activity_types a WHERE a.id=p_target_id AND a.is_active) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Activity type is unknown or inactive'; END IF;
    WHEN 'topic' THEN
      v_table:='resource_topics';v_target_col:='topic_id';
      IF p_action='link' AND NOT EXISTS(SELECT 1 FROM knowledge.topics t WHERE t.id=p_target_id AND t.is_active) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Topic is unknown or inactive'; END IF;
    WHEN 'resource_relation' THEN
      v_table:='resource_relations';v_target_col:='related_resource_id';
      IF p_action='link' AND (p_target_id=p_resource_id OR NOT EXISTS(SELECT 1 FROM knowledge.resources r WHERE r.id=p_target_id AND r.is_active AND r.status<>'archived')) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Related resource is invalid, inactive, or self-referential'; END IF;
  END CASE;
  IF p_action='unlink' THEN
    EXECUTE format('DELETE FROM knowledge.%I WHERE resource_id=$1 AND %I=$2',v_table,v_target_col) USING p_resource_id,p_target_id;
  ELSIF p_kind='resource_relation' THEN
    INSERT INTO knowledge.resource_relations(resource_id,related_resource_id,relationship_type) VALUES(p_resource_id,p_target_id,btrim(p_relationship_type)) ON CONFLICT(resource_id,related_resource_id,relationship_type) DO NOTHING;
  ELSE
    EXECUTE format('INSERT INTO knowledge.%I(resource_id,%I,relationship_type) VALUES($1,$2,$3) ON CONFLICT(resource_id,%I) DO UPDATE SET relationship_type=EXCLUDED.relationship_type',v_table,v_target_col,v_target_col)
      USING p_resource_id,p_target_id,btrim(p_relationship_type);
  END IF;
  PERFORM knowledge._audit('resource_relationship_'||p_action,NULL,jsonb_build_object('resource_id',p_resource_id,'kind',p_kind,'target_id',p_target_id,'relationship_type',p_relationship_type),NULL);
END; $_$;


ALTER FUNCTION "knowledge"."set_resource_relationship"("p_resource_id" "uuid", "p_kind" "text", "p_target_id" "uuid", "p_action" "text", "p_relationship_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."set_resource_source"("p_resource_id" "uuid", "p_source_id" "uuid", "p_source_role" "text" DEFAULT 'reference'::"text", "p_action" "text" DEFAULT 'link'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  PERFORM knowledge._lock_resource(p_resource_id,'knowledge.manage_sources',false);
  IF p_action NOT IN ('link','unlink') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Action must be link or unlink'; END IF;
  IF p_action='unlink' THEN
    DELETE FROM knowledge.resource_sources WHERE resource_id=p_resource_id AND source_id=p_source_id;
  ELSE
    IF nullif(btrim(p_source_role),'') IS NULL OR NOT EXISTS(SELECT 1 FROM knowledge.sources s WHERE s.id=p_source_id AND s.is_active) THEN
      RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Source is unknown/inactive or source role is empty';
    END IF;
    INSERT INTO knowledge.resource_sources(resource_id,source_id,source_role)
    VALUES(p_resource_id,p_source_id,btrim(p_source_role))
    ON CONFLICT(resource_id,source_id) DO UPDATE SET source_role=EXCLUDED.source_role;
  END IF;
  PERFORM knowledge._audit('resource_source_'||p_action,NULL,
    jsonb_build_object('resource_id',p_resource_id,'source_id',p_source_id,'source_role',p_source_role),NULL);
END;
$$;


ALTER FUNCTION "knowledge"."set_resource_source"("p_resource_id" "uuid", "p_source_id" "uuid", "p_source_role" "text", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."submit_for_review"("p_version_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_resource_id uuid;
  v_status text;
BEGIN
  SELECT v.resource_id INTO v_resource_id
  FROM knowledge.resource_versions AS v WHERE v.id=p_version_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='Knowledge version not found'; END IF;
  PERFORM knowledge._lock_resource(v_resource_id,'knowledge.edit',false);
  SELECT v.status INTO v_status
  FROM knowledge.resource_versions AS v
  WHERE v.id=p_version_id AND v.resource_id=v_resource_id
  FOR UPDATE;
  IF NOT FOUND OR v_status <> 'draft' THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Only draft versions may enter review';
  END IF;
  UPDATE knowledge.resource_versions SET status='review' WHERE id=p_version_id;
  UPDATE knowledge.resources SET status='review' WHERE id=v_resource_id AND status='draft';
  PERFORM knowledge._audit('version_submitted_for_review',
    jsonb_build_object('resource_id',v_resource_id,'version_id',p_version_id,'status','draft'),
    jsonb_build_object('resource_id',v_resource_id,'version_id',p_version_id,'status','review'),NULL);
END;
$$;


ALTER FUNCTION "knowledge"."submit_for_review"("p_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."update_resource_metadata"("p_resource_id" "uuid", "p_title" "text", "p_slug" "text", "p_summary" "text", "p_visibility" "text", "p_metadata" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE v_old knowledge.resources%ROWTYPE;
BEGIN
  v_old:=knowledge._lock_resource(p_resource_id,'knowledge.edit',true);
  IF nullif(btrim(p_title),'') IS NULL OR p_slug IS NULL OR p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Title or slug is invalid'; END IF;
  IF p_visibility NOT IN ('public','restricted','private') OR p_metadata IS NULL OR jsonb_typeof(p_metadata)<>'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Visibility or metadata is invalid'; END IF;
  UPDATE knowledge.resources SET title=btrim(p_title),slug=p_slug,summary=p_summary,visibility=p_visibility,metadata=p_metadata WHERE id=p_resource_id;
  PERFORM knowledge._audit('resource_metadata_updated',to_jsonb(v_old),jsonb_build_object('title',btrim(p_title),'slug',p_slug,'summary',p_summary,'visibility',p_visibility,'metadata',p_metadata),NULL);
END; $_$;


ALTER FUNCTION "knowledge"."update_resource_metadata"("p_resource_id" "uuid", "p_title" "text", "p_slug" "text", "p_summary" "text", "p_visibility" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."update_version_content"("p_version_id" "uuid", "p_title" "text", "p_summary" "text", "p_change_summary" "text", "p_metadata" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_resource_id uuid; v_old jsonb;
BEGIN
  v_resource_id:=knowledge._assert_editable_version(p_version_id);
  IF p_metadata IS NULL OR jsonb_typeof(p_metadata)<>'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Metadata must be a JSON object'; END IF;
  SELECT to_jsonb(v) INTO v_old FROM knowledge.resource_versions v WHERE v.id=p_version_id;
  UPDATE knowledge.resource_versions SET title=p_title,summary=p_summary,change_summary=p_change_summary,metadata=p_metadata WHERE id=p_version_id;
  PERFORM knowledge._audit('version_content_updated',v_old,jsonb_build_object('version_id',p_version_id,'resource_id',v_resource_id,'title',p_title,'summary',p_summary,'change_summary',p_change_summary,'metadata',p_metadata),NULL);
END; $$;


ALTER FUNCTION "knowledge"."update_version_content"("p_version_id" "uuid", "p_title" "text", "p_summary" "text", "p_change_summary" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."upsert_content_block"("p_section_id" "uuid", "p_block_id" "uuid", "p_block_type" "text", "p_block_order" integer, "p_content" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_version_id uuid; v_resource_id uuid; v_id uuid;
BEGIN
  SELECT s.resource_version_id INTO v_version_id FROM knowledge.sections s WHERE s.id=p_section_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='Section not found'; END IF;
  v_resource_id:=knowledge._assert_editable_version(v_version_id);
  IF nullif(btrim(p_block_type),'') IS NULL OR p_block_order IS NULL OR p_block_order<0 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Block type and non-negative order are required'; END IF;
  IF p_content IS NULL OR jsonb_typeof(p_content) NOT IN ('object','array') OR p_content='{}'::jsonb OR p_content='[]'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Block content must be a non-empty JSON object or array'; END IF;
  IF NOT EXISTS(SELECT 1 FROM knowledge.sections s WHERE s.id=p_section_id AND s.resource_version_id=v_version_id AND s.is_active) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Content must belong to an active section in the editable version'; END IF;
  IF EXISTS(SELECT 1 FROM knowledge.content_blocks b WHERE b.section_id=p_section_id AND b.block_order=p_block_order AND b.id IS DISTINCT FROM p_block_id) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='Block order is already used in this section'; END IF;
  IF p_block_id IS NULL THEN
    INSERT INTO knowledge.content_blocks(section_id,block_type,block_order,content) VALUES(p_section_id,btrim(p_block_type),p_block_order,p_content) RETURNING id INTO v_id;
  ELSE
    UPDATE knowledge.content_blocks SET block_type=btrim(p_block_type),block_order=p_block_order,content=p_content WHERE id=p_block_id AND section_id=p_section_id RETURNING id INTO v_id;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Block does not belong to the specified section/version'; END IF;
  END IF;
  PERFORM knowledge._audit('content_block_upserted',NULL,jsonb_build_object('resource_id',v_resource_id,'version_id',v_version_id,'section_id',p_section_id,'block_id',v_id,'block_order',p_block_order,'block_type',p_block_type),NULL);
  RETURN v_id;
END; $$;


ALTER FUNCTION "knowledge"."upsert_content_block"("p_section_id" "uuid", "p_block_id" "uuid", "p_block_type" "text", "p_block_order" integer, "p_content" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "knowledge"."upsert_section"("p_version_id" "uuid", "p_section_id" "uuid", "p_title" "text", "p_slug" "text", "p_section_order" integer, "p_summary" "text", "p_is_required" boolean DEFAULT false, "p_is_active" boolean DEFAULT true) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_resource_id uuid; v_id uuid;
BEGIN
  v_resource_id:=knowledge._assert_editable_version(p_version_id);
  IF nullif(btrim(p_title),'') IS NULL OR p_section_order IS NULL OR p_section_order<0 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Section title and non-negative order are required'; END IF;
  IF p_section_id IS NULL THEN
    INSERT INTO knowledge.sections(resource_version_id,title,slug,section_order,summary,is_required,is_active)
    VALUES(p_version_id,btrim(p_title),p_slug,p_section_order,p_summary,COALESCE(p_is_required,false),COALESCE(p_is_active,true)) RETURNING id INTO v_id;
  ELSE
    UPDATE knowledge.sections SET title=btrim(p_title),slug=p_slug,section_order=p_section_order,summary=p_summary,is_required=COALESCE(p_is_required,false),is_active=COALESCE(p_is_active,true)
    WHERE id=p_section_id AND resource_version_id=p_version_id RETURNING id INTO v_id;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Section does not belong to the specified version'; END IF;
  END IF;
  PERFORM knowledge._audit('section_upserted',NULL,jsonb_build_object('resource_id',v_resource_id,'version_id',p_version_id,'section_id',v_id,'section_order',p_section_order),NULL);
  RETURN v_id;
END; $$;


ALTER FUNCTION "knowledge"."upsert_section"("p_version_id" "uuid", "p_section_id" "uuid", "p_title" "text", "p_slug" "text", "p_section_order" integer, "p_summary" "text", "p_is_required" boolean, "p_is_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."advance_session_last_location"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
BEGIN
  UPDATE logistics.tracking_sessions AS ts
  SET last_location_point_id = NEW.id,
      last_location_captured_at = NEW.captured_at,
      updated_at = clock_timestamp()
  WHERE ts.id = NEW.tracking_session_id
    AND (ts.last_location_captured_at IS NULL
         OR NEW.captured_at > ts.last_location_captured_at);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "logistics"."advance_session_last_location"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."apply_tracking_event_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE v_target text;
BEGIN
  v_target := CASE NEW.event_type
    WHEN 'requested' THEN 'requested'
    WHEN 'accepted' THEN 'accepted'
    WHEN 'assigned' THEN 'assigned'
    WHEN 'pickup_scheduled' THEN 'pickup_scheduled'
    WHEN 'picked_up' THEN 'picked_up'
    WHEN 'departed' THEN 'in_transit'
    WHEN 'in_transit' THEN 'in_transit'
    WHEN 'arrived' THEN 'arrived'
    WHEN 'delivered' THEN 'delivered'
    WHEN 'partially_delivered' THEN 'partially_delivered'
    WHEN 'failed' THEN 'failed'
    WHEN 'cancelled' THEN 'cancelled'
    WHEN 'returned' THEN 'returned'
    ELSE NULL
  END;
  IF v_target IS NOT NULL THEN
    UPDATE logistics.shipments SET status = v_target WHERE id = NEW.shipment_id;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "logistics"."apply_tracking_event_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."assign_transport"("p_shipment_id" "uuid", "p_provider_entity_id" "uuid", "p_driver_profile_id" "uuid" DEFAULT NULL::"uuid", "p_vehicle_id" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_assignment_id uuid;
  v_shipment_status text;
BEGIN
  IF NOT logistics.can_access_shipment(p_shipment_id, 'logistics.assign_transport')
     OR NOT EXISTS (SELECT 1 FROM logistics.shipments s WHERE s.id=p_shipment_id AND s.entity_id=core.current_entity_id()) THEN
    RAISE EXCEPTION 'not authorized to assign this shipment' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM core.entities e WHERE e.id=p_provider_entity_id AND e.is_active) THEN
    RAISE EXCEPTION 'provider entity is not active';
  END IF;
  IF p_driver_profile_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM core.entity_members em
    WHERE em.entity_id=p_provider_entity_id AND em.profile_id=p_driver_profile_id
      AND em.is_active AND em.membership_status='active'
  ) THEN RAISE EXCEPTION 'driver must be an active member of the provider entity'; END IF;
  IF p_vehicle_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM logistics.vehicles v
    WHERE v.id=p_vehicle_id AND v.entity_id=p_provider_entity_id AND v.is_active
  ) THEN RAISE EXCEPTION 'vehicle must be active and owned by the selected provider entity'; END IF;
  IF p_driver_profile_id IS NOT NULL
     AND NOT (core.has_permission('logistics.manage_drivers') OR core.has_permission('logistics.assign_transport')) THEN
    RAISE EXCEPTION 'driver assignment permission required' USING ERRCODE = '42501';
  END IF;
  SELECT status INTO v_shipment_status FROM logistics.shipments WHERE id=p_shipment_id FOR UPDATE;
  IF v_shipment_status NOT IN ('requested','accepted','assigned','pickup_scheduled','picked_up','in_transit','arrived') THEN
    RAISE EXCEPTION 'shipment cannot be assigned from status %',v_shipment_status USING ERRCODE='23514';
  END IF;
  UPDATE logistics.assignments SET status='reassigned'
  WHERE shipment_id=p_shipment_id AND status IN ('assigned','accepted','in_progress');
  INSERT INTO logistics.assignments(shipment_id,provider_entity_id,driver_profile_id,vehicle_id,assigned_by_profile_id,notes)
  VALUES(p_shipment_id,p_provider_entity_id,p_driver_profile_id,p_vehicle_id,core.current_profile_id(),p_notes)
  RETURNING id INTO v_assignment_id;
  INSERT INTO logistics.tracking_events(shipment_id,event_type,notes,metadata)
  VALUES(p_shipment_id,'assigned',p_notes,jsonb_build_object('assignment_id',v_assignment_id,'provider_entity_id',p_provider_entity_id));
  RETURN v_assignment_id;
END $$;


ALTER FUNCTION "logistics"."assign_transport"("p_shipment_id" "uuid", "p_provider_entity_id" "uuid", "p_driver_profile_id" "uuid", "p_vehicle_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."can_access_shipment"("p_shipment_id" "uuid", "p_permission" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  SELECT core.has_permission(p_permission)
     AND EXISTS (
       SELECT 1
       FROM logistics.shipments s
       WHERE s.id = p_shipment_id
         AND (
           s.entity_id = core.current_entity_id()
           OR EXISTS (
             SELECT 1 FROM logistics.assignments a
             WHERE a.shipment_id = s.id
               AND a.provider_entity_id = core.current_entity_id()
               AND a.status IN ('assigned','accepted','in_progress')
           )
           OR EXISTS (
             SELECT 1
             FROM commerce.orders o
             LEFT JOIN commerce.business_profiles bp ON bp.id = o.supplier_id
             WHERE o.id = s.order_id
               AND (o.buyer_id = core.current_profile_id() OR bp.entity_id = core.current_entity_id())
           )
         )
     )
$$;


ALTER FUNCTION "logistics"."can_access_shipment"("p_shipment_id" "uuid", "p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."can_operate_entity"("p_entity_id" "uuid", "p_permission" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  SELECT p_entity_id IS NOT NULL
     AND p_entity_id = core.current_entity_id()
     AND core.has_permission(p_permission)
$$;


ALTER FUNCTION "logistics"."can_operate_entity"("p_entity_id" "uuid", "p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."can_record_location"("p_tracking_session_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  SELECT auth.uid() IS NOT NULL
     AND core.current_profile_id() IS NOT NULL
     AND core.has_permission('logistics.record_location')
     AND EXISTS (
       SELECT 1
       FROM logistics.tracking_sessions AS ts
       JOIN logistics.assignments AS a
         ON a.id = ts.assignment_id
        AND a.shipment_id = ts.shipment_id
       WHERE ts.id = p_tracking_session_id
         AND ts.status = 'active'
         AND a.driver_profile_id = core.current_profile_id()
         AND a.provider_entity_id = core.current_entity_id()
         AND a.status IN ('assigned', 'accepted', 'in_progress')
     );
$$;


ALTER FUNCTION "logistics"."can_record_location"("p_tracking_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."complete_tracking_session"("p_tracking_session_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_profile_id uuid;
  v_entity_id uuid;
  v_assignment_id uuid;
  v_driver_profile_id uuid;
  v_provider_entity_id uuid;
  v_assignment_status text;
  v_status text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authenticated driver required' USING ERRCODE = '42501';
  END IF;
  v_profile_id := core.current_profile_id();
  v_entity_id := core.current_entity_id();
  IF v_profile_id IS NULL OR v_entity_id IS NULL
     OR NOT core.has_permission('logistics.record_location') THEN
    RAISE EXCEPTION 'authorized active Logistics driver required' USING ERRCODE = '42501';
  END IF;

  SELECT ts.assignment_id INTO v_assignment_id
  FROM logistics.tracking_sessions AS ts
  WHERE ts.id = p_tracking_session_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tracking session not found or not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT a.driver_profile_id, a.provider_entity_id, a.status
    INTO v_driver_profile_id, v_provider_entity_id, v_assignment_status
  FROM logistics.assignments AS a
  JOIN logistics.shipments AS s ON s.id = a.shipment_id
  JOIN logistics.tracking_sessions AS ts
    ON ts.assignment_id = a.id AND ts.shipment_id = a.shipment_id
  WHERE a.id = v_assignment_id AND ts.id = p_tracking_session_id
  FOR UPDATE OF a;

  IF NOT FOUND
     OR v_driver_profile_id IS DISTINCT FROM v_profile_id
     OR v_provider_entity_id IS DISTINCT FROM v_entity_id
     OR v_assignment_status NOT IN ('assigned', 'accepted', 'in_progress')
     OR NOT EXISTS (
       SELECT 1 FROM core.entity_members AS em
       JOIN core.entities AS e ON e.id = em.entity_id
       WHERE em.entity_id = v_entity_id AND em.profile_id = v_profile_id
         AND em.is_active AND em.membership_status = 'active' AND e.is_active
     ) THEN
    RAISE EXCEPTION 'caller is not the active assigned driver for this session' USING ERRCODE = '42501';
  END IF;

  SELECT ts.status INTO v_status
  FROM logistics.tracking_sessions AS ts
  WHERE ts.id = p_tracking_session_id AND ts.assignment_id = v_assignment_id
  FOR UPDATE;
  IF v_status IS DISTINCT FROM 'active' AND v_status IS DISTINCT FROM 'paused' THEN
    RAISE EXCEPTION 'only an active or paused tracking session can be completed' USING ERRCODE = '23514';
  END IF;

  UPDATE logistics.tracking_sessions SET status = 'completed'
  WHERE id = p_tracking_session_id;
  RETURN p_tracking_session_id;
END;
$$;


ALTER FUNCTION "logistics"."complete_tracking_session"("p_tracking_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."guard_location_point_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
BEGIN
  -- Receipt time is generated on the database, never accepted from the client.
  NEW.received_at := clock_timestamp();
  NEW.created_at := clock_timestamp();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "logistics"."guard_location_point_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."guard_shipment_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status AND pg_trigger_depth() = 1 THEN
    RAISE EXCEPTION 'shipment status changes must be recorded as tracking events' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "logistics"."guard_shipment_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."guard_tracking_session"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_shipment_entity_id uuid;
BEGIN
  SELECT s.entity_id INTO v_shipment_entity_id
  FROM logistics.shipments AS s
  WHERE s.id = NEW.shipment_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tracking session shipment does not exist' USING ERRCODE = '23503';
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.entity_id := v_shipment_entity_id;
    IF NEW.status <> 'active' THEN
      RAISE EXCEPTION 'tracking sessions must be created active' USING ERRCODE = '23514';
    END IF;
    NEW.started_at := clock_timestamp();
    NEW.ended_at := NULL;
    NEW.last_location_point_id := NULL;
    NEW.last_location_captured_at := NULL;
    NEW.created_at := clock_timestamp();
    NEW.updated_at := clock_timestamp();
    RETURN NEW;
  END IF;

  IF NEW.shipment_id IS DISTINCT FROM OLD.shipment_id
     OR NEW.assignment_id IS DISTINCT FROM OLD.assignment_id
     OR NEW.entity_id IS DISTINCT FROM OLD.entity_id
     OR NEW.started_at IS DISTINCT FROM OLD.started_at
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'tracking session identity and start fields are immutable' USING ERRCODE = '23514';
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NOT (
      (OLD.status = 'active' AND NEW.status IN ('paused', 'completed', 'cancelled'))
      OR (OLD.status = 'paused' AND NEW.status IN ('active', 'completed', 'cancelled'))
    ) THEN
      RAISE EXCEPTION 'invalid tracking session state transition: % -> %', OLD.status, NEW.status
        USING ERRCODE = '23514';
    END IF;
    IF NEW.status IN ('completed', 'cancelled') THEN
      NEW.ended_at := clock_timestamp();
    ELSE
      NEW.ended_at := NULL;
    END IF;
  ELSE
    NEW.ended_at := OLD.ended_at;
  END IF;

  NEW.updated_at := clock_timestamp();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "logistics"."guard_tracking_session"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."pause_tracking_session"("p_tracking_session_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_profile_id uuid;
  v_entity_id uuid;
  v_assignment_id uuid;
  v_driver_profile_id uuid;
  v_provider_entity_id uuid;
  v_assignment_status text;
  v_status text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authenticated driver required' USING ERRCODE = '42501';
  END IF;
  v_profile_id := core.current_profile_id();
