CREATE OR REPLACE FUNCTION "logistics"."prepare_tracking_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_status text;
  v_target text;
  v_allowed boolean := false;
BEGIN
  SELECT s.status INTO v_status FROM logistics.shipments s WHERE s.id = NEW.shipment_id FOR UPDATE;
  IF v_status IS NULL THEN RAISE EXCEPTION 'shipment not found'; END IF;

  NEW.actor_profile_id := core.current_profile_id();
  NEW.actor_entity_id := core.current_entity_id();

  v_target := CASE NEW.event_type
    WHEN 'requested' THEN 'requested'
    WHEN 'accepted' THEN 'accepted'
    WHEN 'assigned' THEN 'assigned'
    WHEN 'pickup_scheduled' THEN 'pickup_scheduled'
    WHEN 'picked_up' THEN 'picked_up'
    WHEN 'departed' THEN 'in_transit'
    WHEN 'in_transit' THEN 'in_transit'
    WHEN 'arrived' THEN 'arrived'
    WHEN 'delivered' THEN 'delivered'
    WHEN 'partially_delivered' THEN 'partially_delivered'
    WHEN 'failed' THEN 'failed'
    WHEN 'cancelled' THEN 'cancelled'
    WHEN 'returned' THEN 'returned'
    ELSE NULL
  END;

  IF NEW.event_type = 'pickup_started' THEN
    v_allowed := v_status = 'pickup_scheduled';
  ELSIF NEW.event_type = 'delivery_attempted' THEN
    v_allowed := v_status IN ('in_transit','arrived');
  ELSIF NEW.event_type = 'assigned' AND v_status IN ('pickup_scheduled','picked_up','in_transit','arrived') THEN
    -- Reassignment is recorded without moving the shipment backwards in its lifecycle.
    v_target := NULL;
    v_allowed := true;
  ELSIF v_target = v_status THEN
    v_allowed := true;
  ELSE
    v_allowed := CASE v_status
      WHEN 'draft' THEN v_target IN ('requested','cancelled')
      WHEN 'requested' THEN v_target IN ('accepted','assigned','cancelled')
      WHEN 'accepted' THEN v_target IN ('assigned','cancelled')
      WHEN 'assigned' THEN v_target IN ('pickup_scheduled','cancelled')
      WHEN 'pickup_scheduled' THEN v_target IN ('picked_up','cancelled')
      WHEN 'picked_up' THEN v_target = 'in_transit'
      WHEN 'in_transit' THEN v_target IN ('arrived','failed','returned')
      WHEN 'arrived' THEN v_target IN ('delivered','partially_delivered','failed','returned')
      ELSE false
    END;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'invalid shipment event % from status %', NEW.event_type, v_status USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "logistics"."prepare_tracking_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."record_location_point"("p_tracking_session_id" "uuid", "p_idempotency_key" "uuid", "p_captured_at" timestamp with time zone, "p_latitude" double precision, "p_longitude" double precision, "p_accuracy" double precision DEFAULT NULL::double precision, "p_speed" double precision DEFAULT NULL::double precision, "p_heading" double precision DEFAULT NULL::double precision, "p_altitude" double precision DEFAULT NULL::double precision) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_point_id uuid;
  v_existing logistics.location_points%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR core.current_profile_id() IS NULL THEN
    RAISE EXCEPTION 'authenticated profile required' USING ERRCODE = '42501';
  END IF;
  IF p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'idempotency key is required' USING ERRCODE = '22023';
  END IF;
  IF NOT logistics.can_record_location(p_tracking_session_id) THEN
    RAISE EXCEPTION 'caller is not the assigned driver authorized to record this active session' USING ERRCODE = '42501';
  END IF;

  INSERT INTO logistics.location_points (
    tracking_session_id, idempotency_key, captured_at, latitude, longitude,
    accuracy, speed, heading, altitude
  ) VALUES (
    p_tracking_session_id, p_idempotency_key, p_captured_at, p_latitude, p_longitude,
    p_accuracy, p_speed, p_heading, p_altitude
  )
  ON CONFLICT (tracking_session_id, idempotency_key) DO NOTHING
  RETURNING id INTO v_point_id;

  IF v_point_id IS NOT NULL THEN
    RETURN v_point_id;
  END IF;

  SELECT lp.* INTO v_existing
  FROM logistics.location_points AS lp
  WHERE lp.tracking_session_id = p_tracking_session_id
    AND lp.idempotency_key = p_idempotency_key;

  IF v_existing.captured_at IS DISTINCT FROM p_captured_at
     OR v_existing.latitude IS DISTINCT FROM p_latitude
     OR v_existing.longitude IS DISTINCT FROM p_longitude
     OR v_existing.accuracy IS DISTINCT FROM p_accuracy
     OR v_existing.speed IS DISTINCT FROM p_speed
     OR v_existing.heading IS DISTINCT FROM p_heading
     OR v_existing.altitude IS DISTINCT FROM p_altitude THEN
    RAISE EXCEPTION 'idempotency key already used for a different GPS point' USING ERRCODE = '23505';
  END IF;
  RETURN v_existing.id;
END;
$$;


ALTER FUNCTION "logistics"."record_location_point"("p_tracking_session_id" "uuid", "p_idempotency_key" "uuid", "p_captured_at" timestamp with time zone, "p_latitude" double precision, "p_longitude" double precision, "p_accuracy" double precision, "p_speed" double precision, "p_heading" double precision, "p_altitude" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."record_tracking_event"("p_shipment_id" "uuid", "p_event_type" "text", "p_occurred_at" timestamp with time zone DEFAULT "now"(), "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE v_event_id uuid;
BEGIN
  IF NOT logistics.can_access_shipment(p_shipment_id,'logistics.update_tracking') THEN
    RAISE EXCEPTION 'not authorized to update this shipment tracking history' USING ERRCODE='42501';
  END IF;
  INSERT INTO logistics.tracking_events(shipment_id,event_type,occurred_at,location_id,notes,metadata)
  VALUES(p_shipment_id,p_event_type,p_occurred_at,p_location_id,p_notes,COALESCE(p_metadata,'{}'::jsonb))
  RETURNING id INTO v_event_id;
  RETURN v_event_id;
END $$;


ALTER FUNCTION "logistics"."record_tracking_event"("p_shipment_id" "uuid", "p_event_type" "text", "p_occurred_at" timestamp with time zone, "p_location_id" "uuid", "p_notes" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."resume_tracking_session"("p_tracking_session_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_profile_id uuid;
  v_entity_id uuid;
  v_assignment_id uuid;
  v_driver_profile_id uuid;
  v_provider_entity_id uuid;
  v_assignment_status text;
  v_status text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authenticated driver required' USING ERRCODE = '42501';
  END IF;
  v_profile_id := core.current_profile_id();
  v_entity_id := core.current_entity_id();
  IF v_profile_id IS NULL OR v_entity_id IS NULL
     OR NOT core.has_permission('logistics.record_location') THEN
    RAISE EXCEPTION 'authorized active Logistics driver required' USING ERRCODE = '42501';
  END IF;

  SELECT ts.assignment_id INTO v_assignment_id
  FROM logistics.tracking_sessions AS ts
  WHERE ts.id = p_tracking_session_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tracking session not found or not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT a.driver_profile_id, a.provider_entity_id, a.status
    INTO v_driver_profile_id, v_provider_entity_id, v_assignment_status
  FROM logistics.assignments AS a
  JOIN logistics.shipments AS s ON s.id = a.shipment_id
  JOIN logistics.tracking_sessions AS ts
    ON ts.assignment_id = a.id AND ts.shipment_id = a.shipment_id
  WHERE a.id = v_assignment_id AND ts.id = p_tracking_session_id
  FOR UPDATE OF a;

  IF NOT FOUND
     OR v_driver_profile_id IS DISTINCT FROM v_profile_id
     OR v_provider_entity_id IS DISTINCT FROM v_entity_id
     OR v_assignment_status NOT IN ('assigned', 'accepted', 'in_progress')
     OR NOT EXISTS (
       SELECT 1 FROM core.entity_members AS em
       JOIN core.entities AS e ON e.id = em.entity_id
       WHERE em.entity_id = v_entity_id AND em.profile_id = v_profile_id
         AND em.is_active AND em.membership_status = 'active' AND e.is_active
     ) THEN
    RAISE EXCEPTION 'caller is not the active assigned driver for this session' USING ERRCODE = '42501';
  END IF;

  SELECT ts.status INTO v_status
  FROM logistics.tracking_sessions AS ts
  WHERE ts.id = p_tracking_session_id AND ts.assignment_id = v_assignment_id
  FOR UPDATE;
  IF v_status IS DISTINCT FROM 'paused' THEN
    RAISE EXCEPTION 'only a paused tracking session can be resumed' USING ERRCODE = '23514';
  END IF;

  UPDATE logistics.tracking_sessions SET status = 'active'
  WHERE id = p_tracking_session_id;
  RETURN p_tracking_session_id;
END;
$$;


ALTER FUNCTION "logistics"."resume_tracking_session"("p_tracking_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."start_tracking_session"("p_assignment_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_profile_id uuid;
  v_entity_id uuid;
  v_shipment_id uuid;
  v_provider_entity_id uuid;
  v_driver_profile_id uuid;
  v_assignment_status text;
  v_session_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authenticated driver required' USING ERRCODE = '42501';
  END IF;
  v_profile_id := core.current_profile_id();
  v_entity_id := core.current_entity_id();
  IF v_profile_id IS NULL OR v_entity_id IS NULL
     OR NOT core.has_permission('logistics.record_location') THEN
    RAISE EXCEPTION 'authorized active Logistics driver required' USING ERRCODE = '42501';
  END IF;

  SELECT a.shipment_id, a.provider_entity_id, a.driver_profile_id, a.status
    INTO v_shipment_id, v_provider_entity_id, v_driver_profile_id, v_assignment_status
  FROM logistics.assignments AS a
  JOIN logistics.shipments AS s ON s.id = a.shipment_id
  WHERE a.id = p_assignment_id
  FOR UPDATE OF a;

  IF NOT FOUND
     OR v_driver_profile_id IS DISTINCT FROM v_profile_id
     OR v_provider_entity_id IS DISTINCT FROM v_entity_id
     OR v_assignment_status NOT IN ('assigned', 'accepted', 'in_progress')
     OR NOT EXISTS (
       SELECT 1 FROM core.entity_members AS em
       JOIN core.entities AS e ON e.id = em.entity_id
       WHERE em.entity_id = v_entity_id
         AND em.profile_id = v_profile_id
         AND em.is_active
         AND em.membership_status = 'active'
         AND e.is_active
     ) THEN
    RAISE EXCEPTION 'caller is not the active assigned driver for this assignment' USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
    SELECT 1 FROM logistics.tracking_sessions AS ts
    WHERE ts.assignment_id = p_assignment_id
      AND ts.status IN ('active', 'paused')
  ) THEN
    RAISE EXCEPTION 'assignment already has an open tracking session' USING ERRCODE = '23505';
  END IF;

  INSERT INTO logistics.tracking_sessions (shipment_id, assignment_id, entity_id, status)
  VALUES (v_shipment_id, p_assignment_id, v_entity_id, 'active')
  RETURNING id INTO v_session_id;

  RETURN v_session_id;
END;
$$;


ALTER FUNCTION "logistics"."start_tracking_session"("p_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."touch_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$ BEGIN NEW.updated_at := now(); RETURN NEW; END $$;


ALTER FUNCTION "logistics"."touch_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."validate_delivery_confirmation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE v_status text;
BEGIN
  SELECT s.status INTO v_status FROM logistics.shipments s WHERE s.id = NEW.shipment_id;
  IF v_status IS DISTINCT FROM NEW.result_status THEN
    RAISE EXCEPTION 'confirmation result must match current shipment delivery status' USING ERRCODE = '23514';
  END IF;
  NEW.confirmed_by_profile_id := core.current_profile_id();
  RETURN NEW;
END $$;


ALTER FUNCTION "logistics"."validate_delivery_confirmation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "logistics"."validate_shipment_item"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_shipment_order_id uuid;
  v_order_item_order_id uuid;
  v_variant_item_id uuid;
BEGIN
  SELECT s.order_id INTO v_shipment_order_id
  FROM logistics.shipments s WHERE s.id = NEW.shipment_id;
  IF NEW.order_item_id IS NOT NULL THEN
    SELECT oi.order_id INTO v_order_item_order_id
    FROM commerce.order_items oi WHERE oi.id = NEW.order_item_id;
    IF v_shipment_order_id IS NULL OR v_order_item_order_id IS DISTINCT FROM v_shipment_order_id THEN
      RAISE EXCEPTION 'order_item_id must belong to the shipment order' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF NEW.variant_id IS NOT NULL THEN
    SELECT iv.item_id INTO v_variant_item_id FROM core.item_variants iv WHERE iv.id = NEW.variant_id;
    IF NEW.item_id IS NOT NULL AND NEW.item_id IS DISTINCT FROM v_variant_item_id THEN
      RAISE EXCEPTION 'item_id must match the selected variant parent item' USING ERRCODE = '23514';
    END IF;
    NEW.item_id := COALESCE(NEW.item_id, v_variant_item_id);
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "logistics"."validate_shipment_item"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."activate_listing"("p_listing_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN

  -- Ensure stock exists
    IF NOT EXISTS (
        SELECT 1 FROM commerce.stock_registry
            WHERE id = (SELECT stock_id FROM marketplace.listings WHERE id = p_listing_id)
                AND quantity > 0
                  ) THEN
                      RAISE EXCEPTION 'Cannot activate listing without stock';
                        END IF;

                          UPDATE marketplace.listings
                            SET status = 'active'
                              WHERE id = p_listing_id;

                              END;
                              $$;


ALTER FUNCTION "marketplace"."activate_listing"("p_listing_id" "uuid") OWNER TO "postgres";


