    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'marketplace'
    AS $$ BEGIN IF COALESCE(auth.role(),'') <> 'service_role' AND COALESCE(auth.jwt()->>'user_role','') <> 'admin' AND COALESCE(auth.jwt()->>'role','') <> 'admin' THEN RAISE EXCEPTION 'Market administration permission required' USING ERRCODE='42501'; END IF; END $$;


ALTER FUNCTION "marketplace"."assert_market_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."assign_market_representative"("p_market_id" "uuid", "p_profile_id" "uuid", "p_valid_from" timestamp with time zone DEFAULT "now"(), "p_replaces_assignment_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'marketplace', 'users', 'core'
    AS $$ DECLARE v_id uuid; v_old marketplace.market_representative_assignments%ROWTYPE; BEGIN PERFORM marketplace.assert_market_admin(); IF p_valid_from IS NULL THEN RAISE EXCEPTION 'valid_from is required'; END IF; IF NOT EXISTS (SELECT 1 FROM marketplace.markets WHERE id=p_market_id AND is_active IS TRUE) THEN RAISE EXCEPTION 'Market must be active'; END IF; IF NOT EXISTS (SELECT 1 FROM users.profiles WHERE id=p_profile_id AND is_active IS TRUE AND account_status='active') THEN RAISE EXCEPTION 'Representative must have an active profile'; END IF; IF p_replaces_assignment_id IS NOT NULL THEN SELECT * INTO v_old FROM marketplace.market_representative_assignments WHERE id=p_replaces_assignment_id AND market_id=p_market_id AND assignment_role='representative' AND active IS TRUE AND status='active' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Replacement assignment not found or inactive'; END IF; IF p_valid_from<=v_old.valid_from THEN RAISE EXCEPTION 'Replacement must begin after the previous assignment begins'; END IF; UPDATE marketplace.market_representative_assignments SET active=false,status='expired',valid_until=p_valid_from,updated_at=now() WHERE id=v_old.id; END IF; IF EXISTS (SELECT 1 FROM marketplace.market_representative_assignments a WHERE a.market_id=p_market_id AND a.profile_id=p_profile_id AND a.assignment_role='representative' AND a.active IS TRUE AND a.status='active' AND (a.valid_until IS NULL OR a.valid_until>p_valid_from)) THEN RAISE EXCEPTION 'Representative already has an overlapping active assignment'; END IF; INSERT INTO marketplace.market_representative_assignments(profile_id,market_id,assignment_role,status,active,valid_from,assigned_by_profile_id) VALUES(p_profile_id,p_market_id,'representative','active',true,p_valid_from,core.current_profile_id()) RETURNING id INTO v_id; RETURN v_id; END $$;


ALTER FUNCTION "marketplace"."assign_market_representative"("p_market_id" "uuid", "p_profile_id" "uuid", "p_valid_from" timestamp with time zone, "p_replaces_assignment_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "media"."files" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "bucket" "text" NOT NULL,
    "path" "text" NOT NULL,
    "entity_id" "uuid" NOT NULL,
    "context_type" "text" NOT NULL,
    "context_id" "uuid" NOT NULL,
    "file_type" "text" NOT NULL,
    "mime_type" "text",
    "extension" "text",
    "size_bytes" bigint NOT NULL,
    "width" integer,
    "height" integer,
    "duration_seconds" integer,
    "is_processed" boolean DEFAULT false,
    "has_thumbnail" boolean DEFAULT false,
    "is_original_stored" boolean DEFAULT false,
    "is_public" boolean DEFAULT false,
    "is_deleted" boolean DEFAULT false,
    "expires_at" timestamp with time zone,
    "egress_count" bigint DEFAULT 0,
    "last_accessed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "created_by" "uuid" DEFAULT "core"."current_profile_id"(),
    "thumbnail_path" "text",
    "preview_path" "text",
    CONSTRAINT "media_files_file_type_check" CHECK (("file_type" = ANY (ARRAY['image'::"text", 'video'::"text", 'document'::"text", 'audio'::"text", 'thumbnail'::"text", 'system'::"text"])))
);


ALTER TABLE "media"."files" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."attach_listing_image"("p_listing_id" "uuid", "p_file_id" "uuid", "p_entity_id" "uuid") RETURNS "media"."files"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'marketplace', 'media', 'core'
    AS $$
DECLARE
  v_listing marketplace.listings;
  v_file media.files;
  v_images jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_listing_id::text, 0));

  SELECT * INTO v_listing
  FROM marketplace.listings
  WHERE id = p_listing_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_listing.entity_id <> p_entity_id
     OR NOT EXISTS (
       SELECT 1
       FROM core.entity_members AS em
       JOIN users.profiles AS p ON p.id = em.profile_id
       WHERE em.entity_id = v_listing.entity_id
         AND em.can_manage = true
         AND p.auth_user_id = core.auth_user_id()
     )
  THEN
    RAISE EXCEPTION 'Listing not found or unauthorized';
  END IF;

  SELECT * INTO v_file
  FROM media.files
  WHERE id = p_file_id
    AND bucket = 'media'
    AND context_type = 'listings'
    AND context_id = p_listing_id
    AND entity_id = p_entity_id
    AND file_type = 'image'
    AND mime_type = 'image/webp'
    AND is_deleted = false
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Media file not found or unauthorized';
  END IF;

  SELECT COALESCE(
    jsonb_agg(to_jsonb(x.value) ORDER BY x.ordinality),
    '[]'::jsonb
  )
  INTO v_images
  FROM jsonb_array_elements_text(
    CASE
      WHEN jsonb_typeof(COALESCE(v_listing.images, '[]'::jsonb)) = 'array'
        THEN COALESCE(v_listing.images, '[]'::jsonb)
      ELSE '[]'::jsonb
    END
  ) WITH ORDINALITY AS x(value, ordinality)
  JOIN media.files AS mf
    ON mf.id::text = x.value
   AND mf.bucket = 'media'
   AND mf.context_type = 'listings'
   AND mf.context_id = p_listing_id
   AND mf.entity_id = p_entity_id
   AND mf.file_type = 'image'
   AND mf.mime_type = 'image/webp'
   AND mf.is_deleted = false;

  IF v_images @> to_jsonb(ARRAY[p_file_id::text]) THEN
    RETURN v_file;
  END IF;

  IF jsonb_array_length(v_images) >= 3 THEN
    RAISE EXCEPTION 'Maximum 3 listing images reached';
  END IF;

  UPDATE marketplace.listings
  SET images = v_images || to_jsonb(p_file_id::text), updated_at = now()
  WHERE id = p_listing_id;

  RETURN v_file;
END;
$$;


ALTER FUNCTION "marketplace"."attach_listing_image"("p_listing_id" "uuid", "p_file_id" "uuid", "p_entity_id" "uuid") OWNER TO "postgres";


