                                                                                            );

                                                                                              RETURN NEW;
                                                                                              END;
                                                                                              $$;


ALTER FUNCTION "marketplace"."auto_create_listing"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."complete_contact_unlock_for_order"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_order commerce.orders%rowtype;
begin
  select * into v_order
  from commerce.orders
  where id = p_order_id;

  if v_order.id is null then
    raise exception 'Order not found: %', p_order_id;
  end if;

  if v_order.order_kind <> 'service' then
    raise exception 'Order is not a service order: %', p_order_id;
  end if;

  update marketplace.contact_unlocks cu
    set payment_status = 'completed',
        unlocked = true,
        valid_until = null
  where cu.order_id = p_order_id
    and cu.payment_status = 'pending'
    and cu.unlocked = false;

end;
$$;


ALTER FUNCTION "marketplace"."complete_contact_unlock_for_order"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."correct_market_price_observation"("p_observation_id" "uuid", "p_price" numeric, "p_unit_id" "uuid", "p_quality_grade" "text", "p_notes" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'marketplace', 'core'
    AS $$ DECLARE v_profile_id uuid; v_id uuid; BEGIN
  v_profile_id:=core.current_profile_id();
  IF v_profile_id IS NULL THEN RAISE EXCEPTION 'Authenticated FAMHUB profile required' USING ERRCODE='42501'; END IF;
  UPDATE marketplace.market_prices p SET price=p_price,unit_id=p_unit_id,quality_grade=p_quality_grade,notes=p_notes,status='submitted',submitted_at=now(),updated_at=now()
   WHERE p.id=p_observation_id AND p.submitted_by_profile_id=v_profile_id AND p.status IN ('draft','correction_requested') RETURNING p.id INTO v_id;
  IF v_id IS NULL THEN RAISE EXCEPTION 'Observation is not editable by this profile or is not awaiting correction' USING ERRCODE='42501'; END IF;
  RETURN v_id;
END $$;


ALTER FUNCTION "marketplace"."correct_market_price_observation"("p_observation_id" "uuid", "p_price" numeric, "p_unit_id" "uuid", "p_quality_grade" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."create_market"("p_name" "text", "p_location_id" "uuid", "p_market_type" "text" DEFAULT 'general'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'marketplace', 'core'
    AS $$ DECLARE v_id uuid; BEGIN PERFORM marketplace.assert_market_admin(); IF p_name IS NULL OR btrim(p_name)='' THEN RAISE EXCEPTION 'Market name is required'; END IF; IF p_market_type IS NULL OR p_market_type NOT IN ('general','wholesale','retail','assembly','auction','other') THEN RAISE EXCEPTION 'Invalid market type'; END IF; IF NOT EXISTS (SELECT 1 FROM core.locations l JOIN core.geography_levels gl ON gl.id=l.level_id WHERE l.id=p_location_id AND l.is_active IS TRUE AND lower(trim(gl.level_name))='ward' AND NOT EXISTS (SELECT 1 FROM core.locations ch WHERE ch.parent_id=l.id AND ch.is_active IS TRUE)) THEN RAISE EXCEPTION 'Market must reference an active canonical Ward'; END IF; INSERT INTO marketplace.markets(name,location_id,market_type) VALUES(btrim(p_name),p_location_id,p_market_type) RETURNING id INTO v_id; RETURN v_id; END $$;


ALTER FUNCTION "marketplace"."create_market"("p_name" "text", "p_location_id" "uuid", "p_market_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."deactivate_market_representative_assignment"("p_assignment_id" "uuid", "p_valid_until" timestamp with time zone DEFAULT "now"()) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'marketplace'
    AS $$ DECLARE v_from timestamptz; BEGIN PERFORM marketplace.assert_market_admin(); SELECT valid_from INTO v_from FROM marketplace.market_representative_assignments WHERE id=p_assignment_id AND active IS TRUE AND status='active' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Active assignment not found'; END IF; IF p_valid_until IS NULL OR p_valid_until<=v_from THEN RAISE EXCEPTION 'valid_until must follow valid_from'; END IF; UPDATE marketplace.market_representative_assignments SET active=false,status='revoked',valid_until=p_valid_until,updated_at=now() WHERE id=p_assignment_id; END $$;


ALTER FUNCTION "marketplace"."deactivate_market_representative_assignment"("p_assignment_id" "uuid", "p_valid_until" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."detach_listing_image"("p_file_id" "uuid", "p_entity_id" "uuid") RETURNS TABLE("file_id" "uuid", "bucket" "text", "path" "text", "listing_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'marketplace', 'media', 'core'
    AS $$
DECLARE
  v_file media.files;
  v_images jsonb;
BEGIN
  SELECT * INTO v_file
  FROM media.files
  WHERE id = p_file_id
    AND entity_id = p_entity_id
    AND context_type = 'listings'
    AND is_deleted = false
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'File not found or unauthorized';
  END IF;

  SELECT COALESCE(l.images, '[]'::jsonb)
  INTO v_images
  FROM marketplace.listings AS l
  WHERE l.id = v_file.context_id
    AND l.entity_id = p_entity_id
    AND EXISTS (
      SELECT 1
      FROM core.entity_members AS em
      JOIN users.profiles AS p ON p.id = em.profile_id
      WHERE em.entity_id = l.entity_id
        AND em.can_manage = true
        AND p.auth_user_id = core.auth_user_id()
    )
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Listing not found or unauthorized';
  END IF;

  SELECT COALESCE(
    jsonb_agg(to_jsonb(x.value) ORDER BY x.ordinality),
    '[]'::jsonb
  )
  INTO v_images
  FROM jsonb_array_elements_text(
    CASE
      WHEN jsonb_typeof(v_images) = 'array' THEN v_images
      ELSE '[]'::jsonb
    END
  ) WITH ORDINALITY AS x(value, ordinality)
  JOIN media.files AS mf
    ON mf.id::text = x.value
   AND mf.is_deleted = false
   AND mf.context_type = 'listings'
   AND mf.context_id = v_file.context_id
   AND mf.entity_id = p_entity_id
  WHERE x.value <> p_file_id::text;

  UPDATE marketplace.listings
  SET images = v_images, updated_at = now()
  WHERE id = v_file.context_id;

  UPDATE media.files
  SET is_deleted = true
  WHERE id = p_file_id;

  INSERT INTO media.file_events(file_id, event_type, entity_id, context_id)
  VALUES (p_file_id, 'delete', p_entity_id, v_file.context_id);

  RETURN QUERY SELECT v_file.id, v_file.bucket, v_file.path, v_file.context_id;
END;
$$;


ALTER FUNCTION "marketplace"."detach_listing_image"("p_file_id" "uuid", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."enforce_listing_ownership"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_entity uuid;
  BEGIN
    SELECT entity_id INTO v_entity
      FROM commerce.stock_registry
        WHERE id = NEW.stock_id;

          IF v_entity <> NEW.entity_id THEN
              RAISE EXCEPTION 'Cannot list stock you do not own';
                END IF;

                  RETURN NEW;
                  END;
                  $$;


ALTER FUNCTION "marketplace"."enforce_listing_ownership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."enforce_listing_stock_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Validate NEW.entity_id against NEW.stock_id ownership anchor.
  IF NOT marketplace.validate_listing_stock_ownership(NEW.entity_id, NEW.stock_id) THEN
    RAISE EXCEPTION 'Marketplace listing stock integrity violation: entity_id % does not own stock_id %', NEW.entity_id, NEW.stock_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "marketplace"."enforce_listing_stock_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."enforce_stock_ownership"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_owner uuid;
  BEGIN
    SELECT entity_id INTO v_owner
      FROM commerce.stock_registry
        WHERE id = NEW.stock_id;

          IF v_owner IS NULL THEN
              RAISE EXCEPTION 'Invalid stock';
                END IF;

                  IF v_owner <> NEW.entity_id THEN
                      RAISE EXCEPTION 'Cannot list stock you do not own';
                        END IF;

                          RETURN NEW;
                          END;
                          $$;


ALTER FUNCTION "marketplace"."enforce_stock_ownership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."enforce_stock_variant_consistency"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_variant uuid;
  BEGIN
    SELECT variant_id INTO v_variant
      FROM commerce.stock_registry
        WHERE id = NEW.stock_id;

          IF v_variant IS NULL THEN
              RAISE EXCEPTION 'Invalid stock_id';
                END IF;

                  IF NEW.variant_id <> v_variant THEN
                      RAISE EXCEPTION 'Variant mismatch between listing and stock';
                        END IF;

                          RETURN NEW;
                          END;
                          $$;


ALTER FUNCTION "marketplace"."enforce_stock_variant_consistency"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."enforce_stock_variant_match"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_variant uuid;
  BEGIN
    SELECT variant_id INTO v_variant
      FROM commerce.stock_registry
        WHERE id = NEW.stock_id;

          IF v_variant IS NULL THEN
              RAISE EXCEPTION 'Invalid stock_id';
                END IF;

                  IF NEW.variant_id IS NOT NULL AND NEW.variant_id <> v_variant THEN
                      RAISE EXCEPTION 'Variant mismatch with stock';
                        END IF;

                          NEW.variant_id := v_variant;

                            RETURN NEW;
                            END;
                            $$;


ALTER FUNCTION "marketplace"."enforce_stock_variant_match"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."get_seller_contact_for_unlock"("p_listing_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'core', 'marketplace', 'users', 'commerce'
    AS $$
DECLARE
  v_buyer_entity uuid;
  v_buyer_unlock marketplace.contact_unlocks%ROWTYPE;
  v_listing marketplace.listings%ROWTYPE;
  v_profile users.profiles%ROWTYPE;
  v_business commerce.business_profiles%ROWTYPE;
  v_now timestamptz := now();
BEGIN
  v_buyer_entity := core.get_active_entity();
  IF v_buyer_entity IS NULL THEN
    RAISE EXCEPTION 'No active entity for caller';
  END IF;

  SELECT *
    INTO v_listing
  FROM marketplace.listings
  WHERE id = p_listing_id;

  IF v_listing.id IS NULL THEN
    RAISE EXCEPTION 'Listing not found';
  END IF;

  -- Validate buyer unlock ownership + payment completion + expiration.
  SELECT cu.*
    INTO v_buyer_unlock
  FROM marketplace.contact_unlocks cu
  WHERE cu.listing_id = p_listing_id
    AND cu.entity_id = v_buyer_entity
    AND cu.payment_status = 'completed'
    AND cu.unlocked = true
    AND (
      cu.valid_until IS NULL
      OR cu.valid_until > v_now
    )
  ORDER BY cu.created_at DESC
  LIMIT 1;

  IF v_buyer_unlock.id IS NULL THEN
    RAISE EXCEPTION 'Unlock not available or expired';
  END IF;

  -- Seller contact is based on seller entity.
  -- Listing.entity_id -> core.entities -> (primary_contact_profile_id and/or business profile)
  SELECT *
    INTO v_profile
  FROM users.profiles p
  JOIN core.entities e ON e.primary_contact_profile_id = p.id
  WHERE e.id = v_listing.entity_id
  LIMIT 1;

  SELECT *
    INTO v_business
  FROM commerce.business_profiles bp
  WHERE bp.entity_id = v_listing.entity_id
  LIMIT 1;

  RETURN jsonb_build_object(
    'seller_entity_id', v_listing.entity_id,
    'contact_person', COALESCE(v_business.contact_person, v_profile.first_name || ' ' || v_profile.last_name),
    'email', v_business.email,
    'phone', COALESCE(v_business.phone, v_profile.phone),
    'business_name', v_business.supplier_name,
    'physical_address', v_business.physical_address
  );
END;
$$;


ALTER FUNCTION "marketplace"."get_seller_contact_for_unlock"("p_listing_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."list_market_representative_assignments"("p_market_id" "uuid" DEFAULT NULL::"uuid", "p_profile_id" "uuid" DEFAULT NULL::"uuid", "p_active_only" boolean DEFAULT true) RETURNS TABLE("assignment_id" "uuid", "market_id" "uuid", "market_name" "text", "profile_id" "uuid", "representative_name" "text", "assignment_role" "text", "status" "text", "active" boolean, "valid_from" timestamp with time zone, "valid_until" timestamp with time zone, "assigned_by_profile_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'marketplace', 'users', 'core', 'auth'
    AS $$ DECLARE v_caller uuid; BEGIN v_caller:=core.current_profile_id(); IF COALESCE(auth.role(),'') <> 'service_role' AND COALESCE(auth.jwt()->>'user_role','') <> 'admin' AND COALESCE(auth.jwt()->>'role','') <> 'admin' THEN IF v_caller IS NULL THEN RAISE EXCEPTION 'Authenticated profile required' USING ERRCODE='42501'; END IF; IF p_profile_id IS NOT NULL AND p_profile_id<>v_caller THEN RAISE EXCEPTION 'Cannot inspect another representative assignment history' USING ERRCODE='42501'; END IF; p_profile_id:=v_caller; END IF; RETURN QUERY SELECT a.id,a.market_id,m.name,a.profile_id,concat_ws(' ',p.first_name,p.last_name),a.assignment_role,a.status,a.active,a.valid_from,a.valid_until,a.assigned_by_profile_id FROM marketplace.market_representative_assignments a JOIN marketplace.markets m ON m.id=a.market_id JOIN users.profiles p ON p.id=a.profile_id WHERE (p_market_id IS NULL OR a.market_id=p_market_id) AND (p_profile_id IS NULL OR a.profile_id=p_profile_id) AND (NOT COALESCE(p_active_only,false) OR (a.active IS TRUE AND a.status='active' AND a.valid_from<=now() AND (a.valid_until IS NULL OR a.valid_until>now()))); END $$;


ALTER FUNCTION "marketplace"."list_market_representative_assignments"("p_market_id" "uuid", "p_profile_id" "uuid", "p_active_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."list_markets"("p_market_id" "uuid" DEFAULT NULL::"uuid", "p_active_only" boolean DEFAULT true) RETURNS TABLE("market_id" "uuid", "market_name" "text", "is_active" boolean, "market_type" "text", "ward_id" "uuid", "ward_name" "text", "subcounty_id" "uuid", "subcounty_name" "text", "county_id" "uuid", "county_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'marketplace', 'core', 'auth'
    AS $$
DECLARE
  v_admin boolean;
BEGIN
  v_admin := COALESCE(auth.role(), '') = 'service_role'
    OR COALESCE(auth.jwt()->>'user_role', '') = 'admin'
    OR COALESCE(auth.jwt()->>'role', '') = 'admin';
  RETURN QUERY
  WITH RECURSIVE selected_markets AS (
    SELECT m.id, m.name, m.is_active, m.market_type, m.location_id
    FROM marketplace.markets AS m
    WHERE (p_market_id IS NULL OR m.id = p_market_id)
      AND (m.is_active IS TRUE OR (NOT p_active_only AND v_admin))
  ), location_path AS (
    SELECT sm.id AS market_id, l.id AS location_id, l.name AS location_name,
           gl.level_name, l.parent_id
    FROM selected_markets AS sm
    JOIN core.locations AS l ON l.id = sm.location_id
    JOIN core.geography_levels AS gl ON gl.id = l.level_id
    UNION ALL
    SELECT lp.market_id, parent.id, parent.name, parent_gl.level_name, parent.parent_id
    FROM location_path AS lp
    JOIN core.locations AS parent ON parent.id = lp.parent_id
    JOIN core.geography_levels AS parent_gl ON parent_gl.id = parent.level_id
  ), hierarchy AS (
    SELECT lp.market_id,
      (array_agg(lp.location_id) FILTER (WHERE lower(trim(lp.level_name)) = 'ward'))[1] AS ward_id,
      (array_agg(lp.location_name) FILTER (WHERE lower(trim(lp.level_name)) = 'ward'))[1] AS ward_name,
      (array_agg(lp.location_id) FILTER (WHERE lower(trim(lp.level_name)) IN ('sub-county','subcounty')))[1] AS subcounty_id,
      (array_agg(lp.location_name) FILTER (WHERE lower(trim(lp.level_name)) IN ('sub-county','subcounty')))[1] AS subcounty_name,
      (array_agg(lp.location_id) FILTER (WHERE lower(trim(lp.level_name)) = 'county'))[1] AS county_id,
      (array_agg(lp.location_name) FILTER (WHERE lower(trim(lp.level_name)) = 'county'))[1] AS county_name
    FROM location_path AS lp GROUP BY lp.market_id
  )
  SELECT sm.id, sm.name, sm.is_active, sm.market_type,
         h.ward_id, h.ward_name, h.subcounty_id, h.subcounty_name, h.county_id, h.county_name
  FROM selected_markets AS sm
  JOIN hierarchy AS h ON h.market_id = sm.id
  WHERE v_admin OR sm.is_active IS TRUE
  ORDER BY sm.name, sm.id;
END
$$;


ALTER FUNCTION "marketplace"."list_markets"("p_market_id" "uuid", "p_active_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."listings_broadcast_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  PERFORM realtime.broadcast_changes(
    'market:listing:' || COALESCE(NEW.id, OLD.id)::text,
    TG_OP,
    TG_OP,
    TG_TABLE_NAME,
    TG_TABLE_SCHEMA,
    NEW,
    OLD
  );
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "marketplace"."listings_broadcast_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."market_price_capture_history"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'marketplace', 'core'
    AS $$
DECLARE
  v_event text;
BEGIN
  v_event := CASE
    WHEN (to_jsonb(OLD)->'price') IS DISTINCT FROM (to_jsonb(NEW)->'price')
      OR (to_jsonb(OLD)->'unit_id') IS DISTINCT FROM (to_jsonb(NEW)->'unit_id')
      OR (to_jsonb(OLD)->'quality_grade') IS DISTINCT FROM (to_jsonb(NEW)->'quality_grade')
      OR (to_jsonb(OLD)->'notes') IS DISTINCT FROM (to_jsonb(NEW)->'notes') THEN 'correction'
    WHEN (to_jsonb(OLD)->'status') IS DISTINCT FROM (to_jsonb(NEW)->'status') THEN 'status_change'
    ELSE 'update'
  END;
  INSERT INTO marketplace.market_price_observation_history (
    observation_id, event_type, old_data, new_data, changed_by_profile_id
  ) VALUES (
    OLD.id, v_event, to_jsonb(OLD), to_jsonb(NEW), core.current_profile_id()
  );
  RETURN NEW;
END
$$;


ALTER FUNCTION "marketplace"."market_price_capture_history"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."market_price_validate_dimensions"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'marketplace', 'core', 'users'
    AS $$ DECLARE v_item_id uuid; v_market_location_id uuid; BEGIN SELECT m.location_id INTO v_market_location_id FROM marketplace.markets m WHERE m.id=NEW.market_id AND m.is_active IS TRUE; IF v_market_location_id IS NULL OR NEW.location_id IS DISTINCT FROM v_market_location_id THEN RAISE EXCEPTION 'Observation must use the active market canonical location'; END IF; IF NOT EXISTS (SELECT 1 FROM core.items i WHERE i.id=NEW.item_id AND i.is_active IS TRUE) THEN RAISE EXCEPTION 'item_id must reference an active canonical item'; END IF; IF NEW.variant_id IS NOT NULL THEN SELECT iv.item_id INTO v_item_id FROM core.item_variants iv WHERE iv.id=NEW.variant_id AND iv.is_active IS TRUE; IF v_item_id IS NULL OR v_item_id<>NEW.item_id THEN RAISE EXCEPTION 'variant_id must be an active variant of item_id'; END IF; END IF; IF NOT EXISTS (SELECT 1 FROM core.units u WHERE u.id=NEW.unit_id) THEN RAISE EXCEPTION 'unit_id must reference a canonical unit'; END IF; IF NEW.variant_id IS NOT NULL THEN IF NOT EXISTS (SELECT 1 FROM core.item_variant_unit_map m WHERE m.variant_id=NEW.variant_id AND m.unit_id=NEW.unit_id AND m.is_active IS TRUE) AND NOT EXISTS (SELECT 1 FROM core.item_unit_map m WHERE m.item_id=NEW.item_id AND m.unit_id=NEW.unit_id AND m.is_active IS TRUE) THEN RAISE EXCEPTION 'unit_id is not active for this item or variant'; END IF; ELSIF NOT EXISTS (SELECT 1 FROM core.item_unit_map m WHERE m.item_id=NEW.item_id AND m.unit_id=NEW.unit_id AND m.is_active IS TRUE) THEN RAISE EXCEPTION 'unit_id is not active for this item'; END IF; IF NEW.representative_assignment_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM marketplace.market_representative_assignments a WHERE a.id=NEW.representative_assignment_id AND a.profile_id=NEW.collector_profile_id AND a.market_id=NEW.market_id AND a.valid_from<=NEW.observed_at AND (a.valid_until IS NULL OR a.valid_until>NEW.observed_at)) THEN RAISE EXCEPTION 'Assignment must match collector, market, and observation time'; END IF; RETURN NEW; END $$;


ALTER FUNCTION "marketplace"."market_price_validate_dimensions"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "marketplace"."listings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "entity_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "unit_id" "uuid",
    "price_per_unit" numeric NOT NULL,
    "currency" "text" DEFAULT 'KES'::"text" NOT NULL,
    "location_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'active'::"text",
    "contact_visibility" "text" DEFAULT 'locked'::"text",
    "is_promoted" boolean DEFAULT false,
    "promoted_until" timestamp with time zone,
    "images" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "stock_id" "uuid" NOT NULL,
    "variant_id" "uuid" NOT NULL,
    CONSTRAINT "listings_contact_visibility_check" CHECK (("contact_visibility" = ANY (ARRAY['locked'::"text", 'open'::"text"])))
);


ALTER TABLE "marketplace"."listings" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."publish_listing_from_stock"("p_stock_id" "uuid", "p_price_per_unit" numeric, "p_title" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_images" "jsonb" DEFAULT NULL::"jsonb") RETURNS "marketplace"."listings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'marketplace', 'commerce', 'core', 'users'
    AS $$
DECLARE
  v_stock_entity_id uuid;
  v_variant_id uuid;
  v_unit_id uuid;
  v_location_id uuid;
  v_status text;
  v_available numeric;
  v_listing marketplace.listings;
BEGIN
  IF p_stock_id IS NULL THEN RAISE EXCEPTION 'stock_id is required'; END IF;
  IF p_price_per_unit IS NULL OR p_price_per_unit <= 0 THEN RAISE EXCEPTION 'price_per_unit must be > 0'; END IF;

  SELECT sr.entity_id, sr.variant_id, sr.unit_id, sr.location_id, sr.status, sr.quantity
    INTO v_stock_entity_id, v_variant_id, v_unit_id, v_location_id, v_status, v_available
  FROM commerce.stock_registry AS sr
  WHERE sr.id = p_stock_id;

  IF v_stock_entity_id IS NULL THEN RAISE EXCEPTION 'stock_id not found'; END IF;
  IF NOT commerce.can_access_stock(v_stock_entity_id) THEN RAISE EXCEPTION 'not authorized to publish this stock'; END IF;
  IF v_status <> 'active' THEN RAISE EXCEPTION 'stock is not active'; END IF;
  IF COALESCE(v_available, 0) <= 0 THEN RAISE EXCEPTION 'stock has no available quantity'; END IF;
  IF v_location_id IS NULL THEN RAISE EXCEPTION 'stock location is required before publishing a listing'; END IF;

  INSERT INTO marketplace.listings (
    entity_id, stock_id, variant_id, unit_id, location_id,
    title, description, price_per_unit, images
  )
  VALUES (
    v_stock_entity_id, p_stock_id, v_variant_id, v_unit_id, v_location_id,
    COALESCE(p_title, 'New listing'), p_description, p_price_per_unit,
    COALESCE(p_images, '[]'::jsonb)
  )
  RETURNING * INTO v_listing;

  RETURN v_listing;
END;
$$;


ALTER FUNCTION "marketplace"."publish_listing_from_stock"("p_stock_id" "uuid", "p_price_per_unit" numeric, "p_title" "text", "p_description" "text", "p_images" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."refresh_daily_market_prices"("p_from" "date", "p_to" "date") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'marketplace', 'core', 'auth'
    AS $$ DECLARE v_count integer; BEGIN IF COALESCE(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Service role required for daily price aggregation' USING ERRCODE='42501'; END IF; IF p_from IS NULL OR p_to IS NULL OR p_to<p_from THEN RAISE EXCEPTION 'A valid inclusive date range is required'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('marketplace.refresh_daily_market_prices',0)); DELETE FROM marketplace.daily_market_prices d WHERE d.recorded_on BETWEEN p_from AND p_to AND d.item_id IS NOT NULL; INSERT INTO marketplace.daily_market_prices(market_id,location_id,item_id,variant_id,unit_id,recorded_on,avg_price,average_price,min_price,max_price,observation_count,price_type,currency,quality_grade) SELECT p.market_id,m.location_id,p.item_id,p.variant_id,p.unit_id,(p.observed_at AT TIME ZONE 'UTC')::date,avg(p.price),avg(p.price),min(p.price),max(p.price),count(*)::integer,p.price_type,p.currency,p.quality_grade FROM marketplace.market_prices p JOIN marketplace.markets m ON m.id=p.market_id WHERE p.status='verified' AND (p.observed_at AT TIME ZONE 'UTC')::date BETWEEN p_from AND p_to GROUP BY p.market_id,m.location_id,p.item_id,p.variant_id,p.unit_id,(p.observed_at AT TIME ZONE 'UTC')::date,p.price_type,p.currency,p.quality_grade; GET DIAGNOSTICS v_count=ROW_COUNT; RETURN v_count; END $$;


ALTER FUNCTION "marketplace"."refresh_daily_market_prices"("p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."review_market_price_observation"("p_observation_id" "uuid", "p_new_status" "text", "p_review_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'marketplace', 'core'
    AS $$ DECLARE v_id uuid; v_profile_id uuid; BEGIN
  IF p_new_status NOT IN ('verified','rejected','correction_requested') THEN RAISE EXCEPTION 'Invalid review status'; END IF;
  IF NOT (COALESCE(auth.jwt()->>'user_role','')='admin' OR COALESCE(auth.jwt()->>'role','')='admin'
    OR COALESCE(auth.role(),'')='service_role' OR core.has_permission('market_prices.verify')) THEN
    RAISE EXCEPTION 'Market price review permission required' USING ERRCODE='42501';
  END IF;
  v_profile_id:=core.current_profile_id();
  UPDATE marketplace.market_prices p SET status=p_new_status,
    verified_by_profile_id=CASE WHEN p_new_status IN ('verified','rejected') THEN v_profile_id ELSE p.verified_by_profile_id END,
    verified_at=CASE WHEN p_new_status IN ('verified','rejected') THEN now() ELSE p.verified_at END,
    review_notes=p_review_notes,updated_at=now()
   WHERE p.id=p_observation_id AND p.status IN ('submitted','correction_requested') RETURNING p.id INTO v_id;
  IF v_id IS NULL THEN RAISE EXCEPTION 'Observation does not exist or is not reviewable' USING ERRCODE='42501'; END IF;
  RETURN v_id;
END $$;


ALTER FUNCTION "marketplace"."review_market_price_observation"("p_observation_id" "uuid", "p_new_status" "text", "p_review_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."set_listing_status"("p_listing_id" "uuid", "p_status" "text") RETURNS "marketplace"."listings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'marketplace', 'users', 'core', 'commerce'
    AS $$
DECLARE
  v_profile_id uuid;
  v_listing marketplace.listings;
  v_updated marketplace.listings;
  v_quantity numeric;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_listing_id IS NULL THEN
    RAISE EXCEPTION 'listing_id is required';
  END IF;

  IF p_status IS NULL OR p_status NOT IN ('active', 'inactive') THEN
    RAISE EXCEPTION 'Unsupported listing status: %. Supported statuses are active and inactive', p_status;
  END IF;

  SELECT p.id
    INTO v_profile_id
  FROM users.profiles p
  WHERE p.auth_user_id = auth.uid()
    AND p.is_active = true;

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Active profile not found for authenticated user';
  END IF;

  SELECT l.*
    INTO v_listing
  FROM marketplace.listings l
  WHERE l.id = p_listing_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Listing not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM core.entity_members em
    WHERE em.entity_id = v_listing.entity_id
      AND em.profile_id = v_profile_id
      AND em.membership_status = 'active'
      AND em.is_active = true
      AND em.can_manage = true
  ) THEN
    RAISE EXCEPTION 'Not authorized to manage this listing';
  END IF;

  IF p_status = 'active' THEN
    SELECT sr.quantity
      INTO v_quantity
    FROM commerce.stock_registry sr
    WHERE sr.id = v_listing.stock_id;

    IF v_quantity IS NULL OR v_quantity <= 0 THEN
      RAISE EXCEPTION 'Cannot activate listing without stock';
    END IF;
  END IF;

  UPDATE marketplace.listings l
  SET status = p_status,
      updated_at = now()
  WHERE l.id = p_listing_id
  RETURNING l.* INTO v_updated;

  RETURN v_updated;
END;
$$;


ALTER FUNCTION "marketplace"."set_listing_status"("p_listing_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."set_market_active"("p_market_id" "uuid", "p_active" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'marketplace'
    AS $$ BEGIN PERFORM marketplace.assert_market_admin(); IF p_active IS NULL THEN RAISE EXCEPTION 'Active state is required'; END IF; UPDATE marketplace.markets SET is_active=p_active,updated_at=now() WHERE id=p_market_id; IF NOT FOUND THEN RAISE EXCEPTION 'Market not found'; END IF; IF NOT p_active THEN UPDATE marketplace.market_representative_assignments SET active=false,status='expired',valid_until=GREATEST(now(),valid_from + interval '1 microsecond'),updated_at=now() WHERE market_id=p_market_id AND active IS TRUE AND status='active'; END IF; END $$;


ALTER FUNCTION "marketplace"."set_market_active"("p_market_id" "uuid", "p_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."submit_market_price"("p_market_id" "uuid", "p_item_id" "uuid", "p_variant_id" "uuid", "p_unit_id" "uuid", "p_price" numeric, "p_price_type" "text", "p_currency" "text" DEFAULT 'KES'::"text", "p_observed_at" timestamp with time zone DEFAULT "now"(), "p_quality_grade" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'marketplace', 'core', 'users'
    AS $$ DECLARE v_profile_id uuid; v_assignment_id uuid; v_location_id uuid; v_id uuid; BEGIN
  v_profile_id:=core.current_profile_id();
  IF v_profile_id IS NULL THEN RAISE EXCEPTION 'Authenticated FAMHUB profile required' USING ERRCODE='42501'; END IF;
  SELECT m.location_id INTO v_location_id FROM marketplace.markets m WHERE m.id=p_market_id AND m.is_active IS TRUE;
  IF NOT FOUND OR v_location_id IS NULL THEN RAISE EXCEPTION 'Market is not active or lacks a canonical location' USING ERRCODE='42501'; END IF;
  SELECT a.id INTO v_assignment_id FROM marketplace.market_representative_assignments a
   WHERE a.profile_id=v_profile_id AND a.market_id=p_market_id AND a.active IS TRUE AND a.status='active'
     AND a.assignment_role='representative' AND a.valid_from<=now() AND (a.valid_until IS NULL OR a.valid_until>now())
   ORDER BY a.valid_from DESC LIMIT 1;
  IF v_assignment_id IS NULL THEN RAISE EXCEPTION 'No active representative assignment for this market' USING ERRCODE='42501'; END IF;
  INSERT INTO marketplace.market_prices(market_id,location_id,item_id,variant_id,unit_id,price,price_type,currency,source_type,
    collector_profile_id,representative_assignment_id,quality_grade,notes,status,observed_at,submitted_by_profile_id,submitted_at,recorded_on)
  VALUES(p_market_id,v_location_id,p_item_id,p_variant_id,p_unit_id,p_price,p_price_type,upper(p_currency),'famhub_representative',
    v_profile_id,v_assignment_id,p_quality_grade,p_notes,'submitted',p_observed_at,v_profile_id,now(),(p_observed_at AT TIME ZONE 'UTC')::date)
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;


ALTER FUNCTION "marketplace"."submit_market_price"("p_market_id" "uuid", "p_item_id" "uuid", "p_variant_id" "uuid", "p_unit_id" "uuid", "p_price" numeric, "p_price_type" "text", "p_currency" "text", "p_observed_at" timestamp with time zone, "p_quality_grade" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."sync_variant_from_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  stock_variant uuid;
  BEGIN
    SELECT variant_id INTO stock_variant
      FROM commerce.stock_registry
        WHERE id = NEW.stock_id;

          NEW.variant_id := stock_variant;

            RETURN NEW;
            END;
            $$;


ALTER FUNCTION "marketplace"."sync_variant_from_stock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."unlock_contact"("p_listing_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'core', 'marketplace'
    AS $$
DECLARE
  v_buyer_entity uuid;
  v_seller_entity uuid;
  v_price marketplace.buyer_pricing.amount%TYPE;
  v_currency marketplace.buyer_pricing.currency%TYPE;
  v_unlock_id uuid;
BEGIN
  v_buyer_entity := core.get_active_entity();
  IF v_buyer_entity IS NULL THEN
    RAISE EXCEPTION 'No active entity for caller';
  END IF;

  SELECT l.entity_id
    INTO v_seller_entity
  FROM marketplace.listings l
  WHERE l.id = p_listing_id;

  IF v_seller_entity IS NULL THEN
    RAISE EXCEPTION 'Listing not found';
  END IF;

  -- If already completed/unlocked for this buyer+listing, do nothing.
  IF EXISTS (
    SELECT 1
    FROM marketplace.contact_unlocks cu
    WHERE cu.listing_id = p_listing_id
      AND cu.entity_id = v_buyer_entity
      AND cu.unlocked = true
      AND cu.payment_status = 'completed'
  ) THEN
    RETURN;
  END IF;

  -- If a pending unlock already exists, do nothing (payment will complete later).
  IF EXISTS (
    SELECT 1
    FROM marketplace.contact_unlocks cu
    WHERE cu.listing_id = p_listing_id
      AND cu.entity_id = v_buyer_entity
      AND cu.payment_status = 'pending'
  ) THEN
    RETURN;
  END IF;

  -- Determine configured unlock price.
  SELECT bp.amount, bp.currency
    INTO v_price, v_currency
  FROM marketplace.buyer_pricing bp
  WHERE bp.action = 'contact_unlock'
    AND bp.active = true
    AND (bp.effective_from IS NULL OR bp.effective_from <= now())
  ORDER BY bp.effective_from DESC NULLS LAST
  LIMIT 1;

  IF v_price IS NULL THEN
    RAISE EXCEPTION 'Missing buyer_pricing for action=contact_unlock';
  END IF;

  -- Create *pending* unlock foundation.
  INSERT INTO marketplace.contact_unlocks (
    listing_id,
    amount,
    currency,
    payment_status,
    unlocked,
    valid_until,
    entity_id
  ) VALUES (
    p_listing_id,
    v_price,
    v_currency,
    'pending',
    false,
    NULL,
    v_buyer_entity
  );

END;
$$;


ALTER FUNCTION "marketplace"."unlock_contact"("p_listing_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."update_listing"("p_listing_id" "uuid", "p_changes" "jsonb") RETURNS "marketplace"."listings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'marketplace', 'users', 'core'
    AS $$
DECLARE
  v_listing marketplace.listings;
  v_updated marketplace.listings;
  v_profile_id uuid;
  v_key text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF p_listing_id IS NULL THEN
    RAISE EXCEPTION 'listing_id is required';
  END IF;
  IF p_changes IS NULL OR jsonb_typeof(p_changes) <> 'object' THEN
    RAISE EXCEPTION 'changes must be a JSON object';
  END IF;
  IF p_changes = '{}'::jsonb THEN
    RAISE EXCEPTION 'At least one editable field is required';
  END IF;
  FOR v_key IN SELECT jsonb_object_keys(p_changes)
  LOOP
    IF v_key NOT IN ('title', 'description', 'price_per_unit', 'currency') THEN
      RAISE EXCEPTION 'Field "%" is not editable through update_listing()', v_key;
    END IF;
  END LOOP;
  SELECT p.id INTO v_profile_id
  FROM users.profiles p
  WHERE p.auth_user_id = auth.uid() AND p.is_active = true;
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Active profile not found for authenticated user';
  END IF;
  SELECT l.* INTO v_listing
  FROM marketplace.listings l
  WHERE l.id = p_listing_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Listing not found';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM core.entity_members em
    WHERE em.entity_id = v_listing.entity_id
      AND em.profile_id = v_profile_id
      AND em.membership_status = 'active'
      AND em.is_active = true
      AND em.can_manage = true
  ) THEN
    RAISE EXCEPTION 'Not authorized to manage this listing';
  END IF;
  IF p_changes ? 'title' AND p_changes->>'title' IS NULL THEN
    RAISE EXCEPTION 'title cannot be null';
  END IF;
  IF p_changes ? 'price_per_unit' THEN
    IF p_changes->>'price_per_unit' IS NULL OR (p_changes->>'price_per_unit')::numeric <= 0 THEN
      RAISE EXCEPTION 'price_per_unit must be > 0';
    END IF;
  END IF;
  IF p_changes ? 'currency' AND p_changes->>'currency' <> 'KES' THEN
    RAISE EXCEPTION 'Only KES is supported for marketplace listings';
  END IF;
  UPDATE marketplace.listings l
  SET title = CASE WHEN p_changes ? 'title' THEN p_changes->>'title' ELSE l.title END,
      description = CASE WHEN p_changes ? 'description' THEN p_changes->>'description' ELSE l.description END,
      price_per_unit = CASE WHEN p_changes ? 'price_per_unit' THEN (p_changes->>'price_per_unit')::numeric ELSE l.price_per_unit END,
      currency = CASE WHEN p_changes ? 'currency' THEN p_changes->>'currency' ELSE l.currency END,
      updated_at = now()
  WHERE l.id = p_listing_id
  RETURNING l.* INTO v_updated;
  RETURN v_updated;
END;
$$;


ALTER FUNCTION "marketplace"."update_listing"("p_listing_id" "uuid", "p_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."update_market"("p_market_id" "uuid", "p_name" "text", "p_location_id" "uuid", "p_market_type" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'marketplace', 'core'
    AS $$
DECLARE
  v_id uuid;
  v_existing_location_id uuid;
BEGIN
  PERFORM marketplace.assert_market_admin();
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'Market name is required';
  END IF;
  IF p_market_type IS NULL OR p_market_type NOT IN ('general','wholesale','retail','assembly','auction','other') THEN
    RAISE EXCEPTION 'Invalid market type';
  END IF;
  SELECT m.location_id INTO v_existing_location_id
  FROM marketplace.markets AS m WHERE m.id = p_market_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Market not found';
  END IF;
  IF p_location_id IS DISTINCT FROM v_existing_location_id THEN
    RAISE EXCEPTION 'A market location is immutable to preserve historical geographic identity; create a new market for a new location';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM core.locations AS l
    JOIN core.geography_levels AS gl ON gl.id = l.level_id
    WHERE l.id = p_location_id AND l.is_active IS TRUE
      AND lower(trim(gl.level_name)) = 'ward'
      AND NOT EXISTS (SELECT 1 FROM core.locations AS child WHERE child.parent_id = l.id AND child.is_active IS TRUE)
  ) THEN
    RAISE EXCEPTION 'Market must reference an active canonical Ward';
  END IF;
  UPDATE marketplace.markets
  SET name = btrim(p_name), market_type = p_market_type, updated_at = now()
  WHERE id = p_market_id RETURNING id INTO v_id;
  RETURN v_id;
END
$$;


ALTER FUNCTION "marketplace"."update_market"("p_market_id" "uuid", "p_name" "text", "p_location_id" "uuid", "p_market_type" "text") OWNER TO "postgres";


