CREATE OR REPLACE FUNCTION "marketplace"."validate_listing_owner"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_entity uuid;
  BEGIN
    SELECT entity_id INTO v_entity
      FROM commerce.stock_registry
        WHERE id = NEW.stock_id;

          IF v_entity IS NULL THEN
              RAISE EXCEPTION 'Invalid stock';
                END IF;

                  IF v_entity <> NEW.entity_id THEN
                      RAISE EXCEPTION 'Cannot list another entity stock';
                        END IF;

                          RETURN NEW;
                          END;
                          $$;


