CREATE OR REPLACE FUNCTION "marketplace"."validate_listing_ownership"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  stock_owner uuid;
  BEGIN
    SELECT entity_id INTO stock_owner
      FROM commerce.stock_registry
        WHERE id = NEW.stock_id;

          IF stock_owner IS NULL THEN
              RAISE EXCEPTION 'Invalid stock reference';
                END IF;

                  IF stock_owner <> NEW.entity_id THEN
                      RAISE EXCEPTION 'You can only list your own stock';
                        END IF;

                          RETURN NEW;
                          END;
                          $$;


ALTER FUNCTION "marketplace"."validate_listing_ownership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."validate_listing_stock_ownership"("p_entity_id" "uuid", "p_stock_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_stock_entity_id uuid;
BEGIN
  -- If either key is missing, treat as invalid (listing requires both in practice).
  IF p_entity_id IS NULL OR p_stock_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT sr.entity_id
    INTO v_stock_entity_id
  FROM commerce.stock_registry sr
  WHERE sr.id = p_stock_id;

  RETURN v_stock_entity_id IS NOT NULL
     AND v_stock_entity_id = p_entity_id;
END;
$$;


ALTER FUNCTION "marketplace"."validate_listing_stock_ownership"("p_entity_id" "uuid", "p_stock_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "marketplace"."validate_market_location"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'marketplace', 'core'
    AS $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM core.locations l WHERE l.id=NEW.location_id AND l.is_active IS TRUE)
     OR EXISTS (SELECT 1 FROM core.locations child WHERE child.parent_id=NEW.location_id AND child.is_active IS TRUE) THEN
    RAISE EXCEPTION 'Market location must be an active, lowest-level canonical administrative location';
  END IF;
  RETURN NEW;
END $$;


