CREATE OR REPLACE FUNCTION "public"."create_famhub_item"("p_main_category" "text", "p_category" "text", "p_sub_category" "text", "p_variety" "text", "p_local_name" "text", "p_unit" "text", "p_description" "text", "p_item_type" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_product_id UUID;
  v_mc TEXT := UPPER(p_main_category);
BEGIN
  INSERT INTO public.master_categorization_list (
    main_category, category, sub_category, variety, local_name, unit, description, item_type, is_active
  ) VALUES (
    v_mc, p_category, p_sub_category, p_variety, p_local_name, p_unit, p_description, UPPER(COALESCE(p_item_type, v_mc)), true
  ) RETURNING id INTO v_product_id;

  IF v_mc = 'CROP' THEN
    INSERT INTO public.crop_classification (product_id) VALUES (v_product_id);
  ELSIF v_mc = 'LIVESTOCK' THEN
    INSERT INTO public.livestock_classification (product_id) VALUES (v_product_id);
  ELSIF v_mc = 'INPUT' THEN
    INSERT INTO public.input_attributes (product_id) VALUES (v_product_id);
  ELSIF v_mc = 'TOOL' THEN
    INSERT INTO public.tool_attributes (product_id) VALUES (v_product_id);
  ELSIF v_mc = 'SERVICE' THEN
    INSERT INTO public.service_attributes (product_id) VALUES (v_product_id);
  ELSIF v_mc = 'LABOUR' THEN
    INSERT INTO public.labour_attributes (product_id) VALUES (v_product_id);
  ELSIF v_mc = 'LAND' THEN
    INSERT INTO public.land_attributes (product_id) VALUES (v_product_id);
  END IF;

  RETURN v_product_id;
END;
$$;


ALTER FUNCTION "public"."create_famhub_item"("p_main_category" "text", "p_category" "text", "p_sub_category" "text", "p_variety" "text", "p_local_name" "text", "p_unit" "text", "p_description" "text", "p_item_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."farm_reports_after_write"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE v_farm_id UUID;
BEGIN
  IF (TG_OP = 'DELETE') THEN
    SELECT fc.farm_id INTO v_farm_id FROM public.farm_crops fc WHERE fc.id = OLD.farm_crop_id;
  ELSE
    SELECT fc.farm_id INTO v_farm_id FROM public.farm_crops fc WHERE fc.id = NEW.farm_crop_id;
  END IF;
  PERFORM public.refresh_farm_aggregates(v_farm_id);
  RETURN COALESCE(NEW, OLD);
END;
$$;


