CREATE OR REPLACE FUNCTION "public"."get_listing_with_contact"("p_listing_id" "uuid") RETURNS TABLE("id" "uuid", "seller_id" "uuid", "title" "text", "description" "text", "contact" "jsonb")
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  l marketplace_listings%ROWTYPE;
  buyer_uuid UUID := NULL;
BEGIN
  SELECT * INTO l FROM marketplace_listings WHERE id = p_listing_id;
  IF l.id IS NULL THEN
    RETURN;
  END IF;

  -- try to get buyer id from auth context
  BEGIN
    buyer_uuid := (SELECT auth.uid());
  EXCEPTION WHEN others THEN
    buyer_uuid := NULL;
  END;

  IF l.contact_visibility = 'open' AND (l.contact_open_until IS NULL OR l.contact_open_until > now()) THEN
    contact := jsonb_build_object(
      'supplier_id', l.supplier_id,
      'phone', (SELECT phone FROM suppliers WHERE id = l.supplier_id),
      'email', (SELECT email FROM suppliers WHERE id = l.supplier_id)
    );
  ELSE
    -- check buyer unlocks
    IF buyer_uuid IS NOT NULL AND EXISTS (
      SELECT 1 FROM contact_unlocks cu
      WHERE cu.buyer_id = buyer_uuid
        AND cu.listing_id = p_listing_id
        AND cu.payment_status = 'completed'
        AND (cu.valid_until IS NULL OR cu.valid_until > now())
    ) THEN
      contact := jsonb_build_object(
        'supplier_id', l.supplier_id,
        'phone', (SELECT phone FROM suppliers WHERE id = l.supplier_id),
        'email', (SELECT email FROM suppliers WHERE id = l.supplier_id)
      );
    ELSE
      contact := NULL;
    END IF;
  END IF;

  id := l.id;
  seller_id := l.seller_id;
  title := l.title;
  description := l.description;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."get_listing_with_contact"("p_listing_id" "uuid") OWNER TO "postgres";


