CREATE OR REPLACE FUNCTION "public"."master_categorization_list_audit_fn"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF (TG_OP = 'DELETE') THEN
    INSERT INTO public.master_categorization_list_audit(operation, changed_by, record_id, old_data, new_data)
    VALUES ('DELETE', (SELECT auth.uid()::uuid FROM pg_catalog.pg_user LIMIT 1), OLD.id, to_jsonb(OLD), NULL);
    RETURN OLD;
  ELSIF (TG_OP = 'INSERT') THEN
    INSERT INTO public.master_categorization_list_audit(operation, changed_by, record_id, old_data, new_data)
    VALUES ('INSERT', NULL, NEW.id, NULL, to_jsonb(NEW));
    RETURN NEW;
  ELSIF (TG_OP = 'UPDATE') THEN
    INSERT INTO public.master_categorization_list_audit(operation, changed_by, record_id, old_data, new_data)
    VALUES ('UPDATE', NULL, NEW.id, to_jsonb(OLD), to_jsonb(NEW));
    RETURN NEW;
  END IF;
  RETURN NULL;
END;
$$;


