CREATE OR REPLACE FUNCTION "public"."refresh_farm_aggregates"("p_farm_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO public.farm_aggregates (farm_id, total_income, total_expense, total_yield, updated_at)
  VALUES (
    p_farm_id,
    COALESCE((SELECT SUM(amount) FROM public.farm_reports fr JOIN public.farm_crops fc ON fr.farm_crop_id = fc.id WHERE fc.farm_id = p_farm_id AND fr.report_type = 'income'),0),
    COALESCE((SELECT SUM(amount) FROM public.farm_reports fr JOIN public.farm_crops fc ON fr.farm_crop_id = fc.id WHERE fc.farm_id = p_farm_id AND fr.report_type = 'expense'),0),
    COALESCE((SELECT SUM(amount) FROM public.farm_reports fr JOIN public.farm_crops fc ON fr.farm_crop_id = fc.id WHERE fc.farm_id = p_farm_id AND fr.report_type = 'yield'),0),
    now()
  ) ON CONFLICT (farm_id) DO UPDATE SET
    total_income = EXCLUDED.total_income,
    total_expense = EXCLUDED.total_expense,
    total_yield = EXCLUDED.total_yield,
    updated_at = EXCLUDED.updated_at;
END;
$$;


ALTER FUNCTION "public"."refresh_farm_aggregates"("p_farm_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."relock_expired_listings"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- If contact_open_until is set and now() > contact_open_until, set visibility to 'locked'
  IF (NEW.contact_open_until IS NOT NULL AND NEW.contact_open_until <= now()) THEN
    UPDATE marketplace_listings
    SET contact_visibility = 'locked', contact_open_until = NULL
    WHERE id = NEW.id AND (contact_visibility = 'open');
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."relock_expired_listings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_knowledge_resources"("p_item_id" "uuid" DEFAULT NULL::"uuid", "p_variant_id" "uuid" DEFAULT NULL::"uuid", "p_commodity_id" "uuid" DEFAULT NULL::"uuid", "p_activity_type_id" "uuid" DEFAULT NULL::"uuid", "p_location_id" "uuid" DEFAULT NULL::"uuid", "p_resource_type_code" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20) RETURNS TABLE("resource_id" "uuid", "resource_type" "text", "title" "text", "slug" "text", "version_id" "uuid", "version_number" integer, "matched_item_id" "uuid", "matched_variant_id" "uuid", "matched_commodity_id" "uuid", "matched_activity_id" "uuid", "matched_location_id" "uuid", "specificity_score" integer, "match_reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_item_id uuid;
  v_item_name text;
  v_variant_item_id uuid;
  v_variant_name text;
  v_commodity_item_id uuid;
  v_commodity_name text;
  v_activity_name text;
  v_location_name text;
BEGIN
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 100 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'p_limit must be between 1 and 100';
  END IF;

  IF p_item_id IS NOT NULL THEN
    SELECT i.id, i.name
      INTO v_item_id, v_item_name
    FROM core.items AS i
    WHERE i.id = p_item_id AND i.is_active IS TRUE;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'item_id is unknown or inactive';
    END IF;
  END IF;

  IF p_variant_id IS NOT NULL THEN
    SELECT iv.item_id, iv.name
      INTO v_variant_item_id, v_variant_name
    FROM core.item_variants AS iv
    JOIN core.items AS vi ON vi.id = iv.item_id AND vi.is_active IS TRUE
    WHERE iv.id = p_variant_id AND iv.is_active IS TRUE;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'variant_id is unknown or inactive';
    END IF;
    IF v_item_id IS NOT NULL AND v_item_id <> v_variant_item_id THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'variant_id does not belong to item_id';
    END IF;
    IF v_item_id IS NULL THEN
      v_item_id := v_variant_item_id;
      SELECT i.name INTO v_item_name FROM core.items AS i WHERE i.id = v_item_id;
    END IF;
  END IF;

  IF p_commodity_id IS NOT NULL THEN
    SELECT c.item_id, c.name
      INTO v_commodity_item_id, v_commodity_name
    FROM core.commodities AS c
    WHERE c.id = p_commodity_id AND c.is_active IS TRUE;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'commodity_id is unknown or inactive';
    END IF;
    IF v_item_id IS NOT NULL AND v_commodity_item_id IS DISTINCT FROM v_item_id THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'commodity_id is not canonically associated with item_id';
    END IF;
  END IF;

  IF p_activity_type_id IS NOT NULL THEN
    SELECT a.name INTO v_activity_name
    FROM farm_management.activity_types AS a
    WHERE a.id = p_activity_type_id AND a.is_active IS TRUE;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'activity_type_id is unknown or inactive';
    END IF;
  END IF;

  IF p_location_id IS NOT NULL THEN
    SELECT l.name INTO v_location_name
    FROM core.locations AS l
    WHERE l.id = p_location_id AND l.is_active IS TRUE;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'location_id is unknown or inactive';
    END IF;
  END IF;

  IF p_resource_type_code IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM knowledge.resource_types AS rt
    WHERE rt.code = p_resource_type_code AND rt.is_active IS TRUE
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'resource_type_code is unknown or inactive';
  END IF;

  RETURN QUERY
  WITH RECURSIVE location_ancestry(location_id, distance, path) AS (
    SELECT l.id, 0, ARRAY[l.id]::uuid[]
    FROM core.locations AS l
    WHERE p_location_id IS NOT NULL AND l.id = p_location_id
    UNION ALL
    SELECT parent.id, child.distance + 1, child.path || parent.id
    FROM location_ancestry AS child
    JOIN core.locations AS current_location ON current_location.id = child.location_id
    JOIN core.locations AS parent ON parent.id = current_location.parent_id
    WHERE NOT (parent.id = ANY(child.path))
  ), eligible_resources AS (
    SELECT
      r.id AS rid,
      rt.code AS type_code,
      COALESCE(v.title, r.title) AS display_title,
      r.slug AS resource_slug,
      v.id AS published_version_id,
      v.version_number AS published_version_number,
      r.is_featured,
      item_scope.item_id AS linked_item_id,
      variant_scope.variant_id AS linked_variant_id,
      commodity_scope.commodity_id AS linked_commodity_id,
      activity_scope.activity_type_id AS linked_activity_id,
      location_scope.location_id AS linked_location_id,
      location_scope.distance AS location_distance
    FROM knowledge.resources AS r
    JOIN knowledge.resource_types AS rt
      ON rt.id = r.resource_type_id AND rt.is_active IS TRUE
    JOIN LATERAL (
      SELECT rv.id, rv.version_number, rv.title
      FROM knowledge.resource_versions AS rv
      WHERE rv.resource_id = r.id AND rv.status = 'published'
      ORDER BY rv.version_number DESC, rv.id ASC
      LIMIT 1
    ) AS v ON TRUE
    LEFT JOIN LATERAL (
      SELECT ri.item_id
      FROM knowledge.resource_items AS ri
      WHERE ri.resource_id = r.id AND ri.item_id = v_item_id
      ORDER BY ri.relationship_type, ri.id
      LIMIT 1
    ) AS item_scope ON v_item_id IS NOT NULL
    LEFT JOIN LATERAL (
      SELECT rv.variant_id
      FROM knowledge.resource_variants AS rv
      WHERE p_variant_id IS NOT NULL
        AND rv.resource_id = r.id AND rv.variant_id = p_variant_id
      ORDER BY rv.relationship_type, rv.id
      LIMIT 1
    ) AS variant_scope ON p_variant_id IS NOT NULL
    LEFT JOIN LATERAL (
      SELECT rc.commodity_id
      FROM knowledge.resource_commodities AS rc
      WHERE p_commodity_id IS NOT NULL
        AND rc.resource_id = r.id AND rc.commodity_id = p_commodity_id
      ORDER BY rc.relationship_type, rc.id
      LIMIT 1
    ) AS commodity_scope ON p_commodity_id IS NOT NULL
    LEFT JOIN LATERAL (
      SELECT ra.activity_type_id
      FROM knowledge.resource_activities AS ra
      WHERE p_activity_type_id IS NOT NULL
        AND ra.resource_id = r.id AND ra.activity_type_id = p_activity_type_id
      ORDER BY ra.relationship_type, ra.id
      LIMIT 1
    ) AS activity_scope ON p_activity_type_id IS NOT NULL
    LEFT JOIN LATERAL (
      SELECT rl.location_id, la.distance
      FROM knowledge.resource_locations AS rl
      JOIN location_ancestry AS la ON la.location_id = rl.location_id
      WHERE p_location_id IS NOT NULL AND rl.resource_id = r.id
      ORDER BY la.distance ASC, rl.location_id ASC, rl.id ASC
      LIMIT 1
    ) AS location_scope ON p_location_id IS NOT NULL
    WHERE r.status = 'published'
      AND r.visibility = 'public'
      AND r.is_active IS TRUE
      AND (p_resource_type_code IS NULL OR rt.code = p_resource_type_code)
      AND (v_item_id IS NULL OR item_scope.item_id IS NOT NULL OR variant_scope.variant_id IS NOT NULL)
      AND (p_variant_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM knowledge.resource_variants AS rv
        WHERE rv.resource_id = r.id
      ) OR variant_scope.variant_id IS NOT NULL)
      AND (p_activity_type_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM knowledge.resource_activities AS ra
        WHERE ra.resource_id = r.id
      ) OR activity_scope.activity_type_id IS NOT NULL)
      AND (p_commodity_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM knowledge.resource_commodities AS rc
        WHERE rc.resource_id = r.id
      ) OR commodity_scope.commodity_id IS NOT NULL)
      AND (p_location_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM knowledge.resource_locations AS rl
        WHERE rl.resource_id = r.id
      ) OR location_scope.location_id IS NOT NULL)
      AND (
        item_scope.item_id IS NOT NULL
        OR variant_scope.variant_id IS NOT NULL
        OR commodity_scope.commodity_id IS NOT NULL
        OR activity_scope.activity_type_id IS NOT NULL
        OR location_scope.location_id IS NOT NULL
      )
  ), scored AS (
    SELECT
      e.*,
      (CASE WHEN p_activity_type_id IS NOT NULL AND e.linked_activity_id IS NOT NULL THEN 1000 ELSE 0 END
       + CASE WHEN e.linked_variant_id IS NOT NULL THEN 100 ELSE 0 END
       + CASE WHEN e.linked_item_id IS NOT NULL THEN 50 ELSE 0 END
       + CASE WHEN e.linked_location_id IS NOT NULL THEN 10 ELSE 0 END
       + CASE WHEN e.linked_commodity_id IS NOT NULL THEN 1 ELSE 0 END)::integer AS score
    FROM eligible_resources AS e
  )
  SELECT
    s.rid,
    s.type_code,
    s.display_title,
    s.resource_slug,
    s.published_version_id,
    s.published_version_number,
    CASE WHEN s.linked_item_id IS NOT NULL OR s.linked_variant_id IS NOT NULL THEN v_item_id ELSE NULL END,
    s.linked_variant_id,
    s.linked_commodity_id,
    s.linked_activity_id,
    s.linked_location_id,
    s.score,
    CASE
      WHEN s.linked_variant_id IS NULL
       AND s.linked_item_id IS NOT NULL
       AND s.linked_commodity_id IS NULL
       AND s.linked_activity_id IS NULL
       AND s.linked_location_id IS NULL
        THEN 'General ' || item_label.name || ' guide'
      ELSE 'Matched ' || pg_catalog.concat_ws(
        ' + ',
        CASE WHEN s.linked_variant_id IS NOT NULL THEN variant_label.name
             WHEN s.linked_item_id IS NOT NULL THEN item_label.name END,
        activity_label.name,
        location_label.name,
        commodity_label.name
      )
    END
  FROM scored AS s
  LEFT JOIN core.items AS item_label ON item_label.id = v_item_id
  LEFT JOIN core.item_variants AS variant_label ON variant_label.id = s.linked_variant_id
  LEFT JOIN farm_management.activity_types AS activity_label ON activity_label.id = s.linked_activity_id
  LEFT JOIN core.locations AS location_label ON location_label.id = s.linked_location_id
  LEFT JOIN core.commodities AS commodity_label ON commodity_label.id = s.linked_commodity_id
  ORDER BY s.score DESC,
           s.location_distance ASC NULLS LAST,
           s.is_featured DESC,
           s.published_version_number DESC,
           s.rid ASC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."resolve_knowledge_resources"("p_item_id" "uuid", "p_variant_id" "uuid", "p_commodity_id" "uuid", "p_activity_type_id" "uuid", "p_location_id" "uuid", "p_resource_type_code" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_knowledge_resources"("p_item_id" "uuid", "p_variant_id" "uuid", "p_commodity_id" "uuid", "p_activity_type_id" "uuid", "p_location_id" "uuid", "p_resource_type_code" "text", "p_limit" integer) IS 'Deterministically resolves public published Knowledge resources by canonical item, variant, commodity, activity, location ancestry, and resource type.';



CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_master_item_main_category"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- If main_category_id provided, ensure name is set
  IF NEW.main_category_id IS NOT NULL THEN
    SELECT name INTO NEW.main_category_name FROM public.main_categories WHERE id = NEW.main_category_id LIMIT 1;
  ELSE
    -- If no id, try to resolve from name to id
    IF NEW.main_category_name IS NOT NULL THEN
      SELECT id INTO NEW.main_category_id FROM public.main_categories WHERE name = NEW.main_category_name LIMIT 1;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_master_item_main_category"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_master_item_main_code"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  -- If main_code is null, set it automatically from item_type
  if new.main_code is null then
    new.main_code := upper(replace(new.item_type, ' ', '_'));
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."set_master_item_main_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_promoted_amount"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  pricing_record RECORD;
BEGIN
  -- Fetch active pricing for this supplier type
  SELECT * INTO pricing_record
  FROM platform_pricing
  WHERE charge_type = 'contact_unlock'
    AND payer = 'supplier'
    AND (supplier_type = NEW.supplier_type OR supplier_type IS NULL)
    AND active = true
  ORDER BY effective_from DESC
  LIMIT 1;

  IF pricing_record IS NOT NULL THEN
    NEW.promoted_amount := pricing_record.amount;
    NEW.promoted_currency := pricing_record.currency;
    -- Set promoted_until based on duration_days
    IF pricing_record.duration_days IS NOT NULL THEN
      NEW.promoted_until := now() + (pricing_record.duration_days || ' days')::interval;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_promoted_amount"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_updated_at_column"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_updated_at_column"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."spatial_add_auto_point"("p_session_id" "uuid", "p_lat" double precision, "p_lng" double precision, "p_accuracy" double precision DEFAULT NULL::double precision) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
                                                                                                                                                    DECLARE
                                                                                                                                                        v_seq integer;
                                                                                                                                                            v_allowed boolean;
                                                                                                                                                            BEGIN

                                                                                                                                                                -- check if point passes filter
                                                                                                                                                                    SELECT spatial_filter_gps_point(p_session_id, p_lat, p_lng, p_accuracy)
                                                                                                                                                                        INTO v_allowed;

                                                                                                                                                                            IF v_allowed = false THEN
                                                                                                                                                                                    RETURN;
                                                                                                                                                                                        END IF;

                                                                                                                                                                                            -- next sequence number
                                                                                                                                                                                                SELECT COALESCE(MAX(sequence_no), 0) + 1
                                                                                                                                                                                                    INTO v_seq
                                                                                                                                                                                                        FROM spatial.spatial_capture_points
                                                                                                                                                                                                            WHERE session_id = p_session_id;

                                                                                                                                                                                                                -- insert clean point
                                                                                                                                                                                                                    INSERT INTO spatial.spatial_capture_points (
                                                                                                                                                                                                                            session_id,
                                                                                                                                                                                                                                    latitude,
                                                                                                                                                                                                                                            longitude,
                                                                                                                                                                                                                                                    accuracy_meters,
                                                                                                                                                                                                                                                            sequence_no
                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                    VALUES (
                                                                                                                                                                                                                                                                            p_session_id,
                                                                                                                                                                                                                                                                                    p_lat,
                                                                                                                                                                                                                                                                                            p_lng,
                                                                                                                                                                                                                                                                                                    p_accuracy,
                                                                                                                                                                                                                                                                                                            v_seq
                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                END;
                                                                                                                                                                                                                                                                                                                $$;


ALTER FUNCTION "public"."spatial_add_auto_point"("p_session_id" "uuid", "p_lat" double precision, "p_lng" double precision, "p_accuracy" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."spatial_build_boundary_from_gps"("p_session_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
                                                                                                                                                                                                                                                                                                                                                DECLARE
                                                                                                                                                                                                                                                                                                                                                    v_asset_id uuid;
                                                                                                                                                                                                                                                                                                                                                        v_line geometry;
                                                                                                                                                                                                                                                                                                                                                            v_polygon geometry;
                                                                                                                                                                                                                                                                                                                                                                v_boundary_id uuid;
                                                                                                                                                                                                                                                                                                                                                                BEGIN

                                                                                                                                                                                                                                                                                                                                                                    -- get linked asset
                                                                                                                                                                                                                                                                                                                                                                        SELECT asset_id
                                                                                                                                                                                                                                                                                                                                                                            INTO v_asset_id
                                                                                                                                                                                                                                                                                                                                                                                FROM spatial.spatial_capture_sessions
                                                                                                                                                                                                                                                                                                                                                                                    WHERE id = p_session_id;

                                                                                                                                                                                                                                                                                                                                                                                        IF v_asset_id IS NULL THEN
                                                                                                                                                                                                                                                                                                                                                                                                RAISE EXCEPTION 'Session has no linked asset';
                                                                                                                                                                                                                                                                                                                                                                                                    END IF;

                                                                                                                                                                                                                                                                                                                                                                                                        -- build ordered line from GPS points
                                                                                                                                                                                                                                                                                                                                                                                                            SELECT ST_MakeLine(
                                                                                                                                                                                                                                                                                                                                                                                                                    ST_SetSRID(ST_MakePoint(longitude, latitude), 4326)
                                                                                                                                                                                                                                                                                                                                                                                                                            ORDER BY sequence_no
                                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                                    INTO v_line
                                                                                                                                                                                                                                                                                                                                                                                                                                        FROM spatial.spatial_capture_points
                                                                                                                                                                                                                                                                                                                                                                                                                                            WHERE session_id = p_session_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                IF v_line IS NULL THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                        RAISE EXCEPTION 'No GPS points found';
                                                                                                                                                                                                                                                                                                                                                                                                                                                            END IF;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- close polygon
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    v_polygon := ST_MakePolygon(ST_AddPoint(v_line, ST_StartPoint(v_line)));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        -- fix invalid geometry
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            IF NOT ST_IsValid(v_polygon) THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    v_polygon := ST_MakeValid(v_polygon);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        END IF;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- store boundary
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                INSERT INTO spatial.spatial_boundaries(asset_id, geometry)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    VALUES (v_asset_id, v_polygon)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        RETURNING id INTO v_boundary_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- update area on asset
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                UPDATE spatial.spatial_assets
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    SET area_ha = ST_Area(v_polygon::geography) / 10000,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            updated_at = now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                WHERE id = v_asset_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    RETURN v_boundary_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    END;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $$;


ALTER FUNCTION "public"."spatial_build_boundary_from_gps"("p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."spatial_calculate_area"("p_geom" "public"."geometry") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
    SELECT ST_Area(p_geom::geography) / 10000;
    $$;


ALTER FUNCTION "public"."spatial_calculate_area"("p_geom" "public"."geometry") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."spatial_create_child_asset"("p_parent_asset_id" "uuid", "p_asset_type" "text", "p_name" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
                                                                                                                        DECLARE
                                                                                                                            v_entity_id uuid;
                                                                                                                                v_asset_id uuid;
                                                                                                                                BEGIN

                                                                                                                                    SELECT entity_id
                                                                                                                                        INTO v_entity_id
                                                                                                                                            FROM spatial.spatial_assets
                                                                                                                                                WHERE id = p_parent_asset_id;

                                                                                                                                                    IF v_entity_id IS NULL THEN
                                                                                                                                                            RAISE EXCEPTION 'Parent asset not found';
                                                                                                                                                                END IF;

                                                                                                                                                                    INSERT INTO spatial.spatial_assets (
                                                                                                                                                                            entity_id,
                                                                                                                                                                                    parent_asset_id,
                                                                                                                                                                                            asset_type,
                                                                                                                                                                                                    name,
                                                                                                                                                                                                            metadata
                                                                                                                                                                                                                )
                                                                                                                                                                                                                    VALUES (
                                                                                                                                                                                                                            v_entity_id,
                                                                                                                                                                                                                                    p_parent_asset_id,
                                                                                                                                                                                                                                            p_asset_type,
                                                                                                                                                                                                                                                    p_name,
                                                                                                                                                                                                                                                            p_metadata
                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                    RETURNING id INTO v_asset_id;

                                                                                                                                                                                                                                                                        RETURN v_asset_id;
                                                                                                                                                                                                                                                                        END;
                                                                                                                                                                                                                                                                        $$;


ALTER FUNCTION "public"."spatial_create_child_asset"("p_parent_asset_id" "uuid", "p_asset_type" "text", "p_name" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."spatial_detect_overlap"("p_asset_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        DECLARE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_geom geometry;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            BEGIN

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- get latest boundary
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    SELECT geometry
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        INTO v_geom
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            FROM spatial.spatial_boundaries
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                WHERE asset_id = p_asset_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ORDER BY created_at DESC
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        LIMIT 1;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            IF v_geom IS NULL THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    RAISE EXCEPTION 'No boundary found';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        END IF;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- detect overlaps
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                INSERT INTO spatial.spatial_overlaps (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        asset_a,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                asset_b,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        overlap_area_sq_m,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                overlap_percentage
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        SELECT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                p_asset_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        sb.asset_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ST_Area(ST_Intersection(v_geom, sb.geometry)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        (ST_Area(ST_Intersection(v_geom, sb.geometry)) /
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 NULLIF(ST_Area(v_geom), 0)) * 100
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     FROM spatial.spatial_boundaries sb
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         WHERE sb.asset_id != p_asset_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               AND ST_Intersects(v_geom, sb.geometry);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               END;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               $$;


ALTER FUNCTION "public"."spatial_detect_overlap"("p_asset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."spatial_filter_gps_point"("p_session_id" "uuid", "p_lat" double precision, "p_lng" double precision, "p_accuracy" double precision DEFAULT NULL::double precision) RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
                DECLARE
                    v_last_lat double precision;
                        v_last_lng double precision;
                            v_distance double precision;
                            BEGIN

                                -- get last recorded point
                                    SELECT latitude, longitude
                                        INTO v_last_lat, v_last_lng
                                            FROM spatial.spatial_capture_points
                                                WHERE session_id = p_session_id
                                                    ORDER BY sequence_no DESC
                                                        LIMIT 1;

                                                            -- first point always allowed
                                                                IF v_last_lat IS NULL THEN
                                                                        RETURN true;
                                                                            END IF;

                                                                                -- calculate distance between last and new point
                                                                                    SELECT ST_Distance(
                                                                                            ST_SetSRID(ST_MakePoint(v_last_lng, v_last_lat), 4326)::geography,
                                                                                                    ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography
                                                                                                        )
                                                                                                            INTO v_distance;

                                                                                                                -- filter GPS jitter (< 2 meters ignored)
                                                                                                                    IF v_distance < 2 THEN
                                                                                                                            RETURN false;
                                                                                                                                END IF;

                                                                                                                                    RETURN true;

                                                                                                                                    END;
                                                                                                                                    $$;


ALTER FUNCTION "public"."spatial_filter_gps_point"("p_session_id" "uuid", "p_lat" double precision, "p_lng" double precision, "p_accuracy" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."spatial_finalize_capture"("p_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
      DECLARE
          v_boundary_id uuid;
              v_asset_id uuid;
                  v_area numeric;
                  BEGIN

                      -- Complete session
                          UPDATE spatial.spatial_capture_sessions
                              SET status = 'completed',
                                      completed_at = now()
                                          WHERE id = p_session_id;

                                              -- Build boundary
                                                  SELECT spatial_build_boundary_from_gps(p_session_id)
                                                      INTO v_boundary_id;

                                                          -- Get asset
                                                              SELECT asset_id
                                                                  INTO v_asset_id
                                                                      FROM spatial.spatial_capture_sessions
                                                                          WHERE id = p_session_id;

                                                                              -- Detect overlaps
                                                                                  PERFORM spatial_detect_overlap(v_asset_id);

                                                                                      -- Get final area
                                                                                          SELECT area_ha
                                                                                              INTO v_area
                                                                                                  FROM spatial.spatial_assets
                                                                                                      WHERE id = v_asset_id;

                                                                                                          RETURN jsonb_build_object(
                                                                                                                  'success', true,
                                                                                                                          'asset_id', v_asset_id,
                                                                                                                                  'boundary_id', v_boundary_id,
                                                                                                                                          'area_ha', v_area
                                                                                                                                              );

                                                                                                                                              END;
                                                                                                                                              $$;


ALTER FUNCTION "public"."spatial_finalize_capture"("p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."spatial_get_asset_children"("p_asset_id" "uuid") RETURNS TABLE("id" "uuid", "parent_asset_id" "uuid", "asset_type" "text", "name" "text", "area_ha" numeric)
    LANGUAGE "sql"
    AS $$
                                                                                                                                                                                                                                                                                                    SELECT
                                                                                                                                                                                                                                                                                                            sa.id,
                                                                                                                                                                                                                                                                                                                    sa.parent_asset_id,
                                                                                                                                                                                                                                                                                                                            sa.asset_type,
                                                                                                                                                                                                                                                                                                                                    sa.name,
                                                                                                                                                                                                                                                                                                                                            sa.area_ha
                                                                                                                                                                                                                                                                                                                                                FROM spatial.spatial_assets sa
                                                                                                                                                                                                                                                                                                                                                    WHERE sa.parent_asset_id = p_asset_id
                                                                                                                                                                                                                                                                                                                                                        ORDER BY sa.name;
                                                                                                                                                                                                                                                                                                                                                        $$;


ALTER FUNCTION "public"."spatial_get_asset_children"("p_asset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."spatial_refresh_parent_area"("p_parent_asset_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql"
    AS $$
                                                                                                                                                                                                                                                                                                                                                            DECLARE
                                                                                                                                                                                                                                                                                                                                                                v_total numeric;
                                                                                                                                                                                                                                                                                                                                                                BEGIN

                                                                                                                                                                                                                                                                                                                                                                    SELECT COALESCE(SUM(area_ha), 0)
                                                                                                                                                                                                                                                                                                                                                                        INTO v_total
                                                                                                                                                                                                                                                                                                                                                                            FROM spatial.spatial_assets
                                                                                                                                                                                                                                                                                                                                                                                WHERE parent_asset_id = p_parent_asset_id;

                                                                                                                                                                                                                                                                                                                                                                                    UPDATE spatial.spatial_assets
                                                                                                                                                                                                                                                                                                                                                                                        SET area_ha = v_total,
                                                                                                                                                                                                                                                                                                                                                                                                updated_at = now()
                                                                                                                                                                                                                                                                                                                                                                                                    WHERE id = p_parent_asset_id;

                                                                                                                                                                                                                                                                                                                                                                                                        RETURN v_total;
                                                                                                                                                                                                                                                                                                                                                                                                        END;
                                                                                                                                                                                                                                                                                                                                                                                                        $$;


ALTER FUNCTION "public"."spatial_refresh_parent_area"("p_parent_asset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."spatial_start_session"("p_asset_id" "uuid", "p_mode" "text" DEFAULT 'auto'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
                                                                                                                                                                                                                                                                                                                        DECLARE
                                                                                                                                                                                                                                                                                                                            v_session_id uuid;
                                                                                                                                                                                                                                                                                                                            BEGIN

                                                                                                                                                                                                                                                                                                                                INSERT INTO spatial.spatial_capture_sessions(asset_id, status)
                                                                                                                                                                                                                                                                                                                                    VALUES (p_asset_id, 'active')
                                                                                                                                                                                                                                                                                                                                        RETURNING id INTO v_session_id;

                                                                                                                                                                                                                                                                                                                                            RETURN v_session_id;

                                                                                                                                                                                                                                                                                                                                            END;
                                                                                                                                                                                                                                                                                                                                            $$;


ALTER FUNCTION "public"."spatial_start_session"("p_asset_id" "uuid", "p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."spatial_stop_and_build"("p_session_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        DECLARE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_boundary_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            BEGIN

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- mark session complete
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    UPDATE spatial.spatial_capture_sessions
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        SET status = 'completed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                completed_at = now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    WHERE id = p_session_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        -- build boundary automatically
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            SELECT spatial_build_boundary_from_gps(p_session_id)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                INTO v_boundary_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    RETURN v_boundary_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    END;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $$;


ALTER FUNCTION "public"."spatial_stop_and_build"("p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_famhub_item"("p_product_id" "uuid", "p_master" "jsonb", "p_classification" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_category TEXT;
BEGIN
  UPDATE public.master_categorization_list
  SET
    category = p_master->>'category',
    sub_category = p_master->>'sub_category',
    variety = p_master->>'variety',
    local_name = p_master->>'local_name',
    unit = p_master->>'unit',
    description = p_master->>'description',
    is_active = CASE WHEN p_master ? 'is_active' THEN (p_master->>'is_active')::boolean ELSE is_active END
  WHERE id = p_product_id;

  SELECT main_category INTO v_category FROM public.master_categorization_list WHERE id = p_product_id;

  IF v_category = 'CROP' THEN
    UPDATE public.crop_classification
    SET
      soil_types = (p_classification->'soil_types')::text[],
      rainfall_range_mm = p_classification->>'rainfall_range_mm',
      temperature_range_c = p_classification->>'temperature_range_c',
      altitude_range_m = p_classification->>'altitude_range_m',
      maturity_days = CASE WHEN p_classification ? 'maturity_days' THEN (p_classification->>'maturity_days')::int ELSE maturity_days END,
      spacing_cm = p_classification->>'spacing_cm',
      pests = (p_classification->'pests')::text[],
      diseases = (p_classification->'diseases')::text[],
      irrigation_required = CASE WHEN p_classification ? 'irrigation_required' THEN (p_classification->>'irrigation_required')::boolean ELSE irrigation_required END,
      yield_estimate = p_classification->>'yield_estimate',
      growing_season_months = p_classification->>'growing_season_months',
      notes = p_classification->>'notes'
    WHERE product_id = p_product_id;

  ELSIF v_category = 'LIVESTOCK' THEN
    UPDATE public.livestock_classification
    SET
      species = p_classification->>'species',
      category = p_classification->>'category',
      breed = p_classification->>'breed',
      production_type = p_classification->>'production_type',
      feed_type = (p_classification->'feed_type')::text[],
      feed_schedule = p_classification->>'feed_schedule',
      average_daily_feed = CASE WHEN p_classification ? 'average_daily_feed' THEN (p_classification->>'average_daily_feed')::numeric ELSE average_daily_feed END,
      housing_type = p_classification->>'housing_type',
      space_required = CASE WHEN p_classification ? 'space_required' THEN (p_classification->>'space_required')::numeric ELSE space_required END,
      gestation_period_days = CASE WHEN p_classification ? 'gestation_period_days' THEN (p_classification->>'gestation_period_days')::int ELSE gestation_period_days END,
      common_diseases = (p_classification->'common_diseases')::text[],
      vaccination_required = CASE WHEN p_classification ? 'vaccination_required' THEN (p_classification->>'vaccination_required')::boolean ELSE vaccination_required END,
      care_notes = p_classification->>'care_notes',
      extra_attributes = p_classification->'extra_attributes',
      notes = p_classification->>'notes'
    WHERE product_id = p_product_id;

  ELSIF v_category = 'INPUT' THEN
    UPDATE public.input_attributes
    SET
      input_type = p_classification->>'input_type',
      application_method = p_classification->>'application_method',
      recommended_dosage = p_classification->>'recommended_dosage',
      crop_target = (p_classification->'crop_target')::text[],
      livestock_target = (p_classification->'livestock_target')::text[],
      active_ingredients = (p_classification->'active_ingredients')::text[],
      safety_notes = p_classification->>'safety_notes',
      storage_requirements = p_classification->>'storage_requirements',
      organic_certified = CASE WHEN p_classification ? 'organic_certified' THEN (p_classification->>'organic_certified')::boolean ELSE organic_certified END,
      manufacturer = p_classification->>'manufacturer',
      expiry_date = CASE WHEN p_classification ? 'expiry_date' THEN (p_classification->>'expiry_date')::date ELSE expiry_date END,
      notes = p_classification->>'notes'
    WHERE product_id = p_product_id;

  ELSE
    -- other categories: service, tool, labour, land
    IF v_category = 'SERVICE' THEN
      UPDATE public.service_attributes
      SET
        service_duration = p_classification->>'service_duration',
        skill_level = p_classification->>'skill_level',
        equipment_needed = (p_classification->'equipment_needed')::text[],
        rate = CASE WHEN p_classification ? 'rate' THEN (p_classification->>'rate')::numeric ELSE rate END,
        notes = p_classification->>'notes'
      WHERE product_id = p_product_id;
    ELSIF v_category = 'TOOL' THEN
      UPDATE public.tool_attributes
      SET
        equipment_type = p_classification->>'equipment_type',
        condition = p_classification->>'condition',
        capacity = p_classification->>'capacity',
        rate = CASE WHEN p_classification ? 'rate' THEN (p_classification->>'rate')::numeric ELSE rate END,
        notes = p_classification->>'notes'
      WHERE product_id = p_product_id;
    ELSIF v_category = 'LABOUR' THEN
      UPDATE public.labour_attributes
      SET
        labour_type = p_classification->>'labour_type',
        number_required = CASE WHEN p_classification ? 'number_required' THEN (p_classification->>'number_required')::int ELSE number_required END,
        skills = (p_classification->'skills')::text[],
        rate = CASE WHEN p_classification ? 'rate' THEN (p_classification->>'rate')::numeric ELSE rate END,
        notes = p_classification->>'notes'
      WHERE product_id = p_product_id;
    ELSIF v_category = 'LAND' THEN
      UPDATE public.land_attributes
      SET
        land_size = CASE WHEN p_classification ? 'land_size' THEN (p_classification->>'land_size')::numeric ELSE land_size END,
        land_unit = p_classification->>'land_unit',
        land_type = p_classification->>'land_type',
        location = p_classification->>'location',
        suitability = p_classification->>'suitability',
        notes = p_classification->>'notes'
      WHERE product_id = p_product_id;
    END IF;
  END IF;

END;
$$;


ALTER FUNCTION "public"."update_famhub_item"("p_product_id" "uuid", "p_master" "jsonb", "p_classification" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_listing_on_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  UPDATE marketplace_listings
  SET contact_visibility = 'open',
      contact_unlock_paid = true,
      promoted_until = COALESCE(NEW.valid_to, promoted_until),
      unlock_fee = COALESCE(NEW.amount, unlock_fee)
  WHERE id = NEW.listing_id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_listing_on_payment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."uuid_generate_v7"() RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN encode(overlay(set_bit(set_bit(uuid_send(gen_random_uuid()), 52, 1), 53, 1) 
         placing substring(int8send(floor(extract(epoch from clock_timestamp()) * 1000)::bigint) from 3) from 1 for 6), 'hex')::uuid;
END $$;


ALTER FUNCTION "public"."uuid_generate_v7"() OWNER TO "postgres";


