CREATE OR REPLACE FUNCTION "users"."_admin_location_row"("p_location_id" "uuid") RETURNS TABLE("id" "uuid", "name" "text", "level_id" "uuid", "level_name" "text", "parent_id" "uuid", "parent_name" "text", "country_id" "uuid", "country_name" character varying, "code" bigint, "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth', 'public'
    AS $$
  SELECT l.id, l.name, l.level_id, gl.level_name, l.parent_id, pl.name, l.country_id, c.name, l.code, l.is_active, l.created_at, l.updated_at, 1::bigint
  FROM core.locations l
  LEFT JOIN core.geography_levels gl ON gl.id = l.level_id
  LEFT JOIN core.locations pl ON pl.id = l.parent_id
  LEFT JOIN core.countries c ON c.id = l.country_id
  WHERE l.id = p_location_id;
$$;


ALTER FUNCTION "users"."_admin_location_row"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."_admin_taxonomy_authorize"("p_permission" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;
  IF NOT core.has_permission(p_permission) THEN
    RAISE EXCEPTION 'permission denied: % is required', p_permission USING ERRCODE = '42501';
  END IF;
END;
$$;


ALTER FUNCTION "users"."_admin_taxonomy_authorize"("p_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."_admin_taxonomy_clean_name"("p_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users'
    AS $$
DECLARE v_name text;
BEGIN
  v_name := btrim(p_name);
  IF v_name IS NULL OR v_name = '' THEN
    RAISE EXCEPTION 'name is required' USING ERRCODE = '22023';
  END IF;
  IF char_length(v_name) > 120 THEN
    RAISE EXCEPTION 'name cannot exceed 120 characters' USING ERRCODE = '22023';
  END IF;
  IF core.normalize_taxonomy_name(v_name) = '' THEN
    RAISE EXCEPTION 'name must contain a letter or number' USING ERRCODE = '22023';
  END IF;
  RETURN v_name;
END;
$$;


ALTER FUNCTION "users"."_admin_taxonomy_clean_name"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."_admin_taxonomy_row"("p_kind" "text", "p_id" "uuid") RETURNS TABLE("id" "uuid", "parent_id" "uuid", "parent_name" "text", "name" "text", "is_active" boolean, "source" "text", "created_by_profile_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users'
    AS $$
BEGIN
  IF p_kind = 'domains' THEN
    RETURN QUERY SELECT d.id, NULL::uuid, NULL::text, d.name, d.is_active, NULL::text, NULL::uuid, d.created_at, d.updated_at, 1::bigint FROM core.domains d WHERE d.id = p_id;
  ELSIF p_kind = 'categories' THEN
    RETURN QUERY SELECT c.id, c.domain_id, d.name, c.name, c.is_active, NULL::text, NULL::uuid, c.created_at, c.updated_at, 1::bigint FROM core.categories c JOIN core.domains d ON d.id = c.domain_id WHERE c.id = p_id;
  ELSIF p_kind = 'items' THEN
    RETURN QUERY SELECT i.id, i.category_id, c.name, i.name, i.is_active, NULL::text, NULL::uuid, i.created_at, i.updated_at, 1::bigint FROM core.items i JOIN core.categories c ON c.id = i.category_id WHERE i.id = p_id;
  ELSIF p_kind = 'item_variants' THEN
    RETURN QUERY SELECT v.id, v.item_id, i.name, v.name, v.is_active, v.source, v.created_by_profile_id, NULL::timestamptz, v.updated_at, 1::bigint FROM core.item_variants v JOIN core.items i ON i.id = v.item_id WHERE v.id = p_id;
  ELSE
    RAISE EXCEPTION 'unsupported taxonomy kind' USING ERRCODE = '22023';
  END IF;
END;
$$;


ALTER FUNCTION "users"."_admin_taxonomy_row"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."_admin_validate_location_hierarchy"("p_location_id" "uuid", "p_level_id" "uuid", "p_parent_id" "uuid", "p_country_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth', 'public'
    AS $$
DECLARE v_level record; v_parent record; v_existing record;
BEGIN
  IF p_country_id IS NULL OR NOT EXISTS (SELECT 1 FROM core.countries c WHERE c.id = p_country_id) THEN
    RAISE EXCEPTION 'country_id must reference an existing country' USING ERRCODE = '22023';
  END IF;
  SELECT gl.id, gl.level_order, gl.country_id INTO v_level FROM core.geography_levels gl WHERE gl.id = p_level_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'level_id must reference an existing geography level' USING ERRCODE = '22023'; END IF;
  IF v_level.country_id IS NOT NULL AND v_level.country_id <> p_country_id THEN
    RAISE EXCEPTION 'geography level is not defined for the selected country' USING ERRCODE = '22023';
  END IF;
  IF p_location_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM core.locations l WHERE l.id = p_location_id) THEN
    RAISE EXCEPTION 'location_id must reference an existing location' USING ERRCODE = '22023';
  END IF;
  IF p_parent_id IS NULL THEN
    IF EXISTS (SELECT 1 FROM core.geography_levels gl WHERE gl.country_id = p_country_id AND gl.level_order < v_level.level_order) THEN
      RAISE EXCEPTION 'parent_id is required for non-root geography levels' USING ERRCODE = '22023';
    END IF;
  ELSE
    IF p_location_id IS NOT NULL AND p_parent_id = p_location_id THEN
      RAISE EXCEPTION 'a location cannot be its own parent' USING ERRCODE = '22023';
    END IF;
    SELECT l.id, l.country_id, l.level_id, gl.level_order INTO v_parent
    FROM core.locations l JOIN core.geography_levels gl ON gl.id = l.level_id
    WHERE l.id = p_parent_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'parent_id must reference an existing location' USING ERRCODE = '22023'; END IF;
    IF v_parent.country_id <> p_country_id THEN RAISE EXCEPTION 'parent and location must belong to the same country' USING ERRCODE = '22023'; END IF;
    IF v_parent.level_order <> v_level.level_order - 1 THEN RAISE EXCEPTION 'parent is not at the preceding geography level' USING ERRCODE = '22023'; END IF;
    IF p_location_id IS NOT NULL AND EXISTS (
      WITH RECURSIVE ancestors(id) AS (
        SELECT p_parent_id
        UNION
        SELECT l.parent_id FROM core.locations l JOIN ancestors a ON a.id = l.id WHERE l.parent_id IS NOT NULL
      ) SELECT 1 FROM ancestors WHERE id = p_location_id
    ) THEN RAISE EXCEPTION 'hierarchy change would create a circular ancestry' USING ERRCODE = '22023'; END IF;
  END IF;
END;
$$;


ALTER FUNCTION "users"."_admin_validate_location_hierarchy"("p_location_id" "uuid", "p_level_id" "uuid", "p_parent_id" "uuid", "p_country_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."activate_workspace_context"("p_workspace_id" "uuid", "p_entity_id" "uuid", "p_role_id" "uuid" DEFAULT NULL::"uuid", "p_business_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("workspace_id" "uuid", "profile_id" "uuid", "entity_id" "uuid", "role_id" "uuid", "active_mode" "text", "business_profile_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'users', 'core', 'commerce', 'system'
    AS $$
DECLARE
  v_auth_user_id uuid;
  v_profile_id uuid;
  v_user_workspace_id uuid;
  v_mode text;
  v_resolved_role_id uuid;
  v_role_count integer;
  v_mapping_count integer;
BEGIN
  v_auth_user_id := auth.uid();
  IF v_auth_user_id IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  SELECT p.id
    INTO v_profile_id
  FROM users.profiles p
  WHERE p.auth_user_id = v_auth_user_id
    AND p.is_active = true
    AND p.account_status = 'active';
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'active profile not found' USING ERRCODE = '42501';
  END IF;

  SELECT count(*)::integer
    INTO v_mapping_count
  FROM users.user_workspaces uw
  JOIN system.workspaces w
    ON w.id = uw.workspace_id
   AND w.is_active = true
  WHERE uw.workspace_id = p_workspace_id
    AND uw.auth_user_id = v_auth_user_id;
  IF v_mapping_count = 0 THEN
    RAISE EXCEPTION 'workspace membership is invalid or workspace is inactive' USING ERRCODE = '42501';
  ELSIF v_mapping_count > 1 THEN
    RAISE EXCEPTION 'multiple user workspace memberships exist for this workspace' USING ERRCODE = '21000';
  END IF;

  SELECT uw.id
    INTO v_user_workspace_id
  FROM users.user_workspaces uw
  WHERE uw.workspace_id = p_workspace_id
    AND uw.auth_user_id = v_auth_user_id;

  SELECT count(*)::integer, max(c.mode)
    INTO v_mapping_count, v_mode
  FROM users.user_workspace_entity_contexts c
  WHERE c.user_workspace_id = v_user_workspace_id
    AND c.entity_id = p_entity_id
    AND c.is_active = true
    AND c.business_profile_id IS NOT DISTINCT FROM p_business_profile_id;
  IF v_mapping_count = 0 THEN
    RAISE EXCEPTION 'workspace/entity mapping is invalid or inactive' USING ERRCODE = '42501';
  ELSIF v_mapping_count > 1 THEN
    RAISE EXCEPTION 'multiple active mappings exist; context selection is ambiguous' USING ERRCODE = '21000';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM core.entities e
    WHERE e.id = p_entity_id
      AND e.is_active = true
  ) THEN
    RAISE EXCEPTION 'entity is invalid or inactive' USING ERRCODE = '42501';
  END IF;

  SELECT count(DISTINCT em.role_id)::integer
    INTO v_role_count
  FROM core.entity_members em
  JOIN core.entity_roles er
    ON er.entity_id = em.entity_id
   AND er.profile_id = em.profile_id
   AND er.role_id = em.role_id
   AND er.is_active = true
  JOIN core.user_roles r
    ON r.id = em.role_id
   AND r.is_active = true
  WHERE em.entity_id = p_entity_id
    AND em.profile_id = v_profile_id
    AND em.is_active = true
    AND em.membership_status = 'active'
    AND (p_role_id IS NULL OR em.role_id = p_role_id);

  IF p_role_id IS NOT NULL THEN
    IF v_role_count <> 1 THEN
      RAISE EXCEPTION 'supplied role is not valid for this profile and entity' USING ERRCODE = '42501';
    END IF;
    v_resolved_role_id := p_role_id;
  ELSIF v_role_count = 1 THEN
    SELECT DISTINCT em.role_id
      INTO v_resolved_role_id
    FROM core.entity_members em
    JOIN core.entity_roles er
      ON er.entity_id = em.entity_id
     AND er.profile_id = em.profile_id
     AND er.role_id = em.role_id
     AND er.is_active = true
    JOIN core.user_roles r
      ON r.id = em.role_id
     AND r.is_active = true
    WHERE em.entity_id = p_entity_id
      AND em.profile_id = v_profile_id
      AND em.is_active = true
      AND em.membership_status = 'active';
  ELSIF v_role_count > 1 THEN
    RAISE EXCEPTION 'multiple valid roles exist; role_id is required' USING ERRCODE = '22023';
  ELSE
    RAISE EXCEPTION 'no valid active role exists for this profile and entity' USING ERRCODE = '42501';
  END IF;

  IF p_business_profile_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM commerce.business_profiles bp
    WHERE bp.id = p_business_profile_id
      AND bp.entity_id = p_entity_id
      AND bp.deleted_at IS NULL
      AND bp.is_active = true
  ) THEN
    RAISE EXCEPTION 'business profile is invalid, inactive, deleted, or belongs to another entity' USING ERRCODE = '42501';
  END IF;

  UPDATE core.entity_context_sessions
  SET session_status = 'expired'
  WHERE user_id = v_profile_id
    AND session_status = 'active';

  INSERT INTO core.entity_context_sessions
    (user_id, entity_id, session_status, is_default, last_switched_at,
     active_mode, business_profile_id, active_role_id, metadata)
  VALUES
    (v_profile_id, p_entity_id, 'active', false, now(),
     v_mode, p_business_profile_id, v_resolved_role_id,
     jsonb_build_object('workspace_id', p_workspace_id));

  workspace_id := p_workspace_id;
  profile_id := v_profile_id;
  entity_id := p_entity_id;
  role_id := v_resolved_role_id;
  active_mode := v_mode;
  business_profile_id := p_business_profile_id;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "users"."activate_workspace_context"("p_workspace_id" "uuid", "p_entity_id" "uuid", "p_role_id" "uuid", "p_business_profile_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "users"."activate_workspace_context"("p_workspace_id" "uuid", "p_entity_id" "uuid", "p_role_id" "uuid", "p_business_profile_id" "uuid") IS 'Validates workspace membership, entity membership, role selection, and business profile before establishing core.entity_context_sessions.';



CREATE OR REPLACE FUNCTION "users"."add_workspace_membership"("p_workspace_id" "uuid", "p_make_default" boolean DEFAULT false) RETURNS TABLE("membership_id" "uuid", "workspace_id" "uuid", "workspace_key" "text", "workspace_name" "text", "is_default" boolean, "current_workspace_id" "uuid", "membership_created" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'users', 'system'
    AS $$
#variable_conflict use_column
DECLARE
  v_auth_user_id uuid := auth.uid();
  v_profile_id uuid;
  v_workspace system.workspaces%ROWTYPE;
  v_membership users.user_workspaces%ROWTYPE;
  v_membership_created boolean := false;
BEGIN
  IF v_auth_user_id IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  SELECT p.id
    INTO v_profile_id
  FROM users.profiles AS p
  WHERE p.auth_user_id = v_auth_user_id
    AND p.is_active = true
    AND p.account_status = 'active'
    AND p.deleted_at IS NULL;

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'active profile not found' USING ERRCODE = '42501';
  END IF;

  SELECT w.*
    INTO v_workspace
  FROM system.workspaces AS w
  WHERE w.id = p_workspace_id
    AND w.is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'workspace is invalid or inactive' USING ERRCODE = '22023';
  END IF;

  INSERT INTO users.user_workspaces (auth_user_id, workspace_id, is_default)
  VALUES (v_auth_user_id, p_workspace_id, false)
  ON CONFLICT (auth_user_id, workspace_id) DO NOTHING
  RETURNING * INTO v_membership;

  IF FOUND THEN
    v_membership_created := true;
  ELSE
    SELECT uw.*
      INTO v_membership
    FROM users.user_workspaces AS uw
    WHERE uw.auth_user_id = v_auth_user_id
      AND uw.workspace_id = p_workspace_id;
  END IF;

  IF p_make_default THEN
    UPDATE users.user_workspaces AS uw
    SET is_default = false
    WHERE uw.auth_user_id = v_auth_user_id
      AND uw.workspace_id <> p_workspace_id
      AND uw.is_default = true;

    UPDATE users.user_workspaces AS uw
    SET is_default = true
    WHERE uw.id = v_membership.id;

    UPDATE users.profiles AS p
    SET current_workspace_id = p_workspace_id
    WHERE p.id = v_profile_id;
  END IF;

  SELECT uw.*
    INTO v_membership
  FROM users.user_workspaces AS uw
  WHERE uw.id = v_membership.id;

  membership_id := v_membership.id;
  workspace_id := v_workspace.id;
  workspace_key := v_workspace.key;
  workspace_name := v_workspace.name;
  is_default := v_membership.is_default;
  current_workspace_id := (
    SELECT p.current_workspace_id
    FROM users.profiles AS p
    WHERE p.id = v_profile_id
  );
  membership_created := v_membership_created;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "users"."add_workspace_membership"("p_workspace_id" "uuid", "p_make_default" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_assign_category_attribute"("p_category_id" "uuid", "p_attribute_id" "uuid", "p_is_required" boolean DEFAULT false) RETURNS TABLE("mapping_id" "uuid", "category_id" "uuid", "attribute_id" "uuid", "is_required" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
DECLARE v_id uuid;
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.manage');
  IF p_category_id IS NULL OR NOT EXISTS(SELECT 1 FROM core.categories c WHERE c.id=p_category_id) THEN RAISE EXCEPTION 'p_category_id must reference an existing category' USING ERRCODE='22023'; END IF;
  IF p_attribute_id IS NULL OR NOT EXISTS(SELECT 1 FROM core.attribute_registry ar WHERE ar.id=p_attribute_id AND ar.is_active IS TRUE) THEN RAISE EXCEPTION 'p_attribute_id must reference an existing active attribute' USING ERRCODE='22023'; END IF;
  IF p_is_required IS NULL THEN RAISE EXCEPTION 'p_is_required is required' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('core.category_attribute_map:'||p_category_id::text||':'||p_attribute_id::text,0));
  SELECT cam.id INTO v_id FROM core.category_attribute_map cam WHERE cam.category_id=p_category_id AND cam.attribute_id=p_attribute_id FOR UPDATE;
  IF FOUND THEN
    UPDATE core.category_attribute_map cam SET is_required=p_is_required WHERE cam.id=v_id AND cam.is_required IS DISTINCT FROM p_is_required;
  ELSE
    INSERT INTO core.category_attribute_map(category_id,attribute_id,is_required)
    VALUES(p_category_id,p_attribute_id,p_is_required) RETURNING id INTO v_id;
  END IF;
  RETURN QUERY SELECT cam.id,cam.category_id,cam.attribute_id,cam.is_required,cam.created_at,cam.updated_at
  FROM core.category_attribute_map cam WHERE cam.id=v_id;
END;
$$;


ALTER FUNCTION "users"."admin_assign_category_attribute"("p_category_id" "uuid", "p_attribute_id" "uuid", "p_is_required" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_create_attribute"("p_name" "text", "p_data_type" "text", "p_description" "text" DEFAULT NULL::"text", "p_unit_id" "uuid" DEFAULT NULL::"uuid", "p_attribute_level" "text" DEFAULT NULL::"text") RETURNS TABLE("attribute_id" "uuid", "name" "text", "data_type" "text", "description" "text", "unit_id" "uuid", "unit_name" "text", "unit_symbol" "text", "attribute_level" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "category_count" bigint, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
DECLARE
  v_name text;
  v_data_type text := lower(btrim(p_data_type));
  v_level text := NULLIF(lower(btrim(p_attribute_level)), '');
  v_id uuid;
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.manage');
  v_name := users._admin_taxonomy_clean_name(p_name);
  IF v_data_type NOT IN ('text','number','boolean','date','enum','json') THEN RAISE EXCEPTION 'unsupported p_data_type value' USING ERRCODE='22023'; END IF;
  IF v_level IS NOT NULL AND v_level NOT IN ('category','item','variant','record','module') THEN RAISE EXCEPTION 'unsupported p_attribute_level value' USING ERRCODE='22023'; END IF;
  IF p_unit_id IS NOT NULL AND v_data_type <> 'number' THEN RAISE EXCEPTION 'unit_id is only valid for number attributes' USING ERRCODE='22023'; END IF;
  IF p_unit_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM core.units u WHERE u.id=p_unit_id) THEN RAISE EXCEPTION 'p_unit_id must reference an existing unit' USING ERRCODE='22023'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('core.attribute_registry:'||core.normalize_taxonomy_name(v_name),0));
  IF EXISTS (SELECT 1 FROM core.attribute_registry ar WHERE core.normalize_taxonomy_name(ar.name)=core.normalize_taxonomy_name(v_name)) THEN
    RAISE EXCEPTION 'an attribute with the same normalized name already exists' USING ERRCODE='23505';
  END IF;
  INSERT INTO core.attribute_registry(name,data_type,description,unit_id,attribute_level,is_active)
  VALUES(v_name,v_data_type,NULLIF(btrim(p_description),''),p_unit_id,v_level,true)
  RETURNING id INTO v_id;

  RETURN QUERY SELECT ar.id,ar.name,ar.data_type,ar.description,ar.unit_id,u.name,u.symbol,ar.attribute_level,
    ar.is_active,ar.created_at,ar.updated_at,0::bigint,1::bigint
  FROM core.attribute_registry ar LEFT JOIN core.units u ON u.id=ar.unit_id WHERE ar.id=v_id;
END;
$$;


ALTER FUNCTION "users"."admin_create_attribute"("p_name" "text", "p_data_type" "text", "p_description" "text", "p_unit_id" "uuid", "p_attribute_level" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_create_attribute_value"("p_attribute_id" "uuid", "p_value" "text") RETURNS TABLE("attribute_id" "uuid", "attribute_name" "text", "data_type" "text", "enum_value_id" "uuid", "value" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
DECLARE v_value text:=NULLIF(btrim(p_value),''); v_id uuid; v_name text; v_type text;
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.manage');
  SELECT ar.name,ar.data_type INTO v_name,v_type FROM core.attribute_registry ar WHERE ar.id=p_attribute_id AND ar.is_active IS TRUE FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'p_attribute_id must reference an existing active attribute' USING ERRCODE='22023'; END IF;
  IF v_value IS NULL THEN RAISE EXCEPTION 'p_value is required' USING ERRCODE='22023'; END IF;
  IF char_length(v_value)>120 THEN RAISE EXCEPTION 'p_value cannot exceed 120 characters' USING ERRCODE='22023'; END IF;
  IF v_type<>'enum' AND NOT EXISTS(SELECT 1 FROM core.attribute_enum_values ev WHERE ev.attribute_id=p_attribute_id) THEN RAISE EXCEPTION 'enum values require an enum attribute; existing text-backed enum rows are supported for legacy attributes' USING ERRCODE='22023'; END IF;
  INSERT INTO core.attribute_enum_values(attribute_id,value) VALUES(p_attribute_id,v_value) RETURNING id INTO v_id;
  RETURN QUERY SELECT ar.id,ar.name,ar.data_type,ev.id,ev.value,ev.created_at,ev.updated_at,1::bigint
  FROM core.attribute_registry ar JOIN core.attribute_enum_values ev ON ev.attribute_id=ar.id WHERE ev.id=v_id;
END;
$$;


ALTER FUNCTION "users"."admin_create_attribute_value"("p_attribute_id" "uuid", "p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_create_category"("p_domain_id" "uuid", "p_name" "text") RETURNS TABLE("id" "uuid", "domain_id" "uuid", "domain_name" "text", "name" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
DECLARE v_id uuid; v_name text;
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.manage');
  IF p_domain_id IS NULL OR NOT EXISTS(SELECT 1 FROM core.domains d WHERE d.id=p_domain_id AND d.is_active IS TRUE) THEN RAISE EXCEPTION 'p_domain_id must reference an existing active domain' USING ERRCODE='22023'; END IF;
  v_name:=users._admin_taxonomy_clean_name(p_name);
  INSERT INTO core.categories(domain_id,name) VALUES(p_domain_id,v_name) RETURNING core.categories.id INTO v_id;
  RETURN QUERY SELECT r.id,r.parent_id,r.parent_name,r.name,r.is_active,r.created_at,r.updated_at,r.total_count FROM users._admin_taxonomy_row('categories',v_id) r;
END;
$$;


ALTER FUNCTION "users"."admin_create_category"("p_domain_id" "uuid", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_create_domain"("p_name" "text") RETURNS TABLE("id" "uuid", "name" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
DECLARE v_id uuid; v_name text;
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.manage');
  v_name:=users._admin_taxonomy_clean_name(p_name);
  INSERT INTO core.domains(name) VALUES(v_name) RETURNING core.domains.id INTO v_id;
  RETURN QUERY SELECT r.id,r.name,r.is_active,r.created_at,r.updated_at,r.total_count FROM users._admin_taxonomy_row('domains',v_id) r;
END;
$$;


ALTER FUNCTION "users"."admin_create_domain"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_create_item"("p_category_id" "uuid", "p_name" "text") RETURNS TABLE("id" "uuid", "category_id" "uuid", "category_name" "text", "name" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
DECLARE v_id uuid; v_name text;
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.manage');
  IF p_category_id IS NULL OR NOT EXISTS(SELECT 1 FROM core.categories c JOIN core.domains d ON d.id=c.domain_id WHERE c.id=p_category_id AND c.is_active IS TRUE AND d.is_active IS TRUE) THEN RAISE EXCEPTION 'p_category_id must reference an existing active category under an active domain' USING ERRCODE='22023'; END IF;
  v_name:=users._admin_taxonomy_clean_name(p_name);
  INSERT INTO core.items(category_id,name) VALUES(p_category_id,v_name) RETURNING core.items.id INTO v_id;
  RETURN QUERY SELECT r.id,r.parent_id,r.parent_name,r.name,r.is_active,r.created_at,r.updated_at,r.total_count FROM users._admin_taxonomy_row('items',v_id) r;
END;
$$;


ALTER FUNCTION "users"."admin_create_item"("p_category_id" "uuid", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_create_item_variant"("p_item_id" "uuid", "p_name" "text") RETURNS TABLE("id" "uuid", "item_id" "uuid", "item_name" "text", "name" "text", "is_active" boolean, "source" "text", "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
DECLARE v_id uuid; v_name text;
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.manage');
  IF p_item_id IS NULL OR NOT EXISTS(SELECT 1 FROM core.items i JOIN core.categories c ON c.id=i.category_id JOIN core.domains d ON d.id=c.domain_id WHERE i.id=p_item_id AND i.is_active IS TRUE AND c.is_active IS TRUE AND d.is_active IS TRUE) THEN RAISE EXCEPTION 'p_item_id must reference an existing active item under active ancestors' USING ERRCODE='22023'; END IF;
  v_name:=users._admin_taxonomy_clean_name(p_name);
  IF core.normalize_item_variant_name(v_name)='' THEN RAISE EXCEPTION 'variant name must contain a letter, number, or other non-separator character' USING ERRCODE='22023'; END IF;
  INSERT INTO core.item_variants(item_id,name,is_active,source) VALUES(p_item_id,v_name,true,'admin') RETURNING core.item_variants.id INTO v_id;
  RETURN QUERY SELECT r.id,r.parent_id,r.parent_name,r.name,r.is_active,r.source,r.updated_at,r.total_count FROM users._admin_taxonomy_row('item_variants',v_id) r;
END;
$$;


ALTER FUNCTION "users"."admin_create_item_variant"("p_item_id" "uuid", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_create_location"("p_name" "text", "p_level_id" "uuid", "p_country_id" "uuid", "p_parent_id" "uuid" DEFAULT NULL::"uuid", "p_code" bigint DEFAULT NULL::bigint) RETURNS TABLE("id" "uuid", "name" "text", "level_id" "uuid", "level_name" "text", "parent_id" "uuid", "parent_name" "text", "country_id" "uuid", "country_name" character varying, "code" bigint, "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth', 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
  IF NOT core.has_permission('admin.locations.manage') THEN RAISE EXCEPTION 'permission denied: admin.locations.manage is required' USING ERRCODE='42501'; END IF;
  IF NULLIF(btrim(p_name),'') IS NULL THEN RAISE EXCEPTION 'name is required' USING ERRCODE='22023'; END IF;
  PERFORM users._admin_validate_location_hierarchy(NULL,p_level_id,p_parent_id,p_country_id);
  INSERT INTO core.locations (name,level_id,parent_id,country_id,code,is_active,created_at,updated_at) VALUES (btrim(p_name),p_level_id,p_parent_id,p_country_id,p_code,true,now(),now()) RETURNING core.locations.id INTO v_id;
  RETURN QUERY SELECT * FROM users._admin_location_row(v_id);
END;
$$;


ALTER FUNCTION "users"."admin_create_location"("p_name" "text", "p_level_id" "uuid", "p_country_id" "uuid", "p_parent_id" "uuid", "p_code" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_list_attribute_values"("p_attribute_id" "uuid") RETURNS TABLE("attribute_id" "uuid", "attribute_name" "text", "data_type" "text", "enum_value_id" "uuid", "value" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.view');
  IF p_attribute_id IS NULL OR NOT EXISTS(SELECT 1 FROM core.attribute_registry ar WHERE ar.id=p_attribute_id) THEN RAISE EXCEPTION 'p_attribute_id must reference an existing attribute' USING ERRCODE='22023'; END IF;
  RETURN QUERY SELECT ar.id,ar.name,ar.data_type,ev.id,ev.value,ev.created_at,ev.updated_at,count(*) OVER()::bigint
  FROM core.attribute_registry ar JOIN core.attribute_enum_values ev ON ev.attribute_id=ar.id
  WHERE ar.id=p_attribute_id ORDER BY ev.value,ev.id;
END;
$$;


ALTER FUNCTION "users"."admin_list_attribute_values"("p_attribute_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_list_attributes"("p_search" "text" DEFAULT NULL::"text", "p_data_type" "text" DEFAULT NULL::"text", "p_is_active" boolean DEFAULT NULL::boolean, "p_category_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0, "p_sort" "text" DEFAULT 'name'::"text", "p_order" "text" DEFAULT 'asc'::"text") RETURNS TABLE("attribute_id" "uuid", "name" "text", "data_type" "text", "description" "text", "unit_id" "uuid", "unit_name" "text", "unit_symbol" "text", "attribute_level" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "category_count" bigint, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
DECLARE
  v_limit integer := COALESCE(p_limit, 25);
  v_offset integer := COALESCE(p_offset, 0);
  v_sort text := lower(btrim(COALESCE(p_sort, 'name')));
  v_order text := lower(btrim(COALESCE(p_order, 'asc')));
  v_search text := NULLIF(btrim(p_search), '');
  v_data_type text := NULLIF(lower(btrim(p_data_type)), '');
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.view');
  IF v_limit < 1 OR v_limit > 100 THEN RAISE EXCEPTION 'p_limit must be between 1 and 100' USING ERRCODE='22023'; END IF;
  IF v_offset < 0 THEN RAISE EXCEPTION 'p_offset must be zero or greater' USING ERRCODE='22023'; END IF;
  IF v_sort NOT IN ('name','data_type','attribute_level','is_active','created_at','updated_at') THEN RAISE EXCEPTION 'unsupported p_sort value' USING ERRCODE='22023'; END IF;
  IF v_order NOT IN ('asc','desc') THEN RAISE EXCEPTION 'p_order must be asc or desc' USING ERRCODE='22023'; END IF;
  IF v_data_type IS NOT NULL AND v_data_type NOT IN ('text','number','boolean','date','enum','json') THEN RAISE EXCEPTION 'unsupported p_data_type value' USING ERRCODE='22023'; END IF;
  IF p_category_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM core.categories c WHERE c.id=p_category_id) THEN RAISE EXCEPTION 'p_category_id must reference an existing category' USING ERRCODE='22023'; END IF;

  RETURN QUERY
  WITH rows AS (
    SELECT ar.id, ar.name, ar.data_type, ar.description, ar.unit_id,
           u.name AS unit_name, u.symbol AS unit_symbol, ar.attribute_level,
           ar.is_active, ar.created_at, ar.updated_at,
           (SELECT count(*)::bigint FROM core.category_attribute_map cam WHERE cam.attribute_id=ar.id) AS category_count
    FROM core.attribute_registry ar
    LEFT JOIN core.units u ON u.id=ar.unit_id
    WHERE (v_search IS NULL OR strpos(lower(ar.name),lower(v_search))>0 OR strpos(lower(COALESCE(ar.description,'')),lower(v_search))>0)
      AND (v_data_type IS NULL OR ar.data_type=v_data_type)
      AND (p_is_active IS NULL OR ar.is_active=p_is_active)
      AND (p_category_id IS NULL OR EXISTS (SELECT 1 FROM core.category_attribute_map cam WHERE cam.attribute_id=ar.id AND cam.category_id=p_category_id))
  ), counted AS (SELECT r.*,count(*) OVER()::bigint AS total_count FROM rows r)
  SELECT c.id,c.name,c.data_type,c.description,c.unit_id,c.unit_name,c.unit_symbol,c.attribute_level,
         c.is_active,c.created_at,c.updated_at,c.category_count,c.total_count
  FROM counted c
  ORDER BY CASE WHEN v_sort='name' AND v_order='asc' THEN c.name END ASC NULLS LAST,
           CASE WHEN v_sort='name' AND v_order='desc' THEN c.name END DESC NULLS LAST,
           CASE WHEN v_sort='data_type' AND v_order='asc' THEN c.data_type END ASC,
           CASE WHEN v_sort='data_type' AND v_order='desc' THEN c.data_type END DESC,
           CASE WHEN v_sort='attribute_level' AND v_order='asc' THEN c.attribute_level END ASC NULLS LAST,
           CASE WHEN v_sort='attribute_level' AND v_order='desc' THEN c.attribute_level END DESC NULLS LAST,
           CASE WHEN v_sort='is_active' AND v_order='asc' THEN c.is_active END ASC,
           CASE WHEN v_sort='is_active' AND v_order='desc' THEN c.is_active END DESC,
           CASE WHEN v_sort='created_at' AND v_order='asc' THEN c.created_at END ASC,
           CASE WHEN v_sort='created_at' AND v_order='desc' THEN c.created_at END DESC,
           CASE WHEN v_sort='updated_at' AND v_order='asc' THEN c.updated_at END ASC,
           CASE WHEN v_sort='updated_at' AND v_order='desc' THEN c.updated_at END DESC,c.id
  LIMIT v_limit OFFSET v_offset;
END;
$$;


ALTER FUNCTION "users"."admin_list_attributes"("p_search" "text", "p_data_type" "text", "p_is_active" boolean, "p_category_id" "uuid", "p_limit" integer, "p_offset" integer, "p_sort" "text", "p_order" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_list_categories"("p_domain_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_is_active" boolean DEFAULT NULL::boolean, "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0, "p_sort" "text" DEFAULT 'name'::"text", "p_order" "text" DEFAULT 'asc'::"text") RETURNS TABLE("id" "uuid", "domain_id" "uuid", "domain_name" "text", "name" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
DECLARE v_limit integer := COALESCE(p_limit,25); v_offset integer := COALESCE(p_offset,0); v_sort text := lower(btrim(COALESCE(p_sort,'name'))); v_order text := lower(btrim(COALESCE(p_order,'asc'))); v_search text := NULLIF(btrim(p_search),'');
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.view');
  IF p_domain_id IS NULL THEN RAISE EXCEPTION 'p_domain_id is required' USING ERRCODE='22023'; END IF;
  IF v_limit < 1 OR v_limit > 100 THEN RAISE EXCEPTION 'p_limit must be between 1 and 100' USING ERRCODE='22023'; END IF;
  IF v_offset < 0 THEN RAISE EXCEPTION 'p_offset must be zero or greater' USING ERRCODE='22023'; END IF;
  IF v_sort NOT IN ('name','created_at','updated_at','is_active') THEN RAISE EXCEPTION 'unsupported p_sort value' USING ERRCODE='22023'; END IF;
  IF v_order NOT IN ('asc','desc') THEN RAISE EXCEPTION 'p_order must be asc or desc' USING ERRCODE='22023'; END IF;
  RETURN QUERY SELECT c.id,c.domain_id,d.name,c.name,c.is_active,c.created_at,c.updated_at,count(*) OVER()::bigint
  FROM core.categories c JOIN core.domains d ON d.id=c.domain_id
  WHERE c.domain_id=p_domain_id AND (p_is_active IS NULL OR c.is_active=p_is_active)
    AND (v_search IS NULL OR strpos(lower(c.name),lower(v_search))>0 OR strpos(lower(d.name),lower(v_search))>0)
  ORDER BY CASE WHEN v_sort='name' AND v_order='asc' THEN c.name END ASC NULLS LAST, CASE WHEN v_sort='name' AND v_order='desc' THEN c.name END DESC NULLS LAST,
    CASE WHEN v_sort='created_at' AND v_order='asc' THEN c.created_at END ASC, CASE WHEN v_sort='created_at' AND v_order='desc' THEN c.created_at END DESC,
    CASE WHEN v_sort='updated_at' AND v_order='asc' THEN c.updated_at END ASC, CASE WHEN v_sort='updated_at' AND v_order='desc' THEN c.updated_at END DESC,
    CASE WHEN v_sort='is_active' AND v_order='asc' THEN c.is_active END ASC, CASE WHEN v_sort='is_active' AND v_order='desc' THEN c.is_active END DESC,c.id
  LIMIT v_limit OFFSET v_offset;
END;
$$;


