CREATE OR REPLACE FUNCTION "users"."admin_list_category_attributes"("p_category_id" "uuid") RETURNS TABLE("mapping_id" "uuid", "category_id" "uuid", "attribute_id" "uuid", "is_required" boolean, "attribute_name" "text", "data_type" "text", "description" "text", "unit_id" "uuid", "unit_name" "text", "unit_symbol" "text", "attribute_level" "text", "attribute_is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.view');
  IF p_category_id IS NULL OR NOT EXISTS(SELECT 1 FROM core.categories c WHERE c.id=p_category_id) THEN RAISE EXCEPTION 'p_category_id must reference an existing category' USING ERRCODE='22023'; END IF;
  RETURN QUERY SELECT cam.id,cam.category_id,cam.attribute_id,cam.is_required,ar.name,ar.data_type,ar.description,
    ar.unit_id,u.name,u.symbol,ar.attribute_level,ar.is_active,cam.created_at,cam.updated_at,count(*) OVER()::bigint
  FROM core.category_attribute_map cam
  JOIN core.attribute_registry ar ON ar.id=cam.attribute_id
  LEFT JOIN core.units u ON u.id=ar.unit_id
  WHERE cam.category_id=p_category_id
  ORDER BY ar.name,cam.id;
END;
$$;


