CREATE OR REPLACE FUNCTION "users"."admin_list_items"("p_category_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_is_active" boolean DEFAULT NULL::boolean, "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0, "p_sort" "text" DEFAULT 'name'::"text", "p_order" "text" DEFAULT 'asc'::"text") RETURNS TABLE("id" "uuid", "category_id" "uuid", "category_name" "text", "name" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
DECLARE v_limit integer := COALESCE(p_limit,25); v_offset integer := COALESCE(p_offset,0); v_sort text := lower(btrim(COALESCE(p_sort,'name'))); v_order text := lower(btrim(COALESCE(p_order,'asc'))); v_search text := NULLIF(btrim(p_search),'');
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.view');
  IF p_category_id IS NULL THEN RAISE EXCEPTION 'p_category_id is required' USING ERRCODE='22023'; END IF;
  IF v_limit < 1 OR v_limit > 100 THEN RAISE EXCEPTION 'p_limit must be between 1 and 100' USING ERRCODE='22023'; END IF;
  IF v_offset < 0 THEN RAISE EXCEPTION 'p_offset must be zero or greater' USING ERRCODE='22023'; END IF;
  IF v_sort NOT IN ('name','created_at','updated_at','is_active') THEN RAISE EXCEPTION 'unsupported p_sort value' USING ERRCODE='22023'; END IF;
  IF v_order NOT IN ('asc','desc') THEN RAISE EXCEPTION 'p_order must be asc or desc' USING ERRCODE='22023'; END IF;
  RETURN QUERY SELECT i.id,i.category_id,c.name,i.name,i.is_active,i.created_at,i.updated_at,count(*) OVER()::bigint
  FROM core.items i JOIN core.categories c ON c.id=i.category_id
  WHERE i.category_id=p_category_id AND (p_is_active IS NULL OR i.is_active=p_is_active)
    AND (v_search IS NULL OR strpos(lower(i.name),lower(v_search))>0 OR strpos(lower(c.name),lower(v_search))>0)
  ORDER BY CASE WHEN v_sort='name' AND v_order='asc' THEN i.name END ASC NULLS LAST, CASE WHEN v_sort='name' AND v_order='desc' THEN i.name END DESC NULLS LAST,
    CASE WHEN v_sort='created_at' AND v_order='asc' THEN i.created_at END ASC, CASE WHEN v_sort='created_at' AND v_order='desc' THEN i.created_at END DESC,
    CASE WHEN v_sort='updated_at' AND v_order='asc' THEN i.updated_at END ASC, CASE WHEN v_sort='updated_at' AND v_order='desc' THEN i.updated_at END DESC,
    CASE WHEN v_sort='is_active' AND v_order='asc' THEN i.is_active END ASC, CASE WHEN v_sort='is_active' AND v_order='desc' THEN i.is_active END DESC,i.id
