CREATE OR REPLACE FUNCTION "users"."admin_list_locations"("p_parent_id" "uuid" DEFAULT NULL::"uuid", "p_level_id" "uuid" DEFAULT NULL::"uuid", "p_country_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_is_active" boolean DEFAULT NULL::boolean, "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0, "p_sort" "text" DEFAULT 'name'::"text", "p_order" "text" DEFAULT 'asc'::"text") RETURNS TABLE("id" "uuid", "name" "text", "level_id" "uuid", "level_name" "text", "parent_id" "uuid", "parent_name" "text", "country_id" "uuid", "country_name" character varying, "code" bigint, "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth', 'public'
    AS $$
DECLARE v_limit integer := COALESCE(p_limit,25); v_offset integer := COALESCE(p_offset,0); v_sort text := lower(btrim(COALESCE(p_sort,'name'))); v_order text := lower(btrim(COALESCE(p_order,'asc'))); v_search text := NULLIF(btrim(p_search),'');
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
  IF NOT core.has_permission('admin.locations.view') THEN RAISE EXCEPTION 'permission denied: admin.locations.view is required' USING ERRCODE='42501'; END IF;
  IF v_limit < 1 OR v_limit > 100 THEN RAISE EXCEPTION 'p_limit must be between 1 and 100' USING ERRCODE='22023'; END IF;
  IF v_offset < 0 THEN RAISE EXCEPTION 'p_offset must be zero or greater' USING ERRCODE='22023'; END IF;
  IF v_sort NOT IN ('name','created_at','updated_at') THEN RAISE EXCEPTION 'unsupported p_sort value: %', v_sort USING ERRCODE='22023'; END IF;
  IF v_order NOT IN ('asc','desc') THEN RAISE EXCEPTION 'p_order must be asc or desc' USING ERRCODE='22023'; END IF;
  RETURN QUERY
  WITH rows AS (
    SELECT l.id, l.name, l.level_id, gl.level_name, l.parent_id, pl.name AS parent_name, l.country_id, c.name AS country_name, l.code, l.is_active, l.created_at, l.updated_at
    FROM core.locations l
    LEFT JOIN core.geography_levels gl ON gl.id=l.level_id
    LEFT JOIN core.locations pl ON pl.id=l.parent_id
    LEFT JOIN core.countries c ON c.id=l.country_id
    WHERE (p_parent_id IS NULL OR l.parent_id=p_parent_id)
      AND (p_level_id IS NULL OR l.level_id=p_level_id)
      AND (p_country_id IS NULL OR l.country_id=p_country_id)
      AND (p_is_active IS NULL OR l.is_active=p_is_active)
      AND (v_search IS NULL OR lower(l.name) LIKE '%'||lower(v_search)||'%' OR lower(COALESCE(l.code::text,'')) LIKE '%'||lower(v_search)||'%' OR lower(COALESCE(gl.level_name,'')) LIKE '%'||lower(v_search)||'%' OR lower(COALESCE(pl.name,'')) LIKE '%'||lower(v_search)||'%')
  ), counted AS (SELECT r.*, count(*) OVER() AS total_count FROM rows r)
  SELECT c.id,c.name,c.level_id,c.level_name,c.parent_id,c.parent_name,c.country_id,c.country_name,c.code,c.is_active,c.created_at,c.updated_at,c.total_count
  FROM counted c
  ORDER BY CASE WHEN v_sort='name' AND v_order='asc' THEN c.name END ASC NULLS LAST, CASE WHEN v_sort='name' AND v_order='desc' THEN c.name END DESC NULLS LAST, CASE WHEN v_sort='created_at' AND v_order='asc' THEN c.created_at END ASC, CASE WHEN v_sort='created_at' AND v_order='desc' THEN c.created_at END DESC, CASE WHEN v_sort='updated_at' AND v_order='asc' THEN c.updated_at END ASC, CASE WHEN v_sort='updated_at' AND v_order='desc' THEN c.updated_at END DESC, c.id
  LIMIT v_limit OFFSET v_offset;
END;
$$;


ALTER FUNCTION "users"."admin_list_locations"("p_parent_id" "uuid", "p_level_id" "uuid", "p_country_id" "uuid", "p_search" "text", "p_is_active" boolean, "p_limit" integer, "p_offset" integer, "p_sort" "text", "p_order" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_list_user_activity"("p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0, "p_profile_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_event_type" "text" DEFAULT NULL::"text", "p_start_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_sort" "text" DEFAULT 'occurred_at'::"text", "p_order" "text" DEFAULT 'desc'::"text") RETURNS TABLE("activity_id" "uuid", "profile_id" "uuid", "display_name" "text", "event_type" "text", "description" "text", "entity_id" "uuid", "entity_name" "text", "workspace_id" "uuid", "workspace_name" "text", "status" "text", "occurred_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'users', 'core', 'auth'
    AS $_$
DECLARE
  v_limit integer;
  v_offset integer;
  v_search text;
  v_event_type text;
  v_sort text;
  v_order text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  IF NOT core.has_permission('admin.users.view') THEN
    RAISE EXCEPTION 'permission denied: admin.users.view is required' USING ERRCODE = '42501';
  END IF;

  v_limit := COALESCE(p_limit, 25);
  v_offset := COALESCE(p_offset, 0);
  v_search := NULLIF(btrim(p_search), '');
  v_event_type := NULLIF(btrim(p_event_type), '');
  v_sort := lower(btrim(COALESCE(p_sort, 'occurred_at')));
  v_order := lower(btrim(COALESCE(p_order, 'desc')));

  IF v_limit < 1 OR v_limit > 100 THEN
    RAISE EXCEPTION 'p_limit must be between 1 and 100' USING ERRCODE = '22023';
  END IF;

  IF v_offset < 0 THEN
    RAISE EXCEPTION 'p_offset must be zero or greater' USING ERRCODE = '22023';
  END IF;

  IF v_sort <> 'occurred_at' THEN
    RAISE EXCEPTION 'unsupported p_sort value: %', v_sort USING ERRCODE = '22023';
  END IF;

  IF v_order NOT IN ('asc', 'desc') THEN
    RAISE EXCEPTION 'p_order must be asc or desc' USING ERRCODE = '22023';
  END IF;

  IF p_start_at IS NOT NULL AND p_end_at IS NOT NULL AND p_start_at >= p_end_at THEN
    RAISE EXCEPTION 'p_start_at must be earlier than p_end_at' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH approved_events AS (
    SELECT
      a.id AS activity_id,
      p.id AS profile_id,
      NULLIF(btrim(concat_ws(' ', NULLIF(btrim(p.first_name), ''), NULLIF(btrim(p.middle_name), ''), NULLIF(btrim(p.last_name), ''))), '') AS display_name,
      a.payload->>'action' AS event_type,
      CASE a.payload->>'action'
        WHEN 'logout' THEN 'User signed out'
        WHEN 'user_signedup' THEN 'User signed up'
        WHEN 'user_confirmation_requested' THEN 'User confirmation requested'
        WHEN 'user_recovery_requested' THEN 'User recovery requested'
      END AS description,
      a.created_at AS occurred_at
    FROM auth.audit_log_entries AS a
    JOIN users.profiles AS p
      ON p.auth_user_id = CASE
        WHEN a.payload->>'actor_id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
        THEN (a.payload->>'actor_id')::uuid
        ELSE NULL
      END
    WHERE a.payload->>'action' IN (
      'logout',
      'user_signedup',
      'user_confirmation_requested',
      'user_recovery_requested'
    )
      AND (p_profile_id IS NULL OR p.id = p_profile_id)
      AND (v_event_type IS NULL OR a.payload->>'action' = v_event_type)
      AND (p_start_at IS NULL OR a.created_at >= p_start_at)
      AND (p_end_at IS NULL OR a.created_at < p_end_at)
      AND (
        v_search IS NULL
        OR lower(concat_ws(' ', p.first_name, p.middle_name, p.last_name)) LIKE '%' || lower(v_search) || '%'
        OR lower(a.payload->>'action') LIKE '%' || lower(v_search) || '%'
        OR lower(CASE a.payload->>'action'
          WHEN 'logout' THEN 'User signed out'
          WHEN 'user_signedup' THEN 'User signed up'
          WHEN 'user_confirmation_requested' THEN 'User confirmation requested'
          WHEN 'user_recovery_requested' THEN 'User recovery requested'
        END) LIKE '%' || lower(v_search) || '%'
      )
  ), counted AS (
    SELECT e.*, count(*) OVER () AS total_count
    FROM approved_events AS e
  )
  SELECT
    c.activity_id,
    c.profile_id,
    c.display_name,
    c.event_type,
    c.description,
    NULL::uuid AS entity_id,
    NULL::text AS entity_name,
    NULL::uuid AS workspace_id,
    NULL::text AS workspace_name,
    NULL::text AS status,
    c.occurred_at,
    c.total_count
  FROM counted AS c
  ORDER BY
    CASE WHEN v_order = 'asc' THEN c.occurred_at END ASC,
    CASE WHEN v_order = 'desc' THEN c.occurred_at END DESC,
    c.activity_id
  LIMIT v_limit OFFSET v_offset;
END;
$_$;


ALTER FUNCTION "users"."admin_list_user_activity"("p_limit" integer, "p_offset" integer, "p_profile_id" "uuid", "p_search" "text", "p_event_type" "text", "p_start_at" timestamp with time zone, "p_end_at" timestamp with time zone, "p_sort" "text", "p_order" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_list_users"("p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0, "p_search" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_user_type" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'created_at'::"text", "p_order" "text" DEFAULT 'desc'::"text") RETURNS TABLE("profile_id" "uuid", "display_name" "text", "email" "text", "phone" "text", "is_active" boolean, "account_status" "text", "profile_status" "text", "is_complete" boolean, "verified" boolean, "created_at" timestamp with time zone, "workspace_count" bigint, "default_workspace_id" "uuid", "default_workspace_name" "text", "entity_count" bigint, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'users', 'core', 'system'
    AS $$
DECLARE
  v_limit integer;
  v_offset integer;
  v_search text;
  v_status text;
  v_user_type text;
  v_sort text;
  v_order text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  IF NOT core.has_permission('admin.users.view') THEN
    RAISE EXCEPTION 'permission denied: admin.users.view is required' USING ERRCODE = '42501';
  END IF;

  v_limit := COALESCE(p_limit, 25);
  v_offset := COALESCE(p_offset, 0);
  v_search := NULLIF(btrim(p_search), '');
  v_status := NULLIF(btrim(p_status), '');
  v_user_type := NULLIF(btrim(p_user_type), '');
  v_sort := lower(btrim(COALESCE(p_sort, 'created_at')));
  v_order := lower(btrim(COALESCE(p_order, 'desc')));

  IF v_limit < 1 OR v_limit > 100 THEN
    RAISE EXCEPTION 'p_limit must be between 1 and 100' USING ERRCODE = '22023';
  END IF;

  IF v_offset < 0 THEN
    RAISE EXCEPTION 'p_offset must be zero or greater' USING ERRCODE = '22023';
  END IF;

  IF v_sort NOT IN ('created_at', 'display_name', 'account_status', 'profile_status', 'is_active') THEN
    RAISE EXCEPTION 'unsupported p_sort value: %', v_sort USING ERRCODE = '22023';
  END IF;

  IF v_order NOT IN ('asc', 'desc') THEN
    RAISE EXCEPTION 'p_order must be asc or desc' USING ERRCODE = '22023';
  END IF;

  IF v_user_type IS NOT NULL THEN
    RAISE EXCEPTION 'p_user_type is unsupported: users.profiles has no user_type column' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH directory_rows AS (
    SELECT
      p.id AS profile_id,
      NULLIF(btrim(concat_ws(' ', NULLIF(btrim(p.first_name), ''), NULLIF(btrim(p.middle_name), ''), NULLIF(btrim(p.last_name), ''))), '') AS display_name,
      p.email,
      p.phone,
      p.is_active,
      p.account_status,
      p.profile_status,
      p.is_complete,
      p.verified,
      p.created_at,
      COALESCE(ws.workspace_count, 0::bigint) AS workspace_count,
      ws.default_workspace_id,
      ws.default_workspace_name,
      COALESCE(ec.entity_count, 0::bigint) AS entity_count
    FROM users.profiles AS p
    LEFT JOIN LATERAL (
      SELECT
        count(DISTINCT uw.workspace_id)::bigint AS workspace_count,
        (array_agg(uw.workspace_id ORDER BY uw.created_at, uw.id)
          FILTER (WHERE uw.is_default = true))[1] AS default_workspace_id,
        (array_agg(w.name ORDER BY uw.created_at, uw.id)
          FILTER (WHERE uw.is_default = true))[1] AS default_workspace_name
      FROM users.user_workspaces AS uw
      JOIN system.workspaces AS w
        ON w.id = uw.workspace_id
      WHERE uw.auth_user_id = p.auth_user_id
    ) AS ws ON true
    LEFT JOIN LATERAL (
      SELECT count(DISTINCT em.entity_id)::bigint AS entity_count
      FROM core.entity_members AS em
      JOIN core.entities AS e
        ON e.id = em.entity_id
       AND e.is_active = true
      WHERE em.profile_id = p.id
        AND em.is_active = true
        AND em.membership_status = 'active'
    ) AS ec ON true
    WHERE (v_status IS NULL OR p.account_status = v_status OR p.profile_status = v_status)
      AND (
        v_search IS NULL
        OR lower(concat_ws(' ', p.first_name, p.middle_name, p.last_name)) LIKE '%' || lower(v_search) || '%'
        OR lower(COALESCE(p.email, '')) LIKE '%' || lower(v_search) || '%'
        OR lower(COALESCE(p.phone, '')) LIKE '%' || lower(v_search) || '%'
      )
  ), counted AS (
    SELECT d.*, count(*) OVER () AS total_count
    FROM directory_rows AS d
  )
  SELECT
    c.profile_id,
    c.display_name,
    c.email,
    c.phone,
    c.is_active,
    c.account_status,
    c.profile_status,
    c.is_complete,
    c.verified,
    c.created_at,
    c.workspace_count,
    c.default_workspace_id,
    c.default_workspace_name,
    c.entity_count,
    c.total_count
  FROM counted AS c
  ORDER BY
    CASE WHEN v_sort = 'created_at' AND v_order = 'asc' THEN c.created_at END ASC,
    CASE WHEN v_sort = 'created_at' AND v_order = 'desc' THEN c.created_at END DESC,
    CASE WHEN v_sort = 'display_name' AND v_order = 'asc' THEN c.display_name END ASC NULLS LAST,
    CASE WHEN v_sort = 'display_name' AND v_order = 'desc' THEN c.display_name END DESC NULLS LAST,
    CASE WHEN v_sort = 'account_status' AND v_order = 'asc' THEN c.account_status END ASC,
    CASE WHEN v_sort = 'account_status' AND v_order = 'desc' THEN c.account_status END DESC,
    CASE WHEN v_sort = 'profile_status' AND v_order = 'asc' THEN c.profile_status END ASC,
    CASE WHEN v_sort = 'profile_status' AND v_order = 'desc' THEN c.profile_status END DESC,
    CASE WHEN v_sort = 'is_active' AND v_order = 'asc' THEN c.is_active END ASC,
    CASE WHEN v_sort = 'is_active' AND v_order = 'desc' THEN c.is_active END DESC,
    c.profile_id
  LIMIT v_limit OFFSET v_offset;
END;
$$;


ALTER FUNCTION "users"."admin_list_users"("p_limit" integer, "p_offset" integer, "p_search" "text", "p_status" "text", "p_user_type" "text", "p_sort" "text", "p_order" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_set_attribute_active"("p_attribute_id" "uuid", "p_is_active" boolean) RETURNS TABLE("attribute_id" "uuid", "name" "text", "data_type" "text", "description" "text", "unit_id" "uuid", "unit_name" "text", "unit_symbol" "text", "attribute_level" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "category_count" bigint, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.manage');
  IF p_is_active IS NULL THEN RAISE EXCEPTION 'p_is_active is required' USING ERRCODE='22023'; END IF;
  IF p_attribute_id IS NULL OR NOT EXISTS(SELECT 1 FROM core.attribute_registry ar WHERE ar.id=p_attribute_id) THEN RAISE EXCEPTION 'p_attribute_id must reference an existing attribute' USING ERRCODE='22023'; END IF;
  UPDATE core.attribute_registry ar SET is_active=p_is_active WHERE ar.id=p_attribute_id;
  RETURN QUERY SELECT ar.id,ar.name,ar.data_type,ar.description,ar.unit_id,u.name,u.symbol,ar.attribute_level,
    ar.is_active,ar.created_at,ar.updated_at,
    (SELECT count(*)::bigint FROM core.category_attribute_map cam WHERE cam.attribute_id=ar.id),1::bigint
  FROM core.attribute_registry ar LEFT JOIN core.units u ON u.id=ar.unit_id WHERE ar.id=p_attribute_id;
END;
$$;


ALTER FUNCTION "users"."admin_set_attribute_active"("p_attribute_id" "uuid", "p_is_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_set_category_active"("p_category_id" "uuid", "p_is_active" boolean) RETURNS TABLE("id" "uuid", "domain_id" "uuid", "domain_name" "text", "name" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.manage');
  IF p_is_active IS NULL THEN RAISE EXCEPTION 'p_is_active is required' USING ERRCODE='22023'; END IF;
  IF p_category_id IS NULL OR NOT EXISTS(SELECT 1 FROM core.categories c WHERE c.id=p_category_id) THEN RAISE EXCEPTION 'p_category_id must reference an existing category' USING ERRCODE='22023'; END IF;
  IF p_is_active AND NOT EXISTS(SELECT 1 FROM core.categories c JOIN core.domains d ON d.id=c.domain_id WHERE c.id=p_category_id AND d.is_active IS TRUE) THEN RAISE EXCEPTION 'cannot activate category under an inactive domain' USING ERRCODE='22023'; END IF;
  IF NOT p_is_active AND EXISTS(SELECT 1 FROM core.items i WHERE i.category_id=p_category_id AND i.is_active IS TRUE) THEN RAISE EXCEPTION 'cannot deactivate category while active items exist' USING ERRCODE='22023'; END IF;
  UPDATE core.categories SET is_active=p_is_active WHERE core.categories.id=p_category_id;
  RETURN QUERY SELECT r.id,r.parent_id,r.parent_name,r.name,r.is_active,r.created_at,r.updated_at,r.total_count FROM users._admin_taxonomy_row('categories',p_category_id) r;
END;
$$;


ALTER FUNCTION "users"."admin_set_category_active"("p_category_id" "uuid", "p_is_active" boolean) OWNER TO "postgres";


