    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.manage');
  IF p_is_active IS NULL THEN RAISE EXCEPTION 'p_is_active is required' USING ERRCODE='22023'; END IF;
  IF p_domain_id IS NULL OR NOT EXISTS(SELECT 1 FROM core.domains d WHERE d.id=p_domain_id) THEN RAISE EXCEPTION 'p_domain_id must reference an existing domain' USING ERRCODE='22023'; END IF;
  IF NOT p_is_active AND EXISTS(SELECT 1 FROM core.categories c WHERE c.domain_id=p_domain_id AND c.is_active IS TRUE) THEN RAISE EXCEPTION 'cannot deactivate domain while active categories exist' USING ERRCODE='22023'; END IF;
  UPDATE core.domains SET is_active=p_is_active WHERE core.domains.id=p_domain_id;
  RETURN QUERY SELECT r.id,r.name,r.is_active,r.created_at,r.updated_at,r.total_count FROM users._admin_taxonomy_row('domains',p_domain_id) r;
END;
