CREATE OR REPLACE FUNCTION "users"."admin_set_item_active"("p_item_id" "uuid", "p_is_active" boolean) RETURNS TABLE("id" "uuid", "category_id" "uuid", "category_name" "text", "name" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.manage');
  IF p_is_active IS NULL THEN RAISE EXCEPTION 'p_is_active is required' USING ERRCODE='22023'; END IF;
  IF p_item_id IS NULL OR NOT EXISTS(SELECT 1 FROM core.items i WHERE i.id=p_item_id) THEN RAISE EXCEPTION 'p_item_id must reference an existing item' USING ERRCODE='22023'; END IF;
  IF p_is_active AND NOT EXISTS(SELECT 1 FROM core.items i JOIN core.categories c ON c.id=i.category_id JOIN core.domains d ON d.id=c.domain_id WHERE i.id=p_item_id AND c.is_active IS TRUE AND d.is_active IS TRUE) THEN RAISE EXCEPTION 'cannot activate item under an inactive category or domain' USING ERRCODE='22023'; END IF;
  IF NOT p_is_active AND EXISTS(SELECT 1 FROM core.item_variants v WHERE v.item_id=p_item_id AND v.is_active IS TRUE) THEN RAISE EXCEPTION 'cannot deactivate item while active variants exist' USING ERRCODE='22023'; END IF;
  UPDATE core.items SET is_active=p_is_active WHERE core.items.id=p_item_id;
  RETURN QUERY SELECT r.id,r.parent_id,r.parent_name,r.name,r.is_active,r.created_at,r.updated_at,r.total_count FROM users._admin_taxonomy_row('items',p_item_id) r;
END;
$$;


