CREATE OR REPLACE FUNCTION "users"."admin_set_item_variant_active"("p_variant_id" "uuid", "p_is_active" boolean) RETURNS TABLE("id" "uuid", "item_id" "uuid", "item_name" "text", "name" "text", "is_active" boolean, "source" "text", "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.manage');
  IF p_is_active IS NULL THEN RAISE EXCEPTION 'p_is_active is required' USING ERRCODE='22023'; END IF;
  IF p_variant_id IS NULL OR NOT EXISTS(SELECT 1 FROM core.item_variants v WHERE v.id=p_variant_id) THEN RAISE EXCEPTION 'p_variant_id must reference an existing variant' USING ERRCODE='22023'; END IF;
  IF p_is_active AND NOT EXISTS(SELECT 1 FROM core.item_variants v JOIN core.items i ON i.id=v.item_id JOIN core.categories c ON c.id=i.category_id JOIN core.domains d ON d.id=c.domain_id WHERE v.id=p_variant_id AND i.is_active IS TRUE AND c.is_active IS TRUE AND d.is_active IS TRUE) THEN RAISE EXCEPTION 'cannot activate variant under an inactive item or ancestor' USING ERRCODE='22023'; END IF;
  UPDATE core.item_variants SET is_active=p_is_active WHERE core.item_variants.id=p_variant_id;
  RETURN QUERY SELECT r.id,r.parent_id,r.parent_name,r.name,r.is_active,r.source,r.updated_at,r.total_count FROM users._admin_taxonomy_row('item_variants',p_variant_id) r;
END;
$$;


ALTER FUNCTION "users"."admin_set_item_variant_active"("p_variant_id" "uuid", "p_is_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_set_location_active"("p_location_id" "uuid", "p_is_active" boolean) RETURNS TABLE("id" "uuid", "name" "text", "level_id" "uuid", "level_name" "text", "parent_id" "uuid", "parent_name" "text", "country_id" "uuid", "country_name" character varying, "code" bigint, "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth', 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
  IF NOT core.has_permission('admin.locations.manage') THEN RAISE EXCEPTION 'permission denied: admin.locations.manage is required' USING ERRCODE='42501'; END IF;
  IF p_is_active IS NULL THEN RAISE EXCEPTION 'p_is_active is required' USING ERRCODE='22023'; END IF;
  IF NOT EXISTS (SELECT 1 FROM core.locations WHERE core.locations.id=p_location_id) THEN RAISE EXCEPTION 'location_id must reference an existing location' USING ERRCODE='22023'; END IF;
  IF p_is_active=false AND EXISTS (WITH RECURSIVE descendants(id) AS (SELECT p_location_id UNION SELECT l.id FROM core.locations l JOIN descendants d ON l.parent_id=d.id) SELECT 1 FROM descendants d JOIN core.locations l ON l.id=d.id WHERE d.id<>p_location_id AND l.is_active=true) THEN
    RAISE EXCEPTION 'cannot deactivate a location while active descendants exist' USING ERRCODE='22023';
  END IF;
  UPDATE core.locations SET is_active=p_is_active WHERE core.locations.id=p_location_id;
  RETURN QUERY SELECT * FROM users._admin_location_row(p_location_id);
END;
$$;


ALTER FUNCTION "users"."admin_set_location_active"("p_location_id" "uuid", "p_is_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_suggest_similar_item_variants"("p_item_id" "uuid", "p_name" "text", "p_exclude_variant_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "item_id" "uuid", "name" "text", "is_active" boolean, "source" "text", "similarity_score" real)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
DECLARE v_name text := NULLIF(btrim(p_name),''); v_limit integer := COALESCE(p_limit,10); v_normalized text;
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.view');
  IF p_item_id IS NULL OR NOT EXISTS (SELECT 1 FROM core.items i WHERE i.id=p_item_id) THEN RAISE EXCEPTION 'p_item_id must reference an existing item' USING ERRCODE='22023'; END IF;
  IF v_name IS NULL THEN RAISE EXCEPTION 'p_name is required' USING ERRCODE='22023'; END IF;
  IF v_limit < 1 OR v_limit > 100 THEN RAISE EXCEPTION 'p_limit must be between 1 and 100' USING ERRCODE='22023'; END IF;
  v_normalized := core.normalize_item_variant_name(v_name);
  RETURN QUERY SELECT v.id,v.item_id,v.name,v.is_active,v.source,public.similarity(v.normalized_name,v_normalized)::real
  FROM core.item_variants v
  WHERE v.item_id=p_item_id AND v.id IS DISTINCT FROM p_exclude_variant_id
    AND v.normalized_name IS DISTINCT FROM v_normalized
    AND public.similarity(v.normalized_name,v_normalized)>=0.20
  ORDER BY public.similarity(v.normalized_name,v_normalized) DESC,v.name,v.id
  LIMIT v_limit;
END;
$$;


ALTER FUNCTION "users"."admin_suggest_similar_item_variants"("p_item_id" "uuid", "p_name" "text", "p_exclude_variant_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_unassign_category_attribute"("p_category_id" "uuid", "p_attribute_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
DECLARE v_id uuid;
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.manage');
  IF p_category_id IS NULL OR NOT EXISTS(SELECT 1 FROM core.categories c WHERE c.id=p_category_id) THEN RAISE EXCEPTION 'p_category_id must reference an existing category' USING ERRCODE='22023'; END IF;
  IF p_attribute_id IS NULL OR NOT EXISTS(SELECT 1 FROM core.attribute_registry ar WHERE ar.id=p_attribute_id) THEN RAISE EXCEPTION 'p_attribute_id must reference an existing attribute' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('core.category_attribute_map:'||p_category_id::text||':'||p_attribute_id::text,0));
  SELECT cam.id INTO v_id FROM core.category_attribute_map cam WHERE cam.category_id=p_category_id AND cam.attribute_id=p_attribute_id FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  IF EXISTS (
    SELECT 1 FROM core.item_attributes ia JOIN core.items i ON i.id=ia.item_id
    WHERE i.category_id=p_category_id AND ia.attribute_id=p_attribute_id
  ) OR EXISTS (
    SELECT 1 FROM core.variant_attributes va JOIN core.item_variants iv ON iv.id=va.variant_id JOIN core.items i ON i.id=iv.item_id
    WHERE i.category_id=p_category_id AND va.attribute_id=p_attribute_id
  ) OR EXISTS (
    SELECT 1 FROM core.record_attributes ra JOIN core.records r ON r.id=ra.record_id
    WHERE r.category_id=p_category_id AND ra.attribute_id=p_attribute_id
  ) THEN RAISE EXCEPTION 'cannot unassign this attribute while values exist for items, variants, or records in this category' USING ERRCODE='23514'; END IF;
  DELETE FROM core.category_attribute_map cam WHERE cam.id=v_id;
  RETURN true;
END;
$$;


ALTER FUNCTION "users"."admin_unassign_category_attribute"("p_category_id" "uuid", "p_attribute_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_update_attribute"("p_attribute_id" "uuid", "p_name" "text", "p_data_type" "text", "p_description" "text" DEFAULT NULL::"text", "p_unit_id" "uuid" DEFAULT NULL::"uuid", "p_attribute_level" "text" DEFAULT NULL::"text") RETURNS TABLE("attribute_id" "uuid", "name" "text", "data_type" "text", "description" "text", "unit_id" "uuid", "unit_name" "text", "unit_symbol" "text", "attribute_level" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "category_count" bigint, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
DECLARE
  v_old core.attribute_registry%ROWTYPE;
  v_name text;
  v_data_type text := lower(btrim(p_data_type));
  v_level text := NULLIF(lower(btrim(p_attribute_level)), '');
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.manage');
  SELECT ar.* INTO v_old FROM core.attribute_registry ar WHERE ar.id=p_attribute_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'p_attribute_id must reference an existing attribute' USING ERRCODE='22023'; END IF;
  v_name := users._admin_taxonomy_clean_name(p_name);
  IF v_data_type NOT IN ('text','number','boolean','date','enum','json') THEN RAISE EXCEPTION 'unsupported p_data_type value' USING ERRCODE='22023'; END IF;
  IF v_level IS NOT NULL AND v_level NOT IN ('category','item','variant','record','module') THEN RAISE EXCEPTION 'unsupported p_attribute_level value' USING ERRCODE='22023'; END IF;
  IF p_unit_id IS NOT NULL AND v_data_type <> 'number' THEN RAISE EXCEPTION 'unit_id is only valid for number attributes' USING ERRCODE='22023'; END IF;
  IF p_unit_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM core.units u WHERE u.id=p_unit_id) THEN RAISE EXCEPTION 'p_unit_id must reference an existing unit' USING ERRCODE='22023'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('core.attribute_registry:'||core.normalize_taxonomy_name(v_name),0));
  IF EXISTS (SELECT 1 FROM core.attribute_registry ar WHERE ar.id<>p_attribute_id AND core.normalize_taxonomy_name(ar.name)=core.normalize_taxonomy_name(v_name)) THEN
    RAISE EXCEPTION 'an attribute with the same normalized name already exists' USING ERRCODE='23505';
  END IF;
  IF v_name IS DISTINCT FROM v_old.name AND (
    EXISTS (SELECT 1 FROM core.category_attribute_map cam WHERE cam.attribute_id=p_attribute_id) OR
    EXISTS (SELECT 1 FROM core.item_attributes ia WHERE ia.attribute_id=p_attribute_id) OR
    EXISTS (SELECT 1 FROM core.variant_attributes va WHERE va.attribute_id=p_attribute_id) OR
    EXISTS (SELECT 1 FROM core.record_attributes ra WHERE ra.attribute_id=p_attribute_id) OR
    EXISTS (SELECT 1 FROM farm_management.activity_template_values av WHERE av.attribute_id=p_attribute_id) OR
    EXISTS (SELECT 1 FROM farm_management.activity_values av WHERE av.attribute_id=p_attribute_id) OR
    EXISTS (SELECT 1 FROM farm_management.activity_attribute_rules av WHERE av.attribute_id=p_attribute_id)
  ) THEN RAISE EXCEPTION 'cannot rename an attribute while it is assigned or referenced; preserve its existing key' USING ERRCODE='23514'; END IF;
  IF v_data_type IS DISTINCT FROM v_old.data_type AND (
    EXISTS (SELECT 1 FROM core.category_attribute_map cam WHERE cam.attribute_id=p_attribute_id) OR
    EXISTS (SELECT 1 FROM core.item_attributes ia WHERE ia.attribute_id=p_attribute_id) OR
    EXISTS (SELECT 1 FROM core.variant_attributes va WHERE va.attribute_id=p_attribute_id) OR
    EXISTS (SELECT 1 FROM core.record_attributes ra WHERE ra.attribute_id=p_attribute_id) OR
    EXISTS (SELECT 1 FROM core.attribute_enum_values ev WHERE ev.attribute_id=p_attribute_id) OR
    EXISTS (SELECT 1 FROM farm_management.activity_template_values av WHERE av.attribute_id=p_attribute_id) OR
    EXISTS (SELECT 1 FROM farm_management.activity_values av WHERE av.attribute_id=p_attribute_id) OR
    EXISTS (SELECT 1 FROM farm_management.activity_attribute_rules av WHERE av.attribute_id=p_attribute_id)
  ) THEN RAISE EXCEPTION 'cannot change data_type while the attribute is assigned or referenced' USING ERRCODE='23514'; END IF;

  UPDATE core.attribute_registry ar SET name=v_name,data_type=v_data_type,
    description=NULLIF(btrim(p_description),''),unit_id=p_unit_id,attribute_level=v_level
  WHERE ar.id=p_attribute_id;
  RETURN QUERY SELECT ar.id,ar.name,ar.data_type,ar.description,ar.unit_id,u.name,u.symbol,ar.attribute_level,
    ar.is_active,ar.created_at,ar.updated_at,
    (SELECT count(*)::bigint FROM core.category_attribute_map cam WHERE cam.attribute_id=ar.id),1::bigint
  FROM core.attribute_registry ar LEFT JOIN core.units u ON u.id=ar.unit_id WHERE ar.id=p_attribute_id;
END;
$$;


ALTER FUNCTION "users"."admin_update_attribute"("p_attribute_id" "uuid", "p_name" "text", "p_data_type" "text", "p_description" "text", "p_unit_id" "uuid", "p_attribute_level" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_update_attribute_value"("p_enum_value_id" "uuid", "p_value" "text") RETURNS TABLE("attribute_id" "uuid", "attribute_name" "text", "data_type" "text", "enum_value_id" "uuid", "value" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
    AS $$
DECLARE v_value text:=NULLIF(btrim(p_value),''); v_attribute_id uuid;
BEGIN
  PERFORM users._admin_taxonomy_authorize('admin.taxonomy.manage');
  IF v_value IS NULL THEN RAISE EXCEPTION 'p_value is required' USING ERRCODE='22023'; END IF;
  IF char_length(v_value)>120 THEN RAISE EXCEPTION 'p_value cannot exceed 120 characters' USING ERRCODE='22023'; END IF;
  UPDATE core.attribute_enum_values ev SET value=v_value WHERE ev.id=p_enum_value_id RETURNING ev.attribute_id INTO v_attribute_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'p_enum_value_id must reference an existing enum value' USING ERRCODE='22023'; END IF;
  RETURN QUERY SELECT ar.id,ar.name,ar.data_type,ev.id,ev.value,ev.created_at,ev.updated_at,1::bigint
  FROM core.attribute_registry ar JOIN core.attribute_enum_values ev ON ev.attribute_id=ar.id WHERE ev.id=p_enum_value_id;
END;
$$;


ALTER FUNCTION "users"."admin_update_attribute_value"("p_enum_value_id" "uuid", "p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."admin_update_category"("p_category_id" "uuid", "p_name" "text") RETURNS TABLE("id" "uuid", "domain_id" "uuid", "domain_name" "text", "name" "text", "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
