  UPDATE core.categories SET name=v_name WHERE core.categories.id=p_category_id;
  RETURN QUERY SELECT r.id,r.parent_id,r.parent_name,r.name,r.is_active,r.created_at,r.updated_at,r.total_count FROM users._admin_taxonomy_row('categories',p_category_id) r;
END;
