CREATE OR REPLACE FUNCTION "users"."admin_update_item_variant"("p_variant_id" "uuid", "p_name" "text") RETURNS TABLE("id" "uuid", "item_id" "uuid", "item_name" "text", "name" "text", "is_active" boolean, "source" "text", "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth'
