  v_name:=users._admin_taxonomy_clean_name(p_name);
  IF core.normalize_item_variant_name(v_name)='' THEN RAISE EXCEPTION 'variant name must contain a letter, number, or other non-separator character' USING ERRCODE='22023'; END IF;
  UPDATE core.item_variants SET name=v_name WHERE core.item_variants.id=p_variant_id;
  RETURN QUERY SELECT r.id,r.parent_id,r.parent_name,r.name,r.is_active,r.source,r.updated_at,r.total_count FROM users._admin_taxonomy_row('item_variants',p_variant_id) r;
