CREATE OR REPLACE FUNCTION "users"."admin_update_location"("p_location_id" "uuid", "p_name" "text", "p_level_id" "uuid", "p_parent_id" "uuid", "p_country_id" "uuid", "p_code" bigint) RETURNS TABLE("id" "uuid", "name" "text", "level_id" "uuid", "level_name" "text", "parent_id" "uuid", "parent_name" "text", "country_id" "uuid", "country_name" character varying, "code" bigint, "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'core', 'users', 'auth', 'public'
    AS $$
DECLARE v_old core.locations%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
  IF NOT core.has_permission('admin.locations.manage') THEN RAISE EXCEPTION 'permission denied: admin.locations.manage is required' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_old FROM core.locations WHERE core.locations.id=p_location_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'location_id must reference an existing location' USING ERRCODE='22023'; END IF;
  IF NULLIF(btrim(p_name),'') IS NULL THEN RAISE EXCEPTION 'name is required' USING ERRCODE='22023'; END IF;
  IF p_level_id IS DISTINCT FROM v_old.level_id AND EXISTS (SELECT 1 FROM core.locations child WHERE child.parent_id=p_location_id) THEN RAISE EXCEPTION 'cannot change level while the location has children' USING ERRCODE='22023'; END IF;
  PERFORM users._admin_validate_location_hierarchy(p_location_id,p_level_id,p_parent_id,p_country_id);
  UPDATE core.locations SET name=btrim(p_name), level_id=p_level_id, parent_id=p_parent_id, country_id=p_country_id, code=p_code WHERE core.locations.id=p_location_id;
  RETURN QUERY SELECT * FROM users._admin_location_row(p_location_id);
END;
$$;


ALTER FUNCTION "users"."admin_update_location"("p_location_id" "uuid", "p_name" "text", "p_level_id" "uuid", "p_parent_id" "uuid", "p_country_id" "uuid", "p_code" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."complete_workspace_selection"("p_workspace_id" "uuid", "p_entity_id" "uuid" DEFAULT NULL::"uuid", "p_role_id" "uuid" DEFAULT NULL::"uuid", "p_business_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("workspace_id" "uuid", "profile_id" "uuid", "entity_id" "uuid", "role_id" "uuid", "active_mode" "text", "business_profile_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'users', 'core', 'commerce', 'system'
    AS $$
DECLARE
  v_auth_user_id uuid := auth.uid();
  v_profile_id uuid;
  v_user_workspace_id uuid;
  v_entity_id uuid;
  v_role_id uuid;
  v_mode text;
  v_role_count integer;
BEGIN
  IF v_auth_user_id IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  SELECT p.id INTO v_profile_id
  FROM users.profiles p
  WHERE p.auth_user_id = v_auth_user_id
    AND p.is_active = true
    AND p.account_status = 'active';
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'active profile not found' USING ERRCODE = '42501';
  END IF;

  SELECT uw.id, lower(w.key)
    INTO v_user_workspace_id, v_mode
  FROM users.user_workspaces uw
  JOIN system.workspaces w ON w.id = uw.workspace_id AND w.is_active = true
  WHERE uw.auth_user_id = v_auth_user_id
    AND uw.workspace_id = p_workspace_id;
  IF v_user_workspace_id IS NULL THEN
    RAISE EXCEPTION 'workspace membership is invalid or workspace is inactive' USING ERRCODE = '42501';
  END IF;
  IF v_mode NOT IN ('farmer','trader','buyer','business_rep','supplier','admin','agrovet') THEN
    v_mode := NULL;
  END IF;

  IF p_entity_id IS NULL THEN
    PERFORM core.ensure_entity_for_auth_user(v_auth_user_id);
    SELECT e.id INTO v_entity_id
    FROM core.entities e
    WHERE e.owner_id = v_profile_id
      AND e.entity_type = 'individual_pro'
      AND e.is_active = true
    ORDER BY e.created_at, e.id
    LIMIT 1;
  ELSE
    v_entity_id := p_entity_id;
  END IF;

  IF v_entity_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM core.entities e
    WHERE e.id = v_entity_id AND e.is_active = true
  ) THEN
    RAISE EXCEPTION 'entity is invalid or inactive' USING ERRCODE = '42501';
  END IF;

  IF p_business_profile_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM commerce.business_profiles bp
    WHERE bp.id = p_business_profile_id
      AND bp.entity_id = v_entity_id
      AND bp.deleted_at IS NULL
      AND bp.is_active = true
  ) THEN
    RAISE EXCEPTION 'business profile is invalid, inactive, deleted, or belongs to another entity' USING ERRCODE = '42501';
  END IF;

  SELECT count(DISTINCT em.role_id)::integer, min(em.role_id)
    INTO v_role_count, v_role_id
  FROM core.entity_members em
  JOIN core.entity_roles er ON er.entity_id = em.entity_id
    AND er.profile_id = em.profile_id AND er.role_id = em.role_id AND er.is_active = true
  JOIN core.user_roles r ON r.id = em.role_id AND r.is_active = true
  WHERE em.entity_id = v_entity_id
    AND em.profile_id = v_profile_id
    AND em.is_active = true
    AND em.membership_status = 'active'
    AND (p_role_id IS NULL OR em.role_id = p_role_id);

  IF p_role_id IS NOT NULL THEN
    IF v_role_count <> 1 THEN
      RAISE EXCEPTION 'supplied role is not valid for this profile and entity' USING ERRCODE = '42501';
    END IF;
    v_role_id := p_role_id;
  ELSIF v_role_count <> 1 THEN
    RAISE EXCEPTION 'profile has no single valid active role for this entity' USING ERRCODE = '42501';
  END IF;

  INSERT INTO users.user_workspace_entity_contexts (
    user_workspace_id, entity_id, business_profile_id, mode, is_active
  ) VALUES (
    v_user_workspace_id, v_entity_id, p_business_profile_id, v_mode, true
  ) ON CONFLICT DO NOTHING;

  UPDATE users.user_workspace_entity_contexts c
  SET is_active = true, mode = v_mode, updated_at = now()
  WHERE c.user_workspace_id = v_user_workspace_id
    AND c.entity_id = v_entity_id
    AND c.business_profile_id IS NOT DISTINCT FROM p_business_profile_id
    AND c.mode IS NOT DISTINCT FROM v_mode;

  PERFORM users.activate_workspace_context(
    p_workspace_id, v_entity_id, v_role_id, p_business_profile_id
  );

  workspace_id := p_workspace_id;
  profile_id := v_profile_id;
  entity_id := v_entity_id;
  role_id := v_role_id;
  active_mode := v_mode;
  business_profile_id := p_business_profile_id;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "users"."complete_workspace_selection"("p_workspace_id" "uuid", "p_entity_id" "uuid", "p_role_id" "uuid", "p_business_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."compute_profiles_location_path"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  path_parts TEXT[];
BEGIN
  -- Build location_path as direct concatenation of UUID segments.
  -- This matches the existing check constraint: profiles_location_path_check.
  path_parts := ARRAY_REMOVE(ARRAY[
    NEW.country_id::text,
    NEW.level_2_location_id::text,
    NEW.level_3_location_id::text,
    NEW.level_4_location_id::text,
    NEW.level_5_location_id::text,
    NEW.level_6_location_id::text,
    NEW.level_7_location_id::text
  ], NULL);

  IF path_parts IS NULL OR array_length(path_parts, 1) IS NULL THEN
    NEW.location_path := NULL;
  ELSE
    -- No separator
    NEW.location_path := array_to_string(path_parts, '');
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "users"."compute_profiles_location_path"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."create_item_variant"("p_item_id" "uuid", "p_name" "text") RETURNS TABLE("id" "uuid", "item_id" "uuid", "item_name" "text", "name" "text", "is_active" boolean, "source" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
DECLARE
  v_profile_id uuid;
  v_item_name text;
  v_clean_name text;
  v_normalized_name text;
  v_created core.item_variants%ROWTYPE;
  v_existing_id uuid;
  v_existing_name text;
  v_existing_is_active boolean;
  v_existing_source text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Authentication is required.';
  END IF;

  v_profile_id := core.current_profile_id();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'No profile is associated with the authenticated user.';
  END IF;

  SELECT i.name INTO v_item_name
  FROM core.items AS i
  WHERE i.id = p_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'The requested item does not exist.';
  END IF;

  IF p_name IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Variant name is required.';
  END IF;

  v_clean_name := regexp_replace(p_name, '^[[:space:]]+|[[:space:]]+$', '', 'g');
  IF v_clean_name = '' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Variant name cannot be empty.';
  END IF;
  IF char_length(v_clean_name) > 120 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Variant name cannot exceed 120 characters.';
  END IF;

  v_normalized_name := core.normalize_item_variant_name(v_clean_name);
  IF v_normalized_name = '' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Variant name must contain a letter, number, or other non-separator character.';
  END IF;

  SELECT iv.id, iv.name, iv.is_active, iv.source
    INTO v_existing_id, v_existing_name, v_existing_is_active, v_existing_source
  FROM core.item_variants AS iv
  WHERE iv.item_id = p_item_id
    AND iv.normalized_name = v_normalized_name;
  IF FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '23505',
      MESSAGE = 'A variant with the same normalized name already exists for this item.',
      DETAIL = jsonb_build_object('existing_variant_id', v_existing_id, 'name', v_existing_name, 'is_active', v_existing_is_active, 'source', v_existing_source)::text;
  END IF;

  BEGIN
    INSERT INTO core.item_variants (item_id, name, is_active, created_by_profile_id, source)
    VALUES (p_item_id, v_clean_name, true, v_profile_id, 'user')
    RETURNING * INTO v_created;
  EXCEPTION WHEN unique_violation THEN
    SELECT iv.id, iv.name, iv.is_active, iv.source
      INTO v_existing_id, v_existing_name, v_existing_is_active, v_existing_source
    FROM core.item_variants AS iv
    WHERE iv.item_id = p_item_id
      AND iv.normalized_name = v_normalized_name;
    IF FOUND THEN
      RAISE EXCEPTION USING
        ERRCODE = '23505',
        MESSAGE = 'A variant with the same normalized name already exists for this item.',
        DETAIL = jsonb_build_object('existing_variant_id', v_existing_id, 'name', v_existing_name, 'is_active', v_existing_is_active, 'source', v_existing_source)::text;
    END IF;
    RAISE;
  END;

  RETURN QUERY
  SELECT v_created.id, v_created.item_id, v_item_name, v_created.name,
         v_created.is_active, v_created.source, v_created.updated_at;
END;
$_$;


ALTER FUNCTION "users"."create_item_variant"("p_item_id" "uuid", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."get_available_workspace_contexts"() RETURNS TABLE("workspace_id" "uuid", "workspace_key" "text", "workspace_name" "text", "workspace_description" "text", "user_workspace_id" "uuid", "entity_id" "uuid", "entity_name" "text", "entity_type" "text", "role_id" "uuid", "role_name" "text", "role_type" "text", "active_mode" "text", "business_profile_id" "uuid", "business_entity_type" "text", "business_verification_status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'users', 'core', 'commerce', 'system'
    AS $$
  SELECT
    w.id,
    w.key,
    w.name,
    w.description,
    uw.id,
    c.entity_id,
    e.name,
    e.entity_type,
    em.role_id,
    r.name,
    r.type,
    c.mode,
    c.business_profile_id,
    bp.entity_type,
    bp.verification_status
  FROM users.user_workspace_entity_contexts c
  JOIN users.user_workspaces uw
    ON uw.id = c.user_workspace_id
   AND uw.auth_user_id = auth.uid()
  JOIN system.workspaces w
    ON w.id = uw.workspace_id
   AND w.is_active = true
  JOIN core.entities e
    ON e.id = c.entity_id
   AND e.is_active = true
  JOIN core.entity_members em
    ON em.entity_id = c.entity_id
   AND em.profile_id = (
     SELECT p.id FROM users.profiles p
     WHERE p.auth_user_id = auth.uid()
       AND p.is_active = true
       AND p.account_status = 'active'
  )
   AND em.is_active = true
   AND em.membership_status = 'active'
  JOIN core.entity_roles er
    ON er.entity_id = em.entity_id
   AND er.profile_id = em.profile_id
   AND er.role_id = em.role_id
   AND er.is_active = true
  JOIN core.user_roles r
    ON r.id = em.role_id
   AND r.is_active = true
  LEFT JOIN commerce.business_profiles bp
    ON bp.id = c.business_profile_id
   AND bp.entity_id = c.entity_id
   AND bp.deleted_at IS NULL
   AND bp.is_active = true
  WHERE c.is_active = true
    AND (c.business_profile_id IS NULL OR bp.id IS NOT NULL)
  ORDER BY w.sort_order, w.id, e.name, r.name, r.id;
$$;


ALTER FUNCTION "users"."get_available_workspace_contexts"() OWNER TO "postgres";


