CREATE OR REPLACE FUNCTION "users"."save_user_workspaces"("p_auth_user_id" "uuid", "p_workspace_ids" "uuid"[]) RETURNS TABLE("auth_user_id" "uuid", "workspace_id" "uuid", "is_default" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'users'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service role required' USING ERRCODE = '42501';
  END IF;

  IF p_auth_user_id IS NULL THEN
    RAISE EXCEPTION 'p_auth_user_id cannot be null';
  END IF;

  IF p_workspace_ids IS NULL OR array_length(p_workspace_ids, 1) IS NULL THEN
    DELETE FROM users.user_workspaces AS uw
    WHERE uw.auth_user_id = p_auth_user_id;
    RETURN;
  END IF;

  DELETE FROM users.user_workspaces AS uw
  WHERE uw.auth_user_id = p_auth_user_id;

  INSERT INTO users.user_workspaces (auth_user_id, workspace_id, is_default)
  SELECT p_auth_user_id, wid, (ord = 1)
  FROM unnest(p_workspace_ids) WITH ORDINALITY AS t(wid, ord)
  ORDER BY ord;

  RETURN QUERY
  SELECT uw.auth_user_id, uw.workspace_id, uw.is_default
  FROM users.user_workspaces AS uw
  WHERE uw.auth_user_id = p_auth_user_id;
END;
$$;


ALTER FUNCTION "users"."save_user_workspaces"("p_auth_user_id" "uuid", "p_workspace_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."search_item_variants"("p_item_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_include_inactive" boolean DEFAULT false, "p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "item_id" "uuid", "name" "text", "is_active" boolean, "source" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  v_profile_id uuid;
  v_item_exists boolean;
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 50));
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Authentication is required.';
  END IF;

  v_profile_id := core.current_profile_id();
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'No profile is associated with the authenticated user.';
  END IF;

  SELECT EXISTS (SELECT 1 FROM core.items AS i WHERE i.id = p_item_id)
    INTO v_item_exists;
  IF NOT v_item_exists THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'The requested item does not exist.';
  END IF;

  RETURN QUERY
  WITH search_input AS (
    SELECT CASE
      WHEN p_search IS NULL OR btrim(p_search) = '' THEN NULL::text
      ELSE core.normalize_item_variant_name(p_search)
    END AS normalized_search
  )
  SELECT iv.id, iv.item_id, iv.name, iv.is_active, iv.source, iv.updated_at
  FROM core.item_variants AS iv
  CROSS JOIN search_input AS s
  WHERE iv.item_id = p_item_id
    AND (coalesce(p_include_inactive, false) OR iv.is_active)
    AND (
      s.normalized_search IS NULL
      OR (
        s.normalized_search <> ''
        AND (
          iv.normalized_name = s.normalized_search
          OR left(iv.normalized_name, char_length(s.normalized_search)) = s.normalized_search
          OR strpos(iv.normalized_name, s.normalized_search) > 0
          OR public.similarity(iv.normalized_name, s.normalized_search) >= 0.20
        )
      )
    )
  ORDER BY
    CASE
      WHEN s.normalized_search IS NULL THEN 0
      WHEN iv.normalized_name = s.normalized_search THEN 0
      WHEN left(iv.normalized_name, char_length(s.normalized_search)) = s.normalized_search THEN 1
      WHEN strpos(iv.normalized_name, s.normalized_search) > 0 THEN 2
      ELSE 3
    END,
    CASE WHEN s.normalized_search IS NULL THEN NULL::real
         ELSE public.similarity(iv.normalized_name, s.normalized_search)
    END DESC NULLS LAST,
    iv.name
  LIMIT v_limit;
END;
$$;


ALTER FUNCTION "users"."search_item_variants"("p_item_id" "uuid", "p_search" "text", "p_include_inactive" boolean, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "users"."set_profile_id_from_auth"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- profiles.id is independently generated by its column default.
  -- Maintain only the Auth User ID relationship when the caller omits it.
  IF NEW.auth_user_id IS NULL THEN
    NEW.auth_user_id := core.auth_user_id();
  END IF;
  RETURN NEW;
END;
$$;


