CREATE OR REPLACE VIEW "core"."active_entity_roles" AS
 SELECT "er"."id",
    "er"."profile_id",
    "er"."entity_id" AS "business_profile_id",
    "ur"."name" AS "role_name",
    "ur"."type" AS "role_type",
    "er"."assigned_at",
    "er"."is_active"
   FROM ("core"."entity_roles" "er"
     JOIN "core"."user_roles" "ur" ON (("er"."role_id" = "ur"."id")))
