CREATE OR REPLACE VIEW "core"."v_inventory_registry" AS
 SELECT "d"."name" AS "domain_name",
    "c"."name" AS "category_name",
    "i"."name" AS "item_name",
    "iv"."id" AS "variant_id",
    "iv"."name" AS "variant_name",
    "jsonb_object_agg"("ar"."name", COALESCE("va"."value_text", ("va"."value_number")::"text", ("va"."value_boolean")::"text")) AS "dna"
   FROM ((((("core"."item_variants" "iv"
     JOIN "core"."items" "i" ON (("iv"."item_id" = "i"."id")))
     JOIN "core"."categories" "c" ON (("i"."category_id" = "c"."id")))
     JOIN "core"."domains" "d" ON (("c"."domain_id" = "d"."id")))
     LEFT JOIN "core"."variant_attributes" "va" ON (("va"."variant_id" = "iv"."id")))
     LEFT JOIN "core"."attribute_registry" "ar" ON (("va"."attribute_id" = "ar"."id")))
  GROUP BY "d"."name", "c"."name", "i"."name", "iv"."id", "iv"."name";


ALTER VIEW "core"."v_inventory_registry" OWNER TO "postgres";


