CREATE OR REPLACE VIEW "farm_management"."farmer_daily_journal" AS
 SELECT "a"."id" AS "event_id",
    "a"."entity_id",
    "a"."performed_at",
    "at"."name" AS "event_type",
    "a"."notes" AS "description",
    'activity'::"text" AS "source"
   FROM ("farm_management"."activities" "a"
     JOIN "farm_management"."activity_types" "at" ON (("at"."id" = "a"."activity_type_id")))
UNION ALL
 SELECT "pr"."id" AS "event_id",
    "pr"."entity_id",
    "pr"."created_at" AS "performed_at",
    'production'::"text" AS "event_type",
    ("pr"."data")::"text" AS "description",
    'production'::"text" AS "source"
   FROM "farm_management"."production_records" "pr";


