    CONSTRAINT "location_points_altitude_finite_check" CHECK ((("altitude" IS NULL) OR (("altitude" <> 'NaN'::double precision) AND ("altitude" <> 'Infinity'::double precision) AND ("altitude" <> '-Infinity'::double precision)))),
    CONSTRAINT "location_points_heading_check" CHECK ((("heading" IS NULL) OR (("heading" >= (0)::double precision) AND ("heading" < (360)::double precision)))),
    CONSTRAINT "location_points_latitude_check" CHECK ((("latitude" >= ('-90'::integer)::double precision) AND ("latitude" <= (90)::double precision))),
    CONSTRAINT "location_points_longitude_check" CHECK ((("longitude" >= ('-180'::integer)::double precision) AND ("longitude" <= (180)::double precision))),
    CONSTRAINT "location_points_speed_check" CHECK ((("speed" IS NULL) OR ("speed" >= (0)::double precision))),
    CONSTRAINT "location_points_speed_finite_check" CHECK ((("speed" IS NULL) OR (("speed" >= (0)::double precision) AND ("speed" <> 'NaN'::double precision) AND ("speed" <> 'Infinity'::double precision) AND ("speed" <> '-Infinity'::double precision))))
);


