CREATE OR REPLACE VIEW "marketplace"."daily_market_price_geography" AS
 WITH RECURSIVE "rollup" AS (
         SELECT "d"."recorded_on",
            "d"."market_id",
            "m"."name" AS "market_name",
            "m"."location_id" AS "geography_location_id",
            "gl"."level_name" AS "geography_level",
            "d"."item_id",
            "d"."variant_id",
            "d"."unit_id",
            "d"."price_type",
            "d"."currency",
            "d"."quality_grade",
            "d"."average_price",
            "d"."min_price",
            "d"."max_price",
            "d"."observation_count",
            "l"."parent_id"
           FROM ((("marketplace"."daily_market_prices" "d"
             JOIN "marketplace"."markets" "m" ON (("m"."id" = "d"."market_id")))
             JOIN "core"."locations" "l" ON (("l"."id" = "m"."location_id")))
             JOIN "core"."geography_levels" "gl" ON (("gl"."id" = "l"."level_id")))
          WHERE ("d"."item_id" IS NOT NULL)
        UNION ALL
         SELECT "r"."recorded_on",
            "r"."market_id",
            "r"."market_name",
            "parent"."id",
            "parent_gl"."level_name",
            "r"."item_id",
            "r"."variant_id",
            "r"."unit_id",
            "r"."price_type",
            "r"."currency",
            "r"."quality_grade",
            "r"."average_price",
            "r"."min_price",
            "r"."max_price",
            "r"."observation_count",
            "parent"."parent_id"
           FROM (("rollup" "r"
             JOIN "core"."locations" "parent" ON (("parent"."id" = "r"."parent_id")))
             JOIN "core"."geography_levels" "parent_gl" ON (("parent_gl"."id" = "parent"."level_id")))
        ), "admin_groups" AS (
         SELECT "rollup"."recorded_on",
            NULL::"uuid" AS "market_id",
            NULL::"text" AS "market_name",
            "rollup"."geography_location_id",
            "rollup"."geography_level",
            "rollup"."item_id",
            "rollup"."variant_id",
            "rollup"."unit_id",
            "rollup"."price_type",
            "rollup"."currency",
            "rollup"."quality_grade",
            ("sum"(("rollup"."average_price" * ("rollup"."observation_count")::numeric)) / (NULLIF("sum"("rollup"."observation_count"), 0))::numeric) AS "average_price",
            "min"("rollup"."min_price") AS "minimum_price",
            "max"("rollup"."max_price") AS "maximum_price",
            ("sum"("rollup"."observation_count"))::integer AS "observation_count",
            ("count"(DISTINCT "rollup"."market_id"))::integer AS "market_count"
           FROM "rollup"
          GROUP BY "rollup"."recorded_on", "rollup"."geography_location_id", "rollup"."geography_level", "rollup"."item_id", "rollup"."variant_id", "rollup"."unit_id", "rollup"."price_type", "rollup"."currency", "rollup"."quality_grade"
        ), "market_groups" AS (
         SELECT "d"."recorded_on",
            "d"."market_id",
            "m"."name" AS "market_name",
            "m"."location_id" AS "geography_location_id",
            'Market'::"text" AS "geography_level",
            "d"."item_id",
            "d"."variant_id",
            "d"."unit_id",
            "d"."price_type",
            "d"."currency",
            "d"."quality_grade",
            "d"."average_price",
            "d"."min_price" AS "minimum_price",
            "d"."max_price" AS "maximum_price",
            "d"."observation_count",
            1 AS "market_count"
           FROM ("marketplace"."daily_market_prices" "d"
             JOIN "marketplace"."markets" "m" ON (("m"."id" = "d"."market_id")))
          WHERE ("d"."item_id" IS NOT NULL)
        )
 SELECT "market_groups"."recorded_on",
    "market_groups"."market_id",
    "market_groups"."market_name",
    "market_groups"."geography_location_id",
    "market_groups"."geography_level",
    "market_groups"."item_id",
    "market_groups"."variant_id",
    "market_groups"."unit_id",
    "market_groups"."price_type",
    "market_groups"."currency",
    "market_groups"."quality_grade",
    "market_groups"."average_price",
    "market_groups"."minimum_price",
    "market_groups"."maximum_price",
    "market_groups"."observation_count",
    "market_groups"."market_count"
   FROM "market_groups"
UNION ALL
 SELECT "admin_groups"."recorded_on",
    "admin_groups"."market_id",
    "admin_groups"."market_name",
    "admin_groups"."geography_location_id",
    "admin_groups"."geography_level",
    "admin_groups"."item_id",
    "admin_groups"."variant_id",
    "admin_groups"."unit_id",
    "admin_groups"."price_type",
    "admin_groups"."currency",
    "admin_groups"."quality_grade",
    "admin_groups"."average_price",
    "admin_groups"."minimum_price",
    "admin_groups"."maximum_price",
    "admin_groups"."observation_count",
    "admin_groups"."market_count"
   FROM "admin_groups";


ALTER VIEW "marketplace"."daily_market_price_geography" OWNER TO "postgres";


CREATE OR REPLACE VIEW "marketplace"."listings_feed" AS
 SELECT "l"."id",
    "l"."title",
    "l"."description",
    "l"."price_per_unit",
    "l"."currency",
    "l"."status",
    "l"."created_at",
    "l"."images",
    "v"."name" AS "variant_name",
    "i"."name" AS "item_name",
    "loc"."name" AS "location_name",
    "bp"."supplier_name"
   FROM (((("marketplace"."listings" "l"
     JOIN "core"."item_variants" "v" ON (("v"."id" = "l"."variant_id")))
     JOIN "core"."items" "i" ON (("i"."id" = "v"."item_id")))
     JOIN "core"."locations" "loc" ON (("loc"."id" = "l"."location_id")))
     JOIN "commerce"."business_profiles" "bp" ON (("bp"."entity_id" = "l"."entity_id")))
  WHERE ("l"."status" = 'active'::"text");


ALTER VIEW "marketplace"."listings_feed" OWNER TO "postgres";


CREATE OR REPLACE VIEW "marketplace"."listings_secure" AS
 SELECT "l"."id",
    "l"."entity_id",
    "l"."title",
    "l"."description",
    "l"."unit_id",
    "l"."price_per_unit",
    "l"."currency",
    "l"."location_id",
    "l"."status",
    "l"."contact_visibility",
    "l"."is_promoted",
    "l"."promoted_until",
    "l"."images",
    "l"."created_at",
    "l"."updated_at",
    "l"."stock_id",
    "l"."variant_id",
        CASE
            WHEN ("cu"."unlocked" = true) THEN "bp"."phone"
            ELSE NULL::"text"
        END AS "contact_phone",
        CASE
            WHEN ("cu"."unlocked" = true) THEN "bp"."supplier_name"
            ELSE 'Hidden'::"text"
        END AS "supplier_name"
   FROM (("marketplace"."listings" "l"
     LEFT JOIN "commerce"."business_profiles" "bp" ON (("bp"."entity_id" = "l"."entity_id")))
     LEFT JOIN "marketplace"."contact_unlocks" "cu" ON ((("cu"."listing_id" = "l"."id") AND ("cu"."entity_id" = "core"."current_entity_id"()))));


ALTER VIEW "marketplace"."listings_secure" OWNER TO "postgres";


CREATE OR REPLACE VIEW "marketplace"."listings_view" AS
 SELECT "l"."id",
    "l"."entity_id",
    "l"."title",
    "l"."description",
    "l"."price_per_unit",
    "l"."currency",
    "l"."location_id",
    "l"."status",
    "l"."contact_visibility",
    "l"."is_promoted",
    "l"."promoted_until",
    "l"."images",
    "l"."created_at",
    "l"."updated_at",
    "l"."stock_id",
    "l"."variant_id",
    "sr"."quantity" AS "total_stock",
    "sr"."reserved_quantity",
    ("sr"."quantity" - "sr"."reserved_quantity") AS "available_stock",
    "sr"."unit_id"
   FROM ("marketplace"."listings" "l"
     JOIN "commerce"."stock_registry" "sr" ON (("sr"."id" = "l"."stock_id")));


ALTER VIEW "marketplace"."listings_view" OWNER TO "postgres";


CREATE OR REPLACE VIEW "marketplace"."market_directory" WITH ("security_invoker"='true') AS
 SELECT "m"."id",
    "m"."name",
    "m"."market_type",
    "m"."is_active",
    "m"."location_id",
    "w"."name" AS "ward_name",
    "s"."id" AS "sub_county_id",
    "s"."name" AS "sub_county_name",
    "c"."id" AS "county_id",
    "c"."name" AS "county_name",
    "m"."created_at",
    "m"."updated_at"
   FROM (((("marketplace"."markets" "m"
     JOIN "core"."locations" "w" ON (("w"."id" = "m"."location_id")))
     JOIN "core"."geography_levels" "wgl" ON ((("wgl"."id" = "w"."level_id") AND ("lower"(TRIM(BOTH FROM "wgl"."level_name")) = 'ward'::"text"))))
     LEFT JOIN "core"."locations" "s" ON (("s"."id" = "w"."parent_id")))
     LEFT JOIN "core"."locations" "c" ON (("c"."id" = "s"."parent_id")));


ALTER VIEW "marketplace"."market_directory" OWNER TO "postgres";


