    CONSTRAINT "market_prices_source_type_check" CHECK (("source_type" = ANY (ARRAY['famhub_representative'::"text", 'government_public_dataset'::"text", 'cooperative'::"text", 'farmer_report'::"text", 'trader_report'::"text", 'market_authority'::"text", 'external_data_provider'::"text", 'other'::"text"]))),
