CREATE TABLE IF NOT EXISTS "spatial"."spatial_assets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "entity_id" "uuid" NOT NULL,
    "asset_type" "text" NOT NULL,
    "name" "text",
    "area_ha" numeric DEFAULT 0,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "parent_asset_id" "uuid",
    CONSTRAINT "spatial_assets_asset_type_check" CHECK (("asset_type" = ANY (ARRAY['farm'::"text", 'field'::"text", 'block'::"text", 'carbon_zone'::"text", 'forest'::"text", 'woodlot'::"text", 'water_body'::"text", 'wetland'::"text", 'pasture'::"text", 'orchard'::"text", 'greenhouse'::"text", 'other'::"text"])))
);


ALTER TABLE "spatial"."spatial_assets" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "spatial"."spatial_boundaries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "asset_id" "uuid" NOT NULL,
    "geometry" "public"."geometry"(Polygon,4326) NOT NULL,
    "accuracy_level" "text" DEFAULT 'gps'::"text",
    "created_at" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "spatial"."spatial_boundaries" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "spatial"."spatial_capture_points" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "session_id" "uuid" NOT NULL,
    "latitude" double precision NOT NULL,
    "longitude" double precision NOT NULL,
    "accuracy_meters" double precision,
    "sequence_no" integer NOT NULL,
    "recorded_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "spatial_capture_points_latitude_check" CHECK ((("latitude" >= ('-90'::integer)::double precision) AND ("latitude" <= (90)::double precision))),
    CONSTRAINT "spatial_capture_points_longitude_check" CHECK ((("longitude" >= ('-180'::integer)::double precision) AND ("longitude" <= (180)::double precision)))
);


ALTER TABLE "spatial"."spatial_capture_points" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "spatial"."spatial_capture_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "asset_id" "uuid",
    "status" "text" DEFAULT 'active'::"text",
    "started_at" timestamp with time zone DEFAULT "now"(),
    "completed_at" timestamp with time zone,
    "mode" "text" DEFAULT 'manual'::"text"
);


ALTER TABLE "spatial"."spatial_capture_sessions" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "spatial"."spatial_overlaps" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "asset_a" "uuid" NOT NULL,
    "asset_b" "uuid" NOT NULL,
    "overlap_type" "text" DEFAULT 'boundary'::"text",
    "overlap_area_sq_m" numeric,
    "overlap_percentage" numeric,
    "created_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "spatial_no_self_overlap" CHECK (("asset_a" <> "asset_b"))
);


ALTER TABLE "spatial"."spatial_overlaps" OWNER TO "postgres";


