CREATE TABLE IF NOT EXISTS "weather"."weather_cache" (
    "cache_key" "text" NOT NULL,
    "location_id" "uuid",
    "latitude" numeric(5,2),
    "longitude" numeric(6,2),
    "response" "jsonb" NOT NULL,
    "provider" "text" NOT NULL,
    "fetched_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    CONSTRAINT "weather_cache_coordinates_pair_check" CHECK ((("latitude" IS NULL) = ("longitude" IS NULL))),
    CONSTRAINT "weather_cache_expiry_after_fetch_check" CHECK (("expires_at" > "fetched_at")),
    CONSTRAINT "weather_cache_key_nonempty_check" CHECK (("btrim"("cache_key") <> ''::"text")),
    CONSTRAINT "weather_cache_latitude_range_check" CHECK ((("latitude" IS NULL) OR (("latitude" >= ('-90'::integer)::numeric) AND ("latitude" <= (90)::numeric)))),
    CONSTRAINT "weather_cache_location_present_check" CHECK ((("location_id" IS NOT NULL) OR (("latitude" IS NOT NULL) AND ("longitude" IS NOT NULL)))),
    CONSTRAINT "weather_cache_longitude_range_check" CHECK ((("longitude" IS NULL) OR (("longitude" >= ('-180'::integer)::numeric) AND ("longitude" <= (180)::numeric)))),
    CONSTRAINT "weather_cache_provider_nonempty_check" CHECK (("btrim"("provider") <> ''::"text"))
);


ALTER TABLE "weather"."weather_cache" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "weather"."weather_observations" (
    "id" "uuid" DEFAULT "public"."uuid_generate_v7"() NOT NULL,
    "location_id" "uuid",
    "observed_at" timestamp with time zone NOT NULL,
    "temperature" numeric,
    "rainfall" numeric,
    "wind_speed" numeric,
    "payload" "jsonb",
    "record_kind" "text" DEFAULT 'observation'::"text" NOT NULL,
    "feels_like_temperature" numeric,
    "precipitation_probability" numeric,
    "humidity" numeric,
    "wind_direction" numeric,
    "provider" "text" NOT NULL,
    "provider_external_id" "text",
    "fetched_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "latitude" numeric(9,6),
    "longitude" numeric(9,6),
    CONSTRAINT "weather_observations_coordinates_pair_check" CHECK ((("latitude" IS NULL) = ("longitude" IS NULL))),
    CONSTRAINT "weather_observations_humidity_range_check" CHECK ((("humidity" IS NULL) OR (("humidity" >= (0)::numeric) AND ("humidity" <= (100)::numeric)))),
    CONSTRAINT "weather_observations_latitude_range_check" CHECK ((("latitude" IS NULL) OR (("latitude" >= ('-90'::integer)::numeric) AND ("latitude" <= (90)::numeric)))),
    CONSTRAINT "weather_observations_location_present_check" CHECK ((("location_id" IS NOT NULL) OR (("latitude" IS NOT NULL) AND ("longitude" IS NOT NULL)))),
    CONSTRAINT "weather_observations_longitude_range_check" CHECK ((("longitude" IS NULL) OR (("longitude" >= ('-180'::integer)::numeric) AND ("longitude" <= (180)::numeric)))),
    CONSTRAINT "weather_observations_precipitation_probability_range_check" CHECK ((("precipitation_probability" IS NULL) OR (("precipitation_probability" >= (0)::numeric) AND ("precipitation_probability" <= (100)::numeric)))),
    CONSTRAINT "weather_observations_provider_nonempty_check" CHECK (("btrim"("provider") <> ''::"text")),
    CONSTRAINT "weather_observations_rainfall_nonnegative_check" CHECK ((("rainfall" IS NULL) OR ("rainfall" >= (0)::numeric))),
    CONSTRAINT "weather_observations_record_kind_check" CHECK (("record_kind" = ANY (ARRAY['observation'::"text", 'current'::"text", 'hourly_forecast'::"text", 'daily_forecast'::"text"]))),
    CONSTRAINT "weather_observations_wind_direction_range_check" CHECK ((("wind_direction" IS NULL) OR (("wind_direction" >= (0)::numeric) AND ("wind_direction" <= (360)::numeric)))),
    CONSTRAINT "weather_observations_wind_speed_nonnegative_check" CHECK ((("wind_speed" IS NULL) OR ("wind_speed" >= (0)::numeric)))
);


ALTER TABLE "weather"."weather_observations" OWNER TO "postgres";


COMMENT ON COLUMN "weather"."weather_observations"."observed_at" IS 'Weather record valid/application time; for forecasts, the time the forecast applies to.';



COMMENT ON COLUMN "weather"."weather_observations"."temperature" IS 'Air temperature in degrees Celsius.';



COMMENT ON COLUMN "weather"."weather_observations"."rainfall" IS 'Precipitation amount in millimeters.';



COMMENT ON COLUMN "weather"."weather_observations"."wind_speed" IS 'Wind speed in meters per second.';



COMMENT ON COLUMN "weather"."weather_observations"."feels_like_temperature" IS 'Feels-like temperature in degrees Celsius.';



COMMENT ON COLUMN "weather"."weather_observations"."precipitation_probability" IS 'Precipitation probability in percent (0 through 100).';



COMMENT ON COLUMN "weather"."weather_observations"."humidity" IS 'Relative humidity in percent (0 through 100).';



COMMENT ON COLUMN "weather"."weather_observations"."wind_direction" IS 'Wind direction in degrees (0 through 360).';



COMMENT ON COLUMN "weather"."weather_observations"."latitude" IS 'WGS84 latitude in decimal degrees for the resolved weather point.';



COMMENT ON COLUMN "weather"."weather_observations"."longitude" IS 'WGS84 longitude in decimal degrees for the resolved weather point.';



