ALTER TABLE "agri_connect"."announcements" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "announcements_delete_community_managers" ON "agri_connect"."announcements" FOR DELETE TO "authenticated" USING ((("announcement_type" = 'community'::"text") AND ("community_id" IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM "agri_connect"."communities" "c"
  WHERE (("c"."id" = "announcements"."community_id") AND ("c"."is_active" IS TRUE) AND (NOT ("c"."entity_id" IS DISTINCT FROM "announcements"."entity_id"))))) AND "agri_connect"."is_active_community_member"("community_id", ARRAY['moderator'::"text", 'admin'::"text", 'owner'::"text"])));



CREATE POLICY "announcements_insert_community_managers" ON "agri_connect"."announcements" FOR INSERT TO "authenticated" WITH CHECK ((("announcement_type" = 'community'::"text") AND ("community_id" IS NOT NULL) AND ("published_by" = "agri_connect"."current_profile_id"()) AND (EXISTS ( SELECT 1
   FROM "agri_connect"."communities" "c"
  WHERE (("c"."id" = "announcements"."community_id") AND ("c"."is_active" IS TRUE) AND (NOT ("c"."entity_id" IS DISTINCT FROM "announcements"."entity_id"))))) AND "agri_connect"."is_active_community_member"("community_id", ARRAY['moderator'::"text", 'admin'::"text", 'owner'::"text"])));



CREATE POLICY "announcements_select_public_guest" ON "agri_connect"."announcements" FOR SELECT TO "anon" USING ((("is_published" IS TRUE) AND (("expires_at" IS NULL) OR ("expires_at" > "statement_timestamp"())) AND ((("announcement_type" = 'community'::"text") AND ("community_id" IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM "agri_connect"."communities" "c"
  WHERE (("c"."id" = "announcements"."community_id") AND ("c"."is_active" IS TRUE) AND (NOT ("c"."entity_id" IS DISTINCT FROM "announcements"."entity_id")) AND ("c"."visibility" = 'public'::"text"))))) OR (("announcement_type" = 'famhub'::"text") AND ("community_id" IS NULL) AND ("entity_id" IS NULL)))));



CREATE POLICY "announcements_select_published_scoped" ON "agri_connect"."announcements" FOR SELECT TO "authenticated" USING ((("is_published" IS TRUE) AND (("expires_at" IS NULL) OR ("expires_at" > "statement_timestamp"())) AND ((("announcement_type" = 'community'::"text") AND ("community_id" IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM "agri_connect"."communities" "c"
  WHERE (("c"."id" = "announcements"."community_id") AND ("c"."is_active" IS TRUE) AND (NOT ("c"."entity_id" IS DISTINCT FROM "announcements"."entity_id")) AND (("c"."visibility" = 'public'::"text") OR "agri_connect"."is_active_community_member"("announcements"."community_id", ARRAY['member'::"text", 'moderator'::"text", 'admin'::"text", 'owner'::"text"])))))) OR (("announcement_type" = 'organization'::"text") AND ("community_id" IS NULL) AND ("entity_id" IS NOT NULL) AND ("core"."current_entity_id"() = "entity_id")) OR (("announcement_type" = 'famhub'::"text") AND ("community_id" IS NULL) AND ("entity_id" IS NULL)))));



CREATE POLICY "announcements_update_community_managers" ON "agri_connect"."announcements" FOR UPDATE TO "authenticated" USING ((("announcement_type" = 'community'::"text") AND ("community_id" IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM "agri_connect"."communities" "c"
  WHERE (("c"."id" = "announcements"."community_id") AND ("c"."is_active" IS TRUE) AND (NOT ("c"."entity_id" IS DISTINCT FROM "announcements"."entity_id"))))) AND "agri_connect"."is_active_community_member"("community_id", ARRAY['moderator'::"text", 'admin'::"text", 'owner'::"text"]))) WITH CHECK ((("announcement_type" = 'community'::"text") AND ("community_id" IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM "agri_connect"."communities" "c"
  WHERE (("c"."id" = "announcements"."community_id") AND ("c"."is_active" IS TRUE) AND (NOT ("c"."entity_id" IS DISTINCT FROM "announcements"."entity_id"))))) AND "agri_connect"."is_active_community_member"("community_id", ARRAY['moderator'::"text", 'admin'::"text", 'owner'::"text"])));



ALTER TABLE "agri_connect"."communities" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "communities_insert_creator" ON "agri_connect"."communities" FOR INSERT TO "authenticated" WITH CHECK ((("created_by" = "agri_connect"."current_profile_id"()) AND ("is_active" IS TRUE)));



CREATE POLICY "communities_select_public" ON "agri_connect"."communities" FOR SELECT TO "authenticated", "anon" USING ((("is_active" = true) AND (("visibility" = 'public'::"text") OR (("visibility" = ANY (ARRAY['private'::"text", 'restricted'::"text"])) AND "agri_connect"."is_active_community_member"("id", ARRAY['member'::"text", 'moderator'::"text", 'admin'::"text", 'owner'::"text"])))));



CREATE POLICY "communities_update_admin_owner" ON "agri_connect"."communities" FOR UPDATE TO "authenticated" USING ("agri_connect"."is_active_community_member"("id", ARRAY['admin'::"text", 'owner'::"text"])) WITH CHECK ("agri_connect"."is_active_community_member"("id", ARRAY['admin'::"text", 'owner'::"text"]));



