CREATE POLICY "community_members_delete_admin" ON "agri_connect"."community_members" FOR DELETE TO "authenticated" USING ((("profile_id" <> ( SELECT "agri_connect"."current_profile_id"() AS "current_profile_id")) AND "agri_connect"."is_active_community_member"("community_id", ARRAY['admin'::"text", 'owner'::"text"]) AND (("role" = ANY (ARRAY['member'::"text", 'moderator'::"text"])) OR "agri_connect"."is_active_community_member"("community_id", ARRAY['owner'::"text"]))));



