CREATE POLICY "agri_connect_create_media" ON "media"."files" FOR INSERT TO "authenticated" WITH CHECK ((("bucket" = 'media'::"text") AND ("created_by" = "core"."current_profile_id"()) AND ("is_deleted" = false) AND ((("context_type" = 'agri_connect_community'::"text") AND ("file_type" = 'image'::"text") AND (EXISTS ( SELECT 1
   FROM "agri_connect"."communities" "c"
  WHERE (("c"."id" = "files"."context_id") AND ("c"."is_active" = true) AND ("files"."is_public" = ("c"."visibility" = 'public'::"text")) AND ((("c"."entity_id" IS NOT NULL) AND ("files"."entity_id" = "c"."entity_id")) OR (("c"."entity_id" IS NULL) AND ("core"."current_entity_id"() IS NOT NULL) AND ("files"."entity_id" = "core"."current_entity_id"()))) AND "agri_connect"."is_active_community_member"("c"."id", ARRAY['admin'::"text", 'owner'::"text"]))))) OR (("context_type" = 'agri_connect_conversation'::"text") AND ("file_type" = ANY (ARRAY['image'::"text", 'video'::"text", 'document'::"text", 'audio'::"text"])) AND ("is_public" = false) AND (EXISTS ( SELECT 1
   FROM "agri_connect"."conversations" "c"
  WHERE (("c"."id" = "files"."context_id") AND ("c"."is_active" = true) AND "agri_connect"."messaging_has_active_identity"("c"."id") AND ((("c"."community_id" IS NULL) AND ("core"."current_entity_id"() IS NOT NULL) AND ("files"."entity_id" = "core"."current_entity_id"())) OR (("c"."community_id" IS NOT NULL) AND "agri_connect"."is_active_community_member"("c"."community_id", ARRAY['member'::"text", 'moderator'::"text", 'admin'::"text", 'owner'::"text"]) AND (EXISTS ( SELECT 1
           FROM "agri_connect"."communities" "cm"
          WHERE (("cm"."id" = "c"."community_id") AND ((("cm"."entity_id" IS NOT NULL) AND ("files"."entity_id" = "cm"."entity_id")) OR (("cm"."entity_id" IS NULL) AND ("core"."current_entity_id"() IS NOT NULL) AND ("files"."entity_id" = "core"."current_entity_id"())))))))))))))));



CREATE POLICY "agri_connect_read_media" ON "media"."files" FOR SELECT TO "authenticated", "anon" USING (((("context_type" = 'agri_connect_community'::"text") AND (EXISTS ( SELECT 1
   FROM "agri_connect"."communities" "c"
  WHERE (("c"."id" = "files"."context_id") AND ("c"."profile_image_file_id" = "files"."id") AND ("c"."is_active" IS TRUE) AND ((("c"."visibility" = 'public'::"text") AND ("files"."is_public" IS TRUE)) OR "agri_connect"."is_active_community_member"("c"."id", ARRAY['member'::"text", 'moderator'::"text", 'admin'::"text", 'owner'::"text"])))))) OR (("context_type" = 'agri_connect_conversation'::"text") AND ("is_public" IS FALSE) AND (EXISTS ( SELECT 1
   FROM ("agri_connect"."messages" "m"
     JOIN "agri_connect"."conversations" "c" ON (("c"."id" = "m"."conversation_id")))
  WHERE (("m"."media_file_id" = "files"."id") AND ("m"."conversation_id" = "files"."context_id") AND ("m"."is_deleted" IS FALSE) AND ("c"."is_active" IS TRUE) AND "agri_connect"."messaging_has_active_identity"("c"."id") AND (("c"."community_id" IS NULL) OR "agri_connect"."is_active_community_member"("c"."community_id", ARRAY['member'::"text", 'moderator'::"text", 'admin'::"text", 'owner'::"text"])))))) OR (("context_type" = 'agri_connect_discussion'::"text") AND ("bucket" = 'media'::"text") AND ("is_deleted" IS FALSE) AND ("is_public" IS FALSE) AND "agri_connect"."can_read_discussion_media"("context_id", "id"))));



CREATE POLICY "agri_connect_read_post_media" ON "media"."files" FOR SELECT TO "authenticated" USING ((("bucket" = 'media'::"text") AND ("context_type" = 'agri_connect_post'::"text") AND ("file_type" = 'image'::"text") AND ("is_public" IS FALSE) AND ("is_deleted" IS FALSE) AND (EXISTS ( SELECT 1
   FROM "agri_connect"."post_media" "pm"
  WHERE (("pm"."media_file_id" = "files"."id") AND "agri_connect"."can_read_post_media"("pm"."post_id", "files"."id"))))));



